-- 생성: node scripts/faq129/build-migration.mjs. 답변은 작성일 기준 안내이며 현재 기준과 다를 수 있다.
CREATE TABLE faq_129 (
  faq_id TEXT PRIMARY KEY NOT NULL,
  revision TEXT NOT NULL,
  group_name TEXT,
  category TEXT,
  question TEXT NOT NULL,
  answer TEXT NOT NULL,
  written_date TEXT NOT NULL,
  views INTEGER NOT NULL DEFAULT 0,
  source_url TEXT NOT NULL,
  content_sha256 TEXT NOT NULL
);
--> statement-breakpoint
CREATE TABLE faq_129_alias (
  faq_id TEXT NOT NULL REFERENCES faq_129(faq_id),
  alias TEXT NOT NULL,
  alias_kind TEXT NOT NULL CHECK (alias_kind IN ('tag','category','program')),
  PRIMARY KEY (faq_id, alias, alias_kind)
);
--> statement-breakpoint
CREATE INDEX faq_129_alias_alias ON faq_129_alias(alias);
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('18484', 'faq129-20261010', '인구아동', '아동분야사업', '위탁가정은 어떤 지원을 받을 수 있나요?', '위탁가정 지원은 다음과 같습니다.

♦ 양육보조금

- 지원내용 : 아동 1인당 양육보조금 월 340천원~560천원 이상 차등지원(지방이양)* 권고

* 만7세 미만(83개월까지) 월 340천원 이상, 만7세부터 만13세 미만(84개월∼155개월) 월 450천원 이상, 만13세 이상(156개월부터) 월 560천원 이상

♦ 전문아동보호비

- 지원대상 : 전문위탁부모

- 지원내용 : 아동 1인당 월 100만원 이상

♦ 입양대상아동보호비

- 지원대상 : 입양대상아동을 보호하는 일반·전문위탁부모

- 지원내용 : 아동 1인당 월 100만원 이상

♦ 일시위탁보호비

- 지원대상 : 일시위탁부모

- 지원내용 : 일 3만원 이상~6만원 이하 지급(지방이양) 권고

♦ 아동용품구입비(지방비)

- 지원대상 : 신규 책정 위탁가정

- 지원내용 : 위탁가정 당 100만원 지급 권고

♦ 아동용품구입비(국비)

- 지원대상 : 위기아동 가정보호 및 전문가정위탁 참여가정

- 지원내용 : 전문가정위탁 책정 시 최초 1회 위탁아동 당 100만원 지원

(단, 기존에 다른 아동을 위기아동 가정보호나 전문가정위탁으로 보호하여 아동용품구입비(국비)를 지원받은 이력이 있는 가정은 50만원 지원

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-07', 2, 'https://www.129.go.kr/faq/faq00.do?pageIndex=1#faq18484', '8f985603c39dae179e0b69384d5d3225b313efd6d49ad77c81730665d8b10926'),
('7631', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 수급자 명의의 주택가액은 실거래가로 산정되나요?', '기초연금 산정시 주택 재산가액은 공적자료 조회를 통해 주택, 공동주택, 비거주용 건물(상업용 건물, 오피스텔 등) 보유여부를 확인하고 「지방세법」의 시가표준액으로 적용 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-10-06', 961, 'https://www.129.go.kr/faq/faq00.do?pageIndex=1#faq7631', '5fdf53a2d6aab1ce6f33b22cf5a8698e24d3a3dacae3b8baa20e2b4e0fe83b69'),
('8050', 'faq129-20261010', '보건의료', '건강보험정책', '임신·출산진료비 바우처 잔액은 어떻게 확인 하나요?', '­임산부가 지급금 사용액 및 잔액을 확인하는 방법은 다음과 같습니다.

- 건강보험공단 홈페이지 > 민원서비스 > 서비스찾기 > 임신출산 진료비 잔액 확인

- 건강보험공단 앱(건강보험25시) > 전체메뉴 > 건강보험 > 의료비지원 > 임신.출산 진료비 조회 및 신청

- 카드사 고객센터 전화 상담

- 카드사 승인내역 알림서비스(SMS) 신청 시 단문 메세지 전송

- 정부24 홈페이지 > 임신출산 진료비 지원금 잔액 (통합검색)

단, 지원종료일 경과, 삭제대상, 해지대상은 잔액조회가 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-06', 10710, 'https://www.129.go.kr/faq/faq00.do?pageIndex=1#faq8050', '765b44e4062b71831a597e9e687257519f6c01adffc5b3db7cbb5f7addb65775'),
('12023', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 기저귀조제분유 지원기간에 따른 바우처 지급시기가 궁금합니다.', '기저귀•조제분유지원은 지원대상으로 결정 통보된 날의 익일부터 3개월 단위로 바우처가 지급됩니다.

