더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-06', 69, 'https://www.129.go.kr/faq/faq00.do?pageIndex=1#faq12023', '811989225a6faf22c74d02d84f82b43263b63194019a2e55e7b745aaf4c0f25c'),
('12024', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 바우처 잔액, 다음 바우처 생성일, 이용기간 종료일 등은 어떻게 확인하나요?', '기저귀조제분유 지원 특성상 3개월에 한번씩 3개월치 바우처가 일괄 생성되며, 기저귀조제분유 지원금액, 바우처 잔액, 다음 바우처 생성일, 이용기간 종료일 등은 사회서비스 전자바우처포털 사이트(www.socialservice.or.kr), 바우처사업 콜센터(1566-3232, 단축 4번)을 통해 확인하실 수 있습니다. 또한, 지원금액 및 바우처 잔액은 카드사 콜센터(BC카드 1899-4651 또는 각 은행 콜센터, 롯데카드 1899-4282, 삼성카드 1566-3336, KB국민카드 1599-7900, 신한카드 1544-8868)를 통해서도 수시로 확인 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-06', 59, 'https://www.129.go.kr/faq/faq00.do?pageIndex=1#faq12024', 'cdedb52634fcb37178f2255cee6fc1230f462e257cd6f15421918a11bdbe0790'),
('12034', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 사회복지전산관리번호 부여 아동의 경우 기저귀­조제분유 지원 가능한가요?', '기저귀•조제분유 지원을 위해서는 아동의 월령 확인이 필요함에 따라 사회복지전산관리번호만으로는 지원대상으로 결정하기 어려우며, 만 2세 미만 지원요건 해당 확인시 지원 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-06', 41, 'https://www.129.go.kr/faq/faq00.do?pageIndex=1#faq12034', '8c9b46dd8ffbc9ab9b2751d6ec20d020edbdb567cc38c4b65de74a7ea618a3df'),
('13279', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 신청방법은 어떻게 되나요?', '난임부부 시술비 지원은 보건소 방문(난임부부 중 여성의 주소지 관할 시군구 보건소) 또는 온라인(정부24, e보건소 공공보건포털)을 통해 신청 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-06', 29, 'https://www.129.go.kr/faq/faq00.do?pageIndex=1#faq13279', '6b34c92e83da518b24ce7f7d685d92a2b3c8991bc32bd1a879504f80f82c9aa8'),
('13739', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금에서 종교활동으로 발생한 수입도 소득에 포함되나요?', '기초연금에서 소득 반영 시 「기초연금법 시행령」 제2조제1항에 따라 1) 「소득세법」 제20조제1항에 따른 근로소득, 2) 「소득세법」 제19조에 따른 사업소득, 3) 「소득세법」 제14조제1항제1호가목 등 따른 재산소득, 4) 「국민연금법」­「군인연금법」 등에 따른 공적이전소득 등을 소득평가액 산정 시 반영합니다.

종교활동으로 발생한 소득으로 「소득세법」 제21조제1항제26호에 따라 종교 관련 종사자가 종교의식을 집행하는 등 종교 관련 종사자로서의 활동과 관련하여 대통령령으로 정하는 종교단체로부터 받은 소득(종교인소득)에 대하여 동법 제20조제1항에 따른 근로소득으로 원천징수하거나 과세표준확정신고를 한 경우에는 해당 소득을 근로소득으로 봅니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-10-06', 19, 'https://www.129.go.kr/faq/faq00.do?pageIndex=1#faq13739', '0edcbd944e1b54240d7ab03ac11e450dad6f9eb941ba7975a284a95efd5fd9a1'),
('13760', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금에서 불도저도 자동차에 포함되어 재산으로 반영하나요?', '기초연금 재산으로 반영되는 자동차는 「지방세법」 제124조의 규정에 따라 승용자동차, 승합자동차, 화물자동차, 특수자동차, 이륜자동차, 「건설기계관리법」에 따라 등록된 덤프트럭 및 콘크리트 믹서트럭이 해당됩니다.

건설기계 중 덤프트럭과 콘크리트 믹서트럭을 제외한 불도저, 굴삭기, 지게차, 기중기, 특수건설기계, 타워크레인 등(「건설기계관리법 시행령」 제2조)은 동산으로 처리하여 제외합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-10-06', 18, 'https://www.129.go.kr/faq/faq00.do?pageIndex=1#faq13760', 'a7774e46cd77dc3fd21090dc2842495f3e877b795a281c9693d50de091b578df'),
('13761', 'faq129-20261010', '인구아동', '기초연금사업', '65세 이상으로 기초연금 수급 중 주민등록번호가 65세 미만으로 정정된 경우 기초연금을 못 받나요?', '주민등록번호 정정으로 인해 65세 미만으로 변경된 경우 정정한 날이 속하는 달에 기초연금 수급권을 상실처리합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-10-06', 27, 'https://www.129.go.kr/faq/faq00.do?pageIndex=1#faq13761', '825156a22cbd51161fc7f012534a17d2fac5237b4b4ca6f526dfb3ee1eb8cfa2'),
('13927', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금이란 무엇인가요?', '기초연금은 국민연금제도가 시행된 지 오래되지 않아 국민연금에 가입하지 못하셨거나, 가입하셨다 하더라도 충분한 연금을 받지 못하는 등 노후준비가 되지 못한 어르신들에게 기초연금을 지급하여 안정적인 소득기반을 제공함으로써 어르신의 생활안정을 지원하고 복지를 증진하기 위해 만들어진 제도입니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-10-06', 11, 'https://www.129.go.kr/faq/faq00.do?pageIndex=2#faq13927', '1451feb9b0ab02cbf0f41eeee4ed934ea3d85c75dffface3a82f4328ff0cccbf'),
('16020', 'faq129-20261010', '보건의료', '공공보건정책', '호스피스전문기관 지정현황은 어디에서 확인할 수 있나요?', '호스피스 전문기관은 아래 경로에서 확인 가능합니다.

- 건강보험심사평가원 누리집 > 의료정보 > 특수운영기관 정보 > 특수운영기관 검색 박스의 ''특수운영 항목'' 에서 "호스피스" 선택하여 검색

- 건강보험공단 누리집 > 건강모아 > 기관찾기 > 병(의)원/검진기관 찾기 > 구분*에서 "특성별 병원" > "호스피스 전문기관" 선택하여 검색

- 국립암센터 중앙호스피스센터 누리집 > 호스피스 서비스 제공기관 > 전문기관 찾기 (지도로 찾기/상세검색으로 찾기)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-06', 48, 'https://www.129.go.kr/faq/faq00.do?pageIndex=2#faq16020', '1038bdd98242c9052e0e25890bd10aec96ce26b3177187360c04a8fc818922e4'),
('18582', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 냉동난자 해동비 지원은 어떤건가요?', '냉동난자 해동비 지원은 다음과 같습니다.

(지원대상) 가임력 보존을 목적으로 냉동한 난자를 임신·출산을 위해 사용할 경우, 보조생식술 비용 일부를 지원

(지원액) 생식세포(난자)해동비에 한해 시술당 최대 30만원 지원

(청구방법) 지원대상자가 냉동한 난자를 사용하여 임신·출산을 시도한 경우, 시술 완료 후 관련서류 (생식세포 동결보존 동의서, 동결보존 생식세포 소견서, 시술비 청구서, 시술확인서, 계산서·영수증, 시술자 본인의 계좌통장 사본)를 첨부하여 1개월 이내 관할 보건소 또는 e보건소 공공보건포털로 청구

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-06', 1, 'https://www.129.go.kr/faq/faq00.do?pageIndex=2#faq18582', 'd21c06549ee83fa87885a2db1f3b008e35ff2405b039550c9e98c7e532c33581'),
('18642', 'faq129-20261010', '보건의료', '공공보건정책', '달빛 어린이 병원은 무엇인가요? 병원 현황은 어디서 확인할 수 있나요?', '달빛 어린이 병원은 평일 야간 및 휴일(토·일·공휴일)에 응급실이 아닌 외래 진료를 통해 소아 환자에게 신속한 의료서비스 제공하고 응급의료기관 과밀화 해소 및 경증환자 분산, 응급실 이용으로 발생할 수 있는 환자·보호자 불편 및 비용 부담을 완화하기 위해 운영되는 의료기관입니다.

달빛 어린이 병원은 응급의료포털(http://www.e-gen.or.kr) 및 "응급의료정보제공" 스마트폰앱에서 확인 가능하며, 진료시간이 불규칙 할 수 있으니 반드시 사전에 전화로 진료시간 확인 후 방문하시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국버없이 129)로 연락주시기 바랍니다.', '2026-10-06', 9, 'https://www.129.go.kr/faq/faq00.do?pageIndex=2#faq18642', '840d1d18e3fde416e4e0640e33e180814b617c0792ac52c2f2636ec73f900806'),
('1516', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 신청은 본인만 할 수 있나요?', '기초연금은 본인이 직접 신청하시는 것이 원칙이나 불가피할 경우 배우자나 자녀, 형제자매, 친족(8촌 이내의 혈족, 4촌 이내의 인척), 기타 관계인(후견인), 사회복지시설장 등이 대리 신청할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-10-06', 2596, 'https://www.129.go.kr/faq/faq00.do?pageIndex=2#faq1516', 'df258d5834eb8624d1a56d03b8441693123ce64aca9eaba88f93337251dce73e'),
('1580', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금에 해당되는지 모의계산을 해볼 수 있나요?', '기초연금 모의계산은 본인과 배우자의 소득과 재산사항을 입력하여 아래 사이트에서 활용할 수 있습니다.

- 복지로 홈폐이지(http://www.bokjiro.go.kr) : 복지서비스 > 복지서비스 모의계산

- 국민연금공단 홈페이지(http://csa.nps.or.kr) : 중앙노후준비지원센터 > 재무진단 > 기초연금 모의계산

다만, 모의계산 결과는 신청을 통해 조회된 소득인정액과 차이가 있을 수 있으므로 단순 참고용으로 활용하실 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-10-06', 6326, 'https://www.129.go.kr/faq/faq00.do?pageIndex=2#faq1580', '25f777e252188c394b60955405479b326931fd1c204f1fdc4d2bd7aa2eb13bf9'),
('928', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 지원결정통지서 발급 후 타 지역으로 전입 시 다시 신청해야 하나요?', '난임부부 시술비 지원을 위한 지원결정통지서 유효기간은 6개월이며, 지원결정통지서 유효기간 내인 경우 재신청하지 않아도 됩니다.

전출지 관할 보건소에서 발급한 지원결정통지서로 지원 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-06', 1580, 'https://www.129.go.kr/faq/faq00.do?pageIndex=2#faq928', 'ccc03bd4e74b7f10446fac839055a9a919ea7c16050b2ed008abeaf5c4317af6'),
('939', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 영아의 부모가 건강 또는 직장 등의 사정으로 방문신청이 어려운 경우 대리신청이 가능한가요?', '기저귀 조제분유 지원사업은 영아를 양육하는 부모가 일시적인 사유로 수혜 신청이 어려운 경우에는 할머니 등 친족(조부모 등)이 관계 증빙서류(예: 가족관계증명서)를 지참하고 아동 주소지 관할 보건소 또는 주민센터를 방문하여 대리신청이 가능합니다.

또한 부모가 신청시 온라인(정부24(www.gov.kr) ‘행복출산원스톱서비스’ 또는 복지로(www.bokjiro.go.kr)) 신청도 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-06', 1103, 'https://www.129.go.kr/faq/faq00.do?pageIndex=2#faq939', 'dd4b11df204bee1ca80620148096c429a437c7721203f754d5b37bbcf232e2fc'),
('1252', 'faq129-20261010', '인구아동', '아동수당', '지급 방식은 어떻게 되나요?', '아동수당은 현금 지급(매월 25일) 을 원칙으로 하며, 신청 당시 제출한 아동 또는 보호자의 계좌로 입금됩니다.

* 부모가 보호자가 아닌 경우 아동명의 계좌로 입금시 반드시 부모가 아닌 보호자가 아동명의통장 소유 여부를 확인 후 지급(ex. 아동학대 등으로 가정위탁보호중인 아동 등)

또한 해당 시·군·구에서 조례로 정하는 경우 지역사랑상품권 등으로 지급할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-06', 1805, 'https://www.129.go.kr/faq/faq00.do?pageIndex=2#faq1252', 'd1c063d3633c828f2a6e568bd9d4fed2f2d1db00217d1c05be5b7391b6b6e0c7'),
('18503', 'faq129-20261010', '사회복지', '자활사업', '자활성공지원금을 여러 번 지원받을 수 있나요?', '자활성공지원금을 이미 한번이라도 지원받았다면, 다시 자활근로 참여 후 탈수급·취창업 유지 등 요건을 충족하더라도 재지급은 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-02', 23, 'https://www.129.go.kr/faq/faq00.do?pageIndex=2#faq18503', '86703b4060e89209df9d506d8a8cab2254d2cb61e840c129050ecf07d488efa1');
