INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('18542', 'faq129-20261010', '사회복지', '기초생활보장사업', '수급자가 병원에 입원하게 되면 생계급여가 삭감되나요?', '의료급여수급자가 의료기관에 3개월 중 30일 이상의 기간 동안 입원하게 되면. 30일 초과 입원일수에 대하여 장기 입원하여 지출되지 않는 것으로 판단되는 금액을 생계급여에서 공제하여 지급합니다. 다만, 의료급여 자격 없이 생계급여 자격만 있는 경우에는 적용대상이 아닙니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-02', 36, 'https://www.129.go.kr/faq/faq00.do?pageIndex=3#faq18542', '373a519dea542425bd4fe01cd8aae4f5261cb25e6a335093c1dc3addaf8b804e'),
('18645', 'faq129-20261010', '보건의료', '건강보험정책', '''건강보험 임신·출산 진료비 지급 신청서''의 임신·출산 확인은 누가 하나요?', '''건강보험 임신­출산 진료비 지급 신청서''의 임신·출산 확인은 산부인과 전문의만 할 수 있으며, 출산 확인은 조산사도 가능합니다. 이는 임신·출산과 관련된 전문성을 확보한 전문의가 진료를 함으로써 산모와 태아가 안전하게 분만할 수 있는 환경을 조성하기 위한 취지로 일반의까지 확대하기에는 어려운 점이 있습니다.

* 의료법 제77조 제3항 및 ‘전문의 수련 및 자격인정 등에 관한 규정’ 제3조에 따른 전문 과목 중 산부인과 전문의가 상근하는 의료기관으로 규정

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-02', 6, 'https://www.129.go.kr/faq/faq00.do?pageIndex=3#faq18645', 'fd4639e5261aba887260604c5d5e3433854a8f61d639402f88a4f7069afb7a0e'),
('18644', 'faq129-20261010', '보건의료', '공공보건정책', '기증희망등록을 하면 무조건 기증해야 하나요?', '아닙니다. 기증희망등록은 의사표시일 뿐 법적 강제력이 없습니다.

기증희망등록을 신청했다고 강제로 장기기증을 진행하는 일은 불가능하며, 실제 기증 시에는 가족 1인의 동의가 반드시 필요합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-01', 5, 'https://www.129.go.kr/faq/faq00.do?pageIndex=3#faq18644', 'f447b4c2ca459b784f74c5a486939e9db161c416d4a25ae1fb60d832f99e9bd9'),
('18662', 'faq129-20261010', '보건의료', '공공보건정책', '기증희망등록과 장기기증이 같은 내용인가요?', '아닙니다. 기증희망등록은 향후 기증이 가능한 상황이 오면 장기·인체조직 등을 대가 없이 기증하겠다는 의사표시로 법적 강제성을 띄지 않습니다.

장기기증은 다른 사람의 장기 등의 기능 회복을 위해 대가없이 자신의 장기 등을 제공하는 행위로 주로 뇌사 상태일 경우 기증하며 가족 1인의 동의가 반드시 있어야 기증이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-10-01', 3, 'https://www.129.go.kr/faq/faq00.do?pageIndex=3#faq18662', '3e8d8346b7d541da4cd23813a998dcd03b1fb6b50e44bbf9b439746b2f432674'),
('18584', 'faq129-20261010', '노인장애인', '장애인복지사업', '발달장애인 긴급돌봄서비스에서 보호자의 기준이 어떻게 되나요?', '’보호자‘는 지원대상 발달장애인과 주민등록상 동일 세대를 구성하고 실제로 생계와 거주를 같이 하면서, 실질적으로 발달장애인을 돌보는 가족(2촌 이내)을 의미합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-30', 18, 'https://www.129.go.kr/faq/faq00.do?pageIndex=3#faq18584', 'e71cbd24e20b6d3304c5312f1326afe12b00019dbfc85158363e80ef8d47e87f'),
('4953', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금을 늦게 신청한 경우 지급받지 못한 기간을 소급하여 받을 수 있나요?', '기초연금은 신청주의가 원칙입니다.

이에 따라 기초연금의 지급을 신청한 날이 속하는 달(만 65세 도래 전에 신청한 경우 만 65세 도래한 달)부터 지급되므로 신청하지 않은 달의 기초연금은 소급하여 지급되지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-29', 6701, 'https://www.129.go.kr/faq/faq00.do?pageIndex=3#faq4953', 'eca6c1e8192d818f4d1e7dc62026d497dd05a432994d5da1f9b06ce1db4cacec'),
('15081', 'faq129-20261010', '인구아동', '기초연금사업', '국민연금공단의 찾아뵙는 서비스가 무엇인가요?', '국민연금공단에서 제공하는 ‘찾아뵙는 서비스’는 거동이 불편하거나 격오지 등 원거리 거주, 생업종사 등으로 공단 지사나 관할 지자체로 방문이 어려운 어르신에게 국민연금공단 직원이 직접 희망하는 곳으로 방문하여 기초연금 상담·­신청 업무를 현장에서 제공하는 서비스입니다.

‘찾아뵙는 서비스’는 기초연금 신청을 희망하시는 경우 신청희망자 본인 뿐만 아니라 신청희망자의 가족 등도 대리신청 가능합니다.

* ‘찾아뵙는 서비스’ 신청방법 : 국번없이 1355(국민연금공단 고객센터) 또는 국민연금공단 지사로 문의

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-29', 11, 'https://www.129.go.kr/faq/faq00.do?pageIndex=3#faq15081', '3c7256c0461ab95ae79acaf3489175cfed75f24841e96108c114b74959914ee3'),
('15082', 'faq129-20261010', '인구아동', '기초연금사업', '계좌가 압류되었을 경우 기초연금 수령은 어떻게 하나요?', '기초연금 수급자의 급여가 압류되는 것을 방지하기 위해 복지급여만 입금되고 그 외의 금원은 입금이 차단되는 압류방지 전용통장(명칭: 행복지킴이 통장)으로 수령할 수 있습니다.

압류방지 전용통장은 1인 1계좌 원칙의 예외로 운영되며, 압류방지 전용통장은 1개의 계좌만 사용할 수 있습니다.

* 기존 발급된 압류방지 전용통장이 있는 경우 추가발급이 제한되며, 이 경우 수급계좌 변경만 가능

압류방지 전용통장은 전국 읍­면­동 주민센터에서 ‘기초연금 수급자 확인서(서식18호)’를 발급받아 금융기관에 신청한 후, 다시 관할 읍­면­동 주민센터 또는 전국 국민연금공단 지사에 급여계좌를 변경 신고하면 압류방지 전용통장을 통해 연금을 지급받을 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-29', 16, 'https://www.129.go.kr/faq/faq00.do?pageIndex=3#faq15082', 'f274938fd384a8bb7fdc0a8e0a920da8a55535af9224032d35ad7ba79efc5bb6'),
('16701', 'faq129-20261010', '인구아동', '기초연금사업', '타인 명의 계좌로 기초연금을 받을 수 있나요?', '기초연금은 수급자 명의의 계좌지급이 원칙입니다.

- 수급자인 부부가 모두 동의할 경우에는 일방 배우자의 계좌로 지급 가능

※ 부부 각각의 동의여부를 반드시 확인

다만, 다음 중 어느 하나에 해당하는 경우에는 대리수령인(수급자의 배우자, 직계혈족, 3촌 이내의 방계혈족) 명의의 계좌로 지급 가능합니다.

① 성년후견개시, 한정후견개시 또는 특정후견개시 심판이 확정된 경우

- 후견등기에 관한 법률에 따른 ''후견 등기사항 (부존재)증명서''로 확인

② 채무 불이행으로 금전채권이 압류된 경우

- 법원에서 발행한 채무불이행자 명부 확인

- 압류사실을 증명할 수 있는 서류*를 1부 이상 징구

* 금융기관에서 통지한 금융 압류 사실 통지서, 법원의 채권압류 및 추심명령 결정문 등

③ 치매 또는 보건복지부장관이 정하는 거동이 불가능한 사유로 인해, 본인 명의의 계좌를 개설하기 어렵거나, 본인 명의의 계좌 사용이 불가한 경우

- 보건소(치매안심센터) 치매환자 등록 여부 확인 또는 치매, 중풍, 뇌병변 등으로 인해 거동이 불가하다는 병원진단서 징구

- 노인장기요양보험 대상자는 행복e음을 통해 정보조회

- 정신요양시설 입소자 또는 정신의료기관 입원자로서 거동이 불편하다고 정신과 전문의가 인정하는 자는 입소통지서 또는 정신과 전문의 소견서 징구

(대리수령인 제출서류)

- 기초연금 대리수령 신청서, 수급자·대리인 신분증, 대리수령 사유 관련 서류, 가족관계등록부 등

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-29', 49, 'https://www.129.go.kr/faq/faq00.do?pageIndex=3#faq16701', '6bd84a7076496eb567ef1fb48dd3eaa233220f5ae0223cc3d54abf585a6362fb'),
('1590', 'faq129-20261010', '인구아동', '기초연금사업', '어머님이 공무원 유족연금을 수령중인데 기초연금을 신청할 수 있나요?', '공무원 유족연금을 수령하시는 경우,「기초연금법」제3조 3항에 근거하여 기초연금을 지급하지 않습니다.

* 직역연금 수급권자와 그 배우자는 기초연금대상 제외

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-29', 12998, 'https://www.129.go.kr/faq/faq00.do?pageIndex=3#faq1590', '3b9ec0e369dacdc48763780784d07859c905d406a07cdf5ab48f31a92a4f38c2'),
('1601', 'faq129-20261010', '인구아동', '기초연금사업', '올 해 65세 되는 아버님이 공무원 퇴직연금을 수령하시면 기초연금은 못 받나요?', '공무원 퇴직연금을 수령하시는 경우, 「기초연금법」제3조 3항에 근거하여 기초연금을 지급하지 않습니다.

* 직역연금 수급권자와 그 배우자는 기초연금대상 제외

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-29', 9297, 'https://www.129.go.kr/faq/faq00.do?pageIndex=4#faq1601', '7e37f7bb87e8218aa6edba3048a0f0db190b9f135986120a97de1953e1fe8425'),
('14600', 'faq129-20261010', '노인장애인', '장애인복지사업', '외국인도 최중증 발달장애인 통합돌봄서비스 신청이 가능한가요?', '「장애인복지법」제32조의2(재외동포 및 외국인의 장애인 등록)에 따라 장애 등록한 재외동포 및 외국인은 최중증 발달장애인 통합돌봄서비스 신청 대상에서 제외됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-28', 70, 'https://www.129.go.kr/faq/faq00.do?pageIndex=4#faq14600', '1d713f1dba384b028550e9415640c24185148832628f756652e1e3d18c12e9ff'),
('16800', 'faq129-20261010', '노인장애인', '장애인복지사업', '최중증 발달장애인 통합돌봄서비스 본인부담금이 어떻게 되나요?', '최중증 발달장애인 통합돌봄서비스 이용에 따른 본인부담금은 없지만, 서비스 이용 중에 점심식사, 송영서비스 제공되는 경우와 프로그램 활동비 등에 대해 실비 수준의 비용이 발생할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-28', 62, 'https://www.129.go.kr/faq/faq00.do?pageIndex=4#faq16800', '5cc0534dfe3c165500efd0cd702cca87c71785fc0e0e42b870f2189a6b529047'),
('17160', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인 주간이용시설 이용 중인데 최중증 발달장애인 통합돌봄서비스 대상이 되나요?', '장애인 주간이용시설(주간보호센터) 이용자는 최중증 발달장애인 통합돌봄서비스 대상에서 제외됩니다.

다만, 기존 서비스를 중지하는 것을 전제로 신청할 수 있고, 통합돌봄서비스 이용자로 선정되어 제공기관 이용 시에는 이전 서비스는 종결하셔야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-28', 40, 'https://www.129.go.kr/faq/faq00.do?pageIndex=4#faq17160', '86e9c6cddfca5e9117dc65c46e4ced23e6c73b179b87f4f24ddc7ffa70d70801'),
('18583', 'faq129-20261010', '노인장애인', '장애인복지사업', '최중증 발달장애인 통합돌봄서비스는 거주지를 이전하더라도 계속 이용할 수 있나요?', '최중증 발달장애인 통합돌봄서비스 이용 중에 전입을 가더라도 통합돌봄서비스 수급자격은 유지됩니다.

단, 전입한 지역에 통합돌봄 서비스 제공기관이 있으며, 신규 대상자에게 바우처를 제공할 예산 여유가 있는 경우에 한해 이용 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-28', 8, 'https://www.129.go.kr/faq/faq00.do?pageIndex=4#faq18583', 'c55a44cd470fc9455f0bd8827a8a2eca29e7b0b763eb0b88f9c72a0ba830b5a0'),
('18585', 'faq129-20261010', '노인장애인', '장애인복지사업', '학교 재학 중에도 최중증 발달장애인 통합돌봄서비스 신청할 수 있나요?', '18세 이상이면서「초·중등교육법」에 따른, 일반 중·고등학교 또는 특수학교에 재학 중인 ‘졸업예정자’인 경우에만 신청할 수 있으며, 신청시 졸업예정증명서를 제출해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-28', 6, 'https://www.129.go.kr/faq/faq00.do?pageIndex=4#faq18585', '0ff062c822c9bd2957919d28a255cd022f0c3b9bb396ecafaffebb855db9cceb'),
('18586', 'faq129-20261010', '인구아동', '기초연금사업', '통장·­이장·­반장 활동보상금은 공적 이전소득으로 산정하나요?', '기초연금 소득산정시 통장·­이장·­반장 활동보상금은 지자체 조례에 의해 지급되는 수당으로 공적 이전소득으로 산정하지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-28', 4, 'https://www.129.go.kr/faq/faq00.do?pageIndex=4#faq18586', '1e3347757b86594bee522eebb70751c3e8108a58bb80f5ce31e3e60cf14654fa'),
('18587', 'faq129-20261010', '노인장애인', '장애인복지사업', '현재 직장을 다니고 있는데 최중증 발달장애인 통합돌봄서비스 신청이 가능한가요?', '현재 취업상태에 있는 경우에도 신청은 가능하지만, 직장을 다니고 있는 경우에는 최중증 발달장애인 통합돌봄서비스와 동시 이용은 불가합니다.

통합돌봄서비스 대상자로 선정되어 서비스 이용 시에는 기존 직업활동을 유지할 수 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-28', 6, 'https://www.129.go.kr/faq/faq00.do?pageIndex=4#faq18587', 'f7b6deb5521e925ec46e8b7834f5473200b95dbf2ea85ed2ef3adc1fb8476dcd'),
('2884', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금의 지급이 정지되는 사유는 무엇인가요?', '기초연금의 지급정지 사유는 다음과 같습니다.

- 금고 이상의 형을 선고받고 교정시설 등에 수용 중인 자

- 실종 또는 가출, 행방불명 등의 신고접수일로부터 30일이 경과한 경우

- 국외 체류기간 60일 이상 지속되는 경우

- [주민등록법] 제20조제6항에 따라 거주불명등록자로 등록된 경우

지급 정지기간은 지급정지사유가 발생한 다음 달부터 그 사유가 소멸한 날이 속하는 달까지입니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 3303, 'https://www.129.go.kr/faq/faq00.do?pageIndex=4#faq2884', '9f468af16647ad9d0b6ec546c0a25ab694e0889b51a6041d62edaf381db619d2'),
('3102', 'faq129-20261010', '인구아동', '기초연금사업', '자녀의 소득이 많아도 기초연금을 받을 수 있나요?', '기초연금은 자녀 등 부양의무자의 소득·재산은 조사하지 않고 본인 및 배우자의 소득·재산만을 조사하여 수급자격을 결정합니다.

다만, 본인 또는 배우자의 주민등록상 주소지 주택이 자녀 명의이고, 시가표준액 6억원 이상인 경우 무료임차소득을 적용하여 본인의 소득인정액에 포함합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 9902, 'https://www.129.go.kr/faq/faq00.do?pageIndex=4#faq3102', 'c55c2a4ef4c3927e5a7a9f6ac38db68327fa1a7cee8d5c2f8ef42c42c2e00e48');
