INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('3485', 'faq129-20261010', '인구아동', '기초연금사업', '부부가 모두 기초연금을 받는 경우 기초연금이 감액되나요?', '부부가 모두 65세 이상으로 기초연금을 수급하는 경우 단독가구와 부부가구의 생활비 차이를 감안하여 각각의 기초연금액에서 20%를 감액하게 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 문의주시기 바랍니다.', '2026-09-23', 23893, 'https://www.129.go.kr/faq/faq00.do?pageIndex=5#faq3485', '8077fb8b01b3e511745e7da484bea6706222d1f5d0fc04c9c32b1510b2a7b26a'),
('4712', 'faq129-20261010', '인구아동', '산모신생아건강관리지원사업', '산모의 배우자가 신청해도 되나요?', '산모신생아 건강관리지원사업을 신청할 수 있는 신청권자는 다음과 같습니다.

○ 신청권자 : 산모 본인, 친족, 법정대리인, 담당공무원(직권신청)

* 친족의 범위(민법 제777조) : 배우자, 8촌 이내의 혈족, 4촌 이내의 인척

따라서, 친족에 해당하는 배우자도 신청할 수 있으나, 신청권자 중 산모(본인)를 제외한 신청자는 대리신청에 해당하므로 위임장을 제출하셔야 합니다.

더 자세한 사항은 보건복지상담센터 (국번없이 129)로 연락주시기 바랍니다.', '2026-09-23', 1316, 'https://www.129.go.kr/faq/faq00.do?pageIndex=5#faq4712', 'f7cd6260a4c21ad3900bfe1f8b3ee963b69cc96fa0b88bb0717dc6b9c74a0020'),
('4940', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금을 수급 받다가 포기할 수 있나요?', '기초연금 수급 포기를 희망할 경우에는 ''수급권포기서(임의서식)''를 제출하여 수급권 상실처리가 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 3620, 'https://www.129.go.kr/faq/faq00.do?pageIndex=5#faq4940', '569d1a317f5849ce9a0a99b438d5628f71f7ff3cb1a8886dbb6ca1074160560e'),
('5010', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 신청 부부의 주소가 대도시와 중소도시로 각각 다를 경우 기본재산액 공제는 어디를 기준으로 하나요?', '기초연금 산정시 수급자와 그 배우자의 주민등록 주소지가 다른 경우 일반재산에서 공제 적용하는 기본재산액은 부부 중 상위도시 거주자 주소지를 기준(대도시>중소도시>농어촌)으로 적용합니다.

기초연금 신청 부부가 대도시와 중소도시에 각각 주소를 달리 두고 있는 경우, 대도시 기준으로 1억3천5백만원을 기본재산액으로 일반재산에서 공제 적용하게 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 4768, 'https://www.129.go.kr/faq/faq00.do?pageIndex=5#faq5010', '85a8f462478dc583b8cedebbd3a5ead1c18d734f29e073c1b4e56b3c694a87e8'),
('6491', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 소득산정 시 예금의 이자소득도 반영 하나요?', '기초연금 소득 산정 시 [기초연금법 시행령]제14조제1항제1호 가목~마목의 규정에 해당하는 금융재산에서 발생하는 이자와 배당 또는 할인에 의해 발생하는 소득으로 보건복지부장관이 정하여 고시하는 금액* 이상의 소득은 이자소득으로 반영합니다.

* 이자소득이 있는 수급희망자에 대하여 월 4만원을 소득산정에서 제외하고 반영하며, 이 경우 이자소득에서 월 4만원을 차감한 금액이 0보다 작을 경우 0원으로 산정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 4883, 'https://www.129.go.kr/faq/faq00.do?pageIndex=5#faq6491', '990cf4da49dea615f84f3c1f955f716b6d089f810a3b6f28b0e49f719cc5bdda'),
('6870', 'faq129-20261010', '인구아동', '기초연금사업', '고엽제후유의증수당도 소득에 포함되나요?', '기초연금 산정 시 2021년 부터「고엽제후유의증 환자지원 및 단체설립에 관한 법률」에 의한 고엽제후유의증수당은 소득에 반영하지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 3101, 'https://www.129.go.kr/faq/faq00.do?pageIndex=5#faq6870', '2b0707783f4cb6e7066f3c7f79122d58fdbe5a2484205a8dd9dbddf9a18d35e2'),
('7053', 'faq129-20261010', '인구아동', '기초연금사업', '사망한 기초연금 수급자의 미지급된 연금을 주소지 다른 배우자가 청구할 수 있나요?', '기초연금 사망자의 미지급 연금은 아래 부양의무자 인정기준을 충족한 경우에 한하여 청구할 수 있습니다.

부양의무자 인정기준은 기초연금 수급자가 사망할 당시 주거를 같이한 부양의무자 또는 정기적으로 기초연금 수급자에게 생활비를 지급한 부양의무자가 인정됩니다.

정기적 생활비 지급의 인정 범위는 계좌로 입금한 경우를 우선 인정하되, 직접 현금을 지급했다고 주장하는 경우에는 청구인(본인) 확인서 징구를 통해 인정할 수 있습니다.

참고로 미지급 연금액의 청구권은 5년간 행사하지 않으면 사망일로부터 5년 후에 소멸됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 2858, 'https://www.129.go.kr/faq/faq00.do?pageIndex=5#faq7053', 'c936cddb8efddd41024d7e4711c35903558550827dc1d8dce92628d1b3e49ce0'),
('7272', 'faq129-20261010', '인구아동', '기초연금사업', '금융기관에서 받은 대출만 부채로 인정되나요?', '기초연금 소득인정액 산정 시 금융기관 외에도 아래에 해당하는 기관에서 발급한 증빙서류 제출을 통해 실제 상환하여야 할 본인 대출금을 확인하여 부채인정이 가능합니다.

- 공공기관 대출금

- 법에 근거한 공제회 대출금

- 한국자산관리공사(캠코)가 인수한 부실채권으로 공사가 증명한 부채

- 예금보험공사가 인수한 부실채권으로 공사가 증명한 부채

- 서민금융진흥원 대출금

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 3420, 'https://www.129.go.kr/faq/faq00.do?pageIndex=5#faq7272', '655a31daf94508d856a59b1e5e96ca5d2e38728929e1a806c2e25f89a81673f2'),
('7533', 'faq129-20261010', '인구아동', '산모신생아건강관리지원사업', '주말에도 서비스를 이용할 수 있나요?', '1주간 5일 서비스 제공 시 토요일과 공휴일은 휴무가 원칙입니다.

다만, 이용자의 사정 등으로 부득이하게 서비스 제공 요일 등을 원칙과 달리 정하고자 하는 경우에는 이용자와 제공자 간 협의를 통해 서비스 일자 조정후 제공 가능합니다. (계약에 반영 필요)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-23', 586, 'https://www.129.go.kr/faq/faq00.do?pageIndex=5#faq7533', 'bead52a5b0218f87141c2f71e236daa75e625923e764e25057dc8e692bf6af0c'),
('7611', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 신청 시 전기자동차는 재산반영을 어떻게 하나요?', '기초연금 산정시 전기자동차는 조회된 차량가액(보조금 포함)만큼 재산으로 산정합니다.

보조금을 포함한 차량가액이 4천만원 이상인 경우 고급자동차로 판단하여 차량가액을 그대로 소득인정액으로 산정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 2979, 'https://www.129.go.kr/faq/faq00.do?pageIndex=5#faq7611', 'db5f66617b1c3e17ae445dda20e485d53273a261dc718b22b8fa2ba93a692196'),
('7772', 'faq129-20261010', '인구아동', '기초연금사업', '집행유예 기간 동안 지급된 기초연금은 환수하나요?', '집행유예는 기초연금 지급정지 사유에 해당하는 금고 이상의 형을 선고받고 교정시설 또는 치료감호시설에 수용되어 있는 경우가 아니므로 집행유예 기간에는 기초연금을 지급합니다.

따라서 집행유예 기간동안 지급된 기초연금은 환수하지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 824, 'https://www.129.go.kr/faq/faq00.do?pageIndex=6#faq7772', 'ef52d701626ca8039a08568e01ebf37e67f4a1547e1dca05e010bcb6efe1bc98'),
('7970', 'faq129-20261010', '인구아동', '기초연금사업', '사업자등록이 공동명의인 경우 사업소득은 1/2로 반영되나요?', '공동명의 사업자의 소득세는 개별과세가 원칙입니다.

각각 본인이 소득신고를 하도록 되어있으므로 1/2로 반영하지 않고 공적으로 조회된 국세청 사업소득 금액 그대로 사업소득으로 반영합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 765, 'https://www.129.go.kr/faq/faq00.do?pageIndex=6#faq7970', 'dc804f748d061a5152ef6dfa9b815663e4f41c334e128231ed5a09717946a0ff'),
('8131', 'faq129-20261010', '인구아동', '기초연금사업', '임차보증금 재산 산정시 임대기간이 만료된 임대차계약서를 제출해도 되나요?', '유효기간이 만료된 임대차계약서는 무효합니다.

다만, 묵시적 갱신에 해당하는 것으로 확인되는 경우 계약기간이 만료된 ''임대차계약서''도 인정할 수 있습니다.

「주택임대차보호법」제6조에 따라 임대인이 임대차기간 만료 전 6개월부터 1개월까지 임차인에게 갱신거절 통지 또는 조건의 변경없이 갱신하지 않는다는 통지를 하지 않는 경우이거나 임차인이 임대차기간 만료 1개월까지 통지하지 않은 경우라면 그 기간이 만료된 때에도 전임대차와 동일한 조건으로 다시 임대차한 것으로 인정됩니다.

다만, 소유권의 변동이 없고, 계약기간 중 임차인의 주민등록상 주소지 변동이 없거나 임차권 등기를 하였을때 해당 사실에 대해 담당공무원이 임대인에게 유선 확인한 경우에 한하여 인정할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-23', 1064, 'https://www.129.go.kr/faq/faq00.do?pageIndex=6#faq8131', 'c8b0871a1f6f133272e28a90111c6d3f82af924194ab15a7aee4e7b56f66ecf5'),
('8790', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금에서 공공일자리 소득을 산정하지 않는 이유는 무엇인가요?', '공공일자리 소득은 중앙행정기관 및 지방자치단체 또는 이들로부터 위탁받은 각종 기관 및 단체가 시행하는 사업에 참여한 대가로 제공되는 근로소득을 말합니다.

대표적으로 노인일자리사업, 장애인일자리사업, 공공근로사업 참여자의 소득이 해당되며, 이는 임시적•일용적 성격이 강한 소득으로 어르신의 근로활동을 장려하기 위하여 근로소득 산정에서 제외하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 1308, 'https://www.129.go.kr/faq/faq00.do?pageIndex=6#faq8790', '998c621d16e59fdc11d5b6d8bfc88ceabb7f3cde9997664f5a7ea56e1489ba12'),
('10052', 'faq129-20261010', '인구아동', '기초연금사업', '국가유공자로 보상금을 받고 있는데 수령하는 금액을 전부 소득으로 보나요?', '2022년 8월 1일부터 기초연금법 시행령의 개정으로 「국가유공자 등 예우 및 지원에 관한 법률」, 「보훈대상자 지원에 관한 법률」, 「독립유공자예우에 관한 법률」에 따른 보상금과 6·25전몰군경자녀수당 중 일정액*과 「국가유공자 등 예우 및 지원에 관한 법률」에 따른 4·19혁명 공로수당 전액을 소득에서 제외하고 반영합니다.

* 국가유공자 · 독립유공자 보훈보상금 : 최대 무공영예수당 최고액(43만원) 만큼 소득 제외

6·25 전몰군경자녀수당 : 최대 무공영예수당 최고액(43만원) 만큼 소득 제외

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 1006, 'https://www.129.go.kr/faq/faq00.do?pageIndex=6#faq10052', '322ba6dd8078e1ea8269cf363b3c5695a6e2df82db4e01296f78a805fc8b648e'),
('10235', 'faq129-20261010', '인구아동', '기초연금사업', '이혼으로 국민연금의 분할연금을 수령중인데 기초연금이 감액 되나요?', '기초연금은 ­국민연금법­ 제64조에 의한 분할연금 수급권자는 A급여액과 국민연금 급여액 등 산식에 따라 기초연금액이 감액될 수 있습니다.

* 단, 분할연금 수급권이 발생하였으나 이를 청구하지 않은 경우는 제외

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 1320, 'https://www.129.go.kr/faq/faq00.do?pageIndex=6#faq10235', 'c8dc5d26b63df09b2041c6f503920c0ca41a59cfe4a8211ec0727830fa05e7fa'),
('10557', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 신청은 어떻게 하나요?', '기초연금 신청방법은 방문신청과 온라인신청이 있습니다.

전국 가까운 읍·면·동 주민센터 또는 전국 국민연금공단 지사로 방문신청 하실 수 있으며, 본인 인증을 통해 복지로(www.bokjiro.go.kr)에서 온라인신청을 하실 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 921, 'https://www.129.go.kr/faq/faq00.do?pageIndex=6#faq10557', '18df46763344a37bb5768e51964c97ba0daabfd2fde4f3a5a9a02b9aff7fb3af'),
('11394', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금을 대리신청은 누가 할 수 있나요?', '「기초연금법」제10조제1항에 따라 보건복지부령으로 정하는 대리인은 기초연금의 지급을 대리 신청할 수 있습니다.

기초연금 지급의 신청을 대리할 수 있는 사람은 배우자(65세 미만 포함), 자녀, 형제.자매, 친족(8촌 이내의 혈족, 4촌 이내의 인척), 기타관계인(후견인) 사회복지시설장(개인 및 법인운영 신고시설의 장), 사회복지 전담공무원 등 관계 공무원이 있습니다.

대리인이 신청할 경우 신청서류와 본인 신분증 이외에 대리인의 신분증, 위임장을 추가로 지참하셔야 합니다.

* 배우자 대리신청 시 위임장은 제출하지 않아도 됨

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 673, 'https://www.129.go.kr/faq/faq00.do?pageIndex=6#faq11394', '850d3e4ca4adf5fb88a21e235d2298127b097bf6e60bf540f785e7935df193cc'),
('11415', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 입금일은 언제인가요?', '기초연금 수급자에게 기초연금은 매월 25일에 지급됩니다. (토요일·공휴일인 경우 그 전일에 지급)

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 986, 'https://www.129.go.kr/faq/faq00.do?pageIndex=6#faq11415', 'fccb57afecc4f8623f59fb2822ef5bfd46e230ed9f0d86d685d2849820fe2ce2'),
('13740', 'faq129-20261010', '인구아동', '기초연금사업', '은퇴한 목사님의 사적연금을 교단에서 지원 시 소득으로 산정되나요?', '일부 교단에서는 ‘은급제도’로 불리는 은퇴한 목회자를 위한 노후보장제도가 있습니다. 이러한 사적연금은 보상차원의 실비성격으로서 연금소득으로 산정하지 않습니다.

연금소득 범위는 「기초연금법 시행령」 제2조제1항제3호나목에 규정에 따라 「소득세법」 제20조의3 제1항제2호 및 제3호에 따른 연금 및 소득과 「보험업법」 제4조제1항제1호 나목에 따른 연금보험에서 발생하는 소득으로 규정하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 14, 'https://www.129.go.kr/faq/faq00.do?pageIndex=6#faq13740', '3a0253d86549219c070dc86f19fa4a5e45d0f561dc2fe0aae809694005ab87b8');
