INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('13741', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 수급 중 교정시설에 수감되었다가 출소하는 경우 기초연금을 다시 받을 수 있나요?', '기초연금을 수급 중 금고 이상의 형을 선고받고 교정시설 수용되어 있는 경우 기초연금 지급이 정지됩니다.

이후 교정시설에서 출소를 하게 되면 출소한 날의 다음 달부터 기초연금 지급이 재개됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 22, 'https://www.129.go.kr/faq/faq00.do?pageIndex=7#faq13741', '6e3ff84eb06f1963984752bc977bf077b0826eb6e1f2287ebbaad46c2dbf9558'),
('13958', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금은 누가 받을 수 있나요?', '기초연금은 대한민국 국적을 가지고, 「주민등록법」 제6조 제1호, 2호에 따른 거주자로 주민등록된 65세 이상인 자로 소득인정액이 선정기준액 이하인 분들께 지급하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-23', 9, 'https://www.129.go.kr/faq/faq00.do?pageIndex=7#faq13958', 'd855193b4867f9a19ff7ad91600a2c6da1a34b64ba3c24e120dd043a94a0bfb1'),
('13959', 'faq129-20261010', '인구아동', '기초연금사업', '공무원연금을 받고 있는데 기초연금 받을 수 있나요?', '공무원, 사립학교교직원, 군인, 별정우체국직원 등 직역연금의 수급권자와 그 배우자는 원칙적으로 기초연금을 지급하지 않고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 13, 'https://www.129.go.kr/faq/faq00.do?pageIndex=7#faq13959', '456bd30552291b75c096699e80f3e0b01d4c429671237d4a99e04771552d73f3'),
('15099', 'faq129-20261010', '인구아동', '기초연금사업', '외국인과 외국국적인 배우자는 기초연금을 신청할 수 있나요?', '기초연금은 외국인의 경우 대한민국 국적 요건을 충족하지 못해 신청이 제한되며, 대한민국 국민과 결혼한 외국국적의 배우자는 혼인신고 후 국내 체류기간이 2년이 경과하지 않은 경우에는 기초연금을 신청할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-23', 14, 'https://www.129.go.kr/faq/faq00.do?pageIndex=7#faq15099', '34252cbfde664283a95e767180f8925e67fd52bdc08fd8fe40633f08cadded1b'),
('15359', 'faq129-20261010', '인구아동', '기초연금사업', '주택(농지)연금을 수령하는 경우 그 수령액과 해당주택(농지)의 재산 산정은 어떻게 하나요?', '주택(농지)연금 수령액은 재산담보부 금융부채의 성격이므로 소득으로 산정하지 않고, 주택(농지)연금 수령액 누계를 부채로 산정합니다.

그리고 주택(농지)연금 수령 중인 주택(농지)은 일반재산에 포함해서 월 소득인정액을 산정합니다.

예를 들어 주택(농지)연금에 가입하여 매월 60만원씩 1년째 주택(농지)연금을 지급받고 있는 수급권자가 기초연금을 신청한 경우, 신청 시까지 수령한 주택(농지)연금액 누계(60만원 ×12개월)를 부채로 산정하고, 수급자 선정 이후에는 매월 지급받는 주택(농지)연금액을 부채로 산정합니다

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-23', 8, 'https://www.129.go.kr/faq/faq00.do?pageIndex=7#faq15359', 'a6bb0c10958ce9dbb0f00cf89dd2a45e3e4c46d4291452a7bf091ad940856970'),
('15360', 'faq129-20261010', '인구아동', '기초연금사업', '영주권 취득 후 재외국민용 주민등록을 한 만 65세 이상 노인은 기초연금을 신청할 수 있나요?', '국외이주한 자는 기초연금을 수급할 수 없습니다.(기초연금법 제17조제2항)

영주권 혹은 장기체류 자격을 포기한 후 국내에 영주귀국신고를 완료한 자에 한해 기초연금 신청 대상이 됩니다.

※ 국외로 이주한 자란? 영주권 혹은 외국에 장기체류할 자격을 취득한 자

「주민등록법」 일부개정으로 대한민국 국민으로서 외국의 영주권을 취득한 자 또는 영주할 목적으로 외국에 거주하고 있는 재외국민이 국내에 30일 이상 거주 목적으로 입국하는 경우 주민등록이 가능하며, 이때 ‘재외국민용 주민등록증’을 발급하고 있습니다.

그러나 이 경우는 재외국민의 국내 경제활동 등을 위한 편의를 제공하기 위해 주민등록증을 발급해주는 것이며 국외이주를 포기한 것은 아니므로 해당 어르신은 기초연금을 신청할 수 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-23', 10, 'https://www.129.go.kr/faq/faq00.do?pageIndex=7#faq15360', 'f1aea039c76457b187e2b7dc3f6d539f789c2f5cc79067b418f02bd61b944d32'),
('16782', 'faq129-20261010', '노인장애인', '장애인복지사업', '65세 미만 장기요양 등급자도 최중증발달장애인 통합돌봄서비스 신청이 가능한가요?', '18세 이상~65세 미만의 지적·자폐성 장애인을 대상으로 하는 최중증발달장애인 통합돌봄서비스는 「노인장기요양보험법」 제2조제1호에 따른 노인 등*에 해당하는 경우에는 서비스 대상에서 제외됩니다

* 65세 이상의 노인 또는 65세 미만의 자로서 치매.뇌혈관성 질환 등 노인성 질병을 가진 자

따라서 65세 미만이더라도 노인 등에 해당하여 장기요양등급을 받은 경우 신청대상에서 제외됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 98, 'https://www.129.go.kr/faq/faq00.do?pageIndex=7#faq16782', '088e7d423fcad4080120258b588979c39c260d975901e255d2fb559fec11a0ab'),
('18588', 'faq129-20261010', '인구아동', '기초연금사업', '교정시설에 수용되는 경우 지급받던 기초연금은 어떻게 되나요?', '기초연금은 금고 이상의 형을 선고받고 교정시설 또는 치료감호시설에 수용되어 있는 경우 기초연금 지급을 정지합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 1, 'https://www.129.go.kr/faq/faq00.do?pageIndex=7#faq18588', '18de03470126b9408566e48bef20e2d432ab048862e49c88a1319df0b8187d73'),
('18602', 'faq129-20261010', '인구아동', '기초연금사업', '개인사업자의 사업소득은 어떻게 소득 반영되나요?', '기초연금에서 기타사업소득은 ­소득세법­ 제19조에 따른 도­소매업, 제조업, 기타 사업에서 얻는 소득을 말하며 국세청 종합소득 자료 중 사업소득 금액이 있는 경우 이를 우선 반영합니다.

다만, 동일사업장에서 사회보험 소득자료와 국세청 소득자료가 동시에 조회되는 경우에는 사회보험 소득자료를 우선하여 ‘사업소득’으로 반영합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-23', 2, 'https://www.129.go.kr/faq/faq00.do?pageIndex=7#faq18602', 'b146fd3dece2a7dc2fdcbb0e842dd7019f6b2331982d18eaa2b366d26fec5a2f'),
('18623', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 수령 중 해외체류하는 경우 계속 지급받을 수 있나요?', '기초연금 수급자는 국외 체류기간이 60일 이상 지속되는 경우 국외체류기간 60일이 속하는 달의 다음달부터 입국일이 속하는 달까지 지급정지 됩니다.

지급이 정지된 이후 국내에 입국하여 기초연금을 다시 받고자 하실 경우 변경신고 하시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-23', 0, 'https://www.129.go.kr/faq/faq00.do?pageIndex=7#faq18623', 'd063d47561d1bad6123fe405edd5c8f6d35e803942a01a468680d68bea21c98c'),
('18624', 'faq129-20261010', '인구아동', '기초연금사업', '부부 중 한명이 기초연금 수령 중이고 배우자가 연령 도래하면 신청해야하나요?', '기초연금 기 수급자의 배우자가 65세에 도달하면 기초연금을 신청해야 지원 받을 수 있습니다.

연령도래 시 최초 신청과 동일하게 배우자의 ‘금융정보 등(금융­신용­보험정보) 제공 동의서’ 및 관련 서류를 구비하여 가까운 주민센터나 전국 국민연금공단 방문 신청 또는 복지로 웹사이트(http://www.bokjiro.go.kr)에서 온라인 신청 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-23', 0, 'https://www.129.go.kr/faq/faq00.do?pageIndex=8#faq18624', '7e45af966261bb678908b59d1be672f8017663c059545f184b112019d69302da'),
('1518', 'faq129-20261010', '인구아동', '기초연금사업', '부모님의 주민등록 주소지가 서로 다른 경우 기초연금 신청은 어디로 하나요?', '기초연금은 주소지를 달리하는 부부인 경우에도 전국 읍면동 주민센터(행정복지센터) 또는 국민연금공단 지사로 신청 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 4158, 'https://www.129.go.kr/faq/faq00.do?pageIndex=8#faq1518', 'd65e04391b3eb054dba6510552d0cb23f7dcffb89627b095d56934caa4469beb'),
('1520', 'faq129-20261010', '인구아동', '기초연금사업', '사회복지시설 입소자도 기초연금 신청 및 지급이 가능한가요?', '기초연금은 만 65세 이상인 대한민국 국적자로 소득과 재산이 일정 수준 이하인 분들에게 지급하는 제도로서 사회복지시설 입소는 연금지급에 대한 고려사항이 아닙니다.

따라서 조건이 충족되면 사회복지시설 입소 여부와 관계없이 기초연금을 신청·지급 받을 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 2724, 'https://www.129.go.kr/faq/faq00.do?pageIndex=8#faq1520', '5761b2d5e67e561cec05dd0320aba1faf6b821a2f74acee3b48e56ee33b54c96'),
('1579', 'faq129-20261010', '인구아동', '기초연금사업', '국외체류 중에도 기초연금 신청 가능한가요?', '국외체류 중에도 65세 이상의 한국 국적을 가지고 주민등록이 있는 어르신은 온라인 및 대리신청을 통해 기초연금을 신청하실 수 있습니다.

다만, 국외 체류기간이 60일 이상이면 체류 목적과 의도와 관계없이 신청이 제한됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 1538, 'https://www.129.go.kr/faq/faq00.do?pageIndex=8#faq1579', 'de2cda7e96c9815865045452910503ec3ed685b2aca5311a5d8339a8ef7c2e06'),
('1583', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금을 신청하면 언제 결과를 확인할 수 있나요?', '기초연금 수급자격 결정을 위한 소득과 재산조사는 신청일로부터 30일(조사에 시일을 요하는 경우 60일)이내 결과에 대해서 통지됩니다.

결정통지가 지연되더라도 기초연금대상자로 선정이 되면 기초연금은 신청일이 속한 달(사전신청의 경우는 생일이 속한달)을 기준으로 지급합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 26970, 'https://www.129.go.kr/faq/faq00.do?pageIndex=8#faq1583', '5aa3cfca0c7f1c46764575898aa0877511978160292dbac7038f3761786fb65b'),
('1593', 'faq129-20261010', '인구아동', '기초연금사업', '무료임차소득이란 무엇인가요?', '무료임차소득이란 1촌 이내의 직계비속이 소유하는 고가주택(시가표준액 6억원 이상)에 거주하는 본인 또는 배우자에 대하여 임차료에 상응하여 소득으로 인정하는 금액입니다.

본인 또는 그 배우자의 주민등록상 주소지의 주택이 1촌 이내의 직계비속인 자녀 명의의 시가표준액 6억원 이상의 주택인 경우 해당 주택 시가표준액의 연 0.78%를 무료임차소득으로 부과합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 4428, 'https://www.129.go.kr/faq/faq00.do?pageIndex=8#faq1593', '02fd3457602d97ebd4fcd0dc7ed82ed3609e5c28e563841b60d417e2bf1471cb'),
('1594', 'faq129-20261010', '인구아동', '기초연금사업', '장애인이 소유한 자동차 차량가액이 4000만원 이상인 경우 기초연금 지원이 가능한가요?', '기초연금은 「장애인복지법」에 따라 등록한 장애인이 소유한 자동차 1대에 한하여 재산에서 제외하고 있습니다. 따라서 고급자동차라고 하더라도 장애인이 소유한 차량은 재산에서 제외됩니다.

다만, 2대 이상 소유 시 1대를 제외한 나머지 차량은 재산산정하여 반영됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 11192, 'https://www.129.go.kr/faq/faq00.do?pageIndex=8#faq1594', '011bf87955c66ac0c11d95d3548c906d8b2a05c41e0aa2b6daea59279409cf16'),
('1602', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 신청자의 마이너스 통장도 부채로 인정가능한가요?', '기초연금 재산산정시 한도대출(마이너스 통장)에 대하여는 소득인정액 산정 시 부채로 인정되지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 3418, 'https://www.129.go.kr/faq/faq00.do?pageIndex=8#faq1602', 'e42c980a12c3f6f545dfdcfd87fc14c74c737fe54d2568787467e421e8a23759'),
('1595', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 신청자가 가입한 보험도 재산으로 포함 되나요?', '기초연금 재산산정시 보험은 보험계약자 명의가 신청자 및 배우자인 경우 해약 시 지급받게 될 환급금 또는 최근 1년 이내 지급된 보험금을 금융재산으로 산정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 2914, 'https://www.129.go.kr/faq/faq00.do?pageIndex=8#faq1595', '668758bf8581a6f7ff5663503ab5935c02e4edf7b0803f6c5788cd5d70a02215'),
('1599', 'faq129-20261010', '인구아동', '기초연금사업', '분양권도 기초연금 신청 시 재산으로 반영되나요?', '기초연금 재산 산정시 신청인이 보유한 분양권도 재산에 포함이 됩니다.

조사일 현재까지 납부된 계약금, 중도금 등을 일반재산으로 반영합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 3148, 'https://www.129.go.kr/faq/faq00.do?pageIndex=8#faq1599', '8d056b339c0691290d59c87f549a0f3602c244610a444e208e85f3d6841a2601');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('1603', 'faq129-20261010', '인구아동', '기초연금사업', '사망한 남편명의 집도 재산으로 산정하나요?', '기초연금 재산산정시 사망자의 미등기 재산은 일차적으로는 「민법」상 지분대로 재산을 산정하되, 상속등기가 되지 않아 상속지분이 유동적이므로 신청자(수급자)가 납세의무자 기준으로 재산 산정을 원하는 경우 납세의무자 기준으로 재산산정할 수 있습니다.

미등기 재산의 납세의무자를 신청자(수급자) 외 타인으로 변경한 경우 재산산정에서 제외합니다.

단, 추후 본인상속지분 등기가 확인될 시에는 재산산정 제외 시점으로 소급하여 재산산정에 포함하여 재계산처리 될 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 2093, 'https://www.129.go.kr/faq/faq00.do?pageIndex=9#faq1603', '916902c2d094565e880a8ddfa358500db3feedfcd8ffb616e623fb8b31318e4b'),
('1634', 'faq129-20261010', '인구아동', '기초연금사업', '일용직 근무 중 산재로 인한 휴업급여는 소득으로 반영되나요?', '「산업재해보상보험법」 에 의한 보험급여 중 휴업급여는 공적이전 소득에 포함되나, 산재급여 발생 원천이 근로소득 산정에서 제외하는 일용근로, 공공일자리, 자활근로로 인한 산재급여(휴업급여)인 경우는 공적이전소득에서 제외합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-23', 5106, 'https://www.129.go.kr/faq/faq00.do?pageIndex=9#faq1634', '6638bb1ce777b469ab8fe272c1e8556d57982c57b96070eabb20627662f55eb2'),
('2889', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 기저귀 바우처 지원대상이 어떻게 되나요?', '기저귀 지원대상은 다음과 같습니다.

○ 만2세 미만의 영아를 둔 아래 기초생활보장, 차상위계층, 한부모가족 수급 가구 대상으로 영아별로 지원(예/쌍둥이·삼둥이 등의 경우 각각의 아동별로 지원)

- 국민기초생활보장법 상 생계·의료·주거·교육급여 수급 가구

- 차상위 본인부담경감 대상 가구

- 자활사업에 참여하는 차상위 가구

- 차상위 장애인 수당·연금 수급 가구

- 차상위계층확인서 발급 대상 가구

- 한부모가족지원법에 의한 지원 대상 가구(청소년한부모가족 포함)

○ 만2세 미만의 영아를 둔 기준중위소득 100% 이하의 장애인 가구

- 부 또는 모 또는 영아가 일반장애인으로 등록된 가구 대상 영아별로 지원

○ 만2세 미만의 영아를 둔 기준중위소득 100% 이하의 다자녀(2인이상) 가구

- 2인 이상 다자녀 가구 내 2세 미만 영아별로 지원

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 5473, 'https://www.129.go.kr/faq/faq00.do?pageIndex=9#faq2889', '213d3ae7867aa9b415735e7b95cfcbeec56f0fbb6bb949138286d400db6222d2'),
('4970', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 정부 체외수정, 인공수정 시술 지정 병원은 어디에서 확인할 수 있나요?', '정부 체외·인공수정시술 지정병원 현황은 보건복지부 홈페이지와 건강보험심사평가원 홈페이지, 임신육아종합포털 아이사랑 홈페이지에서 확인 가능합니다.

[확인경로]

* 보건복지부홈페이지 > 정보공개 > 사전정보공표 > 인구정책 > 인구출산 검색창에서 ''난임시술''로 검색

* 건강보험심사평원홈페이지 > 의료정보 > 특수운영기관 정보 > 난임시술

* 임신육아종합포털 아이사랑 홈페이지 > 임신 > 난임 > 정부지정 난임 시술기관

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 3073, 'https://www.129.go.kr/faq/faq00.do?pageIndex=9#faq4970', '0b30a292c23d4456dc30186117755ee459907fc02c5471591518b1a1a11f4035'),
('6322', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 사실혼 부부 중 한 사람만 건강보험 가입자인 경우 지원이 가능한가요?', '난임부부 시술비 지원사업은 사실혼도 부부 모두 건강보험 가입 및 보험료 고지 여부가 확인되어야 합니다.

다만, 국가유공자로서 건강보험가입의무자가 아니거나 의료급여 수급자인 경우 예외적으로 지원 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 769, 'https://www.129.go.kr/faq/faq00.do?pageIndex=9#faq6322', '235b75bae407393cb1e33c7bf841e24e7e6ea1295d52d2018759fd984981808e'),
('6323', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 부부가 외국인이고 건강보험가입자인 경우 건강보험 적용을 위해 보건소에서 사실혼 확인을 받을 수 있나요?', '건강보험적용을 위한 사실혼 확인은 부부 중 1인은 한국국적 및 건강보험가입자인 경우 사실혼 확인절차를 통해 ''난임부부 시술비 지원결정통지서''가 발급됩니다.

따라서 부부 모두 외국인인 경우 건강보험 가입자라 하더라도 사실혼 확인 및 지원결정통지서 발급은 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 1746, 'https://www.129.go.kr/faq/faq00.do?pageIndex=9#faq6323', '192b0b4cc62c8f46a359ccaa0e1903d13fe19bd13b800ec41e6269e1b9233136'),
('6324', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 지원을 받은 적이 있던 자가 재혼 후 난임부부 신청 시 신규와 동일하게 서류를 제출해야 하나요?', '재혼한 난임부부가 난임지원 신규 신청하는 경우, 난임진단서 포함하여 신규와 동일하게 서류를 제출해야 지원 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 1002, 'https://www.129.go.kr/faq/faq00.do?pageIndex=9#faq6324', 'fe71132d1d8967e6e4a81f8a448e4f295524deb8b7e0387b17027439c5a5b2da'),
('6690', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 난임부부에 대한 정부지원 외 민간단체지원 정보가 궁금합니다.', '민간단체 난임부부 지원사업은 다음과 같습니다.

- 기관명 : (사)한국난임가족연합회 : 02-3431-3382

- 사업내용 : 난임예방교육, 난임극복교육 등

- 난임상담 : 1899-1806(www.agaya.org)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 1144, 'https://www.129.go.kr/faq/faq00.do?pageIndex=9#faq6690', '5336388ef9945668765c903359b70218523777ff8e9c94f5331ee71dfac13e61'),
('6850', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 시술과정 중 원외약처방을 받은 경우에도 지원 가능한가요?', '난임부부 시술비 지원은 시술과 직접적 관련이 있는 원외약처방을 받은 경우 처방전과 약제비영수증 등 제출시 일부 본인부담금, 비급여(전액본인부담금 포함) 약제비에 대하여 정부지원금액 한도 내에서 지급 가능합니다.

- 시술비 지급은 시술 완료 후 관련서류(청구서, 체외수정 또는 인공수정 시술확인서 사본1매, 원외약처방전 및 영수증, 시술자 본인의 계좌사본)를 첨부하여 1개월 이내에 관할 보건소로 청구

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 1017, 'https://www.129.go.kr/faq/faq00.do?pageIndex=9#faq6850', '6b041deb3d0e3b0a8c33150dd4be829a5bfc3f80f915c71aa09f65e9ba5422a9'),
('7170', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 법적 혼인상태로 1년 이상 되어야 지원 가능한가요?', '난임부부 시술비 지원은 법적 혼인상태로 1년 이상이 되지 않더라도 난임시술 지정 의료기관에서 발급한 난임진단서를 제출하면 지원 가능합니다.

다만, 정액검사•배란기능•자궁강 및 난관검사 결과 의학적 소견상 모두 정상으로 진단된 경우, 다음과 같이 원인불명 난임으로 진단할 수 있는 의학적 기준 가이드라인을 정하고 있습니다.

[체외수정 시술 의학적 기준 가이드라인]

- 원인불명 난임 : 3년 이상 임신이 되지 않은 경우. 단, 부인연령이 35세 이상인 경우 1년 이상 임신이 되지 않은 경우.

[인공수정 시술 의학적 기준 가이드라인]

- 원인불명 난임 : 1년 이상 자연임신이 되지 않은 경우. 단, 부인연령이 35세 이상인 자는 6개월 이상 자연임신이 되지 않은 경우.

더 궁금한 사항 있으시면 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 2543, 'https://www.129.go.kr/faq/faq00.do?pageIndex=9#faq7170', '3a409776315ac9e78ecfa25ba7807b267b8b39fa06565c3f5ba10d9158371789'),
('11518', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 사실혼 부부의 남편이 건강보험 미가입자인 경우 건강보험 적용을 위한 지원결정통지서 발급이 가능한가요?', '난임부부 시술비 지원이 아닌 건강보험 적용만을 위한 사실혼 지원결정통지서는 부부 중 한 명이 건강보험에 가입되어 있다면 가능합니다.

단, 건강보험 가입자에 한하여 난임시술에 대한 급여 적용이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 521, 'https://www.129.go.kr/faq/faq00.do?pageIndex=10#faq11518', '66d20183ebb617ca22792ad2d3f13cfc9aa13f3f135f3e3ef4aebdbf22b3b64d'),
('11954', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 지원 신청시 정액검사결과서의 유효기간이 별도로 있나요?', '난임부부 시술비 지원 신청시 정액검사결과서의 유효기간은 인공수정 및 체외수정 진단서 진단일 기준 6개월 이내 검사결과서로 인정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 456, 'https://www.129.go.kr/faq/faq00.do?pageIndex=10#faq11954', '4fd88193a8275323fed6b08985d31e275bc385affada5586c0081446b9d20d6d'),
('11974', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 사실혼 부부인 경우 사실혼 확인 서류를 매 회차마다 증빙해야 하나요?', '사실혼 확인에 대한 유효기간은 지원결정통지서 발급일로부터 6개월이므로, 유효기간 내 지원신청 시에는 사실혼 확인 서류를 증빙하지 않아도 됩니다.

다만, 난임부부 시술비 지원대상에 대한 지원결정통지서는 시술비 신청 시마다 발급이 필요합니다.

(* 사실상 혼인관계 인정은 지원신청 접수일 기준으로 확인)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 711, 'https://www.129.go.kr/faq/faq00.do?pageIndex=10#faq11974', 'e4a67df9d0a6d62011247bc9ddd45c530a11f36a686309b3a73d8c97606d7b2e'),
('12021', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 입양특례법에 따라 입양된 아동의 경우 의료급여 자격을 보유하고 있는데 기저귀 및 조제분유 지원신청 가능한가요?', '입양아동이 보유하게 되는 1종 의료급여(특례)는 [의료급여법]상 자격이므로 해당 자격만으로는 기저귀 지원대상에 포함되지 않습니다.

다만, 해당 입양 아동 또는 그 가정이 1종 의료급여(특례) 자격 외에 국민기초생활보장법 상 기초생활보장, 차상위계층, 한부모가족 수급 자격을 보유하거나 기준중위소득 100% 이하의 장애인, 다자녀 가구에 해당하는 경우 기저귀 및 조제분유를 동시에 신청하여 지원받을 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 39, 'https://www.129.go.kr/faq/faq00.do?pageIndex=10#faq12021', '5c25410537b0d359587f5b1522592f49c78c31f0827ef2762130e0ef36ed8370'),
('12022', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 둘째 출산 후 기저귀조제분유 신청시 첫째가 24개월 미만인 경우 첫째도 지원대상에 포함되나요?', '기저귀•조제분유지원은 2인 이상의 자녀를 둔 가구로서 기준중위소득 100% 이하에 해당하는 경우 지원 가능합니다. 따라서 둘째 자녀에 대한 서비스 신청일 기준, 첫째 아이가 만2세(24개월) 미만인 경우 첫째 아이에 대해서도 바우처 지원이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 51, 'https://www.129.go.kr/faq/faq00.do?pageIndex=10#faq12022', '37807c0e711cf3e81f8394ffe519809fb1563c9eb7f6ef8ea4fc5553fdc33acc'),
('13200', 'faq129-20261010', '인구아동', '디딤씨앗통장', '디딤씨앗통장 적립 및 사용계획서는 어디에서 다운받나요?', '디딤씨앗통장 가입시 필요한 디딤씨앗통장 적립 및 사용계획서 서식은 아래 경로를 통해 다운로드 가능합니다.

복지로 홈페이지 - 복지서비스 - 서비스 찾기 - "디딤씨앗통장"으로 검색

- 복지서비스 상세(중앙) 아동발달지원계좌(디딤씨앗통장)지원

- 추가정보 탭 클릭 후 [서식 12호] 디딤씨앗통장 적립 및 사용 계획서 다운로드 후 활용하시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 50, 'https://www.129.go.kr/faq/faq00.do?pageIndex=10#faq13200', 'f2e438f2c38f5f4ff1adbae07ec47d9f52212a095b75798b57d8f3d411d31dfb'),
('13278', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 지원 대상은 누구인가요?', '아래 신청 자격에 모두 충족하는 경우 난임부부 시술비 지원이 가능합니다.

1) 정부지정 난임시술 의료기관에서 발급한 ''난임진단서'' 제출

2) 법적 혼인상태에 있거나, 신청일 기준 최근 1년 이상 사실상 혼인관계를 유지하였다고 관할 보건소로부터 확인된 난임부부(지원신청 접수일 기준)

3) 부부 중 최소한 한 명은 주민등록이 되어 있는 대한민국 국적 소유자(주민등록 말소자, 재외국민 주민등록자는 대상에서 제외)이면서, 부부 모두 건강보험 가입 및 보험료 고지 여부가 확인되는 자

더 궁금한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 30, 'https://www.129.go.kr/faq/faq00.do?pageIndex=10#faq13278', '254f76269f69196c8d94a7242a605d5a1baf487135c75126fa18e6c51dcf7eaa'),
('15060', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 체외수정 5회차에 임신성공하여 ''23.2월 첫째 출산. 현재 둘째 임신 위해 체외수정 8회차 진행중. 이 경우 체외수정 몇 회에 해당하나요?', '2024. 11. 1일부터 난임부부시술비 지원회차가 출산당 적용하게 됨으로써 개정사항 반영한 시술 회차는 둘째아 3회만 반영합니다.

* 체외수정 총 8회 사용 중(첫째아 체외수정 5회 사용, 둘째아 체외수정 3회 사용 중)이었으나, 첫째아 5회를 제외한 둘째아 3회만 반영

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 19, 'https://www.129.go.kr/faq/faq00.do?pageIndex=10#faq15060', 'b1206fe339ba706a59e9a7229e02cdc50d15a99de55746df3d20922b983aa36e'),
('15061', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 출산당 급여인정 횟수의 적용기준은 어떻게 되나요?', '출산당 급여인정 횟수의 적용기준은,

보조생식술 이력있는 여성이 출산(사산* 포함) 후, 2024년 11월 1일부터 보조생식술을 재시행하는 경우 체외수정(신선배아, 동결배아) 20회, 인공수정 5회 횟수가 다시 적용됩니다. 난임 부부 시술비 지원사업도 급여인정 횟수의 적용기준과 같습니다.

* 사산 : 임신 20주 이후 태아 사망으로 임신이 종결된 경우 의미

다만, 위 대상자가 2024년 11월 1일 전에 보조생식술을 재시행한 경우, 체외수정(신선배아, 동결배아) 20회, 인공수정 5회에서 이미 재시행한 횟수를 차감한 횟수가 적용됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 13, 'https://www.129.go.kr/faq/faq00.do?pageIndex=10#faq15061', '66b63eacbdca5713ba6df02f0ef9d4aca9af3074350db323a19ed28d7c72a186'),
('15062', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 24.11월부터 난임시술 지원을 난임부부당 25회에서 출산당 25회로 변경에 대한 개선사항은 어떻게 되나요?', '''24. 11월 시행된 난임부부 시술비 지원 개선사항은

난임시술을 통해 출산 후 추가적인 임신을 원할 경우 기존에 받은 지원 횟수는 전부 차감되며, 새롭게 25회의 기회가 주어집니다. 난임부부시술비 지원사업도 이에 기존에 받은 지원 횟수는 전부 차감되며, 새롭게 25회의 지원 기회가 주어집니다.

(예시1) 인공수정 5회차에 임신·출산에 성공한 A씨는 인공수정 기회가 남지 않아 다음 임신 시에는 상대적으로 건강에 부담이 큰 체외수정 시술로 변경 고려 중

⇒ 난임시술 급여기준이 출산당으로 변경되면서 인공수정 기회도 5회 추가되고, 난임부부시술비 지원사업도 인공수정 5회의 지원이 추가됨

(예시2) 인공수정에 실패하고, 체외수정 18회차에 어렵게 임신·출산에 성공한 B씨는 난임시술 기회가 2회 밖에 남지 않아, 추가 임신 시도가 망설여짐

⇒ 체외수정 기회가 새롭게 20회 제공되어 둘째아 출산을 위한 임신 시도 예정, 난임부부시술비 지원사업도 체외수정20회 지원이 추가됨

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 14, 'https://www.129.go.kr/faq/faq00.do?pageIndex=10#faq15062', '3bc5d2839ad1198bb2b1fdb2e7a0fde2ff19bb1157226d62dc846096df4f71b5');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('15079', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 공난포 발생 등으로 비자발적 난임시술 중단된 경우에도 시술비 지원 가능한가요?', '공난포 발생 등으로 비자발적 난임시술 중단된 경우에도 시술비 지원 가능합니다.

단, 비자발적 난임시술 실패·중단 시 지원은 지원결정통지서 유효기간 내에 시술이 시작된 경우로서 시술시작일부터 난자채취를 시행했으나 ▲공난포만 채취된 경우, ▲성숙한 난자없이 미성숙 난자 또는 비정상 난자만 채취되어 수정 가능한 난자를 획득하지 못한 경우, 시술중단일까지의 시술비용을 지원합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 16, 'https://www.129.go.kr/faq/faq00.do?pageIndex=11#faq15079', 'acd2b138e19ab2e05735c0399ae376925048767fa66fc1d2a55b337e65988d76'),
('954', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 병원에서 발급한 일반 진단서로 지원이 가능한가요?', '난임부부 시술비 지원을 받기 위해서는 모자보건사업안내 지침의 난임 진단서 서식(인공수정시술 또는 체외수정시술 지원신청용)을 사용해야 하며, 정부지정 난임시술 의료기관에서 발급받아 제출해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 1788, 'https://www.129.go.kr/faq/faq00.do?pageIndex=11#faq954', '88acbd96099efbec33a3d909af8a1c522892965945f1322406c69bcc45385467'),
('958', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 해외 거주로 건강보험 자격이 정지된 자가 시술을 위해 입국한 경우 신청 가능한가요?', '난임부부 시술비 지원사업은 부부 모두 건강보험 가입 및 보험료 고지 여부가 확인되어야 신청 가능합니다.

따라서 입국 후 건강보험 자격취득 및 보험급여 정지 해제 처리 후 첨부 서류를 모두 제출할 수 있다면 난임지원 신청 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 3936, 'https://www.129.go.kr/faq/faq00.do?pageIndex=11#faq958', 'c6a99d8801c770ab35d2c80a1e6509922e55145b38ce07fccf89c78e22a29cdf'),
('926', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 부부 중 한 명이 해외 체류 중인 경우 지원 가능한가요?', '난임부부 시술비 지원사업은 부부 모두 건강보험 가입 및 보험료 고지 여부가 확인되어야 합니다.

따라서 국내 입국하여 건강보험 급여 정지 해제 처리 후 고지된 보험료가 확인되고 신청 자격에 부합한다면 지원 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 1546, 'https://www.129.go.kr/faq/faq00.do?pageIndex=11#faq926', 'f8e6eea206427403530cf0a2c6442558336fa6cba655f9d7df1ce9ede5492420'),
('965', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 부부 주소지가 다른 경우 신청은 어느 보건소로 하나요?', '난임부부 시술비 지원사업은 부인 주소지 관할 시·­군·­구 보건소에 신청해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 1999, 'https://www.129.go.kr/faq/faq00.do?pageIndex=11#faq965', 'e90dff105ccc04ae6d1bcde5dc3c5e9ef8b6743f59654e8cf8c0411ee1e9f3fc'),
('929', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 1차 지원 신청시 의료급여수급자였다가 2차 지원 신청시 건강보험가입자로 변경된 경우에도 2차 신청시 서류를 제출해야 하나요?', '난임부부 시술비 지원은 회차마다 선정기준에 따른 지원자격을 조사해야 하므로 2차 신청 시 서류를 제출해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 1521, 'https://www.129.go.kr/faq/faq00.do?pageIndex=11#faq929', 'c3bd07bbf0dd038ffa1daebf3fd2caba26906eb5dd044a656cab6797dd315295'),
('967', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 대리 신청이 가능한가요?', '난임부부 시술비 지원 신청은 원칙적으로 난임부부가 신청할 수 있으며, 불가피한 경우 난임부부의 직계존속이나 형제자매가 가족관계를 증빙할 수 있는 서류(가족관계증명서 등)와 신분증 확인 후 대리 신청 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 1233, 'https://www.129.go.kr/faq/faq00.do?pageIndex=11#faq967', '7961023365ac6c75d81e6b488b8deed7fcd7540c145d32d96b11bebd34fd7b21'),
('930', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 오래 전에 난임 1차 지원결정통지서를 발급받고 시술받지 않아 재신청 대상인데 진단서를 다시 제출해야하나요?', '난임 진단서는 1차 신청시 제출한 내용을 최종 지원시까지 갈음합니다. 다만, 신청일 기준 진단서 발급일로부터 10년이 경과하였다면 다시 재발급 받아 보건소에 제출하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 2246, 'https://www.129.go.kr/faq/faq00.do?pageIndex=11#faq930', 'c458c2d0f89c4b984413002a3f2a09866523a190f51eb751566a3617ff1f5799'),
('973', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 냉동배아 보관비용도 지원되나요?', '신선배아 시술에 따른 배아 이식 후 남은 배아, 자궁내막 등 여성의 건강상태가 이식을 하지 못할 상태 및 질병 확인 때문에 배양 배아를 향후 난임 시술 목적으로 배아를 동결, 보관할 필요가 있는 경우 지원합니다.

지원금액은 동결 및 최대 1년까지의 보관비용에 한해 시술당 최대 30만원이며, 동결·보관비를 포함한 지원금은 각 시술별 상한액을 넘지 않아야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 5173, 'https://www.129.go.kr/faq/faq00.do?pageIndex=11#faq973', 'e7eb23890c18f31df6af9603fabbdf9562fe03f47cc1bed4a71f7e9372c58b8a'),
('974', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 난자공여자의 생식세포 채취를 위해 발생된 의료비는 지원 가능한가요?', '난임부부 정부지원금은 시술지원신청자(난임부부)에 한하므로 난자공여자 대한 시술비 지원은 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 1278, 'https://www.129.go.kr/faq/faq00.do?pageIndex=11#faq974', '00480694e0729b717cca648c134bc559aa421296d8c5160839da4222935666c1'),
('976', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 직장 등에서 시술비를 지원받을 경우 지원이 가능한가요?', '난임부부 시술비를 지원받았다면 직장 등에서 지원받은 금액을 제외하고 신청 가능합니다. 단, 지원사업 지원범위와 중복되지 않는 비급여항목 등을 지원받았다면 제외 없이 신청할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 1133, 'https://www.129.go.kr/faq/faq00.do?pageIndex=12#faq976', '43bf31ff6c43920731ae126ed95d2bab7bc911701c99419f7f5b4f71a0f4d239'),
('1022', 'faq129-20261010', '인구아동', '출산정책', '(기저귀­조제분유)기저귀 조제분유 지원 바우처 잔액이 있는데 결제가 안 되는 경우, 어떻게 해야 하나요?', '기저귀조제분유 지원 바우처 잔액이 있음에도 불구하고 결제가 되지 않은 경우는 다음과 같은 사유가 있습니다.

① 기저귀 또는 조제분유 그 외 다른 물품을 구매한 경우

② 바우처 결제가 아닌 일반 결제를 선택한 경우

③ 바우처 잔액보다 초과 결제하여 연동된 계좌에 잔액이 부족한 경우

④ 결제시 배송비가 발생되어 연동된 계좌에 잔액이 부족한 경우

⑤ 정보원과 카드사간 잔액 전송과정에 누락이 발생한 경우 등

①~④에 해당하는 경우 사유에 따라 재확인 후 결제 부탁드리며, ⑤의 경우에는 바우처사업콜센터(1566-3232, 내선4) 또는 카드사 콜센터(BC카드 1899-4651 및 각 은행 콜센터, 롯데카드 1899-4282, 삼성카드 1566-3336, KB국민카드 1599-7900, 신한카드 1544-8868, 현대카드 1577-6000)를 통해 바우처 잔액 확인 요청을 해주시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-22', 3205, 'https://www.129.go.kr/faq/faq00.do?pageIndex=12#faq1022', '512bf320153c3eef3ff9ff8f6f9961e40e38854a5fe4b0c92322aaefd90b1b3b'),
('16320', 'faq129-20261010', '보건의료', '건강보험정책', '재난적의료비 지원사업은 소득 기준이 있나요?', '재난적의료비지원사업의 가구의 소득수준은 가구원수에 따라 월 건강보험료로 판정하며, 가구의 소득이 기준중위소득 100% 이하인 가구를 지원합니다.

예외적으로 기준중위소득 100% 초과 200% 이하인 가구는 의료비 부담이 큰 경우 개별심사 대상으로 지원합니다.

* 기초생활 수급자와 차상위계층은 지방자치단체 등에서 저소득층으로 확인된 가구이므로 소득기준을 적용하지 않음. (다만, 「의료급여법」제3조제1항제2호부터 제10호까지에 따른 의료급여 수급자에 해당하는 경우 건강보험 가입자와 동일하게 심사)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-21', 297, 'https://www.129.go.kr/faq/faq00.do?pageIndex=12#faq16320', 'bdcaaaf8553bf0d61caa1666348b9c7ef526e479d7f81fb8f9bb1debe7fc3566'),
('18563', 'faq129-20261010', '보건의료', '건강보험정책', '재난적의료비 지원사업은 2.3인실 입원료가 지원이 되나요?', '26년 6월 30일 이전 진료 건은 병원 2.3인실 입원료를 지원하나, 26년 7월 1일 이후 진료 건부터 7대 중증질환으로 발생한 병원 2.3인실 입원료에 대해서 지원합니다.

* 7대 중증질환: 암, 심장, 뇌혈관, 중증난치 및 희귀, 중증화상, 중증외상

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-21', 32, 'https://www.129.go.kr/faq/faq00.do?pageIndex=12#faq18563', 'a1de911d81ebbded5b1c238289e4a19d09680c0ab11b8ab5672c3613b05415d3'),
('3341', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 기저귀조제분유 온라인 구매시 배송비도 바우처로 결제 가능한가요?', '기저귀·조제분유를 옥션, G마켓 등 온라인 사이트를 통한 구매 시 발생하는 배송비는 바우처로 결제할 수 없으며, 본인부담금으로 결제됩니다. 발급받으신 국민행복카드가 체크카드이고 해당 카드와 연계된 계좌 잔액으로 배송비를 결제할 수 없는 경우 바우처 결제가 불가능하오니 사용에 유의하여 주시기 바랍니다

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2026-09-15', 1741, 'https://www.129.go.kr/faq/faq00.do?pageIndex=12#faq3341', '01f666361a5b8eb72a24c792b31ac063b1378c9d08d398b3c377dafcafcfce0c'),
('5630', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 기저귀 조제분유 지원사업은 온라인 신청이 가능한가요?', '기저귀 조제분유 지원사업은 온라인(복지로(www.bokjiro.go.kr) 또는 정부24(www.gov.kr) 행복출산원스톱서비스)에서 신청 가능합니다.

* 단, 복지로는 기저귀 지원 신청만 가능

또한, 아래와 같이 온라인 신청이 불가능한 가구는 영아의 주민등록 주소지 관할 보건소나 읍면동 주민센터로 방문신청 해주시기 바랍니다.

(온라인 신청이 불가능한 가구)

- 대상 아동의 부모 중 한 명이라도 만 19세 미만인 경우

- 가구원 간 주소지가 다르거나 조손 세대인 경우

- 부모중 외국국적의 가구원이 있는 경우

- 가족관계 확인이 필요한 경우

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 1523, 'https://www.129.go.kr/faq/faq00.do?pageIndex=12#faq5630', '58adf793113955c779dd320525afaedf52c296a352ca45c4f8d8f6dc68649ed1'),
('6318', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 영양플러스사업으로 분유지원을 받고 있는데 조제분유 지원을 같이 받을 수 있나요?', '조제분유 지원은 기저귀 지원대상 중 산모의 사망·질병 등으로 모유수유가 불가능한 경우 신청할 수 있습니다.

다만, 영양플러스사업의 조제분유 지원과 중복지원은 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 776, 'https://www.129.go.kr/faq/faq00.do?pageIndex=12#faq6318', 'f724e7df0cf1f48501fa91b1500d486ff2ab5a6577b7e20fd2b20e9550824858'),
('6319', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 기저귀지원은 3개월마다 바우처가 생성된다고 합니다. 해당 분기에 사용 못하면 소멸되나요?', '3개월마다 생성된 바우처는 해당 분기에 사용하지 못하더라도 이월되며 바우처 지원기간동안 사용 가능합니다.

*소득, 가구원 등 변동사항 발생시 14일 내 보건소로 신고필요

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2026-09-15', 2289, 'https://www.129.go.kr/faq/faq00.do?pageIndex=12#faq6319', 'e00a8d9d6da5f0a22087874047e0844b8dbb4a9a6da03aebaf480f02c458ea42'),
('6990', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 외국인 아동도 지원받을 수 있나요?', '기저귀 조제분유 지원은 국내에 외국인 등록을 한 2세 미만 영아로서 부모 중 어느 한 쪽이 대한민국 국적을 가진 경우에 한해 지원합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 1030, 'https://www.129.go.kr/faq/faq00.do?pageIndex=12#faq6990', 'c51d1ed1050350b0eae5419dfd978da150bbbdd0448a5e01d3d787a04d837f47'),
('8396', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 영아의 어머니가 귀화하여 변경된 주민등록번호로 카드를 재발급 받았습니다. 어떻게 해야 하나요?', '기저귀·조제분유 지원신청 당시의 주민등록번호가 아닌 변경된 주민등록번호로 카드를 재발급 받은 경우, 바우처 사용이 불가합니다.

영아의 주민등록주소지 관할 보건소(또는 주민센터)를 방문하시어 주민등록번호 변경 신청을 해주셔야 사용이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 609, 'https://www.129.go.kr/faq/faq00.do?pageIndex=12#faq8396', '79335cff1ef460638f0101d30d0a0f22ee743869dcc217382104557805836e95');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('8415', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 조제분유 지원대상인 경우 이유식도 구입 가능한가요?', '조제분유지원은 축산물 위생관리법(조제분유), 식품위생법(조제식)에 따라 제조, 유통중인 물품에 대해 구매 가능합니다.

단, 죽 형태의 이유식(기타 영유아식) 등은 위 조제이유식에 포함되지 않아 결제가 불가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 430, 'https://www.129.go.kr/faq/faq00.do?pageIndex=13#faq8415', '22af7fe3065af28ca360e77f9cf0d22ca5613695c58464238956f232c9924a93'),
('10514', 'faq129-20261010', '인구아동', '출산정책', '(첫만남이용권) 첫만남이용권 사용 중인데 잔액 확인은 어떻게 하나요?', '첫만남이용권 바우처 잔액 확인은 사회서비스 전자바우처 포털 (http://www.socialservice.or.kr)에서 바우처 생성내역 확인 가능(생성일로부터 3~5일 이후)하며, 본인의 지원금(포인트)잔액 및 사용내역은 전담금융기관(국민행복카드 카드사)에서 확인 가능합니다.

또한 카드사별로 관리되므로 사용하는 카드사를 통해 알림톡 서비스를 신청하거나 카드사에 잔액 등 안내서비스가 있는지 확인 후 이용바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 5653, 'https://www.129.go.kr/faq/faq00.do?pageIndex=13#faq10514', 'cca7e42bf266320280cbf4a50592ee553b74b44a55a8b19b37dbaaa21a30fa16'),
('10518', 'faq129-20261010', '인구아동', '출산정책', '(첫만남이용권) 기저귀 바우처와 같이 지급을 받았는데 결제를 어떻게 해야하나요?', '바우처 동시 수급시, 각 물품을 각각 결제해야 바우처 차감 가능합니다.

기저귀 바우처로 사용 원할시 기저귀 품목만 구입 후 결제하면 기저귀 바우처로 사용처리 됩니다.

아래 예시 참고하여 사용바랍니다.

< 중복수혜 대상자 결제 유형별 예시>

사례 1 |
판매점에서 기저귀(또는 타 바우처) 2만원 구입(결제) 시

- (기저귀 바우처 잔액 1만원인 경우) 기저귀 바우처 1만원 차감 후, 초과 분 1만원 개인부담

- (기저귀 바우처 잔액 0원인 경우) 첫만남이용권 2만원 차감(초과 분 개인부담) |

사례 2 |
판매점에서 기저귀(또는 타 바우처) 2만원과 생필품 1만원 동시에 구입(결제) 시

- (기저귀 바우처 잔액 2만원인 경우) 기저귀 바우처 2만원 차감 후, 생필품 1만원은 개인부담

※ 기저귀 2만원, 생필품 1만원을 각각 결제하는 경우 생필품 1만원은 첫만남이용권에서 차감가능

- (기저귀 바우처 잔액 0원인 경우) 첫만남이용권으로 기저귀, 생필품 3만원 차감(초과 분 개인부담) |

사례 3 |
판매점에서 생필품 3만원 구입(결제) 시

→ 기저귀 바우처 유무에 관계 없이 첫만남이용권으로 생필품 3만원 차감(초과분 개인부담) |

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2026-09-15', 866, 'https://www.129.go.kr/faq/faq00.do?pageIndex=13#faq10518', '93d87d6662da8a8df1078d2f3594f20fc6409ef4e4391ceb60492af58e7f0dab'),
('11156', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 기저귀 조제분유 지원되는 금액은 얼마인가요?', '저소득층 기저귀·조제분유 지원사업 지원금액은 아래와 같습니다.

< 지원대상별 지원금액>

지원 내용 |
지원유형 |
지원금액(원) |

기저귀 지원 |
가유형 |
90,000 |

기저귀+조제분유 지원 |
나유형 |
200,000 |

조제분유 추가 지원 |
다유형 |
110,000 |

안내된 금액은 월지원액이며, 지원대상으로 결정통보된 날의 익일부터 3개월 단위(3개월분)로 바우처 지급됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 323, 'https://www.129.go.kr/faq/faq00.do?pageIndex=13#faq11156', 'e85a65bf744dc87dc6d73704e09813a7593b9967ebcbc088d071ceb685f5c905'),
('12035', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 기발급된 BC국민행복카드가 2장입니다. 기저귀조제분유 지원을 받으려면 어떤 카드로 결제해야하나요?', 'BC 국민행복카드면 어떤 카드로든 결제 가능합니다.

기저귀•조제분유 지원신청을 통해, 기 발급되거나 발급될 예정인 BC 국민행복카드에 자동으로 기저귀•조제분유 기능이 추가됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 54, 'https://www.129.go.kr/faq/faq00.do?pageIndex=13#faq12035', 'eebd07fae4969950b0ae7230a3be3595258efe037b2ce6a734d721495eb72776'),
('12036', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) BC카드, 삼성카드 두 개의 국민행복카드를 소지하고 있는 경우, 어떤 카드로 결제해야 하나요?', '기저귀조제분유 결제는 BC카드, 삼성카드 모두 병행(바우처 공유)하여 사용할 수 있습니다.

* 카드사별 구매처가 다름

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 87, 'https://www.129.go.kr/faq/faq00.do?pageIndex=13#faq12036', 'ff40176f038f5605c03b7ad4ce75b3195c607279b0690f0cb5f494eb1c2cf11c'),
('12257', 'faq129-20261010', '인구아동', '출산정책', '(첫만남이용권) 첫만남이용권이 무엇인가요?', '첫만남이용권은 출산가정의 생애초기 아동양육에 따른 경제적 부담 경감을 위해 1회에 한하여 지원하는 바우처입니다.

* 첫째아 200만원, 둘째아 이상은 300만원(2024년 기준)

(23년 12월까지는 출생순위 상관없이 동일하게 200만원)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 220, 'https://www.129.go.kr/faq/faq00.do?pageIndex=13#faq12257', 'a28db57d210c415cd81362ba0f13c9699bbe6e0fbe851cf5cbaca1281f155cf2'),
('18482', 'faq129-20261010', '인구아동', '출산정책', '(기저귀­조제분유) 카드사별로 사용 가능한 판매점 확인은 어디에서 가능한가요?', '기저귀조제분유바우처 이용 가능한 판매점 확인은 사회서비스전자바우처 홈페이지에서 확인할 수 있습니다.

https://www.socialservice.or.kr:444/user/htmlEditor/view2.do?p_sn=39

