('1003', 'faq129-20261010', '인구아동', '출산정책', '(기저귀­조제분유) 신청방법은 어떻게 되나요?', '기저귀조제분유 지원 신청은 영아의 주민등록 관할 보건소, 읍­면­동 주민센터 방문 또는 온라인(정부24(www.gov.kr) ‘행복출산원스톱서비스’ 또는 복지로(www.bokjiro.go.kr))으로 신청할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 1026, 'https://www.129.go.kr/faq/faq00.do?pageIndex=13#faq1003', 'b253c093c2b5a0a8bca2af73751e33c5c595392bf52d97530886267305e36621'),
('1006', 'faq129-20261010', '인구아동', '출산정책', '(기저귀·조제분유) 기저귀­조제분유 지원 신청 당일부터 바우처 사용이 가능한가요?', '기저귀조제분유 신청을 했더라도 지원 대상으로 결정 통보된 날의 익일부터(3개월 단위로 바우처 지원) 지원기간 동안 사용 가능합니다.

보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 1135, 'https://www.129.go.kr/faq/faq00.do?pageIndex=13#faq1006', '7ad4e4d0ddf5feabb854e8bbb65627183d538e0fa65e19fcb3c1dbff6621edbc'),
('1007', 'faq129-20261010', '인구아동', '출산정책', '(기저귀­조제분유) IBK기업은행 국민행복카드가 있는데, 국민행복카드를 추가로 발급받아야 하나요?', 'IBK기업은행(BC카드) 등 국민행복카드를 이미 발급받은 분은 국민행복카드 추가발급 없이 기존 국민행복카드로 정부지원금 결제 가능한 구매처에서 결제 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 1295, 'https://www.129.go.kr/faq/faq00.do?pageIndex=14#faq1007', '793a801816678ad6395dde71d4bff0ce9a689b26641e6166c38ea4cba0e8d5a3'),
('1008', 'faq129-20261010', '인구아동', '출산정책', '(기저귀·조제분유) 기저귀 조제분유 결제 가능한 국민행복카드를 분실하고, 재발급 받았는데 바로 사용 가능한가요?', '바우처 카드 재발급 신청 후 실물카드를 받으셨다 하더라도 재발급 신청 정보가 연계되는데 영업일 기준 2~3일 정도 소요되므로 그 이후 사용을 권장합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 1531, 'https://www.129.go.kr/faq/faq00.do?pageIndex=14#faq1008', '71b4f0fea22b4891b6d97130e9e0948ae2f0d4ea73c4eabe568c097978390dd4'),
('1009', 'faq129-20261010', '인구아동', '출산정책', '(기저귀­조제분유)기저귀 지원 대상자인데, 정부지원금으로 조제분유 구매가 가능한가요?', '기저귀만 지원받는 대상자는 기저귀 구매 시에만 정부지원이 가능하며, 국민행복카드로 조제분유 구매 시에는 자동으로 대상자 개인에게 청구되니 유의하시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 1530, 'https://www.129.go.kr/faq/faq00.do?pageIndex=14#faq1009', '2bc66ecd8d547cbd8795eab00466184526df4c4a2651a63a9bfdfdeeb89c4672'),
('1010', 'faq129-20261010', '인구아동', '출산정책', '(기저귀­조제분유) 기저귀와 조제분유를 모두 지원 받는 대상자 입니다. 조제분유 지원금액을 기저귀 구입에 사용해도 되나요?', '기저귀와 조제분유 동시 지원받는 대상자는 지원금액 전부를 기저귀 또는 조제분유 구매에 자유롭게 이용할 수 있습니다.

예를 들어, 기저귀와 조제분유 지원비용은 월 9만원과 11만원이므로 합계 월 20만원 범위 내에서 기저귀와 조제분유를 자유롭게 구매할 수 있습니다.

다만, 지원금액을 초과하여 구매하는 경우 초과분은 대상자에게 직접 청구되니 유의하시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 1471, 'https://www.129.go.kr/faq/faq00.do?pageIndex=14#faq1010', '8c81b7af9ecba0b1859a51dc86831530faed8e328417133bb91b2b480299d6db'),
('1011', 'faq129-20261010', '인구아동', '출산정책', '(기저귀­조제분유) 영아 출생신고를 하지 않았을 경우 기저귀­조제분유 지원 신청이 가능한가요?', '기저귀조제분유 지원 신청은 영아의 출생신고가 반드시 완료되어 주민등록번호 확인이 되어야 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 991, 'https://www.129.go.kr/faq/faq00.do?pageIndex=14#faq1011', '522ec905b6e953b96b5fded68e05d6b987d81a9bed0ea736ed3f9569e8440a3a'),
('1012', 'faq129-20261010', '인구아동', '출산정책', '(기저귀­조제분유) 아동양육시설에서 보호중인 영아에 대해서도 기저귀 조제분유 신청 가능한가요?', '기저귀조제분유 신청권자는 원칙적으로 영아의 부모가 신청권자가 됩니다. 다만, 주양육자가 부모가 아닌 경우에는 영아의 양육을 주로 담당하는자, 즉. 아동양육시설의 시설장 또는 근무자가 신청 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 1401, 'https://www.129.go.kr/faq/faq00.do?pageIndex=14#faq1012', '793912a1b90f93c76fc897f9795c563cf49aabb911b25d2c273d3cae5c487897'),
('1014', 'faq129-20261010', '인구아동', '출산정책', '(기저귀­조제분유) 기저귀 바우처를 지원받고 있는 대상자인데, 신청 당시 보유자격(차상위계층 등)을 상실하였습니다. 어떻게 해야 하나요?', '기저귀바우처 지원을 받는 기간 동안 기초생활보장·차상위계·한부모가족 수급 자격 등에 변동이 있을 경우 14일 이내에 보건소로 신고하여야 합니다.

자격을 상실하였으나 변동에 따른 신고없이 기저귀바우처를 지원받은 경우 ''­사회보장급여의 이용 제공 및 수급권자 발굴에 관한 법률­ 제22조''에 따라 지원금이 환수될 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 2145, 'https://www.129.go.kr/faq/faq00.do?pageIndex=14#faq1014', '9a34afb2d819d6201293a6f0346955e09b18231f37c77cfac9c0c628ee3fbe1e'),
('1016', 'faq129-20261010', '인구아동', '출산정책', '(기저귀­조제분유) 기저귀·조제분유 바우처 포인트가 이용기간이 종료되어 소멸되었습니다. 바우처 포인트를 사용할 수 없나요?', '기저귀·조제분유 지원 사업은 지원대상 영아의 월령(0~24개월) 및 바우처 지급 시가 아닌 지원대상자의 기저귀 등 구매 시에 예산이 집행되는 점 등 예산의 효율적 운영·관리 측면을 고려하여 서비스 이용기간이 종료되는 날의 다음 날부터 바우처가 소멸되며, 이미 소멸된 바우처의 복구 및 재사용은 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 3845, 'https://www.129.go.kr/faq/faq00.do?pageIndex=14#faq1016', 'a811839d56c363fcab568c1c0aaa728f01a71616876834c2babfee13a2e68211'),
('1017', 'faq129-20261010', '인구아동', '출산정책', '(기저귀­조제분유) 기저귀 조제분유 이용기간 종료일 전 안내 메시지를 받아 볼 수 있나요?', '기저귀 조제분유 지원 대상자에게 이용기간 종료일 1~2개월 전 신청당시 등록하셨던 휴대폰번호로 이용기간 만료 안내 메시지(이용기간 종료일 및 바우처 잔액)를 보내드립니다.

등록된 휴대폰번호로 메시지가 전송되므로 이용도중 연락처 변동시 영아의 주민등록 관할 보건소에 변경 신청을 해주셔야 안내받으실 수 있습니다.

다만, 통신 및 연락처 오류. 수신 거부 등의 사유로 메세지가 전송되지 않을 수 있으니, 사회서비스전자바우처 포털사이트(www.socialservice.or.kr)에서 이용기간 종료일을 확인하시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-15', 1183, 'https://www.129.go.kr/faq/faq00.do?pageIndex=14#faq1017', '4a2a5271ebd03e51f2972952084d3895220302fb36e94a6f1a695cd361408027'),
('18402', 'faq129-20261010', '인구아동', '기초연금사업', '부부 모두 수급하는 경우 20% 감액적용하고 소득역전방지 감액도 적용하나요?', '''부부감액''과 ''소득역전방지감액''은 감액의 취지가 각각 다르므로 둘 다 적용합니다.

''부부감액''은 단독가구와 부부가구의 생활비 차이를 감안하여 부부 모두 수급자인 경우 기초연금액에서 20%를 감액하는 것입니다.

반면, ''소득역전방지감액''은 기초연금을 받는 사람과 못 받는 사람 간에 기초연금 수급으로 인해 발생할 수 있는 소득역전을 최소화하기 위해 기초연금의 일부를 감액하는 것입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-11', 12, 'https://www.129.go.kr/faq/faq00.do?pageIndex=14#faq18402', 'f9d3f96f0cda7f42577a4b1b8af3f0fb90d18033241974ccce5a4f7917b1ca42');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('18403', 'faq129-20261010', '인구아동', '기초연금사업', '''소득역전방지 감액''이 무엇인가요?', '''소득역전방지 감액''은 기초연금을 받는 사람과 못 받는 사람 간에 기초연금 수급으로 인해 발생할 수 있는 소득역전을 최소화하기 위해 기초연금의 일부를 감액하는 것입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-11', 4, 'https://www.129.go.kr/faq/faq00.do?pageIndex=15#faq18403', '42cefc9572e5b6b8b0ae2dc0be811d6471f09ce5e5ecb3605d52b37715692f82'),
('18422', 'faq129-20261010', '인구아동', '기초연금사업', '국민연금을 받으면 기초연금은 무조건 감액되나요?', '국민연금을 받는다고 해서 기초연금이 무조건 감액되는 건 아닙니다.

국민연금 급여의 종류는 노령연금, 분할연금, 유족연금, 장애연금, 반환일시금, 사망일시금 등이 있습니다. 이중에서 국민연금과 관련하여 연계 감액되는 수급자는 노령연금과 분할연금 수급자이고, 장애연금과 유족연금은 금액에 상관없이 연계감액이 적용되지 않습니다.

또한, 국민연금의 노령연금과 분할연금 수급자라 하더라도 매월지급 받는 연금액에서 가족수당처럼 지급되는 부양가족연금액을 제외한 금액(국민연금 급여액)이기준연금액의 150%(’26년 기준 524,550원) 이하인 경우도 감액되지 않고 기준연금액 전액을 받습니다.

따라서, 국민연금 연계 감액자는 국민연금의 노령연금과 분할연금 수급자로서 국민연금 급여액이 524,550원을 초과하고, A급여액이 262,270원을 초과하는 2가지 요건을 모두 충족하는 수급자입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-11', 11, 'https://www.129.go.kr/faq/faq00.do?pageIndex=15#faq18422', 'cf952e6fede929300fefac120d5859b38855fa9a363bd34de7c8389223aa5ea8'),
('18423', 'faq129-20261010', '인구아동', '기초연금사업', '직역연금 수급권자와 이혼하여 연금분할청구제도가 적용된다면 기초연금 지급대상에서 제외되나요?', '공무원연금 등 직역연금 수급권자는 기초연금 수급자격에서 제외하지만, 직역연금수급권자와 이혼하여 연금을 분할하여 수급받는 경우 기초연금 신청이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-11', 6, 'https://www.129.go.kr/faq/faq00.do?pageIndex=15#faq18423', 'ef4b7ba82fa55c90a3720e284a7958befb038dfe5c1242dda93293070a000543'),
('18424', 'faq129-20261010', '인구아동', '기초연금사업', '''기초연금 수급희망 이력관리''만 별도 신청할 수 있나요?', '''기초연금 수급희망 이력관리'' 신청은 기초연금 신청시 동시 신청만 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-11', 3, 'https://www.129.go.kr/faq/faq00.do?pageIndex=15#faq18424', '1072f4e539ef5cec1d53563176d194bb69e3796b869fde2cb2af9c0eea147cb1'),
('18442', 'faq129-20261010', '인구아동', '기초연금사업', '''기초연금 수급희망 이력관리'' 제도가 무엇인가요?', '''기초연금 수급희망 이력관리''란,

기초연금 신청 시 수급(권)이 탈락되거나 수급중 탈락한 수급희망자에 대해 정기적인 이력관리를 통해 수급 가능성이 확인되면 별도 신청없이 신청간주로 할 수 있는 제도입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-11', 5, 'https://www.129.go.kr/faq/faq00.do?pageIndex=15#faq18442', 'c7444e0056520ce4e692f25bd31fabb968e84b2eca262a93de2d6f4234166321'),
('18462', 'faq129-20261010', '보건의료', '보건의료정책', '비의료기관에서 의료행위를 한 경우 어떤 처발을 받게 되나요?', '① 의료인이 아닌 자가 의료행위를 한 경우(무면허 의료행위)

- 의료법 제27조제1항 위반으로 5년 이하의 징역이나 5천만원 이하의 벌금 부과 대상입니다.

② 의료기관이 아닌 곳에서 의료행위를 행한 경우

- 의료법 제33조제1항 위반으로 500만원 이하의 벌금 부과 대상입니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2026-09-11', 35, 'https://www.129.go.kr/faq/faq00.do?pageIndex=15#faq18462', 'fc51b67b984cf1bfba7d0c5869db9a647f3c927b298b0b29aa705b56919c8bec'),
('1582', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 선정기준 초과로 탈락 시 다시 신청을 할 수 있나요?', '기초연금 신청 후 소득인정액 초과로 기초연금 대상자에서 탈락하였으나 이후 소득 또는 재산 등이 감소하여 기초연금 수급을 다시 희망하는 경우에는 재신청 가능합니다. 기초연금 재신청 시 시·군·구에서 소득·재산 조사를 통해 수급여부를 다시 결정하게 됩니다.

또한, 기초연금 신청 시 ''기초연금 수급희망 이력관리''를 동시에 신청하면 수급권이 탈락되거나 수급중 탈락한 수급희망자에 대해 정기적인 이력관리를 통해 수급 가능여부를 예측하여 신청 간주로 할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-09-11', 4064, 'https://www.129.go.kr/faq/faq00.do?pageIndex=15#faq1582', '19e9c69a786fc113fd6347ac4e7af4b8f4bc6ee36ced01b1321b67c669bc5a2e'),
('18425', 'faq129-20261010', '인구아동', '기초연금사업', '''기초연금 수급희망 이력관리'' 신청시 부부가구인데 부부 중 한명만 신청할수 있나요?', '''기초연금 수급희망 이력관리'' 신청은 부부가구인 경우에는 부부 모두 ''기초연금 수급희망 이력관리''를 신청해야 합니다.

부부 중 한 명이라도 신청하지 않은 경우 수급희망 이력관리 신청은 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-10', 6, 'https://www.129.go.kr/faq/faq00.do?pageIndex=15#faq18425', '0d30643266115166fe9b45ef8166d9b88e86783215e2691a11992348d7a7e470'),
('18322', 'faq129-20261010', '사회복지', '기초생활보장사업', '디딤씨앗통장 가입액도 기초생활수급자의 재산으로 반영되나요?', '기초생활수급자의 재산 반영 시 금융재산은 다음의 항목을 공제하고 반영하고 있습니다.

① 생활준비금(가구 당 500만원 공제)

② 장기금융저축공제(가구당 연간한도 500만원, 총한도 1,500만원 공제)

③ 「자동차손해배상 보장법」 제30조 및 동법 시행령 제22조에 따른 자립지원 적립금

④ 보건복지부 자산형성지원사업, 디딤씨앗통장 가입기간 중의 통장 가입액

⑤ 시설퇴소 및 가정위탁 종료된 자립준비청년과 가정 밖 청소년의 자립정착금

⑥ 성폭력피해자보호시설 퇴소 청소년의 퇴소자립지원금

따라서 아동이 디딤씨앗통장을 통해 가입한 가입액은 만 24세 도래 전까지 금융재산에서 제외됩니다.

다만, 통장 가입액은 만 18세까지 납입한 금액만 금융재산에서 제외되고 18세 이후 납입한 금액은 금융재산으로 산정됨을 참고해주시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-09', 96, 'https://www.129.go.kr/faq/faq00.do?pageIndex=15#faq18322', '3446cf45baa090ec3c6aec9d59b40bbc4ed2904b1be1d076bb46707494035869'),
('18323', 'faq129-20261010', '사회복지', '기초생활보장사업', '수급자가 지자체로부터 받는 봉사활동비도 소득으로 반영되나요?', '지자체 조례에 따라 예산이 100% 지자체의 부담으로 지급되는 봉사활동비 중 실비지원적* 성격의 금품은 월 40만원 이내에서 공제됩니다.

실비지원적 성격이 아니거나 월 40만원 공제 후 남은 차액은 근로소득으로 산정됩니다.

* 실비지원적 성격 해당 여부는 지자체 조례, 지침 등을 통해 파악

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-09', 66, 'https://www.129.go.kr/faq/faq00.do?pageIndex=15#faq18323', 'cb17ebc89c1b0e168bc536a73f681a244923775475f9c0d1d23cf2e85e0edaa2'),
('9692', 'faq129-20261010', '보건의료', '공공보건정책', '어떤 환자가 부산의 oo응급환자이송업체의 구급차를 이용하여 부산(자택) → 서울(외래) → 부산(자택)으로 이동하였다면 이송처치료 요금은? 이 경우 통행료는?', '부산 출발 → 서울병원에서 대기 → 다시 부산으로 귀가하면서 기본요금은 1번만 청구하고 실제로 환자가 탑승하여 움직인 거리에 대해 이송처치료를 받는 것은 합당하나, 서울에서 출발할 때 기본 요금을 다시 한번 받으면 허가지역 외 영업 또는 부당 추가비용 수취에 해당합니다. 다만, 서울병원에 도착하여 대기하는 때에는 병원 도착 후 30분이 초과한 시점부터 10분 단위로 대기요금을 청구할 수 있으며, 서울 병원을 출발한 시점부터는 다시 이송거리에 따라 추가요금이 부과됩니다.

통행료 역시 받아서는 안 됩니다.

다만, 구급차는 ­유료도로법­ 제15조, 같은 법 시행령 제8조제3항, 같은 법 시행규칙 제5조제7항에 의해 통행료가 100% 감면되므로 각 시·도를 통해 ''긴급면제카드''를 한국도로공사에 신청하면 됩니다.(신고필증, 허가필증 발급 구급차에 한해 신청 가능)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-07', 1281, 'https://www.129.go.kr/faq/faq00.do?pageIndex=16#faq9692', '918ec266f315308458816b29bab2ee33b877506943dce366d948da74a13cee6c'),
('14011', 'faq129-20261010', '보건의료', '건강정책', '아동치과주치의 건강보험 시범사업에 참여할 수 있는 대상은 누구인가요?', '­초등학교 전학년이 대상이나, 시범사업으로 선정된 지역에 한해 실시되기 때문에 선정 지역내 초등학교 재학 아동에 한해 참여가 가능하며, 해당 지역에 주민등록이 되어 있더라도 관할 지역 초등학교에 재학 중이 아닌 경우 참여가 제한됩니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2026-09-07', 63, 'https://www.129.go.kr/faq/faq00.do?pageIndex=16#faq14011', '2fb54366bf9dfad01ad18ecab252454b5e44c27f43cfa072739d929b870cd5c0'),
('9710', 'faq129-20261010', '보건의료', '공공보건정책', 'A병원 구급차가 환자 외래진료를 위해 B병원에 이송하여 대기 후 다시 A병원으로 돌아온 경우 이송처치료 산정기준은?', '환자 이송 시 이송처치료는 「응급의료에 관한 법률」 제24조 등에서 규정하고 있으며, 응급환자 등 이송 시 A병원에서 B병원으로 외래진료를 위해 이동 후 대기하였다가 다시 A병원으로 돌아오는 경우 기본요금은 1번만 청구하고 B병원에 도착하여 대기하는 동안에는 B병원 도착 후 30분이 초과한 때부터 10분 단위로 대기 요금을 청구할 수 있습니다. B병원에서 출발할 때 다시 기본요금을 받으면 부당 추가비용 수취에 해당합니다.

한편, 의료기관 A병원에서 외래진료를 위해 의료기관 B병원으로 갔다가 원래 소속으로 복귀하여 새로운 요청과정을 거쳐 동일한 응급환자가 이전 이송이 종료된 장소에서 다시 탑승하였을 경우 별도 행위로 간주하여 기본 요금 산정이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-03', 702, 'https://www.129.go.kr/faq/faq00.do?pageIndex=16#faq9710', '626505b28a2fd4f6b49c35cdb26165f9ed9ecef8fb485f93ecde582569bd210c'),
('12317', 'faq129-20261010', '보건의료', '건강정책', '영유아 발달 정밀검사비 지원신청 기간이 어떻게 되나요?', '영유아 발달 정밀검사비는 올해 3~8차까지 영유아건강검진 대상자가 해당 차수의 영유아건강검진을 받은 날로부터 1년 이내에 영유아 발달 정밀검사를 받고, 정밀검사를 실시한 해의 다음연도 상반기(6월말)까지 신청하면 지원이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-01', 379, 'https://www.129.go.kr/faq/faq00.do?pageIndex=16#faq12317', '9f186cd682beb776acc030b3fd2eb91cadd7da741653e579c13fc0b8d25e8118'),
('14719', 'faq129-20261010', '보건의료', '건강정책', '영유아 건강검진 대상 여부 및 검진 시기는 어떻게 확인할 수 있나요?', '건강보험공단에서 영유아건강검진 대상자(2∼8차)를 확인할 수 있는 ­영유아 건강검진표 및 안내문­을 디지털 전자문서로 발송한 후 미열람자에 대해 개인별 주소지로 발송하고 있습니다. (월령별 검진시작일 전월 25일까지)

※ 1차(14~35일) 검진대상자는 영아기초기검진안내문 또는 알림톡 발송

또한, 건강보험공단 홈페이지, 모바일앱에서도 본인인증 후 조회 가능하며 경로는 아래와 같습니다.

- 공단 홈페이지 > 건강모아 > 자녀 건강 > 영유아건강검진

- 모바일앱 건강보험25시 > 건강모아 > (하단) 전체메뉴 > 자녀 건강 > 영유아건강검진 > 영유아 검진대상 조회

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-09-01', 37, 'https://www.129.go.kr/faq/faq00.do?pageIndex=16#faq14719', '86eaf0d28d6a172c5e9f32c02d09a757bf06a5d8462a29d8b2ae32d64286d26c'),
('18344', 'faq129-20261010', '노인장애인', '장애인편의증진(표지)', '해외에서 장애인으로 인정받기 위해서 국제장애인카드를 발급받아야 하나요?', '현재 해외에서 장애로 인정받기 위한 국제장애인카드(국제복지카드)는 없습니다.

최근 불법 국제장애인카드 홍보 등이 유포되고 있으니 장애인의 피해가 발생하지 않도록 주의가 필요합니다.

해외에서 장애인임을 증명하기 위해서는 복지로(www.bokjiro.go.kr) 온라인 또는 주민센터에 방문하여 장애인증명서를 발급 받으신 후 아포스티유 누리집(www.apostille.go.kr)에 접속해 본인 인증을 거쳐 문서의 정보를 입력하여 아포스티유 인증서*를 발급받아 사용하실 수 있습니다.

* 아포스티유는 국내에서 발급한 공문서가 외국에서도 공적 효력을 가질 수 있도록 하는 인증 제도

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-08-31', 28, 'https://www.129.go.kr/faq/faq00.do?pageIndex=16#faq18344', '94c13fd18e541d8b8ea27420e6e46c5babc51bd9d2274f8a0f461509387f814a'),
('18363', 'faq129-20261010', '노인장애인', '노인복지사업', '어르신이 퇴원 후 긴급하게 돌봄이 필요한데 지원이 있나요?', '어르신이 병원에서 퇴원 후 신속한 지역사회 복귀를 지원하기 위해 노인맞춤돌봄 퇴원환자 단기집중서비스에 긴급지원 절차를 시행하고 있습니다.

노인맞춤돌봄 대상자 요건에 부합되는 어르신이 퇴원 후 14일 이내에 주민등록상 주소지 행정복지센터에 신청하면 확인 절차 후 7일 이내 신속하게 서비스를 제공받을 수 있도록 지원하고 있습니다.

- 제공서비스 : 영양지원, 가사지원, 동행지원

- 제공기간 : 1개월 이내 (44시간)

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-08-31', 72, 'https://www.129.go.kr/faq/faq00.do?pageIndex=16#faq18363', 'c05f9cc80e8e98f3d5af539247bcab72eaa4698d01af2ca7fcc37917c214e5f8'),
('9330', 'faq129-20261010', '노인장애인', '장애인연금(수당)', '장애인연금수급자가 농지연금을 받으면 소득으로 반영되나요?', '농지연금은 재산(농지) 담보부 금융부채의 성격을 지니고 있으므로 소득산정 없이 지급받은 농지연금 수령액 누계를 부채로 산정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-08-28', 784, 'https://www.129.go.kr/faq/faq00.do?pageIndex=16#faq9330', '8cd2a38b3849b96e9856b38c89110cfee47fcdd686cbb015cdb7e6febe02783c'),
('18342', 'faq129-20261010', '노인장애인', '치매(노인건강증진)', '보훈의료대상자도 치매검사비 및 치매치료관리비를 지원받을 수 있나요?', '2026년 8월 1일부터 보훈의료대상자와 그 가족들도 지원기준 충족 시 치매안심센터의 치매검사비 및 치매치료관리비를 지원받을 수 있습니다.

다만, 보훈·위탁병원에서 치매치료비 감면 등의 지원을 받은 경우에는 중복 지원을 받을 수 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-08-28', 26, 'https://www.129.go.kr/faq/faq00.do?pageIndex=16#faq18342', '37956fe1de1343237430bdb015844064be23892fece770a3a72c7fb432911775'),
('18343', 'faq129-20261010', '노인장애인', '노인복지사업', '연못장도 자연장에 해당하나요?', '- 자연장이란 화장한 유골의 골분을 수목, 화초, 잔디 등의 밑이나 주변에 묻거나 해양 등 일정 구역에 뿌리는 장사방법입니다

- 화장한 유골의 골분을 뿌릴 수 있는 구역은 ①해양, ②화장한 유골의 골분을 뿌릴 수 있 는 시설 또는 장소가 마련된 묘지, 화장시설, 봉안시설, 자연장지입니다.

그러므로 연못장은 자연장에 해당하지 않습니다

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-08-28', 27, 'https://www.129.go.kr/faq/faq00.do?pageIndex=16#faq18343', '86d6849c490abb7ab135d98adfd7dc3dc0b470978e0f3a3103066139ab3047b8');
