INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('18362', 'faq129-20261010', '노인장애인', '장애인등록', '폰탄 수술을 받은 사람도 장애 등록이 가능한가요?', '''26.7.1일 장애정도 판정기준 개정으로 폰탄 수술을 받은 사람도 심장장애 심하지 않은 장애로 등록이 가능합니다.

장애 진단은 폰탄 수술 후 즉시 가능하며, 구비서류는 장애정도 심사용 진단서와 수술기록지입니다.

* 장애인등록 신청 및 심사과정에서 추가 서류 보완요청이 있을 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-08-28', 28, 'https://www.129.go.kr/faq/faq00.do?pageIndex=17#faq18362', '61715a5905b3f249cbb07e03076bd9daf755c86550d8cb506931d9699948e7e1'),
('18364', 'faq129-20261010', '노인장애인', '장애인연금(수당)', '장애인연금 수급 중 교정시설에 수용되면 지급이 안되나요?', '장애인연금은 금고 이상의 실형을 선고받고 교정시설 또는 치료감호시설에 수용 중인 경우 지급이 정지됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-08-28', 35, 'https://www.129.go.kr/faq/faq00.do?pageIndex=17#faq18364', 'fa80710ef96abc6367d7fa9ad53c44c9bb66b84efcef1ed4b716dba78eb7d110'),
('18345', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급지원 요청시 디딤씨앗통장 가입액도 금융재산으로 반영되나요?', '저소득층의 자활을 지원하는 희망키움통장, 디딤씨앗통장 등의 자금은 가입기간 중의 본인 저축액에 대해서 차감 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-08-26', 118, 'https://www.129.go.kr/faq/faq00.do?pageIndex=17#faq18345', '36e7cd24393b6334f9e8544ea14dbfbd35f5cfcfe0aba73cbc4e5826102cc15d'),
('2329', 'faq129-20261010', '보건의료', '건강보험정책', '재난적의료비지원사업 지급신청은 어디로 하나요?', '재난적의료비지원사업은 주소지와 상관없이 전국에 있는 국민건강보험공단 지사를 통해 신청 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-08-13', 3217, 'https://www.129.go.kr/faq/faq00.do?pageIndex=17#faq2329', 'e55fd614d45078bfda1c362b74cd0c60dfb48971498ba0f2ccfc12f2f6de1ba8'),
('2368', 'faq129-20261010', '보건의료', '건강보험정책', '재난적의료비 지원사업은 민간보험이 있으면 지원이 불가한가요?', '재난적의료비 지원사업은 보험회사 등으로부터 보험금(실손형만 해당) 등을 받거나 받을 수 있는 경우 해당 보험금 등에 상당하는 금액을 제외 후 지원하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-08-13', 3932, 'https://www.129.go.kr/faq/faq00.do?pageIndex=17#faq2368', 'cf17f7dcd9e88811d49eef2c832e663f50c2df54f716e782a5535e66aff79784'),
('6386', 'faq129-20261010', '인구아동', '아동분야사업', '(자립수당) 사이버강의 이수증은 어떻게 출력하나요?', '사이버강의는 서민금융진흥원 금융교육포털(https://edu.kinfa.or.kr) 또는 아동복지통합서비스 사이버교육센터(https://edu.ncrc.or.kr)에서 수강할 수 있으며, 자립지원 제도(자립수당, 자립정착금, 디딤씨앗통장), 경제교육(청년자산형성계좌, 청년청약저축, 지출관리), 법률(근로계약 및 부동산 거래) 등으로 구성되어 있습니다.

3차시 필수강의를 모두 수강 후 이수증을 출력할 수 있으며, 2020년 1월부터 자립수당을 신청하는 자는 반드시 이수증을 첨부해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-08-12', 2286, 'https://www.129.go.kr/faq/faq00.do?pageIndex=17#faq6386', '937241b24eb1608c93bbe36b4861820beff867ce5519221eb1a4d4ca990e5530'),
('9715', 'faq129-20261010', '보건의료', '공공보건정책', '구급차가 출동하여 출동 및 처치기록 작성 시 환자를 인수한 응급의료종사자의 서명이 꼭 있어야 하나요?', '응급의료법 제49조 및 같은 법 시행규칙 40조에서 응급구조사(또는 의사나 간호사)가 출동한 때에는 출동사항과 응급처치의 내용을 [별지 제16호서식]의 출동 및 처치기록지에 기록하고 이를 소속 구급차 등의 운용자와 해당 응급환자의 진료의사에게 제출하여야 한다고 규정하고 있습니다.

또한, 같은 법 시행규칙 [별지 제16호] 출동 및 처치기록지 서식은 의사, 간호사, 응급구조사 등 그 응급환자를 인수한 응급의료종사자의 면허번호, 성명, 서명을 필수기재 사항으로 정하고 있으며, 이는 환자이송에 대한 기본적인 기록으로 의료기관으로의 이송 시 환자인수자에 대한 정보를 반드시 기입하여야 합니다.

* 의료기관이 아닌 환자의 자택 등으로 이송 시, ''도착기관 명칭''에는 환자의 자택이라고 기재 후 환자인수자는 공란으로 처리

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-08-12', 1196, 'https://www.129.go.kr/faq/faq00.do?pageIndex=17#faq9715', 'fac18579b41ef14aa693f4c6631f7eca668d1204d21f203470955c05e556f36c'),
('9718', 'faq129-20261010', '보건의료', '공공보건정책', '구급차 ''출동 및 처치 기록지''를 환자 또는 보호자에게 교부해야 하나요?', '네. 그렇습니다.

「응급의료에 관한 법률 시행규칙」 제40조제2항에 의해 출동 및 처치기록은 3부를 작성하여 응급환자를 인수한 응급의료종사자의 서명을 받은 뒤, 그 중 1부는 이송처치료 징수용(이송처리용 영수증과 별개)으로 환자 또는 보호자에게 교부해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-08-12', 507, 'https://www.129.go.kr/faq/faq00.do?pageIndex=17#faq9718', 'aeec306e5b6831e482e6d87f4f4781cce7a72ae69b402cfecd2c85d2cf69bb65'),
('14500', 'faq129-20261010', '보건의료', '건강정책', '청소년의 찜질방 출입제한 시간이 어떻게 되나요?', '황토, 맥반석 등으로 땀을 낼 수 있는 시설 및 설비 등의 서비스를 제공하는 목욕장업으로서 24시간 영업을 하는 영업소의 경우에는 22:00이후부터 05:00까지 청소년보호법에 의한 청소년*의 출입이 제한됩니다.

* 청소년 보호법 제2조 : "청소년"이란 19세 미만인 사람을 말한다. 다만, 19세가 되는 해의 1월 1일을 맞이하는 사람은 제외한다.

다만, 친권자 또는 후견인이 동행하거나 친권자 또는 후견인의 출입동의서를 받는 등의 경우 출입이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2026-08-05', 109, 'https://www.129.go.kr/faq/faq00.do?pageIndex=17#faq14500', 'b4f3419afeedb8b8473c48d0a133d622279d7c3c8d1c94f2017cd18c925ca44e'),
('18264', 'faq129-20261010', '노인장애인', '장애인등록', '대입이나 취업을 위해 췌장장애 등록을 빨리 받을 수 있나요?', '장애인전형으로 대입이나 취업을 응시하기 위해 빠른 장애인등록이 필요한 경우라면 췌장장애 신청 시 ’26년 12월까지 행정복지센터에서 대입 또는 취업 관련 우선심사 신청을 하실 수 있습니다.

이 때 고교 또는 대학 재학·졸업(예정)증명서나 구직활동을 증명할 수 있는 워크넷 구직등록확인서, 면접확인서, 공무원·공공기관 채용시험 응시원서 접수증 등을 제출하셔야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-08-05', 38, 'https://www.129.go.kr/faq/faq00.do?pageIndex=17#faq18264', 'a038294ab48725cbaf91a55add3f6a54125aa8983e5b876e7fe121d86eb56d79'),
('8311', 'faq129-20261010', '보건의료', '건강보험정책', '조산아 및 저체중 출생아 외래진료비 본인부담 경감 대상자 등록 시 본인부담률은 어떻게 되나요?', '등록된 조산아 및 저체중 출생아가 외래진료를 받거나 약국 또는 한국희귀의약품센터에서 처방전에 따라 의약품을 조제 받는 경우 환자가 부담하여야 할 본인부담률은 5%입니다.

※ 대상자: (조산아) 재태기간 37주 미만 (저체중 출생아) 출생체중 2,500g 이하

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-08-04', 569, 'https://www.129.go.kr/faq/faq00.do?pageIndex=18#faq8311', '9f02c9d16b218cb4e013389371b776bb1acf4015b77e623f9b76eef59eaf11de'),
('14499', 'faq129-20261010', '보건의료', '건강정책', '목욕장업(남탕,여탕) 출입 시 연령제한이 있나요?', '공중위생관리법 시행규칙[별표4] 목욕장업 영업자의 준수사항에 ''목욕실 및 탈의실에 4세(48개월) 이상의 남녀를 함께 입장시켜서는 아니된다'' 라고 규정하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-08-04', 112, 'https://www.129.go.kr/faq/faq00.do?pageIndex=18#faq14499', 'de33dc4775be33a4ea9bf0406581efaa90d20ca25ac414dd9345db68b5a984c0'),
('18282', 'faq129-20261010', '보건의료', '건강보험정책', '본인일부부담금 산정특례 제도란 무엇인가요?', '본인일부부담금 산정특례 제도란 진료비 본인부담이 높은 암 등 중증질환자와 희귀질환자, 중증난치질환자에 대하여 본인부담률을 경감해주는 제도입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-08-03', 62, 'https://www.129.go.kr/faq/faq00.do?pageIndex=18#faq18282', 'eb51826f505b9b7fbade82e5df24b0fd416af60179899cf7b1bbf003be732ddb'),
('18262', 'faq129-20261010', '노인장애인', '장애인등록', '장애인등록증을 종류별로 여러 장 발급받을 수 있나요?', '장애인등록증의 종류는 금융기능(신용/체크) 유무에 따라 ''신분증형 장애인등록증'', ''금융카드형 장애인등록증'' 두가지로 구분하고, 그 각각은 다시 하이패스 기능(고속도로 통행료 감면) 유무에 따라 ''일반(신분증형 또는 금융카드형)''과 ''통합(신분증형 또는 금융카드형)''으로 4종류로 구분됩니다.

장애인등록증은 4종류 중 1종류만 발급 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-07-31', 55, 'https://www.129.go.kr/faq/faq00.do?pageIndex=18#faq18262', 'a959182a10c76856bdea69213e7247accef9b255124bbf2e8039e930f6a255f9'),
('18243', 'faq129-20261010', '노인장애인', '장애인등록', '장애 등록이 가능한 최소 연령 시점이 정해져 있나요?', '「장애인복지법」에 따른 장애등록 유형에 따라 장애 판정이 가능한 최소 연령 시점이 있습니다.

뇌병변장애, 지체기능장애(척수손상) : 만 1세 이상

지체변형장애 : 왜소증 - 남성 만 18세, 여성 만 16세, 연골무형성증인 경우는 만 2세 이상

언어 장애 : 만 3세 이상

자폐성 장애 : 자폐증이 확실해진 시점(만 2세 이상)에 판정가능

선천성 정신지체(지적장애) : 만 2세 이상

투렛장애: 만 20세 이상

신장장애: 만성신부전으로 3개월 이상 지속적으로 투석받은 것이 확인되는 시점

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-07-30', 49, 'https://www.129.go.kr/faq/faq00.do?pageIndex=18#faq18243', '43263d1355de351fe68024a36642a3f62a05c932b20d2ead5a3bba7fb445c5eb'),
('18244', 'faq129-20261010', '노인장애인', '노인복지사업', '노인일자리 신청, 선발 제외자 기준이 있나요?', '노인일자리 및 사회활동 지원사업에 신청· 선발 제외자 기준은 아래와 갚습니다.

[신청 제외자]

­- 과거 부정수급 등으로 사업 참여가 제한된 자(제한기간 종료 후 신청 가능)

- 국내 거주자 중 외국민인 자

[선발 제외자]

-­「국민기초생활 보장법」에 의한 생계급여 수급자(취업 지원 사업 제외)

※ 의료급여, 교육급여, 주거급여 수급자는 선발 가능

­- 국민건강보험 직장가입자(취업 지원 사업 제외)

(노인역량활용사업 및 공동체사업단은 해당 사업의 건강보험 직장가입자일 경우 해당 없음)

- ­ 장기요양보험 등급 판정자 1~5등급, 인지지원등급(취업 지원 사업 제외)

※ 인지지원등급자의 경우 전문의의 활동 가능 진단서 첨부 시에 한해 선발 가능

­- 정부부처 및 지자체에서 추진하는 일자리사업에 2개 이상 참여하고 있는 자

(노인 일자리 및 사회활동 지원사업 내 중복참여 불가)

※ 그 외 선발 제외자 해당 여부 등은 당해연도 직접일자리사업 중앙 - 지자체합동지침에 따름. 다만, 직접일자리사업 참여로 인해 실업급여를 수급한 후 노인 일자리 및 사회활동 지원사업에 신청할 경우, 90일 이후 가능(실업급여 수급일로부터 90일 이내에 참여하려는 경우, 취업지원 프로그램을 거쳐야만 선발 가능

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-07-30', 48, 'https://www.129.go.kr/faq/faq00.do?pageIndex=18#faq18244', '9ef34428e60b906e82338f81b99019a04984f8362430089d40271cd3878f60f5'),
('18245', 'faq129-20261010', '노인장애인', '치매(노인건강증진)', '치매안심재산관리서비스가 무엇인가요?', '치매 등으로 스스로 재산관리가 어려운 어르신이 본인의 의사에 따라 요양비, 병원비, 생활에 필요한 물품 및 서비스 비용이 적절히 지출될 수 있도록 지원하는 공공서비스입니다

2026년 4월부터 치매안심재산관리서비스 시범사업은 신뢰성 있는 공공기관(국민연금공단)에서 어르신의 재산을 투명하게 관리하고 보호하는 공공신탁 기반의 재산관리 지원사업을 수행하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-07-30', 40, 'https://www.129.go.kr/faq/faq00.do?pageIndex=18#faq18245', 'fa57d9d96049b4a18a006ac9aeb67bb3a1292b2906c85de9cc8fced0e084a04e'),
('18263', 'faq129-20261010', '노인장애인', '장애인등록', '췌장장애 등록은 1형 당뇨병만 가능하고 2형 당뇨병은 제외되는 건가요?', '췌장의 원인질환이 1형 당뇨병 또는 2형 당뇨병인지와 관계 없이 췌장의 인슐린 분비 기능 손상으로 인하여 장애정도판정기준 고시에서 정하는 장애상태에 해당하는 경우에는 췌장장애로 인정되고 장애인등록이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-07-30', 43, 'https://www.129.go.kr/faq/faq00.do?pageIndex=18#faq18263', 'd61a870d6843aa806c45651e4020b47567dd72e6327f41fee4e107797babf69b'),
('18202', 'faq129-20261010', '사회복지', '기초생활보장사업', '조건부수급자가 무엇인가요?', '자활사업 참여를 조건으로 생계급여를 지급받는 수급자를 조건부수급자라고 합니다.

근로능력이 있는 수급자가 생계급여를 지급받기 위해서는 자활사업에 참여하여야 하며, 이에따라 자활근로사업참여 대상자 선정시에는 조건부수급자를 우선하여 선정하게 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-27', 398, 'https://www.129.go.kr/faq/faq00.do?pageIndex=18#faq18202', 'e0138503751c5f83a4e3474af21e7ffabf723cb98e7a3717460d9a0db791664f'),
('18203', 'faq129-20261010', '사회복지', '자활사업', '자활근로 참여자도 병가 사용이 가능한가요?', '진단서, 처방전, 의사소견서 등 사전에 증빙서류를 제출하여 자활사업 실시기관장의 승인을 받는 경우 병가 사용이 가능합니다.

다만, 병가를 사용한 날은 무급휴일로 처리되어 해당일의 자활급여는 지급되지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-27', 125, 'https://www.129.go.kr/faq/faq00.do?pageIndex=18#faq18203', '8848199d8738c160bc7ffab7e20086c65f7497dbcdf1b41ff5ab735d8d50ac09');
