INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('18204', 'faq129-20261010', '보건의료', '보건의료정책', '비의료기관에서 건강관리서비스를 제공할 때 반드시 대상자의 질환 보유 여부를 확인하여야 하나요?', '일반적으로 ''건강한 사람''에게 제공하는 것을 전제로 설계·기획된 서비스의 경우 질환의 보유 여부 확인은 의무 사항이 아닙니다.

다만, 질환을 보유하고 있을 경우 의사의 상담을 권고한다는 안내 등은 서비스의 안전성을 위하여 권장되는 사항입니다.

질환자를 대상으로 설계·기획된 서비스의 경우 제공하고자 하는 질환관리 서비스 범위에서 대상자의 질환 및 합병증 보유 여부를 확인하여야 할 것입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-21', 50, 'https://www.129.go.kr/faq/faq00.do?pageIndex=19#faq18204', '1e01573a9b93e36ca86294f2b25f6b5273c2f3d9984b604aa38fd10f0ae1ac18'),
('18222', 'faq129-20261010', '보건의료', '보건의료정책', '질병의 치료를 위한 상담·조언 중 비의료기관에 예외적으로 허용된 행위란 무엇인가요?', '상담·조언의 내용이 질환의 치료를 직접적 목적으로 하는 경우 의료기관에서 수행해여야 합니다.

비의료기관은 의료기관의 진단·처방·의뢰의 범위 내에서 보조적으로 해당 서비스를 제공할 수 있음을 의미합니다.

예를 들어, 당뇨병 환자에게 혈당 수치에 따른 당질의 섭취 지침을 내리거나, 부상을 당한 환자에게 운동의 지침을 주는 것 등을 의미합니다.

질환자를 대상으로 해더라도 단순한 일상적 건강관리는 비의료기관에서 수행할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-21', 51, 'https://www.129.go.kr/faq/faq00.do?pageIndex=19#faq18222', 'cd220397a1c4cf3f8240ce521c478a282688fa215247f5da1c7eceddf9b9f988'),
('17480', 'faq129-20261010', '사회복지', '의료급여사업', '2026년부터 의료급여 수급자의 과다 외래이용자 관리가 시행되나요?', '의료급여 수급자의 과다한 외래 이용을 관리하기 위해 2026년 1월부터 본인부담 차등제가 시행되었습니다.

연간 외래 진료횟수가 365회를 초과하는 경우, 해당연도 12월 31일까지 초과되는 외래진료에 대해 수급자가 급여비용 총액의 30%를 부담하게 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-20', 140, 'https://www.129.go.kr/faq/faq00.do?pageIndex=19#faq17480', '1e41fa5182aa26dfb73cb143a95a07640c4b6d772d1ab551ef1eadd9d9887547'),
('17841', 'faq129-20261010', '사회복지', '의료급여사업', '의료급여 부양의무자가 출가한 딸인 경우 소득 및 재산 기준은 어떻게 되나요?', '26년부터 1월부터 의료급여 부양의무자의 부양비제도가 폐지되면서 혼인한 딸인 부양의무자의 소득재산 기준은 다음과 같습니다.
○소득기준 : 없음

○재산기준 : 금융재산이 2억원 미만

* 주거용재산과 일반재산 고려하지 않음

* 생활준비금(500만원)과 재산가액에서 차감하는 부채는 공제하며, 3년 이상 장기금융저축 공제는 미적용

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-20', 127, 'https://www.129.go.kr/faq/faq00.do?pageIndex=19#faq17841', 'caa2aeb1f612f58bb6a5e95370eeb1cf585b8dd7f333775fdb69dffa9da09f02'),
('15259', 'faq129-20261010', '사회복지', '자활사업', '근로능력판정이란 무엇인가요?', '근로능력판정은 기초생활수급(권)자 중 질병, 부상 또는 그 휴유증으로 치료 또는 요양이 필요한 사람 중에서 근로능력이 없다는 판정을 받고자 하는 사람에 대하여 근로능력 유무를 판정하는 제도입니다. 근로능력평가 신청서와 근로능력평가용 진단서, 최근 2개월 이상의 진료기록지 사본 등을 읍·면·동 주민센터로 제출하면 근로능력평가가 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-16', 732, 'https://www.129.go.kr/faq/faq00.do?pageIndex=19#faq15259', 'a82b65218f7a28d90b55a7543de69b180f680d67c18eb9355c2ae59b752b7e51'),
('17402', 'faq129-20261010', '사회복지', '기초생활보장사업', '국민기초생활보장에서 국가 불법행위 피해 수급자 특례가 신설 되었나요?', '과거 국가의 불법행위 피해에 대한 배상금 등 일시적 지원금으로 인한 수급 탈락 방지를 위해 특례가 신설되었습니다.

ㅇ 특례대상

국가 불법행위의 피해자로서 다른 법률 및 국가배상판결에 따라 배상금 등 일시금을 지급받은 수급자가 포함된 수급가구

ㅇ 특례내용

다른 법률 및 국가배상판결에 따른 배상금 등 일시금을 재산 산정에서 제외

ㅇ 특례적용기간

배상금 등 일시금 수령일로부터 3년(수령일로부터 3년이 되는 날이 속한 달의 말일을 적용기간 종료일로 함)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-16', 175, 'https://www.129.go.kr/faq/faq00.do?pageIndex=19#faq17402', '37e1db48cc64cf864f225bac1004a9a2185b818a6dfa57fb9a97152394381f60'),
('17840', 'faq129-20261010', '사회복지', '기초생활보장사업', '청년의 근로소득공제 적용 기준이 변경되었나요?', '2026년 1월부터 34세 이하(35세 생일이 속한 달의 전월까지 적용) 수급(권)자의 근로 및 사업소득은 60만원 공제 후 나머지 금액에 대해 30% 추가 공제하여 소득인정액으로 반영됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-16', 127, 'https://www.129.go.kr/faq/faq00.do?pageIndex=19#faq17840', 'f47515164f9137854a29091f7cfdce1e78ada16b04bacbb13db0ff8b4b332f63'),
('17920', 'faq129-20261010', '사회복지', '자산형성지원통장사업', '청년내일저축계좌와 청년미래적금은 중복 가입이 가능한가요?', '청년내일저축계좌와 청년미래적금은 중복 가입이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2026-07-16', 60, 'https://www.129.go.kr/faq/faq00.do?pageIndex=19#faq17920', '0013970ac23f3659804c6ca5be31fb2a61eae5d63773d0a133911175a8b8e9bc'),
('17981', 'faq129-20261010', '사회복지', '자활사업', '자활근로참여자도 월차휴가를 받을 수 있나요?', '해당 월(1개월)내의 기간 동안 모두 개근하였을 경우 그 다음달 월 1회의 유급휴일이 월차로 부여됩니다.

참여자의 사업시작일이 해당 월의 1일이 아닌 경우 사업 참여 시작일부터 참여종료일까지의 참여일 수가 12일 이상이면 월차가 발생되며 , 월 중에 자활이 종료되는 경우는 자활근로가 연속되지 않으므로 월차가 발생하지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-16', 72, 'https://www.129.go.kr/faq/faq00.do?pageIndex=19#faq17981', '12b0f586835296342db2be3df0cebc80ee2906a3aec866f8f63a9be3a7c67f20'),
('13999', 'faq129-20261010', '보건의료', '건강정책', '건강검진은 어디서 할수 있나요?', '건강보험공단에서 지정한 검진기관이면 주소지와 상관없이 전국 어디에서나 가능하며, 지정된 검진기관은 아래의 경로에서 확인하실 수 있습니다.

> 건강보험공단홈페이지 > 건강모아 > 기관찾기 > 병(의)원/검진기관 찾기 > 검진기관 찾기

> 모바일앱(건강보험25시) > 건강모아 > 병(의)원/검진기관 > 검진기관 찾기

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-14', 118, 'https://www.129.go.kr/faq/faq00.do?pageIndex=19#faq13999', '0e102a50f5f15ec3f8bcd1a70220e1aa7cbfc145c43b7678b25a6a14fdbb3f7f'),
('10279', 'faq129-20261010', '보건의료', '건강정책', '우수 건강검진기관은 어떻게 확인할 수 있나요?', '우수 검진기관은 건강보험공단 홈페이지에서 조회 가능하며, 경로는 아래와 같습니다.

- 국민건강보험공단 홈페이지 > 건강모아 > 기관찾기 > 병(의)원/검진기관 평가정보 > 검진기관 평가정보 > 평가등급 우수 검진기관 조회 체크(V) 후 지역별 검색

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-13', 773, 'https://www.129.go.kr/faq/faq00.do?pageIndex=20#faq10279', 'cbb2dc1287c36792e51e82a327470814a73418da6a383d26e9b1c73f9208a60e'),
('18182', 'faq129-20261010', '사회복지', '긴급지원사업', '거주불명등록이 된 경우에는 긴급지원 요청이 어려운가요?', '거주불명등록자라도 위기사유 발생으로 인한 생계곤란 등이 발생하였고, 해당 위기사유 해소를 위해 지원이 필요하다고 시­군­구청장이 인정을 하는 경우에는 긴급지원이 가능할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-07', 145, 'https://www.129.go.kr/faq/faq00.do?pageIndex=20#faq18182', '6746dcbc72aa55e53b3ef7e4f99ff755900f11d620837f25ce8f4e3cec677a9f'),
('12076', 'faq129-20261010', '보건의료', '공공보건정책', '자동심장충격기 사용 시 신고해야 하나요?', '「응급의료에 관한 법률 시행규칙」 제38조의3에 따라 해당 다중이용시설 등의 개설자 또는 관리자나 이를 직접 사용한 자는 응급의료지원센터에 그 사실을 지체 없이 알려야 합니다.

* 다만, 법 제47조의2제1항제1호(공공보건의료기관) 및 제2호(119구급차, 의료기관에서 운용중인 구급차)의 경우에는 그러하지 아니한다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-06', 309, 'https://www.129.go.kr/faq/faq00.do?pageIndex=20#faq12076', '7cb79d0a9eed399ee78ff73787237d07c7e86c5f0813d9fc77b0233228b03553'),
('12638', 'faq129-20261010', '보건의료', '공공보건정책', '자동심장충격기 설치장소가 변경되면 신고해야 하나요?', '설치기관 이전 등으로 설치장소 주소가 변경되고 설치위치가 변경된 경우 관할 보건소에 ''이전''신고를 하셔야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-06', 186, 'https://www.129.go.kr/faq/faq00.do?pageIndex=20#faq12638', '98155ab877c643e8435855e2a82e929c4eaa8cb709cdc0cae60c47287e792a97'),
('18162', 'faq129-20261010', '보건의료', '건강보험정책', '임신·출산 진료비 지원금 사용범위가 어떻게 되나요?', '임신·출산 진료비 지원금은 임산부의 진료비 및 약제·치료재료 구입에 대한 본인부담금(급여·비급여), 2세 미만 영유아의 진료비 및 처방된 약제·치료재료 구입에 대한 본인부담금 (급여·비급여)으로 사용 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-06', 36, 'https://www.129.go.kr/faq/faq00.do?pageIndex=20#faq18162', '20da617ce4f23698399c673ea8cf95cd46c7c646c4cfb0ae4af4db195b9ffea4'),
('13277', 'faq129-20261010', '보건의료', '건강보험정책', '재난적의료비 지원 대상은 누구인가요?', '국내에 거주하는 국민으로서 소득, 재산, 의료비 부담수준을 고려하여 지원기준을 충족하는 자가 대상입니다.

- 최종 입원진료 또는 외래진료일 이전 1년 이내 발생한 진료비용과 의약품 등을 구입한 비용이 지원기준에 해당하는 경우 (단, 의료비 부담수준 확인 시 10만 원 미만의 소액 진료비 및 단순 약제비는 제외)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-07-02', 527, 'https://www.129.go.kr/faq/faq00.do?pageIndex=20#faq13277', '60d43151f772e61d95e239e4184a77830914f59380b23699c6edc10d549210a1'),
('18082', 'faq129-20261010', '노인장애인', '장애인등록', '2026년 7월1일부터 당뇨병 환자가 모두 장애인등록이 가능한가요?', '2026년 7월1일부터 췌장의 만성적인 중증 내분비기능 이상이 있는 경우 췌장장애 등록이 가능합니다.

췌장장애로 등록하기 위해서는 먼저 의료기관에서 췌장장애로 진단받아야 하는데, 췌장장애로 진단받기 위해서는 ① 6개월 이상 집중적인 인슐린 치료를 받아야 하고, ② C-펩타이드 검사를 통해 인슐린 분비가 일정 기준 이하인 상태로 확인되어야 합니다.

췌장장애는 다른 장애유형과 마찬가지로 원인 질환의 진단과는 구별되므로, 당뇨병 진단만으로 인정되지 않습니다.

상세기준과 요건은 「장애정도판정기준」 고시에서 정하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-06-30', 144, 'https://www.129.go.kr/faq/faq00.do?pageIndex=20#faq18082', 'f07313040cd4603afce1f1f3ccf16df022b26fc2a7c25608234698e7bac73094'),
('18122', 'faq129-20261010', '노인장애인', '장애인등록', '췌장장애 진단을 위해 3차 의료기관으로 전원했는데 전원 전에 받은 검사나 치료기간도 인정되나요?', '전원 전에 치료나 검사한 의사가 내과 내분비대사분과 전문의나 소아청소년과 내분비분과 전문의가 아닌 가정의학과 의사나 일반 의사인 경우에도 전원 후에 진단하는 전문의가 ''췌장장애 요건을 충족하는 적합한 치료나 검사라고 인정''하는 경우에는 췌장장애 진단이 가능합니다.

다만, 췌장장애 진단을 하는 전문의가 전원 전에 실시된 치료나 검사에 오류가 있다고 판단하는 경우에는, 전원한 병원에서 췌장장애 진단을 위한 치료 및 검사를 새로 진행하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이☎129)로 연락주시기 바랍니다.', '2026-06-30', 55, 'https://www.129.go.kr/faq/faq00.do?pageIndex=20#faq18122', 'fa82a00cbd14f8148798668d3a56e1703e9031c5a056730964b77aead90802c8'),
('18142', 'faq129-20261010', '노인장애인', '장애인등록', '장애인등록 서류나 장애인복지서비스 등 관련정보를 쉽게 확인할 수 있는 방법이 있나요?', '장애인 등록을 위한 구비서류, 장애인복지서비스, 장애인서비스지원종합조사, 장애인활동지원 등 관련정보를 카카오톡 채널 ''챗코디''에서 쉽게 알아볼 수 있습니다.

* 챗코디'' 활용방법: 카카오톡에서 챗코디 추가 ① 카카오톡 돋보기 아이콘 누르기 - 채널명 「챗코디with한국장애인개발원」 입력 - ② 채널 추가하여 이용 (버튼 클릭 또는 메시지 입력으로 정보 검색)

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-06-30', 85, 'https://www.129.go.kr/faq/faq00.do?pageIndex=20#faq18142', '58ae9e4e9424ff31a815c591fc5a076f0a7650f78e738d3bbcfdc2bb24563f4a'),
('6737', 'faq129-20261010', '인구아동', '아동분야사업', '(자립수당) 지급 기간은 어떻게 되나요?', '자립수당은 보호종료일로부터 최대 60개월 한도 내 지급 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-26', 1748, 'https://www.129.go.kr/faq/faq00.do?pageIndex=20#faq6737', '51b157e32f2d44f7df98cc7a5b804cfe43c13da2ad9b6c2c832ba3a27df143a3');
