INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('14241', 'faq129-20261010', '인구아동', '출산정책', '(선천성 대사이상 환아) 특수식이 지원 신청 시 구비서류는 어떻게 되나요?', '특수식이 신청 시 구비서류는 다음과 같습니다.

<선천성대사이상 및 희귀 등 기타 질환(크론병 제외)>

- (최초 신청) 진단서 1부

* 진단서에 분유명, 필요량(1일 또는 월간) 등이 명시되지 않은 경우, 해당 내용이 기재된 소견서 제출 필요

- (환아 등록 이후 변경사항 발생) 소견서(또는 진단서) 1부

* 예) 1. 환아가 2단계 연령에 도달하였으나, 1단계를 유지해야 할 사유 발생, 2. 품목, 분유 단계, 섭취량 변경

등으로 추가 지원이 필요한 경우

- (정기적 진단서 제출) 최초 제출월 기준 매 1년마다 제출

* 단장증후군 환아의 경우 진단서 및 영양상태평가서 매 1년마다 제출

- 주민등록등본

* 전자정부법에 따른 행정정보의 공동이용을 통한 확인에 동의 시 생략 가능

<크론병>

- (최초 신청) 진단서 1부, 영양상태평가서 1부

* 진단서에 분유명, 필요량(1일 또는 월간) 등이 명시되지 않은 경우, 해당 내용이 기재된 소견서 제출 필요

- (집중치료 후 추가 지원 신청 시) 진료확인서[서식 4] 1부

* 집중치료기간(8주) 종료 후 추가 지원(최대 1년)을 받기 위해서는 담당의사로부터 진료확인서 발급받아 제출

해야 함(필요량, 필요개월수 등이 기재된 소견서/진단서로 대체 가능)

* 진료확인서는 최대 6개월 간 유효하며, 환아 기본정보와 1일 1포 또는 1일 2팩 특수조제분유 필요 개월 수에

대한 담당의사 의견과 서명, 병원직인이 기재되어야 함

- (유전성 크론병) 6개월마다 필요량, 필요기간 등이 기재된 소견서(또는 진단서) 제출 필수

- 주민등록등본

* 전자정부법에 따른 행정정보의 공동이용을 통한 확인에 동의 시 생략 가능

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-26', 8, 'https://www.129.go.kr/faq/faq00.do?pageIndex=21#faq14241', 'f51aeb8252509d1c942dd97a8ba9c0245772e795b1db5227e90727b4760dec17'),
('2369', 'faq129-20261010', '보건의료', '건강보험정책', '재난적의료비 지원사업은 재산 기준이 있나요?', '재난적의료비 지원사업은 지원대상자가 속한 가구의 주택, 건물, 토지 등 재산 합산액이 7억 원(재산과표액기준)을 초과하는 경우 지원 대상에서 제외하고 있습니다.

※ ''재난적의료비 지원을 위한 기준 등에 관한 고시'' [별표 3], [별표 3의2]에 따라 해당 연도 ''재난적의료비 지원사업 안내'' 지침에서 정함

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-26', 3087, 'https://www.129.go.kr/faq/faq00.do?pageIndex=21#faq2369', '27dee48393f82f8eff0518c5ba9795fec4661f98065e55e6a949374143dc704d'),
('7931', 'faq129-20261010', '보건의료', '보건의료정책', '의료기관세탁물 관리규칙의 적용 대상은 누구인가요?', '「의료기관세탁물 관리규칙」 제1조에서 규정하고 있는 병상(의료법상 허가병상을(일반병상) 의미)이 있는 의료기관은 의료기관세탁물 관리규칙을 준용하여야 하며, 병상이 없는 의료기관의 경우에도 세탁물 처리에 있어서 감염관리에 유념해야 할 것 입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-25', 1157, 'https://www.129.go.kr/faq/faq00.do?pageIndex=21#faq7931', '6e34ee9ba8d41875958ef35ae4ea074c9bc759fc92cb35a0e3036035bfa55938'),
('18083', 'faq129-20261010', '노인장애인', '장애인등록', '췌장장애 등록을 위한 장애진단은 어느 의료기관에서 받을 수 있나요?', '췌장장애는 장애진단 직전 3개월 이상 지속적으로 진료한 내과(내분비대사분과) 또는 소아청소년과(내분비분과) 전문의가 진단이 가능하며, 췌장이식의 경우는 췌장이식을 시술하였거나 이식환자를 진료하는 의료기관의 외과 또는 내과 전문의가 진단 가능합니다.

췌장장애는 6개월이상 적극적인 인슐린치료에도 불구하고 호전의 기미가 거의없는 췌장의 만성적인 중증 내분비기능 이상을 보이는 경우 진단이 가능합니다. 단, 전체췌장전제로 장애 고착이 명백하거나 2종 이상의 자가항체가 양성인 경우, 췌장이식의 경우에는 치료기간과 무관하게 진단 할수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-06-25', 49, 'https://www.129.go.kr/faq/faq00.do?pageIndex=21#faq18083', '1724cfc0474814d7a6f3bed4a58ce033cddb1a979bdc821d5c02890f8ad15ce1'),
('18085', 'faq129-20261010', '노인장애인', '장애인등록', '췌장장애 2회 검사를 하고 2회 모두 췌장장애 진단 기준을 충족하면 장애인등록이 가능한가요?', '췌장장애 신규 진단을 위해서는 최근 6개월 이내 최소 3개월 이상의 간격을 두고 검사가 장애정도 판정기준을 만족할 경우 심한장애로 판정하는데, 이때 두 검사일의 간격이 3개월 이상, 두 번의 검사에서 모두 췌장장애 진단 기준을 충족해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-06-25', 31, 'https://www.129.go.kr/faq/faq00.do?pageIndex=21#faq18085', 'e5996e68f06de8cae120b37b854d8d3d20a738288ccd6c68a45aa624ea3f8674'),
('18084', 'faq129-20261010', '노인장애인', '장애인등록', '췌장장애 진단을 위한 ‘6개월 이상의 인슐린 치료기간’은 기준일이 언제인가요?', '췌장장애 진단을 위한 ‘6개월 이상의 인슐린 치료기간’은 기준일은 진단일 기준입니다.

진단일 직전 6개월 이상 다회인슐린주사요법 또는 자동인슐린주입기 등을 사용하는 등 적극적인 인슐린 치료로 인정되는 기간이 6개월 이상이어야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-06-24', 27, 'https://www.129.go.kr/faq/faq00.do?pageIndex=21#faq18084', 'e1d2d9c65e8de4224ec8663721e1470cfa54121ee06f3b63fcd18c82a905a96b'),
('3268', 'faq129-20261010', '인구아동', '아동분야사업', '(자립수당) 신청할 때 제출해야 할 서류는 무엇인가요?', '자립수당 신청시 구비서류는 다음과 같습니다.

­○ 필수 제출서류

- 자립준비청년 자립수당 지급 신청서 1부

- 국민연금공단 희망출발 재무상담 확인서* 또는 아동권리보장원 아동복지통합서비스

사이버교육센터 사이버강의 이수증** 또는 서민금융진흥원 사이버강의 이수증 *** 중 택 1부

* 전국 40개 지사에서 자립준비청년에게 희망출발 재무상담(대면, 영상 상담 가능) 후 확인서 발급

** 아동권리보장원 아동복지통합서비스 사이버교육센터(https://edu.ncrc.or.kr)에서 ‘보호종료(예정)아동 온라인 자립교육 강의 수강 후 이수증 출력

*** 서민금융진흥원 금융교육포털(https://edu.kinfa.or.kr)에서 ‘보호종료아동 자립교육’ 강의 수강 후 이수증 출력

※ 온라인 신청의 경우 사이버강의 이수증 또는 희망출발 재무상담 확인서만 첨부

- 신분증 : 주민등록증, 여권, 자동차운전면허증, 장애인등록증 중 1종

○ 추가 제출서류

- 수급계좌가 압류방지통장 계좌인 경우 통장 사본 1부

- 대리 신청시 ­보호종료아동 자립수당 관련 위임장­ 및 대리인 신분증, 보호종료 아동과 관계를 확인할 수 있는 증빙서류

※ 친족은 가족관계증명서 또는 제적등본, 시설종사자는 재직 증빙 서류, 위탁부모는 가정위탁 확인서 등

- 시스템 상 보호종료 사실 확인이 어려운 경우 보호종료 확인서

※ 담당 공무원이 요청할 경우, 보호종료자가 아동복지시설 또는 가정위탁지원센터에서 보호종료 확인서를 발급받아 제출

※ 온라인 신청의 경우 수급계좌번호 확인 5회 이상 실패시 통장사본 추가 첨부 필요

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-16', 1594, 'https://www.129.go.kr/faq/faq00.do?pageIndex=21#faq3268', '95bf5990c3c9d29a09e9330c0f54a4772bc011d3d3f362e75348cdd42228bfa6'),
('4187', 'faq129-20261010', '인구아동', '출산정책', '(산후조리원) 전국 산후조리원 현황(전화번호,이용가격 등)자료가 있나요?', '전국 산후조리원 현황 자료(산후조리원명, 주소, 전화번호, 이용가격)는 보건복지부 홈페이지에서 확인가능합니다.

* 확인경로 : 보건복지부 홈페이지 > 정보 > 현황 > 전국 산후조리원 현황(2025.12월.기준)/26.03.11등록

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-16', 2451, 'https://www.129.go.kr/faq/faq00.do?pageIndex=21#faq4187', '609b7fa52c66e41fe5a6f4b95cfd1830eee9d4bc2a26129a3d38ad25c7bae8fd'),
('4971', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 난임부부 심리상담 지원이 있나요?', '난임부부에 대한 심리 및 의료 상담서비스를 받을 수 있는 전문상담센터가 운영되고 있습니다.

www.nmc22762276.or.kr 사이트에서 예약제로 운영되고 있으며 모든 상담내용은 개인정보가 보호 됩니다.

정서적 심리적 어려움을 겪는 난임 부부 및 임산부를 대상으로 상담을 제공하며 비용은 없습니다.

