('11697', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '서비스제공을 친동생에게 받을수 있나요?', '가사간병방문지원사업에서는 제공인력이 이용자와 가족 관계에 있는 경우에는 해당 이용자에게 서비스를 제공할 수 없습니다.

(가족의 범위)

- 배우자, 직계혈족(고조부­모, 조부­모, 부­모, 자녀, 손자녀, 증손자녀), 형제­·자매

- 직계혈족의 배우자, 배우자의 직계혈족, 배우자의 형제·­자매

더 자세한 문의 사항은 보건복지상담센터(국번없이 129)로 문의하여 주시기 바랍니다.', '2026-06-16', 379, 'https://www.129.go.kr/faq/faq00.do?pageIndex=22#faq11697', '241b303d8916275a334937577bbb7977e251b0d741c0fcf392bc8fefaf7a2815'),
('13259', 'faq129-20261010', '인구아동', '출산정책', '(보청기지원) 난청환아 대상 보청기 지원을 받을 수 있는 연령과 기준이 되는 시점은 언제인가요?', '난청환아 대상 보청기 지원의 기준이 되는 시점은 거주지 보건소 신청일(접수일) 입니다.

보건소 신청일을 기준으로 만 12세 미만(12세 생일 전날까지)인 경우 난청환아 대상 보청기 지원을 위한 신청이 가능합니다. 신청일 전후 6개월이내 양측 청력저하로 검사하고, 보청기를 구입하신 경우 지원을 받으실 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2026-06-16', 17, 'https://www.129.go.kr/faq/faq00.do?pageIndex=22#faq13259', '30f72a930830b0bbd7b3b4a145f59cab98d71c0dc458d990e66da465c8d20abd'),
('14156', 'faq129-20261010', '인구아동', '지역사회서비스투자사업', '(긴급돌봄) 긴급돌봄 서비스란?', '긴급돌봄서비스는 질병, 부상, 주돌봄자의 갑작스러운 부재(입원, 사망 등)로 혼자 일상생활을 수행하기 어려움에도 돌볼 수 있는 다른 가족이 없거나 타 서비스를 이용할 수 없는 경우 한시적으로 가정에 방문하여 돌봄·가사 및 이동지원 등의 도움을 드리는 서비스입니다.

* 서울, 경기는 지역으로 문의

더 자세한 사항은 보건복지 상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-16', 36, 'https://www.129.go.kr/faq/faq00.do?pageIndex=22#faq14156', '6729882b5301e3412e3749cdea73e315d624a568c28d9feaccaeeb7d78b7370e'),
('14222', 'faq129-20261010', '인구아동', '출산정책', '(보청기지원) 보건소 신청일 기준 8개월 전에 자비로 구입한 보청기 지원도 가능할까요?', '보청기 지원은 보건소 신청일 전후 6개월* 이내에 구입한 보청기에 대해서만 지원 가능하므로, 신청일 기준 이미 착용한 지 6개월이 넘은 보청기는 지원 불가합니다.

* 국민연금공단의 국가 청각장애진단 기준에 준한 것으로써, 일반적으로 6개월 경과 시 청력의 변동 가능성이 있기 때문에 설정

단, 아이가 성장하면서 청력의 변화나 보청기 분실, 고장 등으로 보청기를 교체해야 할 경우가 발생하면 만 12세 미만 시기에 신청 시 지원 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2026-06-16', 7, 'https://www.129.go.kr/faq/faq00.do?pageIndex=22#faq14222', '360fd42ee2b963724a308b7fc6cb2e78b5ac19b8c4f86f610cd51a84bf4fd4dc'),
('14228', 'faq129-20261010', '인구아동', '출산정책', '(선천성 대사이상 환아) 검사비 신청 시 구비서류는 어떻게 되나요?', '선천성 대사이상 환아 검사비는 영아의 주민등록 주소지 관할 보건소로 신청 또는 e보건소 공공보건포털, 아이마중앱 등 온라인 신청도 가능합니다.

구비서류로는 다음과 같습니다.

(신청자 공통)

- 지원 신청서 1부

- 검사비 영수증, 검사비 세부내역서 각 1부

- 지원금 입금계좌통장 사본 1부

- 주민등록등본 1부*

* 전자정부법에 따른 행정정보의 공동이용을 통한 확인에 동의 시 생략 가능

(해당자 제출)

- (확진검사비) 진단서 등 확진 관련 증빙서류

- (필요시) 가족관계증명서 1부

* 전자정부법에 따른 행정정보의 공동이용을 통한 확인에 동의 시 생략 가능

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-16', 8, 'https://www.129.go.kr/faq/faq00.do?pageIndex=22#faq14228', 'afd02cca294daabb2cc40292b5a302b242ab722398ae35d86e8dc2b0a1d52438'),
('14238', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 신청 시 구비서류는 어떻게 되나요?', '난임부부 시술비 지원사업 신청 시 구비서류는 다음과 같습니다.

[기본 서류]

① 난임부부 시술비 지원 신청서

② 난임 진단서

* 난임 진단서는 1차 신청 시 제출한 내용을 최종 지원 시까지 갈음함

* 사실혼 부부의 경우 난임진단서 없이 신청 가능. 시술 종료 후 비용청구 전까지 진단서 별도 제출.

③ 부부 모두의 건강보험증 사본 또는 건강보험자격확인서 1부씩

④ 주민등록등본 1부(단, 부부 또는 직계비속이 별도의 주민등록지에 거주하고 있는 경우 가족관계증명서(상세) 1부 제출)

※ ③∼④의 경우 ­전자정부법­에 따라 행정정보의 공동이용을 통한 확인에 동의한 경우는 제출 생략

[추가 서류]

⑤ 사실상 혼인관계인 경우

- 당사자 시술동의서

- 제3자와의 혼인관계가 없다는 것을 확인할 수 있는 주민등록등본* 및 가족관계증명서(또는 혼인관계증명서) 당사자별 각 1부

* ­전자정부법­에 따라 행정정보의 공동이용을 통한 확인에 동의한 경우는 제출 생략

* 당사자가 외국인인 경우 대사관에서 발급한 ''혼인관계 진술서'', ''미혼증명서'' 중 1부 또는 자국행정기관에서 발급받은 ''가족관계증명서'', ''호적등본'', 이에 준하는 서류 중 아포스티유 또는 영사확인을 거친 후 필요시 공증 및 번역 절차를 완료한 서류 1부(당사자가 외국인인 경우에 한함) (서류 유효기간 : 발급일로부터 1년)

- 1년 이상 사실상 혼인관계를 증명할 수 있는 공문서 1부(해당 공문서가 없는 경우 사실혼 확인보증서 및 보증인 신분증 사본 각 1부)

* 주민등록등본상 동일 거주지에 1년 이상 동거한 기록이 있는 경우 제출 생략 가능

- 1년 이상 체류를 증빙할 수 있는 외국인등록사실증명, 국내거소신고사실 증명 중 1부(당사자가 외국인인 경우에 한함)

* 상기 서류 외에 1년 이상 체류를 추가 증빙하려는 경우 출입국기록을 추가 제출할 수 있음', '2026-06-16', 12, 'https://www.129.go.kr/faq/faq00.do?pageIndex=22#faq14238', '160109c79971d04f820c77ba7c42f76f81e8da7d378b48c8936e86d246dcdcfd'),
('14244', 'faq129-20261010', '인구아동', '출산정책', '(미숙아의료비) 의료비 신청 시 구비서류는 어떻게 되나요?', '미숙아의료비는 (최종)퇴원일로부터 6개월 이내에 제출서류를 구비하여 신청일 기준 대상 영아의 주민등록 주소지 관할 보건소로 신청 또는 e보건소 공공보건포털, 아이마중앱으로 온라인 신청 가능하며, 신청 시 구비서류는 다음과 같습니다.

- 지원신청서 1부

- 진료비 영수증, 진료비 세부내역서 각 1부

- 지원금 입금계좌통장 사본 1부

- 주민등록등본 1부

* 전자정부법에 따른 행정정보의 공동이용을 통한 확인에 동의 시 생략 가능

- 출생보고서 또는 출생증명서 1부

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2026-06-16', 6, 'https://www.129.go.kr/faq/faq00.do?pageIndex=22#faq14244', '6788614687e4b94a71959c44d8e71041b2388f5afd13fb5d3a2e03a3fcc948d7'),
('14245', 'faq129-20261010', '인구아동', '출산정책', '(선천성이상아) 의료비 신청 시 구비서류는 어떻게 되나요?', '선천성이상아 의료비는 (최종)퇴원일로부터 6개월 이내에 제출서류를 구비하여 신청일 기준 대상 영아의 주민등록 주소지 관할 보건소로 신청 또는 e보건소 공공보건포털, 아이마중앱으로 온라인 신청 가능하며, 신청 시 구비서류는 다음과 같습니다.

- 지원신청서 1부

- 진료비 영수증, 진료비 세부내역서 각 1부

- 진단서, 입.퇴원확인서 각 1부(질병명 및 질병코드 포함)

* 입.퇴원확인서는 입원횟수별로 제출. 단, 진단서 상에 각각의 입.퇴원 진료기록이 모두 기재된 경우에는 생략 가능

- 지원금 입금계좌통장 사본 1부

- 주민등록등본 1부

* 전자정부법에 따른 행정정보의 공동이용을 통한 확인에 동의 시 생략 가능

- (필요시) 가족관계증명서, 소견서 각 1부

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2026-06-16', 4, 'https://www.129.go.kr/faq/faq00.do?pageIndex=22#faq14245', 'a380dd379766637aa6f61a101d0a3a79de601ec94bfce6e33eb27228333499d4'),
('14303', 'faq129-20261010', '인구아동', '출산정책', '(미숙아의료비) 지원 금액은 얼마인가요?', '미숙아 의료비는 지원대상 금액*별로 지원율**을 차등 적용하여 출생시 체중에 따른 1인당 지원한도 내에서 지급합니다.

* 전액본인부담금 및 비급여 진료비 합산금액에서 지원제외 항목분을 차감한 금액

** 지원대상 금액 중 100만원 이하분에 대해서는 지원율 100%를, 100만원 초과분에 대해서는 지원율 90%를 각각 적용

예) 지원대상 금액이 130만원인 경우 : 100만원 + {(130만원-100만원) x 0.9} = 127만원

○ 지원한도

- 2.0kg~2.5kg 미만, 재태기간 37주 미만 : 4백만원

- 1.5kg~2.0kg 미만 : 5백만원

- 1kg~1.5kg 미만 : 10백만원

- 1kg 미만 : 20백만원

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-16', 10, 'https://www.129.go.kr/faq/faq00.do?pageIndex=22#faq14303', '5e820576a72797e578ea5625d15ccad4c2f26919b501bb8bd0a757a6d585b4aa');
