INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('14304', 'faq129-20261010', '인구아동', '출산정책', '(선천성이상아) 지원 금액은 얼마인가요?', '선천성이상아 의료비는 지원대상 금액*별로 지원율**을 차등 적용하여 1인당 최대 700만원 한도 내 지급합니다.

* 전액본인부담금 및 비급여 진료비 합산금액에서 지원제외 항목분을 차감한 금액

** 지원대상 금액 중 100만원 이하분에 대해서는 지원율 100%를, 100만원 초과분에 대해서는 지원율 90%를 각각 적용

예) 지원대상 금액이 130만원인 경우 : 100만원 + {(130만원-100만원) x 0.9} = 127만원

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-16', 4, 'https://www.129.go.kr/faq/faq00.do?pageIndex=23#faq14304', 'b6186f27b4487f6d30d4b568bfdf856d218f7f44a9f17f6ccc7c1156ba2a771e'),
('15179', 'faq129-20261010', '인구아동', '지역사회서비스투자사업', '(일상돌봄) 일상돌봄서비스란?', '일상돌봄서비스는 질병, 고립 등으로 일상생활에 돌봄이 필요한 청(소)년·중장년(13~64세) 또는 질병·정신질환 등을 앓고 있는 가족*을 돌보거나 그로 인해 생계책임을 지고 있는 청(소)년(39세 이하, 청소년 포함)에게 재가돌봄(식사도움, 신체청결, 옷갈아입히기 등), 가사(청소, 설거지, 식사준비 등), 일상지원(장보기, 은행방문 등) 등의 도움을 드리는 서비스입니다.

* (가족의 기준) 부모, 조부모, 배우자, 형제자매, 친척 등을 돌보는 경우로 ''자녀를 돌보는 경우'' 제외

더 자세한 사항은 보건복지 상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-16', 35, 'https://www.129.go.kr/faq/faq00.do?pageIndex=23#faq15179', '584dca1a7d516d19aead02a19fe1b31f0ba3d9332c6054a7ddfcfb98c8dd93ca'),
('1586', 'faq129-20261010', '인구아동', '기초연금사업', '재산은 없고 근로소득만 있는데 기초연금을 못 받나요?', '근로소득이 있다고 해서 기초연금 신청이 안되는 것은 아닙니다.

상시근로소득 공제를 통해서 일하시는 어르신들이 기초연금을 받을수 있도록 하고 있습니다.

2026년 기준으로 상시근로자로 근무 시 월 상시근로소득에서 116만원 공제 후 30% 추가공제를 하고 있습니다.

또한, 3개월 미만(건설 공사 근로자는 1년 미만) 일용근로자의 근로소득 및 노인일자리 등 공공일자리 소득은 소득으로 산정하지 않습니다.

예) 근로소득 300만원일 경우, (300만원 - 116만원)*0.7 = 128.8만원 반영

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-06-16', 4433, 'https://www.129.go.kr/faq/faq00.do?pageIndex=23#faq1586', '1aff36e3b98cd9d9f9b940dd0dba6ab96a783491ab4068c6cb670d80fbaaacf4'),
('963', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 지원결정통지 후 시술은 받지 않은 상태에서 자연임신이 된 경우 철회하고 추후 재신청하면 되는건가요?', '지원결정통지서 유효기간(6개월) 이후 자동 소멸되므로 별도의 철회 절차는 없습니다.

다만, 추후 다시 시술을 진행하는 경우에는 새롭게 신청해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-16', 1265, 'https://www.129.go.kr/faq/faq00.do?pageIndex=23#faq963', 'ef32326fd93fc3111aa147d8d071cd11e6ac93920c1ac23daee38ca39946e79d'),
('1159', 'faq129-20261010', '인구아동', '아동분야사업', '(아동복지시설) 아동복지시설은 어떤 종류가 있나요?', '아동복지법 제52조에 따른 아동복지시설의 종류는

①아동양육시설 ②아동일시보호시설 ③아동보호치료시설 ④공동생활가정(그룹홈) ⑤자립지원시설 ⑥아동상담소 ⑦아동전용시설(어린이공원, 어린이놀이터, 아동회관, 아동휴게숙박시설 등) ⑧지역아동센터 ⑨협동돌봄센터 ⑩아동보호전문기관 ⑪가정위탁지원센터 ⑫아동권리보장원 ⑬자립지원전담기관 ⑭ 학대피해아동쉼터가 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-16', 19344, 'https://www.129.go.kr/faq/faq00.do?pageIndex=23#faq1159', '29b8ad33e04fdf629dafc52b4af8fa35e725cdde707491fef6949dff5f82e14e'),
('18063', 'faq129-20261010', '사회복지', '기초생활보장사업', '신용대출(카드론)이 부채로 인정되나요?', '단기간(1년 이내)의 신용카드회사에서 제공하는 신용대출(카드론) 및 어음할인 대출은 부채로 인정되지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2026-06-11', 43, 'https://www.129.go.kr/faq/faq00.do?pageIndex=23#faq18063', '41ec82ff008951e7dd24b63ac23c77125960d82dce8da5fbb8922db4d226fa2c'),
('18060', 'faq129-20261010', '보건의료', '공공보건정책', '법정 자동심장충격기 구비 의무기관이 아니라도 응급의료정보제공 웹사이트/앱에 안내를 하고 싶은데 어떻게 해야 되나요?', '법정 자동심장충격기 구비 의무가 없는 그 밖의 기관도 관할 보건소에 설치 신고를 하셔야만 장비 등록 및 월 점검 기능을 활용하실 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-04', 28, 'https://www.129.go.kr/faq/faq00.do?pageIndex=23#faq18060', 'dab845cfa183f3f7a71cb53fe17ad0ca345fb2d95370e375fb2f23c01c6c9699'),
('18061', 'faq129-20261010', '보건의료', '공공보건정책', '심폐소생술 및 자동심장충격기 사용 방법 등 참고할 수 있는 교육 동영상이나 지침서가 있나요?', '「일반인 심폐소생술 표준 교육프로그램」

▷ 동영상

-「일반인 심폐소생술 표준 교육프로그램(기초) 동영상」

-「일반인 심폐소생술 표준 교육프로그램(심화) 동영상」

* (다운로드) 질병관리청 홈페이지 http://www.kdca.go.kr ☞ 알림자료 ☞ 홍보자료 ☞ 영상자료 ☞ “심폐소생술” 또는 “표준 교육” 으로 검색

▷ 지침서

-「일반인 심폐소생술 표준 교육프로그램 강사 지침서」(기초·심화 공통)

-「일반인 심폐소생술 표준 교육프로그램 교육 운영지침」(기초·심화 공통)

* (다운로드) 질병관리청 홈페이지 http://www.kdca.go.kr ☞ 알림자료 ☞ 홍보자료 ☞ 교육자료 ☞ “심폐소생술” 또는 “표준 교육” 으로 검색

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2026-06-04', 19, 'https://www.129.go.kr/faq/faq00.do?pageIndex=23#faq18061', 'bbb854c93985e7276a9348db951abc5311bb58b9ca7730a172fadbbef9b7cc3c'),
('14009', 'faq129-20261010', '보건의료', '건강정책', '아동치과주치의 서비스 이용 신청은 어떻게 하나요?', '아동치과주치의 서비스 등록 신청은 시범사업 기간내 언제든지 가능하며, 건강보험공단 누리집 등을 통해 참여 의료기관 확인한 후 해당 의료기관 방문하여 주치의에게 서비스 등록 신청을 하여야 합니다.

시범사업에 참여중인 의료기관 정보는 아래의 경로에서 확인이 가능합니다.

- 국민건강보험공단 홈페이지 > 건강모아 > 기관 찾기 > 병(의)원/검진기관 찾기 > 특성별 기관찾기 > (구분) 아동치과주치의 의료기관

- 모바일 앱(건강보험25시)> 건강모아 > 병(의)원/검진기관 > 병.의원 찾기 > 아동치과주치의 의료기관 찾기

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2026-06-02', 81, 'https://www.129.go.kr/faq/faq00.do?pageIndex=23#faq14009', 'f7fc79749cad8e8210d05752d3ff2e2490e556c517049f13d389638dfd620b05'),
('17180', 'faq129-20261010', '보건의료', '건강보험정책', '재난적의료비지원사업은 긴급지원 등과 중복지원이 가능한가요?', '재난적의료비 지원 신청기간 중 다른 법령 또는 계약에 따라 재난적의료비에 대하여 국가 또는 지방자치단체로부터 급여­금품 등을 받았거나 받을 수 있는 경우에는 해당 급여, 금품 등에 상당하는 액수를 제외하고 지원금액을 산정합니다.

다만, 긴급복지(의료비)지원사업은 지원(승인)을 받은 경우에만 재난적의료비 지원 항목인 ''2·3인실 입원료'', ''선별급여'', ''전액본인부담금'', ''비급여'' 차감 후 지급합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-02', 367, 'https://www.129.go.kr/faq/faq00.do?pageIndex=23#faq17180', '5049d5a6aa0f59397679f065233fb458e17285e971e2f64441a6db98720db5f0'),
('18040', 'faq129-20261010', '보건의료', '건강보험정책', '장기요양등급자도 진료 시 신분증을 제시해야 하나요?', '장기요양등급이 있는 경우 본인확인 예외대상으로 신분증 추가 제출하지 않고 수진자 조회 화면에서 예외대상 여부 확인 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-06-02', 30, 'https://www.129.go.kr/faq/faq00.do?pageIndex=24#faq18040', '35db12198245bdbf171b65174c84f1215f940bf2dc63161e3a109311f3633fb0'),
('18000', 'faq129-20261010', '노인장애인', '노인복지사업', '통합돌봄 대상자로 선정된 후 병원에 입원하면 어떻게 되나요?', '통합돌봄 대상자가 3개월 미만의 병원 입원 시에는 서비스 제공을 중단하며, 이후 3개월이 경과한 경우 통합돌봄 대상자 종결사유에 해당합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-05-29', 78, 'https://www.129.go.kr/faq/faq00.do?pageIndex=24#faq18000', '0d0c077fc8b82fdc098a6f15950c3cc8641cf346b63e2aece2d84027e32faf61'),
('18001', 'faq129-20261010', '노인장애인', '노인장기요양제도', '노인장기요양 통합재가서비스는 어떤 서비스인가요?', '하나의 기관(주야간보호 또는 방문간호)에서 수급자의 욕구·상태에 따라 다양한 재가서비스(주·야간보호, 방문요양·목욕·간호)를 전문인력(간호사·간호조무사, 물리·작업치료사, 사회복지사, 요양보호사)이 복합적으로 제공하는 서비스 입니다.

더 자세한 사항은 보건복지상담센터 (국번없이 ☎129)로 문의주시기 바랍니다.', '2026-05-29', 88, 'https://www.129.go.kr/faq/faq00.do?pageIndex=24#faq18001', '68209db7321016b2b5fe89b3155b79b7e9eb898c1eabcb606707b9b2f497ced3'),
('18020', 'faq129-20261010', '노인장애인', '노인복지사업', '통합돌봄 대상자가 다른 지역으로 이사하면 어떻게 되나요?', '다른 시·군·구로 이사하는 경우 전출에 따른 종결 사유에 해당하여, 새롭게 이사한 주소지 읍·면·동 행정복지센터로 통합돌봄을 신청하셔야 합니다

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-05-29', 47, 'https://www.129.go.kr/faq/faq00.do?pageIndex=24#faq18020', 'cf65f3c932bfd102757f2749a91d123d613e5347e922ba4824c8483c5fbdf1f7'),
('18021', 'faq129-20261010', '노인장애인', '노인복지사업', '개인주택 마당 등에 산분이 가능한가요?', '산분은 장사시설(묘지, 화장시설, 봉안시설, 자연장지)로 관할 지자체에 설치 신고 또는 허가를 받고 산분을 할 수 있는 장소나 시설을 마련한 경우에만 가능하며, 장사시설로 신고·허가 받지 않은 경우(장사시설이 아닌 경우) 산분은 제한됩니다.

참고로, 별도의 표지를 설치하지 않는 개인·가족 자연장지는 주거지역 일부(일반· 준주거지역), 상업지역 일부(일반·근린·유통상업지역), 공업지역 일부(일반·준공업지 역)에 조성할 수 있으며(장사법 시행령 제22조), 해당 개인·가족 자연장지의 별도의 장소 등을 마련한다면 산분이 가능할 수 있으므로 관할 지자체로 문의하시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-05-29', 43, 'https://www.129.go.kr/faq/faq00.do?pageIndex=24#faq18021', '6232c4300f4af8db29e1ebfdda903a6aae02030fc34c4d9e8e25968cfcc31ae7'),
('17960', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급주거지원은 긴급생계지원처럼 매달 현금으로 지원을 받나요?', '긴급주거지원은 국가 또는 지방자치단체가 소유한 임시거소를 제공하거나 임시로 거처할 수 있는 주거를 제공하는 것이 원칙입니다.

다만, 국가 또는 지방자치단체가 아닌 타인 소유의 임시거소에 대한 지원의 경우에는 임시거소 제공자에게 거소사용비용(상한액 내 실비지원)을 지급할 수 있습니다

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-05-18', 244, 'https://www.129.go.kr/faq/faq00.do?pageIndex=24#faq17960', 'edec873a775ca005345d302490427d400c2df63ae3c50ee21f1c4d4e355a6dc1'),
('17941', 'faq129-20261010', '사회복지', '긴급지원사업', '사회복무요원으로 복무중인 자녀의 장병내일준비적금도 금융재산으로 산정하나요?', '장병내일준비적금의 본인 저축액에 대해서는 금융재산으로 산정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-05-12', 43, 'https://www.129.go.kr/faq/faq00.do?pageIndex=24#faq17941', '7d5918f6e10dbcd2298266abf93e8963eab0d7d13c5c35e45f831bd551564444'),
('10601', 'faq129-20261010', '보건의료', '공공보건정책', '헌혈증서는 재발급이 가능한가요?', '혈액관리법 개정(''22.9.24. 시행)에 따라 2022년 9월 24일 이후 발급된 헌혈증서부터 재발급 받을 수 있습니다.

2022년 9월 24일부터 발급되는 헌혈증서는 노란색으로 이전 헌혈증서(파란색)와 구분되며, 2022년 9월 23일까지 발급된 헌혈증서(파란색)은 재발급 받을 수 없습니다.

헌혈증서 재발급은 헌혈증서 당 1회만 가능하며, 증서 재발급과 동시에 기존 발급한 헌혈증서는 사용할 수 없습니다.

또한 혈액원에 기증하거나, 의료기관에 혈액제제를 무상으로 수혈받기 위해 제출한 헌혈증서는 재발급 받을 수 없습니다.

헌혈증서 재발급은 온라인 신청 또는 직접 방문하시어 신청 가능하며, 신청 후 3일 이내 헌혈의집에 방문하시어 수령하셔야 하며, 3일 내 수령하지 않는 경우 재발급 신청이 자동 취소됩니다.

온라인 신청은 혈액관리본부 홈페이지 또는 헌혈앱 레드커넥트를 이용해주시기 바라며, 한마음혈액원에서 발급받은 헌혈증서는 한마음혈액원에서 재발급 신청 및 처리 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-05-11', 916, 'https://www.129.go.kr/faq/faq00.do?pageIndex=24#faq10601', '10bab43c17ebf562a212620b64faacf2a47b0db483d633f710715b6b365dfb4b'),
('14059', 'faq129-20261010', '보건의료', '건강보험정책', '차상위 본인부담경감대상자 지원사업 신청은 어떻게 하나요?', '본인 또는 대리인이 신청서 등 구비서류를 갖추어 거주지 관할 읍,면,동 행정복지센터에 신청하면 됩니다.

단, 주거가 일정하지 아니한 경우에는 실제 거주지역을 관할하는 읍,면,동 행정복지센터에 신청할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-05-11', 228, 'https://www.129.go.kr/faq/faq00.do?pageIndex=24#faq14059', 'f1971a0ea2d93b052ffd6591c4f200dfcca0e65ea0d61509f2420ad79f0d6d2c'),
('14060', 'faq129-20261010', '보건의료', '건강보험정책', '차상위 본인부담경감대상자 지원사업은 어떤 지원을 하는 사업인가요?', '차상위 본인부담경감대상자 지원사업은 의료급여와 유사한 수준으로 요양급여비용 본인부담금을 경감하는 사업입니다.

또한, 건강보험 지역가입자에 대한 건강보험료 전액도 국고에서 지원합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-05-11', 259, 'https://www.129.go.kr/faq/faq00.do?pageIndex=24#faq14060', 'ebc33c9fb7bf3ecc6cf236dc5c6aad37d5b02b0735b5b83f1ac374727e7339a9');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('17860', 'faq129-20261010', '보건의료', '건강정책', '금연클리닉은 어떻게 참여할 수 있나요?', '금연클리닉은 6개월 9차 이상의 금연상담서비스, CO 및 코티닌측정,니코틴보조제 등 금연지원서비스를 제공하며,

주민등록상 지역주민이 아니더라도 이용자의 접근성과 편의를 고려해 가까운 보건소 및 보건지소를 통해 참여할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-05-11', 35, 'https://www.129.go.kr/faq/faq00.do?pageIndex=25#faq17860', '3c794600dc1e96ed1b8c4090efe63194eeec1373b06317ed1655929c4b152484'),
('17861', 'faq129-20261010', '보건의료', '건강정책', '금연치료 지원사업이 무엇인가요?', '의사의 진료­상담과 금연치료의약품 및 니코틴보조제 구입비용을 지원하여 흡연으로 인해 발생하는 질환 및 사망의 위험을 예방하기 위한 제도로,

건강보험공단에 금연치료 참여 신청을 등록한 병,의원 및 보건소를 통해 1년에 3번(차수)까지, 8주에서 12주 기간 동안 6회 이내의 의사의 전문적인 진료­상담과 금연 치료 의약품 또는 니코틴 보조제 (니코틴패치, 껌, 정제) 구입비용의 일부를 지원합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-05-11', 33, 'https://www.129.go.kr/faq/faq00.do?pageIndex=25#faq17861', '088ee406b5c71c33698fcb5ead0e012587f2e4859668df5d37b05004157e134e'),
('2400', 'faq129-20261010', '보건의료', '건강정책', '금역구역에서 전자담배를 피울 경우 과태료가 부과되나요?', '「담배사업법」상 담배에 해당하는 전자담배의 경우 금연구역에서 흡연 시 과태료 처분이 가능하나, 의약품 및 의약외품으로 분류된 금연보조제일 경우 과태료 부과 대상이 아닙니다.

다만, 전자식 흡연욕구저하제는 ‘담배’에 해당하지는 않으나 외관상 액상형 전자담배 유사행위로서 타인에게 흡연 욕구를 유발할 수 있으며, 객관적인 입증자료를 통하여 해당 제품이 담배가 아님을 적발자가 직접 소명하여야 합니다.', '2026-05-11', 8436, 'https://www.129.go.kr/faq/faq00.do?pageIndex=25#faq2400', 'fa88878cfdc1c7fd913e2ea56e47543552ab17ff8c92f3bdbc55629044bed8be'),
('17880', 'faq129-20261010', '보건의료', '공공보건정책', '자동심장충격기를 구비한 건물 입구에는 안내 표시를 부착해야 되나요? 부착해야 된다면 별도 양식이 있나요?', '「응급의료에 관한 법률」제47조2제4항 및 동 지침(p.6)에 따라 자동심장충격기가 설치된 시설 등의 출입구 또는 여러 사람이 보기 쉬운 곳에 자동심장충격기 설치 및 사용 안내표시를 반드시 부착하여야 합니다.

안내판 파일은 응급의료정보제공 홈페이지에서 다운 받으실 수 있습니다.

※ 안내판 파일: www.e-gen.or.kr 접속 > 알림·소식 > 공지사항

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-05-08', 14, 'https://www.129.go.kr/faq/faq00.do?pageIndex=25#faq17880', '88b33c38171cd0708f65b82867f1b1a279a93aa2fbde9b1f05db0d4c34d930ca'),
('17900', 'faq129-20261010', '보건의료', '공공보건정책', '자동심장충격기 의무 설치기관 외의 기관에서도 점검하고 시스템에 등록하여야 하나요?', '의무설치기관 외의 기관에 대해서도 의무설치기관에 준하여 자동심장충격기를 관리하도록 권고하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2026-05-08', 8, 'https://www.129.go.kr/faq/faq00.do?pageIndex=25#faq17900', '863620b03d61066da6ecd1bae450df8354c45520e1e9ecb7cbee562151eae635'),
('17800', 'faq129-20261010', '노인장애인', '노인복지사업', '의료·요양 통합돌봄 비해당군으로 결정된 경우 다시 신청이 불가한가요?', '통합돌봄의 불필요한 신청 등을 방지하기 위해 사전조사 결과 비해당군으로 결정되는 경우 직전 신청일로부터 3개월 이내에는 신청이 제한됩니다.

- 예외적으로 대상자의 건강상태가 변화하여 복합적인 욕구가 발생했다고 판단되는 경우(사전조사 이후 퇴원 등)에는 신청이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-04-28', 72, 'https://www.129.go.kr/faq/faq00.do?pageIndex=25#faq17800', '45bf2e2fdcf3ade158a0e713e6b53c18752ab4b0dcdff104b6b6208819d2fa66'),
('17802', 'faq129-20261010', '노인장애인', '노인복지사업', '65세 이상 장애인이 통합돌봄 신청 시 노인과 장애인 대상 중 어느 절차에 따라 신청해야 하나요?', '65세 이상 및 65세에 도달하기 2개월 전 이내에 심한 장애인이 통합돌봄을 신청하시는 경우 ‘노인 절차’로 신청하시면 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-04-28', 123, 'https://www.129.go.kr/faq/faq00.do?pageIndex=25#faq17802', 'fc860f0e9f2f86582cd7173ebb9f803bdf8f7b96bb043e673fe3e61926f5c0f2'),
('17820', 'faq129-20261010', '노인장애인', '노인장기요양제도', 'A요양시설에 입소하고 있는 의료급여자가 B요양시설로 입소를 원할 경우 어떻게 해야 하나요?', '장기요양인정서와 개인별장기요양이용계획서의 급여종류에 ‘시설급여’로 표기가 되어 있는 장기요양 수급자로서 시설 간 이동을 원할 경우,

의료급여법에 따른 수급자는 급여이용 전에 급여비용을 부담하는 수급자 관할 지자체의 입소­ 이용 승인을 받아야 하며, 이용하고자 하는 기관을 변경하는 경우도 마찬가지입니다.

따라서 관할 지자체 담당자와 상담하여 해당 B시설 이용에 대한 지자체의 승인을 받은 후 A시설과의 계약을 해지하고 B시설을 이용할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-04-28', 63, 'https://www.129.go.kr/faq/faq00.do?pageIndex=25#faq17820', '8d2599ce3eea0a0f210df6d5e53195a885fa63aeb1b6e4d8ddcc4c925bb89735'),
('17801', 'faq129-20261010', '노인장애인', '노인복지사업', '장기요양 등급을 받은 사람도 통합돌봄을 이용할 수 있나요?', '65세 이상으로 장기요양 재가급여자(방문급여, 주야간보호 등 장기요양 재가급여수급자)도 신청을 통해 통합돌봄 대상자가 되면 이용할 수 있습니다.

다만, 장기요양 서비스와 중복된 서비스는 일부 제한될 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-04-27', 95, 'https://www.129.go.kr/faq/faq00.do?pageIndex=25#faq17801', '6a186584120d5e8c68f9a97e146d02cb78ad9b507d399868f93800557e594903'),
('16079', 'faq129-20261010', '인구아동', '지역사회서비스투자사업', '정신건강 심리상담 바우처 서비스와 중복 이용 가능한가요?', '정신건강 심리상담 바우처 서비스(구. 전국민 마음투자 지원사업)와 지역사회서비스 투자사업 중 아동­·청소년

심리지원 서비스, 아동­·청소년 정서발달지원 서비스, 정신건강 토탈케어 서비스, 성인 심리지원 서비스는 유사

중복 사업으로 동일 기간 내 중복 수혜 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-23', 138, 'https://www.129.go.kr/faq/faq00.do?pageIndex=25#faq16079', '120952732220f1e40daee7cb20c942e23bba6e525576a027475d72dcb0d5b084'),
('17522', 'faq129-20261010', '인구아동', '지역아동센터', '(야간연장돌봄) 야간 연장돌봄사업은 어떤 서비스인가요?', '야간 연장돌봄사업은 경조사, 맞벌이 부부 야간근무, 저녁시간 생업 등으로 돌봄 공백이 발생하는 경우, 아동을 안전하게 보호­돌봄하기 위한 공적 돌봄 서비스입니다.

기존 지역아동센터­다함께돌봄센터 이용 여부와 관계없이 긴급 상황 시 누구나 이용할 수 있습니다.

참여 센터의 운영 유형에 따라 월~금요일(주중) 18시부터 22시 또는 24시까지 이용 가능하며, 각 센터의 운영 시간 유형은 아동권리보장원 누리집(www.ncrc.or.kr) - ‘야간연장돌봄사업’ 및 해당 시도지원단 누리집 등에서 확인 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-22', 34, 'https://www.129.go.kr/faq/faq00.do?pageIndex=26#faq17522', 'c9ae6a12e09279b3035dad4e93508ad12f3d47b5489a0cdb55da023c414f4192'),
('17523', 'faq129-20261010', '인구아동', '지역아동센터', '(야간연장돌봄) 이용료는 얼마인가요?', '야간 연장돌봄 이용료는 1일 기준 5,000원 범위 내에서 센터별로 자율적으로 결정합니다.

기초생활수급자, 차상위계층 등 취약계층 아동은 이용료가 면제됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-22', 25, 'https://www.129.go.kr/faq/faq00.do?pageIndex=26#faq17523', 'b9bfbb369a5c88159f3b0547d2a7aa6a7cf430d2361d4004a05614078d3badd1'),
('17540', 'faq129-20261010', '인구아동', '지역아동센터', '(야간연장돌봄) 이용 가능한 연령 기준은 어떻게 되나요?', '야간 연장돌봄은 긴급상황 시 돌봄 필요한 6세부터 12세까지의 아동은 누구나 이용 가능합니다.

다만, 형제·­자매가 함께 이용하는 경우 등 불가피한 상황에서는 센터 판단하에 미취학 아동도 제한적으로

이용 가능합니다.

※ 기존 센터에 이용아동으로 등록된 중·고등학생의 경우 밤 10까지 이용 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-22', 17, 'https://www.129.go.kr/faq/faq00.do?pageIndex=26#faq17540', '4332137dcb87bb19827436645a97bd9bfcdaffe50ff418bbf0e4dc00e7f8bef2'),
('17541', 'faq129-20261010', '인구아동', '지역아동센터', '(야간연장돌봄) 신청은 언제, 어떻게 하나요?', '야간 연장돌봄은 이용희망일에 이용시간 기준 최소 2시간 전까지 신청이 원칙이고,

이용일 5일 전부터 사전 예약이 가능합니다. (당일 21시 50분 신청 마감)

- (예외) 2시간 전에 신청 못한 사유가 시·도 지원단(또는 돌봄센터)을 통해 소명되는 경우 당일 돌봄 가능

보호자 등이 전국 대표 전화번호(1522-1318)* 및 해당 돌봄센터로 신청 가능합니다.

* 지역에 소재한 시·도 지원단으로 연결

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-22', 13, 'https://www.129.go.kr/faq/faq00.do?pageIndex=26#faq17541', 'e96de8f1af7ffce7ff38c7bf60a92a2c9457c4e62072d69ec4143a39ef1202f0'),
('17760', 'faq129-20261010', '인구아동', '디딤씨앗통장', '통장 이월 발급은 어떻게 하나요?', '아동(미성년자인 경우 대리인 가능)이 통장 및 실명확인서류(주민등록증 등)를 지참하여 해당 지역 신한은행에

직접 이월 발급 신청할 수 있습니다.

더 자세한 사항은 보건복지상담센터 (국번없이 129)로 연락주시기 바랍니다.', '2026-04-22', 19, 'https://www.129.go.kr/faq/faq00.do?pageIndex=26#faq17760', 'f67606d93d6b914147b9730b1b6a6424333655983ac92d53d506a57f11a8e4f6'),
('1169', 'faq129-20261010', '인구아동', '디딤씨앗통장', '통장 분실 시 재발급 어떻게 하나요?', '아동(미성년자인 경우 대리인 가능)이 해당 시­·군­·­구의 지자체를 방문하여 통장 재발급을 신청하면 지자체에서

공문, 제신고 및 재발행신청서, 지자체 사업자등록증, 담당 공무원증 사본을 구비하여 해당 지역 신한은행에

재발급 신청합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-22', 6588, 'https://www.129.go.kr/faq/faq00.do?pageIndex=26#faq1169', '150d553b9129d1b2b9019c5643508481ac2d381730778f4a71d7796eb1bb9bc8'),
('7770', 'faq129-20261010', '노인장애인', '장애인복지사업', '발달재활서비스 제공기관도 장애인학대관련 범죄등 경력조회를 하여야하나요?', '2021년 6월 30일부터 「장애인복지법」 개정에 따라 제59조의3에 따른 취업제한 대상 범죄가 장애인 대상 성범죄 외에 장애인학대 관련 범죄로 확대되고, 취업제한 대상 기관이 장애인관련기관으로 늘어남에 따라 「장애아동 복지지원법」 제21조제3항의 발달재활서비스 제공기관의 운영자와 제공인력도 장애인학대관련 범죄나 성범죄 등의 결격사유를 확인하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-04-17', 2225, 'https://www.129.go.kr/faq/faq00.do?pageIndex=26#faq7770', 'a292b0e8ba5cf032f046a5f918b9d4fc9dfaa64d162222105b9ebbfbbfadc642'),
('11515', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인복지시설 일람표는 어디서 볼 수 있나요?', '보건복지부 홈페이지(www.mohw.go.kr) > 정보 > 법인/시설/단체 > “장애인복지시설 일람표”로 검색하시면 2025년 장애인복지시설 일람표 정보*를 확인하실 수 있습니다.

* 2024.12월말 기준

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-04-17', 666, 'https://www.129.go.kr/faq/faq00.do?pageIndex=26#faq11515', '9099061afd1e702b98998dcf898b5f48af11e36c9d6839828e0afa84b2701249'),
('17661', 'faq129-20261010', '사회복지', '기초생활보장사업', '교육급여 수급자에게 지원되는 교육활동지원비는 현금으로 주나요?', '교육급여 수급자에게 지원되는 항목으로는, 입학금 및 수업료, 고등학생 교과서대, 초중고 교육활동지원비가 있으며, 이 중 교육활동지원비는 현금이 아닌 바우처로 연 1회 지급됩니다.
따라서 모든 교육급여수급자는 온라인 홈페이지(e-voucher.kosaf.go.kr)를 통해 해당 바우처를 신청해야 합니다.

* 교육활동지원비 바우처 신청 문의 : 한국장학재단 콜센터(1599-2000)

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2026-04-10', 406, 'https://www.129.go.kr/faq/faq00.do?pageIndex=26#faq17661', 'bc025840b7a449aae4c4f58d4b517d9d9ab26b76a80c84d9f9accc3088c7e7fb'),
('2543', 'faq129-20261010', '보건의료', '공공보건정책', '장기, ­인체조직 기증희망등록 방법은 어떻게 되나요?', '기증희망등록은 인터넷, 모바일, 방문신청, 우편·FAX 중에서 선택하여 본인이 신청 가능합니다.

[장기,인체조직 기능희망등록 신청방법]

- (인터넷, 모바일) 국립장기조직혈액관리원 누리집(www.konos.go.kr)에서 공동인증서 또는 휴대폰 본인인증 등의 본인확인 절차를 거쳐 신청합니다.

* 기증희망등록 > 기증희망등록 신규신청 > 본인확인 > 신청인 주소, 성명 및 신청내용 입력 > 신청하기

- (방문 신청) 본인이 장기이식등록기관*을 방문해서 직접 기증희망자 등록신청서 작성

* 보건소, 의료기관 등 장기이식등록기관(국립장기조직혈액관리원 누리집에서 조회 가능)

- (우편·FAX) 본인이 신청서를 작성해서 국립장기조직혈액관리원(문의전화 02-2628-3602)으로

* 우편(서울특별시 중구 한강대로 416 서울스퀘어 17층) 또는 FAX(02-2628-3629)로 신청

※ 기증희망등록이란 본인이 장래에 뇌사 또는 사망할 때 장기·인체조직 등을 기증하겠다는 의사표시

※ 16세 미만의 경우에는 법정대리인 동의 및 관련 서류 필요

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-10', 5684, 'https://www.129.go.kr/faq/faq00.do?pageIndex=26#faq2543', '3e91c4cc9640d7ee4cde2d85265c4051ef1f456aada57f8ae9e97ce24e1656fd');
