INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('2663', 'faq129-20261010', '보건의료', '건강정책', '어린이집 건물 앞에서는 흡연을 할 수 없나요?', '국민건강증진법 제9조제6항에 따라 「유아교육법」에 따른 유치원 시설과 「영유아보육법」에 따른 어린이집 시설, 「초ㆍ중등교육법」에 따른 학교 시설의 경계선으로부터 30미터 이내의 구역도 금연구역으로 지정 되어 흡연시 과태료가 부과됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-09', 4455, 'https://www.129.go.kr/faq/faq00.do?pageIndex=27#faq2663', 'b3c76e565194496e917844d3bf6a34743cb819f84e758ed2ded8a4852aa7fd17'),
('9450', 'faq129-20261010', '보건의료', '공공보건정책', '응급환자이송업체가 허가받은 지역 외에서 환자 또는 응급의료종사자를 이송하여 올 수 있나요?', '응급환자이송업체의 미허가지역 영업 판단은 출발지를 기준으로 하며, 허가받은 시·도에서 ''환자 또는 응급의료종사자''를 타 지역으로 이송하는 것은 가능하나 타 시·도의 ''환자 또는 응급의료종사자''를 이송하기 위해 허가받은 시·도를 벗어나 응급환자이송업을 할 경우 「응급의료에 관한 법률」 제60조제2항제3호에 따라 5년 이하의 징역 또는 5천만원 이하의 벌금이 부과될 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-08', 564, 'https://www.129.go.kr/faq/faq00.do?pageIndex=27#faq9450', 'b5c14e9f1e47d75c6ee239eb218db39ea65a971502f6a007f7ebba4ebc82f0a8'),
('12858', 'faq129-20261010', '보건의료', '공공보건정책', '출동 및 처치기록을 전자제출 방식으로 제출하였는데도 별도 보관해야 하나요?', '네, 그렇습니다. 응급의료에 관한 법률 시행규칙 제40조제3항에 의해 구급차등의 운용자는 응급구조사등이 작성하여 제출한 출동 및 처치기록은 3년간 보존해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-08', 173, 'https://www.129.go.kr/faq/faq00.do?pageIndex=27#faq12858', '4c64ce3fa0e3c9d0e137a0aec7cb13c6df2ee907782acf553a904c8ee3539fdc'),
('13818', 'faq129-20261010', '보건의료', '건강정책', '공중위생영업자는 위생교육을 받아야 하나요?', '공중위생영업자는 매년 3시간의 위생교육을 받아야 합니다.

- 다만, 공중위생영업자가 직접 영업에 종사하지 않거나, 복수 사업장을 운영하는 경우 종업원 중 공중위생에 관한 책임자를 지정하여 위생교육을 이수할 수 있습니다.(이용업, 미용업은 제외)

- 1개의 영업장에 영업신고자가 2인이상(공동대표)인 경우 그 중 1인만 교육 이수하여도 인정이 가능합니다.(영업장 당 1명의 교육이수자 있어야 함)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-07', 42, 'https://www.129.go.kr/faq/faq00.do?pageIndex=27#faq13818', 'e2f30f02f018248009d8eadea8b9d016d56f465c11103fb4278a6d23281c9425'),
('17740', 'faq129-20261010', '보건의료', '건강정책', '종합미용업 영업자의 경우 위생교육을 어디에서 이수해야하나요?', '종합미용업 영업자의 경우 미용업 위생교육 실시단체 4곳 중 한 곳에서 교육을 이수하면 됩니다.

- (사)대한미용사회, (사)한국피부미용사회중앙회, (사)대한네일미용사회, (사)한국메이크업미용사회

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-07', 9, 'https://www.129.go.kr/faq/faq00.do?pageIndex=27#faq17740', 'fda16cbf1adea670088c9efe84e64d858d84e819fc1cc330208aed3bfddc31e9'),
('12604', 'faq129-20261010', '인구아동', '아동수당', '첫시행부터 연혁을 알고 싶습니다.', '아동수당은 2018년 9월부터 소득기준을 충족하는 6세 미만 아동에게 지원하기 시작하여

2019년 1월 소득기준을 폐지하였고, 2019년 9월부터 7세 미만, 2022년 1월부터 8세 미만으로 연령이 확대되었습니다.

아동수당법 개정(''26.3.)에 따라 2026년부터 2030년까지 대상 연령이 매년 1세씩 단계적으로 확대*됩니다.

* (''26) 9세 → (''27) 10세 → (''28) 11세 → (''29) 12세 → (''30) 13세

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-06', 122, 'https://www.129.go.kr/faq/faq00.do?pageIndex=27#faq12604', 'ecf7db786c4d379df55b3b2a65565587ee4a9d74abe91d14a3cdf5cf18f63e19'),
('1253', 'faq129-20261010', '인구아동', '아동수당', '지급 금액은 얼마인가요?', '아동수당은 대상아동 1인당 월 10만원을 지급하며, 지역에 따라 추가 지급됩니다.

- 수도권 10만원, 비수도권 10.5만원, 인구감소(우대)지역 11만원, 인구감소(특별)지역 12만원

또한 인구감소지역에서 지역사랑상품권으로 지급 시 1만원 추가 지급 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-06', 1993, 'https://www.129.go.kr/faq/faq00.do?pageIndex=27#faq1253', '47ef6edc5cf965227c6a93aaa76cf0a67630bd63a28097386b02b5221edd2ed2'),
('1172', 'faq129-20261010', '인구아동', '아동수당', '지급 대상은 누구인가요?', '아동수당은 2026년 기준 9세 미만 아동*으로 대한민국 국적 보유 및 주민등록번호가 정상적으로 부여된 아동에게 지급합니다.

* 아동수당 대상 연령은 2030년까지 매년 1세씩 단계적으로 확대

- 아동수당법 부칙 제2조에 따라 2017년생은 13세 생일 전달까지 신청 및 지급

- 복수국적자, 특별기여자, 난민인정자, 사회복지 전산관리번호 부여 대상아동, 법원등을 통해 출생신고 절차가 진행중인 출생 미등록 미혼부 자녀의 경우에도 신청 및 지급

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-03', 2258, 'https://www.129.go.kr/faq/faq00.do?pageIndex=27#faq1172', 'c38fa45e21fe501fc0503242759d6db3217bda14c8cca985ebb1248db99beb11'),
('1191', 'faq129-20261010', '인구아동', '아동수당', '언제까지 지원되나요?', '아동수당은 2026년 3월 아동수당법 개정에 따라 2017년 이후 출생 아동은 13세 생일 전달까지 지급됩니다.

* 예) ''17년 1월생은 ''29년 12월까지 지원 / ''19년 7월생은 ''32년 6월까지 지원

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-03', 1731, 'https://www.129.go.kr/faq/faq00.do?pageIndex=27#faq1191', 'bba7a551b3dc84763300050fd049c359f2cfa0de006fb3a68033f44b1ddc2297'),
('17663', 'faq129-20261010', '노인장애인', '노인복지사업', '의료,요양 통합돌봄은 어떤 제도인가요?', '의료·요양 등 지역 통합돌봄 사업은 노쇠, 장애, 질병, 사고 등으로 일상생활 수행에 어려움을 격는 분들이 살던 곳에서 건강하고 행복한 삶을 살아갈 수 있도록 의료, 요양 등 돌봄서비스를 통합적으로 제공하는 사업입니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-04-02', 107, 'https://www.129.go.kr/faq/faq00.do?pageIndex=27#faq17663', 'b92f476113a9a635e0fafa0fd82e5e8ba0ef472514e4b0f6f385f67e9507ea37'),
('17664', 'faq129-20261010', '노인장애인', '노인복지사업', '의료-요양 통합돌봄은 누가 이용할 수 있나요?', '의료-요양 통합돌봄은 노쇠·장애·질병 등으로 일상생활 유지에 어려움이 있어 의료·요양·돌봄 등의 복합적 지원이 필요한 65세 이상 어르신이 이용할 수 있습니다.

또한 65세 미만이어도 의료필요도가 높은 심한 장애인(지체, 뇌병변 등)도 신청이 가능합니다. 다만, 장애인은 장애인 통합돌봄 사업을 수행하는 지자체*에서만 신청이 가능하며, 향후 시행 지역이 확대될 예정입니다.

* 장애인 통합돌봄 시행 지자체는 복지부 통합돌봄 누리집(mohw.go.kr/integratedcare)에 게시

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-04-02', 92, 'https://www.129.go.kr/faq/faq00.do?pageIndex=28#faq17664', '2ac80b6da65abf85db291c286f2e8cc61c26631431c3b6b312a5a65469409f5d'),
('17701', 'faq129-20261010', '노인장애인', '노인복지사업', '65세 이상 노인으로 통합돌봄은 어디로 신청하나요?', '65세 이상 노인 통합돌봄은 대상자 주소지 관할 읍면동 행정복지센터 및 국민건강보험공단 지사에 방문, 우편, 팩스로 신청할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-04-02', 104, 'https://www.129.go.kr/faq/faq00.do?pageIndex=28#faq17701', '1259c2fe0b8c78420fe6760a8118e2b8b98acea40abca99856db9b70bb35aedc'),
('17720', 'faq129-20261010', '사회복지', '긴급지원사업', '수용시설별로 구금기간 합산이 가능한지?', '유치장과 교도소에 연속해서 구금된 경우라면 합산하여 산정 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-02', 37, 'https://www.129.go.kr/faq/faq00.do?pageIndex=28#faq17720', 'dd3861c7b335ecc580679312f5405ef92af237fadd55ffa968bf8b56e9d96b92'),
('2317', 'faq129-20261010', '보건의료', '건강보험정책', '조산아 및 저체중 출생아 외래진료비 본인부담 경감적용 기간이 어떻게 되나요?', '다음의 어느 하나에 해당하는 자 중 국민건강보험공단에 조산아 및 저체중 출생아 외래진료비 본인부담률 경감 대상자로 등록된 자로써

1) 조산아 : 출생일(주민등록상의 생년월일)로부터 아래의 재태기간 구분에 따른 기간까지

(가) 재태기간 33주 이상 ~ 37주 미만 : 5년 2개월

(나) 재태기간 29주 이상 ~ 33주 미만 : 5년 3개월

(다) 재태기간 29주 미만 : 5년 4개월

2) 저체중 출생아 : 출생제충 2,500g 이하로써 출생일(주민등록상의 생년월일)로부터 5년이 되는 날까지

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-02', 1804, 'https://www.129.go.kr/faq/faq00.do?pageIndex=28#faq2317', '364f27c02037564cd543b1319d89b0b4afd465c1ed39843dc2e6f64b3d16a1bc'),
('2070', 'faq129-20261010', '보건의료', '보건의료정책', '의료인이란 누구인가요?', '「의료법」 제2조에 따른 "의료인"이란 보건복지부장관의 면허를 받은 의사, 치과의사, 한의사, 조산사, 간호법에 따른 간호사를 말합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-04-02', 12611, 'https://www.129.go.kr/faq/faq00.do?pageIndex=28#faq2070', '11678427826de32dfe9333ba2f105e15d7536195f18c784ec8f08e580e9fc6fb'),
('17700', 'faq129-20261010', '노인장애인', '노인복지사업', '가족이 있어도 통합돌봄을 이용할 수 있나요?', '가족이 있어도 돌봄 필요도가 있는 경우 등 종합판정 결과에 따라 서비스가 제공될 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-03-31', 124, 'https://www.129.go.kr/faq/faq00.do?pageIndex=28#faq17700', '797aa7bdd947bcf97d83b50929bf924190686de69591767087922aa9d94c6ab5'),
('2881', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금을 신청할 때 필요한 서류는 무엇인가요?', '기초연금 신청시 제출해야하는 서류는 다음과 같습니다.

<필수 제출서류>

① 신분증(대리신청 시 위임장 및 대리인의 신분증 포함)

② ''사회보장급여 신청(변경)서''

③ ''소득­재산 신고서''

④ 본인 및 배우자의 ­''금융정보 등 제공 동의서''

<추가 제출서류> - 필수 제출서류 외 추가로 제출해야 하는 사유가 있는 경우에 한함

① 금융정보 등 제공사실 통보요구서 (금융정보 등 제공사실을 통보받기를 희망하는 경우에 한함)

② 기초연금 수급희망 이력관리 신청서

③ 사실(이)혼 관계 확인서

④ 임대차계약서

⑤ 사용대차 확인서

⑥ 계좌유효성 확인이 불가능한 경우(압류방지통장 등) 지급받을 계좌의 통장사본

⑦ 기타 수급(신청)자의 인적사항­소득­재산 확인에 필요한 서류

※ 예시) 자영업자 폐업 시 폐업신고서, 근로자 휴직 시 휴직증명서, 사업소득이 다르다고 주장하는 경우 소득금액증명원 등

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-03-18', 11273, 'https://www.129.go.kr/faq/faq00.do?pageIndex=28#faq2881', '315720b342e596785a075fa5d0777dcbf79adbd65ec95c53c1820162a10c3076'),
('6327', 'faq129-20261010', '인구아동', '출산정책', '(선천성이상아) 질병코드 Q로 진단받고 2회 이상 입원하여 수술 시 의료비 지원 가능한가요?', '선천성이상아 의료비는 출생 후 2년 이내에 선천성이상(Q코드)으로 진단받은 환아로서 2회 이상 입.퇴원하며 수술한 경우에도 700만원 한도 내에서 지원 가능 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-18', 2807, 'https://www.129.go.kr/faq/faq00.do?pageIndex=28#faq6327', '20732fb6c5f0d56fc420493929ac9719e359999ca7171083a0571cc13ab63873'),
('7370', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 금액은 어떤 기준으로 결정되나요?', '기초연금의 금액은 기준연금액과 국민연금 급여액 등을 고려하여 산정합니다.

기준연금액은 보건복지부장관이 그 전년도의 기준연금액에 통계청의 전국소비자 물가변동률을 반영하여 매년 고시합니다.

올해 기준연금액은 349,700원으로 적용기간은 해당 조정연도 1월부터 12월까지로 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-03-18', 1835, 'https://www.129.go.kr/faq/faq00.do?pageIndex=28#faq7370', 'a8e0b38718e6bd96d7be4c43bc5cfdc37dc2d1200c76f1aec62c990b0b5d96bd'),
('8398', 'faq129-20261010', '인구아동', '출산정책', '(보청기지원) 국민연금공단에서 국가 청각장애 진단을 받은 경우, 지원 가능한가요?', '국민연금공단의 국가 청각장애 진단을 받은 경우 난청환아 대상 보청기 지원은 불가합니다.

단, 청각장애 진단 기준에 해당되어 청각장애 등록 신청을 하였으나 ''불승인''된 경우에는 불승인 사유가 기재된 ''장애등급결정서'' 추가 제출 시 난청환아 대상 보청기 지원이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-18', 1721, 'https://www.129.go.kr/faq/faq00.do?pageIndex=28#faq8398', '1ec476b8b3fe901a541a0da9b5df9cb5962801c6c98967dab0652c4f5475a180');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('12879', 'faq129-20261010', '사회복지', '긴급지원사업', '2026년도 중도에 퇴사한 직원도 긴급지원 신고의무자 교육 이수를 확인해야 하나요?', '교육결과 집계는 26.12.31 이후이므로 퇴사자는 이수대상, 이수인원에서 제외 처리합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-18', 107, 'https://www.129.go.kr/faq/faq00.do?pageIndex=29#faq12879', 'd1d0c0fb760313cca9bb6042b305faaba01fe74f5416f5382e9a0efe9b7690f2'),
('13140', 'faq129-20261010', '인구아동', '출산정책', '(보청기지원) 난청이 있는 자녀가 보청기 지원을 받을 수 있나요?', '보청기 지원은 아래의 기준에 모두 충족하는 경우 보청기 지원이 가능합니다

- 난청 선별검사 및 확진검사 결과 난청으로 확진받은 만 12세(144개월) 미만 난청환아

* 단, 지원기간 내 1회 지원

-양측성 난청이면서 청력이 좋은 귀의 평균 청력역치가 40~59dB로서, 청각장애등급을 받지 못하는 난청이 있는 경우 보청기 2개 지원

- 나쁜 귀의 평균 청력역치가 55dB 이상이면서 좋은 귀의 평균청력역치가 40dB 이하인 경우 보청기 1개 지원

- (지원내용) 보청기 1개 또는 2개 (개당 135만원 한도)

[유의사항]

- 대학병원급* 병원에서 청성뇌간반응(ABR) 또는 청성지속반응검사(ASSR)를 최소 1개월 이상의 간격으로 2회 실시(ABR 반드시 포함)

*대학병원급 병원이란 1)영아에게 진정제 투여 후 ABR을 안전하게 시행할 수 있고, 2)연령에 맞는 언어발달 검사와 언어치료가 모두 가능한 병원을 의미함

- 가장 최근 실시한 2회 이상의 청력검사 결과에서 청력역치가 10dB 이내의 차이를 보이는 경우에 인정

- 만 4세 이상 환아의 경우, 청성뇌간반응검사(ABR) 1회와 순음청력검사(PTA) 3회 검사로 대체할 수 있으며, 순음청력검사(PTA)는 2~7일 간격으로 3번 시행하여야 함

- 보청기 처방을 받은 병원에서 보청기 구입. 착용 및 검수확인*을 원칙으로 함

*검수확인은 보청기 구입일로부터 1개월(30일) 이상 경과 후 보청기 착용 상태에서 청력개선 효과가 확인될 경우 발급

- 만 4세 이상 환아의 경우, 청성뇌간반응검사(ABR) 1회와 순음청력검사(PTA) 3회 검사로 대체할 수 있으며, 순음청력검사(PTA)는 2~7일 간격으로 3번 시행하여야 함.

- 보건소 신청일 기준 6개월 전후에 구입한 보청기에 대해 지원 가능

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2026-03-18', 36, 'https://www.129.go.kr/faq/faq00.do?pageIndex=29#faq13140', '8759dd0f1f54a9c1d21825e4d014adb920d044c35afad2a42fd7dd6182383ee2'),
('13557', 'faq129-20261010', '인구아동', '부모급여', '어린이집 이용으로 보육료 신청시 부모급여 차액 지원은 어떻게 되나요?', '부모급여 받는 아동이 어린이집 이용 시 보육료 바우처로 신청해서 받을 수 있습니다.

0세 아동이 어린이집을 이용하는 경우, 부모급여 지원금액과 부모보육료와의 차액을 현금으로 보호자에게 다음 달에 지급합니다.(아동 소재지 시­군­구에서 지급)

- 0세 아동 1인당 월 보육료(58.4만원) + 부모급여 차액(41.6만원)

- 1세 아동 1인당 월 보육료(51.5만원) + 부모급여 차액(없음)

* 0세인데 1세반으로 상위반 편성한 경우, 보육료 결제를 해야 그 다음 달에 6.9만원을 추가 지급받을 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-18', 377, 'https://www.129.go.kr/faq/faq00.do?pageIndex=29#faq13557', 'dc803c60325df14682bc8be59f30da1471d56905c389b06d1dcf32f6e32c12ec'),
('13577', 'faq129-20261010', '인구아동', '부모급여', '어린이집을 월중 퇴소하는 경우 부모급여 지원은 어떻게 되나요?', '부모급여(보육료) 받던 아동이 어린이집 퇴소하여 가정양육시 부모급여(현금)로 서비스 변경신청해야 변경된 부모급여(현금)로 지원합니다.

◎ 부모급여(보육료) → 부모급여(현금) 변경신청

- 신청일이 15일 이내인 경우(15일까지): 신규신청 자격 부모급여(현금) 지원, 기존 부모급여(보육료) 미지급

- 신청일이 16일 이후인 경우(16일부터): 기존 부모급여(보육료) 지급, 다음 달 신규 신청한 부모급여(현금)

자격으로 수당 지급

부모급여(보육료) 지원시 입­퇴소하는 월의 경우 일할계산된 보육료를 결제하시면 되며, 부모보육료(0세반 584천원, 1세반 515천원)와 어린이집에 지원된 금액 간의 차액은 입·퇴소 다음월에 수당을 지급받았던 기존 계좌로 지급 받으실 수 있습니다. 따라서 입·퇴소일 변동이 어려운 점 유의하시기 바랍니다. 특히, 퇴소시에는 퇴소희망일 7일 전까지 퇴소신청서를 통해 퇴소 의사를 미리 밝혀야 하며, 퇴소 의사를 표시한 이후에 퇴소일을 소급하실 수 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-18', 242, 'https://www.129.go.kr/faq/faq00.do?pageIndex=29#faq13577', 'b1528bc5972cd1a73cacd135bea1a0c6d03708eb3014c49ed9f1f0c632bd2de5'),
('17640', 'faq129-20261010', '인구아동', '기초연금사업', '농업소득도 소득으로 반영하나요?', '네, 기초연금 산정 시 농업소득도 소득*으로 반영합니다.

* 소득세법 제19조에 따른 농업(작물재배업 중 곡물 및 기타 식량작물 재배업은 제외한다. 이하 같다)ㆍ임업 및 어업에서 발생하는 소득

구 분 |
정 의 |

농업소득 |
경종업, 과수·­원예업, 양잠업, 종묘업, 특수작물생산업, 가축의 사육업, 종축업 또는 부화업 등과 이에 부수하는 업무에서 얻는 소득 |

임업소득 |
영립업·­임산물생산업 또는 야생조수사육업과 이에 부수하는 업무에서 얻는 소득 |

어업소득 |
어업과 이에 부수하는 업무에서 얻는 소득 : 어가(漁家)가 어업 경영의 결과로 얻은 총 수입에서 동 수입을 획득하는데 소요된 소모적 비용을 차감한 금액 |

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-16', 18, 'https://www.129.go.kr/faq/faq00.do?pageIndex=29#faq17640', '1e4405b00ed55d4e7dfcb707f13ac2a283b2507811e1d6db5933512ee20c4f0b'),
('2396', 'faq129-20261010', '인구아동', '사회복지시설', '사회복지시설 종사자에 대한 인건비 보조금 지급 연령 상한기준이 있나요?', '정부의 인건비 보조금 지급 연령 상한 기준은 아래와 같으며, 지급상한기준에 대해서는 각 지자체에서 사회통념 및 지자체 재정여건 등이 허용되는 범위 내에서 상향조정할 수 있고, 특히 농촌 취약지 등 지역적 특성 및 종사자 직군별 업무 특수성 등을 감안하여 지자체별로 개별 특례를 마련할 수 있습니다.

<인건비 보조금 지급 연령 상한기준>

- 시설장은 65세(단, 2002년 1월 1일부터 현재까지 재직 중인 설립자 및 설립자의 직계가족 1세대에 한해 70세)

- 종사자는 60세

* 조리원 65세

※ 기준을 초과하여 계속 근무하는 종사자의 인건비는 시설 자체적으로 지급해야 함

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-16', 5221, 'https://www.129.go.kr/faq/faq00.do?pageIndex=29#faq2396', '7c1439d6d5169b26843cb7c5607bb78384e85bf147ecc65c238f665ab844af5e'),
('4911', 'faq129-20261010', '인구아동', '출산정책', '(기저귀조제분유) 조제분유 지원대상이 어떻게 되나요?', '조제분유는 기저귀 지원을 받고 있는 대상자 중 아래 사유에 해당하는 경우 지원됩니다.

- 아동복지시설, 공동생활가정, 가정위탁보호, 입양대상아동, 한부모(부자,조손) 및 영아 입양 가정의 아동

- 산모의 사망, 질병으로 모유수유가 불가능한 경우

① 에이즈(B20, B21, B22, B23, B24, O98.7, Z21, Z20.6)

② HTLV감염(C91.5, Z22.6)

③ 마약 및 정신이상약에 의한 중독(T40)

­④ 분류되지 않은 마약 및 환각제에 의한 자의의 중독 및 노출(X62)

­⑤ 악성신생물(C00~C97)

* 항암화학요법 중인 경우만 모유수유 금지, 동 내용이 의사진단서에 기재된 경우만 지원

⑥ 유방의 악성신생물(C50)

* 항암화학요법을 포함한 치료를 받고 있는 경우 모유수유 금지, 동 내용이 의사진단서에 기재된 경우만 지원

⑦ 방사선 치료(Z51.0)

⑧ 항암제 치료(Z51.1)

⑨ 뇌하수체의 기능저하증(E23)

⑩ 정신장애(F00~F99)로 수유가 불가능하다고 의사가 판단하는 경우

- 산모의 방사성 요오드 치료, 의식불명, 뇌출혈 등으로 인한 의식 기능의 현저한 저하, 상반신 마비, 장기간(4주 이상) 입원치료, 희귀·중증 난치질환자로서 스테로이드 고용량 투여 또는 면역억제제 투여, 산모의 유방절제술•유방확대술 등으로 인한 유선손상, 질환으로 인한 지속적 약물 복용(3개월 이상)이 모유를 통해 영아에게 영향을 미치는 경우로 모유수유를 권장하지 않는다고 의사가 판단하는 경우

조제분유 지원 대상에 해당되는 경우 산모의 사망이나 질병을 확인할 수 있는 가족관계증명서 또는 의사의 진단서(소견서), 아동복지시설 등의 아동임을 확인할 수 있는 증명서 등 1부를 추가로 제출하셔야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-13', 1144, 'https://www.129.go.kr/faq/faq00.do?pageIndex=29#faq4911', 'a5ce2ddf919d481b275b677ac25e375a4efdb794258daa08300401d7903a7bde'),
('8830', 'faq129-20261010', '인구아동', '출산정책', '(첫만남이용권) 신청기간이 있나요?', '첫만남이용권의 신청기간은 별도로 없습니다.

그러나, 첫만남이용권의 사용 기간은 아동 출생일(주민등록일)부터 2년(아동의 두 돌 전 날)까지이므로, 이용권 지급 신청일로부터 30일 이내에 지급결정이 이루어지고, 신규로 국민행복카드발급을 위한 시간이 필요하므로 사용종료일 이전에 여유있게 신청해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-13', 1204, 'https://www.129.go.kr/faq/faq00.do?pageIndex=29#faq8830', '0a48261b6e8bb24867031aa309a0615418aa4894c7a6584d336483628d334ee9'),
('13281', 'faq129-20261010', '인구아동', '출산정책', '(선천성 대사이상 환아) 선별검사비를 지원 받을 수 있나요?', '선천성대사이상 선별검사비는 소득수준 관계없이 선천성대사이상 외래 선별검사비의 (일부)본인부담금을 지원합니다

- 출생 후 28일 이내에 실시하여 건강보험이 적용된 선별검사(D5190, D5191, D5192)를 대상으로 함

* 단, 출생일 기준 28일 이후에 실시하였으나 건강보험이 적용된 선별검사는 지원가능

- 1회 지원이 원칙이나, 유소견 검사결과에 따라 선별검사를 재실시한 경우에는 1회에 한하여 추가 지원 가능

- 검사비 외 항목(진찰료 등)은 지원 제외

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-13', 22, 'https://www.129.go.kr/faq/faq00.do?pageIndex=29#faq13281', '214c211469de38921cf1b1d10cfb7f0a38764184a784f2bd0c06bc6ec6b7d49c'),
('13966', 'faq129-20261010', '인구아동', '출산정책', '(임신사전건강관리) 부부가 모두 외국인인 경우 지원 가능한가요?', '내국인 배우자가 있는 외국인은 별도 비자 조건 없이 지원 가능하나, 부부가 모두 외국인인 경우 지원 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-13', 21, 'https://www.129.go.kr/faq/faq00.do?pageIndex=29#faq13966', '343d1b9dfe736ba07adfcda9f08646496ca5442cabab8ba0f54c7fb801dc8a87'),
('13976', 'faq129-20261010', '인구아동', '출산정책', '(임신사전건강관리) 난소기능검사 또는 부인과 초음파 중 한 가지 검사만 받더라도 지원 가능한가요?', '여성 가임력 검사시 난소기능검사(AMH)와 부인과 초음파 중 한가지만 검사받더라도 해당 검사 항목의 검사료 및 진찰료 실비에 한하여 지원 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-13', 19, 'https://www.129.go.kr/faq/faq00.do?pageIndex=30#faq13976', 'd8acee8e8d19bc9ab1788deb8cce374c3e99603d1162f9dcb2c4b8a87347d245'),
('14239', 'faq129-20261010', '인구아동', '출산정책', '(선천성 대사이상 환아) 크론병 환아는 어떤 지원을 받을 수 있나요?', '크론병 환아는 엘리멘탈 028, 모노웰, 모노웰펩토, 뉴케어 IBD 아미노, 뉴케어 IBD 플러스를 지원하며,

1) 최초 신청 시 집중치료기간(8주) 동안 월간 필요량의 100% 지원 (진단서 또는 소견서에 명시된 1일 필요량)

- 집중치료기간(8주)은 최초 신청 후 1회만 적용 가능. 최대 1일 8포(분말) 또는 16팩(액상) 지원되며, 최초 신청 시 2회(3주,5주)로 분할 지원

2) 집중치료기간(8주) 경과 후 추가 지원 필요 시, 1일 1포(월간 30포) 또는 액상 1일 2팩(월간 60팩) 지원 가능 (진료확인서 6개월마다 제출)

- 집중치료(8주) 종료 후 추가 지원은 원칙적으로 최대 1년까지 가능 (1년 경과 시 지원 종료)

3) 유전성 크론병의 경우는 1~2)이 적용되지 않으며, 월간 필요량(진단서 또는 소견서에 명시된 1일 필요량)의 50% 지원

- 유전성크론병 여부는 진단서 또는 소견서 상의 담당 의사 소견을 통해 확인 가능하며, 특수조제분유를 지원 받기 위해서는 6개월 마다 필요량, 필요기간 등이 기재된 소견서(또는 진단서)를 제출하여야 함

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-13', 11, 'https://www.129.go.kr/faq/faq00.do?pageIndex=30#faq14239', 'f449560527b6cbf6a90f9e90687be54622f889033c52a80c60145cff6e9083f5'),
('17620', 'faq129-20261010', '보건의료', '공공보건정책', '사업장 소재지와 의료기관 소재지가 다른 경우에도 외국인 근로자등 의료지원이 가능한가요?', '외국인 근로자의 사업장 소재지나 주소가 의료기관을 이용하고 지원을 받는데 영향을 주지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-13', 36, 'https://www.129.go.kr/faq/faq00.do?pageIndex=30#faq17620', 'ac39664e1fd2542601bfebfe7b835018e7a72379602ed5b6dcd21c02e843896f'),
('17621', 'faq129-20261010', '보건의료', '공공보건정책', '외국인 근로자의 국내 체류기간이 90일을 경과하지 않았으나 급성 질환이 발병된 경우에는 외국인 근로자등 의료지원이 가능한가요?', '국내 체류기간이 90일을 경과하지 않았더라도, 질병이 국내에서 발병하였다는 의사의 판단(의사의 소견서 필요)이 있고, 사업담당자가 의료비 국가지원이 반드시 필요하다고 판단하는 경우, 의료기관의 자체심의를 거쳐 지원 대상에 예외적으로 포함할 수 있습니다.

이 경우, 시도에 예외적 선정대상 및 사유를 자체심의 결과와 함께 보고해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-13', 39, 'https://www.129.go.kr/faq/faq00.do?pageIndex=30#faq17621', '1e372b315565e05933184acb032dc6a44cd6c171b14be3743a07a354469f91fb'),
('918', 'faq129-20261010', '인구아동', '출산정책', '(청소년산모의료비) 지원 대상은 누구인가요?', '''청소년산모 임신·출산 의료비 지원 신청 및 임신확인서''상 임신확인일 기준 만19세 이하 산모가 지원 대상입니다.

별도 소득기준은 없으나 주민등록말소자, 국외 출국자 등은 제외됩니다.

※ (연령산정 예시) ''06.2.10. 출생한 김산모가 청소년산모 임신­·출산 의료비지원을 받기 위한 임신확인일 기준 만 19세는 ­26.2.9 까지임

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-13', 2140, 'https://www.129.go.kr/faq/faq00.do?pageIndex=30#faq918', '7a956c1d68d7aac27bc6f76273bbf4cd6d58b687085c7efd935655282cd2790c'),
('921', 'faq129-20261010', '인구아동', '출산정책', '(청소년산모의료비) 사용은 언제까지 가능한가요?', '청소년산모 임신·출산 의료비 지원은 임산부 본인이 국민행복카드를 수령한 날(국민행복카드 소지자는 서비스신청 승인 다음날)부터 분만예정일(유산진단일, 출산 이후 서비스 신청한 경우 출산일) 이후 2년까지 사용 가능합니다.

* 예) 분만예정일이 2026년 5월 1일인 경우 2026년 4월 30일까지 사용 가능

사용 기간이 지나면 지원금 잔액은 자동으로 소멸되어 사용할 수 없게 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-13', 1380, 'https://www.129.go.kr/faq/faq00.do?pageIndex=30#faq921', 'a0c45ec905eb2bc7663a43d6f04ccec80fc83f314b45111f113d4fd67e03bba6'),
('1004', 'faq129-20261010', '인구아동', '출산정책', '(기저귀­조제분유) 국민행복카드가 없는데 어떻게 해야하나요?', '기저귀 ­조제분유 결제 가능한 국민행복카드는 BC카드사(또는 제휴은행 지점), 삼성카드사, 롯데카드사, KB국민카드사, 신한카드사 영업점을 직접 방문하여 신청하거나, 기저귀 ­조제분유 지원 신청 시 ‘국민행복카드 상담전화를 위한 개인정보 제공동의서’를 작성하여 함께 제출하시면 금융기관(카드사)의 카드발급 상담전화(TM)를 통해 본인확인 후 발급 가능합니다.

* BC카드 제휴은행：IBK기업은행, 수협은행, NH농협, 우리은행(우리카드), 하나은행(하나카드), iM뱅크(구.대구은행), BNK부산은행, BNK경남은행, 광주은행, 제주은행, 신협, 우체국

* 삼성카드 : 삼성카드사 전국 영업점 및 신세계 백화점

* 롯데카드 : 롯데카드 전국영업점 및 롯데백화점

* KB국민카드 : KB국민카드 전국 영업점, 전북은행 전 영업점

* 신한카드 : 신한카드사 전국 영업점

* 체크카드 발급 등으로 계좌개설이 필요한 경우에는 지원결정통지서를 지참하고 직접 전담금융기관 영업점을 방문하여 신청하여야 함

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-13', 1314, 'https://www.129.go.kr/faq/faq00.do?pageIndex=30#faq1004', '10971848cdf5a9495d5183ec94c56d5bbdda1a3c3726514a6962ab2b41215dd2'),
('13995', 'faq129-20261010', '보건의료', '건강정책', '영양플러스사업 참여 대상자는 누구인가요?', '영양플러스사업의 대상자는 사업을 수행하는 보건소의 관할 지역 내에 거주하면서 대상 분류, 소득 및 영양위험 기준을 모두 충족하는 자로 대상자 기준은 아래와 같습니다.

• 영아 : 생후 12개월까지

• 유아 : 1세 ~ 5세(72개월)까지

• 임신부 : 출산 후 6주까지

• 출산부 : 출산 후 6개월까지

• 모유수유부 : 출산 후 12개월까지

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-04', 81, 'https://www.129.go.kr/faq/faq00.do?pageIndex=30#faq13995', '5049efa7ec84d8eb5244c4c34154cc698c16bb3ec05ffa8fe13c215eee723ec3'),
('14054', 'faq129-20261010', '보건의료', '건강보험정책', '차상위 본인부담경감대상자 지원사업의 대상자 기준이 어떻게 되나요?', '차상위 본인부담경감대상자 지원사업의 세부 대상자 기준은 아래와 같습니다.

1. 희귀질환자·중증난치질환자·중증질환자

- 보건복지부장관이 고시하는 희귀질환, 중증난치질환 또는 중증질환을 가진 자

☞ ­ 「본인일부부담금 산정특례에 관한 기준­(보건복지부 고시 제2025-231호) 제9조에 따른 희귀질환자, 중증난치질환자, 중증질환(암환자, 중증화상환자), 결핵질환자 및 잠복결핵감염자 산정특례대상

2. 만성질환자

- 희귀질환, 중증난치질환 또는 중증질환 외의 질환으로 6개월 이상 치료를 받고 있거나, 6개월 이상 치료를 필요로 하는 자

☞ 희귀질환, 중증난치질환 및 중증질환자 중 건강보험 산정특례 미등록자 포함

3. 18세 미만인 자(18세가 도래하는 날이 속하는 해)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-04', 290, 'https://www.129.go.kr/faq/faq00.do?pageIndex=30#faq14054', '90d7469d8b20081af6b1eb8e270740c9be581b8c1da18433c29cf55763057d8f'),
('14218', 'faq129-20261010', '보건의료', '건강보험정책', '상병수당 신청을 하면 얼마를 지원받게 되나요?', '질병 또는 부상으로 인해 일을 하지 못한 기간 동안 아래와 같이 지원하며, 최대 150일까지 지원 가능합니다.

(2단계) 지역은 일 49,540원

(3단계) 지역은 직전 3개월 평균임금일액의 60% 지급(상한 68,100원~하한 49,540원).

실시간 소득파악이 어려운 건강보험 지역가입자 등은 日 49,540원 정액 지급

다만, 국민건강보험공단의 심사에 따라 기간이 결정되며, 대기기간 및 회사로부터 보수를 받은 날 등은 제외됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-04', 185, 'https://www.129.go.kr/faq/faq00.do?pageIndex=30#faq14218', '260af3913bfc24cc22ca337fbf6cdccd96952720f84b3ff8e17bd02cbb554665');
