INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('16681', 'faq129-20261010', '노인장애인', '장애인등록', '장애인으로 등록된 이후에 장애정도 재판정을 받아야 되는 경우도 있나요?', '「장애인복지법」 제32조제3항 및 동법 시행규칙 제7조에 따라 장애인등록 이후에도 등록장애인의 장애상태를 확인하고 그에 맞는 장애정도를 유지할 수 있도록 등록장애인에 대한 사후관리를 하고 있습니다.

등록장애인의 장애상태 확인을 위한 재판정은 다음 4종류로 구분합니다.

① (의무적 재판정) 장애상태 변화가 예상되어 정기적으로 재판정기한을 정하여 시행하는 재판정

② (직권 재판정) 부정수급 신고, 감사, 수사 등으로 지자체가 직권으로 대상자에게 요구하는 재판정

③ (서비스 재판정) 장애인연금, 장애수당 등을 신청인이 공단 심사 이력이 없는 경우 해당 서비스를 받기 위해 시행하는 재판정

④ (조정 재판정) 등록장애인이 장애정도 상향을 희망하여 신청하는 재판정

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-03-04', 198, 'https://www.129.go.kr/faq/faq00.do?pageIndex=31#faq16681', 'a2ef01c3c81189c7eb9e3d0bef0f9f82231f264871068e494ce9b3c1a4fb65d0'),
('16682', 'faq129-20261010', '노인장애인', '장애인등록', '등록장애인에 대한 의무적 재판정 대상자 및 시기는 어떻게 결정되나요?', '장애정도를 판정할 때에 향후 치료 등으로 장애 상태의 변화가 예상되는 경우에는 1년에서 9년 사이의 기간을 정하여 재판정을 받도록 하고 있습니다.

장애를 재판정 할 필요성과 시기는 국민연금공단에서 장애정도 심사시 「장애정도판정기준」에 따른 재판정 기준, 의사 소견 및 장애상태 변동 가능성 등을 종합적으로 고려하여 재판정 필요성, 재판정 주기 및 재판정 기한을 결정하고, 시군구(읍면동)에서는 의무적 재판정 대상 장애인에게 재판정 시기를 통지하고 안내합니다.

* 단, 2011.4.1. 이전에 등록된 장애인의 재판정주기와 기한은 「장애등급판정기준」에 따른 재판정 기준 적용 또는 장애진단서 상 진단의사 소견에 따라 정함

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-03-04', 145, 'https://www.129.go.kr/faq/faq00.do?pageIndex=31#faq16682', 'e632e9cb85a5af8d3692f16a3c97de8b7d99b8a5e7191cfaa3b879dc1c44a0af'),
('17600', 'faq129-20261010', '보건의료', '건강정책', '영양플러스사업에 참여할 수 있는 영양위험 요인은 어떤 것이 있나요?', '빈혈, 저체중, 성장부진, 영양섭취상태 중 한 가지 이상의 영양 위험요인 보유자가 대상이며, 임신부의 경우, 소득수준이 해당될 경우 영양위험요인 판정절차 없이 대상자로 선정 가능하다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-04', 24, 'https://www.129.go.kr/faq/faq00.do?pageIndex=31#faq17600', '54e8a9f49cb86b9060bec68a91b1a620dc0d43321e9ba86c1e5ccf42c9cdcc1f'),
('2399', 'faq129-20261010', '보건의료', '건강정책', '실내 흡연실(흡연부스) 제작 시 실외로 연결된 환풍 시설을 필수로 설치해야 하나요?', '「국민건강증진법」 시행규칙 별표 2의 제2호다항3)에 따라 흡연실의 연기를 실외로 배출할 수 있도록 환기시설을 설치하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-04', 3733, 'https://www.129.go.kr/faq/faq00.do?pageIndex=31#faq2399', 'f6fad54e07cc685b17aa9874d3f20f11190c5ae817ae66f07c9d657f5533fa4e'),
('2487', 'faq129-20261010', '보건의료', '건강정책', '금연구역 내에서 담배를 직접적으로 피우지는 않고, 담배에 불만 붙여 놓은 경우에도 과태료 부과가 가능한지?', '담배를 소지하고, 불을 붙인 경우 과태료 부과가 가능합니다.

다만, 불이 붙지 않은 담배를 물고만 있는 경우 과태료 부과가 어렵습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-03-04', 2155, 'https://www.129.go.kr/faq/faq00.do?pageIndex=31#faq2487', '7d0b2af7d01d6a70eab6bd562087d9dbc3a44e8ba530b2bba50a5200307b939e'),
('7051', 'faq129-20261010', '노인장애인', '장애인등록', '신규로 장애등록을 했는데 장애인등록증 발급은 어떻게 받나요?', '신규로 장애등록한 장애인은 주소지 읍·면·동 주민센터에 방문하여 장애인등록증 발급신청을 할 수 있습니다.

장애인등록증의 종류는 금융기능(신용카드 또는 직불카드)유무에 따라 ''신분증형 장애인등록증'', ''금융카드형 장애인등록증'' 두가지로 구분하고, 그 각각은 다시 하이패스 기능(고속도로 통행료 감면) 유무에 따라 ''일반(신분증형 또는 금융카드형)''과 ''통합(신분증형 또는 금융카드형)''으로 구분됩니다.

등록한 장애인은 본인의 희망에 따라 장애인등록증 4가지 종류 중 1종류를 발급 받을 수 있으며, 14세 이상 등록장애인* 은 추가로 모바일 장애인등록증 발급신청이 가능합니다.

* 미성년자, 지적·자폐성·정신 장애인이 모바일 장애인등록증을 신청하고자 하는 경우에는 법정대리인 또는 보호자의 동의를 받아야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-03-03', 6169, 'https://www.129.go.kr/faq/faq00.do?pageIndex=31#faq7051', '1832a4314d72f99078e2f626a10d5c863eb848e8caba7f89ed4208ac728ee5dd'),
('17580', 'faq129-20261010', '사회복지', '긴급지원사업', '주소득자가 유치장에 수감된 경우에도 구금시설 수용으로 볼 수 있는지?', '유치장도 구금시설에 해당되며, 주(부)소득자가 구금시설에 1개월이상 수감중으로 소득상실하여 생계곤란한지를 파악하여 지원여부를 결정할 수 있습니다.
※ 상기 위기상황 외에도 소득, 재산, 금융재산 기준을 충족하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2026-03-03', 33, 'https://www.129.go.kr/faq/faq00.do?pageIndex=31#faq17580', 'f4e39823eb954c5dfa6f0993ce67f0c84800b495e3dc09584c4fd3aec2257c62'),
('5290', 'faq129-20261010', '노인장애인', '노인복지사업', '노인맞춤돌봄서비스 수행기관의 전담사회복지사 자격기준은 어떻게 되나요?', '노인맞춤돌봄서비스 수행기관의 전담사회복지사는 중간관리자급 역량을 갖춘 자로 사회복지사업 근무경력*이 있는 사회복지사 자격증 소지자입니다.

* 「사회복지사업법」제2조제1호에 따른 사회복지사업 근무경력자 우대

* 사회복지사 자격증 소지 외 별도 부가기준은 지역별 여건을 고려하여 시·군·구 및 사업수행기관에서 조정 가능

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-27', 2592, 'https://www.129.go.kr/faq/faq00.do?pageIndex=31#faq5290', 'e670da3c54218ff653bcd685107cca87998f41e907d9b7658876e21141b6638d'),
('5590', 'faq129-20261010', '노인장애인', '치매(노인건강증진)', '치매공공후견 대상자 선정기준은 어떻게 되나요?', '치매공공후견대상자는 ''치매진단을 받은 자''로 아래의 조건을 참고하여 후견대상자로 선정합니다.

- 소득기준 : 기초생활수급자, 차상위 등 저소득자 및 기초연금 수급권자 우선 지원
- 가족기준 : 권리를 적절하게 대변하여 줄 가족이 없는 경우

* 가족이나 친족이 있더라도 학대, 방임, 자기방임의 가능성이 있는 경우 또는 치매환자가 후견인 지원을 요청하는 경우

- 욕구기준 : 후견인을 통한 도움을 원하거나 의사결정 지원이 필요한 사람

위 조건을 참고하여 후견대상자를 선정하되, 조건을 충족하지 않은 자라도 후견이 필요하다고 지자체장이 판단할 경우 선정이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)또는 치매상담콜센터(☏1899-9988)로 연락주시기 바랍니다', '2026-02-27', 2021, 'https://www.129.go.kr/faq/faq00.do?pageIndex=31#faq5590', 'e3c44147a8a33ad65f62a9ec94cad1d9cd1cba11efa9181693376ad1552dd57a'),
('12778', 'faq129-20261010', '노인장애인', '노인복지사업', '노인일자리 사업 중 현장실습 훈련 지원사업(시니어인턴십) 참여는 어떻게 하나요?', '현장실습 훈련 지원사업(구 시니어인턴십)은 60세 이상 구직 희망자의 취업을 지원하기 위해 기업에 인건비를 일부 지원하여, 기업의 시니어 고용을 유도하는 사업입니다.

만60세 이상으로 노인인력개발원 및 수행기관에서 진행하는 교육을 이수한 경우 참여 신청이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-27', 278, 'https://www.129.go.kr/faq/faq00.do?pageIndex=31#faq12778', 'b9e1f8806e6daa38c11ab69c2cdb7a740fd36f1563e7a06cef0f176b4ccd7f47'),
('1501', 'faq129-20261010', '노인장애인', '장애인활동지원', '학교 내에서 활동지원서비스 이용이 가능한가요?', '학교 내에서 수업시간 또는 휴게시간 중 활동지원사로 하여금 서비스를 제공하도록 하는 것은 원칙적으로 제한됩니다.

다만, 학교 내 보조인력이 부족하여 학부모가 활동지원사의 교내 지원을 요청할 경우 해당학교 개별화교육지원팀은 장애아동의 장애유형 .­정도 등 개인별 특성, 서비스 필요도 등을 고려하여 지원 필요 여부 및 지원내용, 지원시간 등을 결정한 후, 학교장의 승인을 얻어 지원할 수 있도록 하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-27', 2083, 'https://www.129.go.kr/faq/faq00.do?pageIndex=32#faq1501', 'b8be6974ba9babbbd2a5e9848258c09f9de009e3cd0e78c57b25fc1f947afe1a'),
('1496', 'faq129-20261010', '노인장애인', '장애인활동지원', '직장 내에서 활동지원서비스 이용이 가능한가요?', '장애인활동지원 수급자가 직장생활을 하고 있는 경우 직장 내에서는 근로지원인 또는 업무지원인 등의 서비스가 우선 이용되어야 하며 근로지원인 또는 업무지원인에게 지원받을 수 없는 경우 생업과 직접 관련된 업무를 제외하고서는 활동지원급여 이용이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-27', 1814, 'https://www.129.go.kr/faq/faq00.do?pageIndex=32#faq1496', '3df0b578e4f22caa511feec9fe6630dbd1485926dbbb96de6697a3690c638ce7'),
('6651', 'faq129-20261010', '보건의료', '공공보건정책', '성인 암환자 의료비지원사업의 지원대상은?', '보건복지부에서는 저소득층 암환자에게 의료비를 지원하여 경제적 부담을 줄이고 치료접근성을 높이기 위하여 암환자 의료비지원 사업을 운영하고 있습니다.

성인 암환자의료비지원사업의 지원대상은 의료급여수급권자 중 18세 이상의 전체 암환자와 차상위 본인부담경감대상자(건강보험증의 구분자 코드 C, E해당자)입니다.

※ 차상위 및 의료급여 암환자의 원활한 지원금 지급을 위해 건강보험가입자 하위 50%에 대한 지원은 ’21.6.30에 종료(유예기간을 두어 해당자에 한해 한시적으로 지원): 2026년도 암환자 의료비지원 사업의 성인 건강보험가입자 건강보험료 기준은 직장가입자 127,500원 이하, 지역가입자 60,000원 이하

지원암종 및 지원범위 등은 아래 ''바로가기''를 클릭하여 참고하세요.

☞ 바로가기 (https://www.cancer.go.kr/lay1/S1T559C563/contents.do)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-02-26', 6993, 'https://www.129.go.kr/faq/faq00.do?pageIndex=32#faq6651', 'bf71b9998356fcaef4638e6c22716919b136b6968d8d99b20490bb2d0454f3ff'),
('6722', 'faq129-20261010', '노인장애인', '치매(노인건강증진)', '치매환자 기저귀 등 물품 지원을 받을 수 있나요?', '치매안심센터에서는 치매환자의 상태에 따라 돌봄에 필요한 조호물품을 무상공급하여 치매환자 및 가족의 경제적 부담을 경감하고자 조호물품 제공 사업을 하고 있습니다.

ㅇ 대 상 : 치매안심센터에 등록된 재가(집에 거주하는) 치매환자

- 한달 이상 입소/입원 시, 해당 기간에 대해 물품 제공하지 않음

ㅇ 신청장소 : 치매안심센터 및 분소

ㅇ 지원품목 : 인지강화/인지재활 용품, 미끄럼방지 용품(매트 및 양말, 테이프), 약달력 및 약보관함, 보호대(고관절, 무릎, 허리), 기저귀, 요실금 팬티, 물티슈, 위생매트, 방수매트, 식사용 에이프런, 욕창예방용품(방석, 크림), 노린스샴푸 총 12품목 내에서 지자체가 상황에 맞게 선택하여 제공(*지자체별 보유 품목이 상이)

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-26', 8222, 'https://www.129.go.kr/faq/faq00.do?pageIndex=32#faq6722', 'e5e3c0609aacb3ed0bc169dbd29d32058b94ec04bbbcc9c04df3eda0dddfa7fb'),
('7030', 'faq129-20261010', '보건의료', '보건의료정책', '간호·간병통합서비스사업을 병동의 일부 병상만 참여 할 수 있나요?', '간호간병통합서비스는 병동 단위로 참여가 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-02-26', 1822, 'https://www.129.go.kr/faq/faq00.do?pageIndex=32#faq7030', '2d362fe565e3a55904abb49e7d508c2ad34d39b3d8b4fccdf1578d0c58bf6fdc'),
('12341', 'faq129-20261010', '노인장애인', '노인복지사업', '주변에 인가가 있어도 묘지를 설치할 수 있나요?', '묘지의 경우 20호 이상의 인가밀집지역, 학교, 그 밖에 공중이 수시로 집합하는 시설 또는 장소로 부터 500m 이상 떨어진 곳에 설치 가능합니다.

다만, 개인·­가족묘지에 한하여 위의 이격 거리기준을 ­300m 이상­으로 완화 적용 할 수 있습니다.

또한 묘지를 설치하려는 지역이 각 법령에 따른 장사시설 설치·조성 제한지역에 해당하지 않아야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-26', 456, 'https://www.129.go.kr/faq/faq00.do?pageIndex=32#faq12341', '132dc7ecc69abe7431a014e51529284cbf4b7bd5d8900537fb0c1e382808d16d'),
('13857', 'faq129-20261010', '보건의료', '보건의료정책', '간호간병통합서비스를 제공하는 병원은 어디에서 확인하나요?', '간호간병통합서비스 제공기관 검색경로는 다음과 같습니다.

① 국민건강보험공단 홈페이지(www.nhis.or.kr)

☞ 건강모아 > 검진기관/병원찾기 > 검진기관/병(의)원찾기 > 특성별 기관찾기 > ''간호간병통합서비스 병원 찾기'' 를 선택

② 건강보험심사평가원 홈페이지(www.hira.or.kr)

☞ 상단 ''의료정보'' > 특수운영기관 정보 > 특수운영기관 검색 박스의 특수운영 항목에서 ''간호간병통합서비스'' 선택 후 상세항목에서 ''간호간병통합서비스 제공기관'' 선택하여 검색

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-02-26', 223, 'https://www.129.go.kr/faq/faq00.do?pageIndex=32#faq13857', 'a9f59f45803524e25756af2aab8259e97d68cd7c9cc107fbfced05bf9e86dba7'),
('14000', 'faq129-20261010', '보건의료', '공공보건정책', '소아암환자 의료비 지원사업의 지원대상은?', '의료급여 수급권자, 차상위본인부담경감대상자(건강보험증 구분자코드 C, E 해당자) 및 건강보험가입자 중 소득과 재산기준이 지원기준에 적합한 18세 미만의 전체 암환자가 대상이 됩니다.

