('3621', 'faq129-20261010', '노인장애인', '노인복지사업', '기초연금을 수급받지 못하면 노인일자리 참여를 못하나요?', '노인일자리 중 공익형 일자리는 65세 이상 기초연금수급자, 직역연금 수급 저소득 가구* 어르신을 대상으로 선발기준표에 따른 고득점자 순으로 선정합니다.

* 직역연금수급자(배우자 포함) 중 보건복지부 장관이 정하는 기준을 충족한 자는 참여 가능

노인일자리 중 사회서비스형, 시장형 및 인력파견형 일자리 사업은 기초연금 미수급 어르신도 사업 특성에 따라 적합할 경우 참여하실 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-25', 3262, 'https://www.129.go.kr/faq/faq00.do?pageIndex=32#faq3621', 'b3af619034f9f8a726ecf174e2ed3920febbc6cacc19daa825cbce49c6fa4df6'),
('4737', 'faq129-20261010', '노인장애인', '노인복지사업', '노인맞춤돌봄서비스 대상자격이 어떻게 되나요?', '노인맞춤돌봄서비스의 대상자격은 돌봄이 필요한 65세 이상의 국민기초생활수급자, 차상위계층 또는 기초연금 수급자로서 유사 중복사업 자격에 해당되지 않는 경우 신청 가능합니다. (다만, 시군구청장이 서비스가 필요하다고 인정하는 경우 예외적으로 신청 가능)

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다', '2026-02-25', 5951, 'https://www.129.go.kr/faq/faq00.do?pageIndex=32#faq4737', '78c82703893ee66e21d98cbc4a0c66781566a0c64bb56cde832b27095653e2e2');
