INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('4752', 'faq129-20261010', '노인장애인', '노인복지사업', '노인맞춤돌봄서비스 수행기관의 생활지원사 자격기준이 있나요?', '노인맞춤돌봄서비스 수행기관의 생활지원사는 노인맞춤돌봄서비스 수행을 위한 역량과 의지를 갖춘 경우 참여 가능합니다.

또한, 사회복지사나 요양보호사 자격이 있으면 채용 시 우대될 수 있으며, 자격에 관한 별도 부가기준은 지역별 여건을 고려하여 시­군­구 및 지역수행기관마다 다를 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다', '2026-02-25', 8346, 'https://www.129.go.kr/faq/faq00.do?pageIndex=33#faq4752', '1f6aa092cdc1c689845e855fd48a4ccc94bc431d9515d20c19ef3d115616687b'),
('4753', 'faq129-20261010', '노인장애인', '노인복지사업', '노인맞춤돌봄서비스는 누가 신청할 수 있나요?', '노인맞춤돌봄서비스는 관할 읍면동 주민센터로 신청자격이 있는 노인(신청자)이 직접 신청하시거나, 신청자의 친족*, 이해관계인** 및 지역수행기관이 대리신청 할 수 있습니다.

* 친족 : 배우자, 8촌 이내의 혈족, 4촌 이내의 인척

** 이해관계인 : 친족을 제외한 이웃 등 그 밖의 관계인

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다', '2026-02-25', 2144, 'https://www.129.go.kr/faq/faq00.do?pageIndex=33#faq4753', 'f89af5276158479d63c01b24ce2b837a52c8997392f8e58a7b2d727f5b8c3820'),
('4952', 'faq129-20261010', '노인장애인', '노인복지사업', '노인맞춤돌봄서비스 수행기관의 시설기준은 어떻게 되나요?', '노인맞춤돌봄서비스 수행기관의 시설기준은 사업 수행을 위한 사무공간 및 상담공간과 프로그램실이 확보 되어야 합니다.

사무공간과 상담공간은 전용공간을 확보하여야 하며, 프로그램실은 전용공간 또는 별도 공간활용계획을 마련하여 최소 10인 이상이 활동 가능한 공간으로 프로그램의 목적에 부합할 수 있는지 여부로 판단합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-25', 2191, 'https://www.129.go.kr/faq/faq00.do?pageIndex=33#faq4952', 'df2f1bd508a6c84c384330262034a4be4ff0c7ff29bd3558acccacc7466d83ea'),
('5271', 'faq129-20261010', '노인장애인', '노인복지사업', '노인맞춤돌봄 대상자로 결정되면 제공기간은 어떻게 되나요 ?', '시·군·구에서 노인맞춤돌봄서비스 이용 자격이 승인되면 승인 익일로부터 1년간 서비스를 제공 받으실 수 있습니다.

또한 1년 도래 전 ''재사정''을 통해 서비스 제공여부를 다시 결정하게 됩니다.

※ ''퇴원환자 단기지원 서비스''는 별도 기준에 따라 1개월 이내 서비스를 제공하고, 필요 시 1개월 범위 내 연장이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-25', 1741, 'https://www.129.go.kr/faq/faq00.do?pageIndex=33#faq5271', '62e1d3c2dbc6e6e1df67eef2dd802e32791c38d5b239f3f4298518ea577e275b'),
('5676', 'faq129-20261010', '노인장애인', '노인복지사업', '노인맞춤돌봄서비스 제외 대상은 어떻게 되나요?', '노인맞춤돌봄서비스는 연령 및 소득기준 요건이 충족되어도 다음의 경우 유사중복사업에 해당자로 신청 대상에서 제외됩니다.

① 노인장기요양보험 등급자

- 장기요양 등급자가 장기요양을 포기하고 노인 맞춤돌봄서비스를 신청하는 것은 불가

(단, 장기요양 등급 유효기간 만료자는 신청 가능하고, 노인장기요양보험 등급포기자는 시장·군수·구청장이 서비스가 필요하다고 인정하는 경우 예외적으로 신청 가능)

② 가사·간병 방문지원사업 이용자

③ 국가보훈처 보훈재가복지서비스 이용자

­④ 장애인 활동지원 사업 이용자

⑤ 기타 국가 및 지방자치단체에서 시행하는 서비스 중 노인맞춤돌봄서비스와 유사한 재가서비스

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-25', 3271, 'https://www.129.go.kr/faq/faq00.do?pageIndex=33#faq5676', '3f9e5e204204f9727a46efc2e96d2762aefe5cd768d112408ebf5532e25d267c'),
('8491', 'faq129-20261010', '노인장애인', '노인복지사업', '병원 입원기간동안 노인맞춤돌봄서비스를 받을 수 있나요?', '노인맞춤돌봄서비스는 재가서비스를 원칙으로 하므로 병원 입원 시 간병서비스 제공이 불가하며, 해당 기간동안 서비스는 중지됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-25', 1347, 'https://www.129.go.kr/faq/faq00.do?pageIndex=33#faq8491', '98b0161f0ccceb43b8e2df0a92fb43a6cd9457064785a1dd67941bef501c72ba'),
('8970', 'faq129-20261010', '노인장애인', '치매(노인건강증진)', '주민등록 주소지 치매안심센터만 이용 가능한가요?', '주민등록등본상 주소지와 관계없이 이용자가 희망하는 지역의 치매안심센터 1개소를 선택하여 등록 및 서비스 이용이 가능합니다.

다만, 다중센터 이용은 불가하며, 치매공공후견사업은 주민등록상 주소지에서 신청가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-25', 967, 'https://www.129.go.kr/faq/faq00.do?pageIndex=33#faq8970', '8a3e19a91eeb7b8f5d83ff90d0588c8350d3f120d55fe95f67a861f254cffadf'),
('9113', 'faq129-20261010', '노인장애인', '노인복지사업', '''응급안전안심서비스''는 어떤 서비스인가요?', '지역사회 예방적 돌봄의 차원에서 노인 가구 및 장애인 가구에 게이트웨이(GW), 화재감지기 등을 설치하여 화재, 질병 등 응급상황 발생 시 119에 자동으로 신고하고 응급관리요원에게 알려 대상자가 응급상황에 신속하게 대처하는 체계를 구축하여 지원하는 서비스 입니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-25', 2676, 'https://www.129.go.kr/faq/faq00.do?pageIndex=33#faq9113', 'e5757d4550a6a2b67758ad262e08e97304d8173508b697a58fad641ad7538294'),
('12339', 'faq129-20261010', '노인장애인', '노인복지사업', '장례식장영업자 등에 대한 교육 면제 대상이 있나요?', '장례식장영업자(예정자 포함) 및 종사자의 준법의식과 역량 강화를 통한 이용자 안전 및 서비스 품질 제고를 위하여 매년 장례식장영업자 등에 대한 교육을 시행하고 있습니다.

다만, 다음과 같이 부득이하게 교육을 받기 어렵다고 인정되는 경우 당해 연도 교육을 면제할 수 있습니다.

- 해외체류·휴업 또는 폐업, 군복무, 육아휴직 등으로 인하여 당해 연도에 6개월 이상 관련 업무에 종사하지 않은 사람

※ 매년 12월 31일을 기준으로 해당일까지 6개월 미만으로 근로한 자를 말함

- 장례식장에서 염습, 행정, 상담 외 식당, 매점, 미화, 주차 등에만 종사하는 사람

※ 다만, 염습, 행정, 상담업무 겸직 시 교육 대상자

- 장례지도사 교육기관(대학과 대학원 포함)에 재학 중인 사람

- 본인의 질병이나 그 밖의 사유로 교육을 받기 어렵다고 보건복지부장관이 인정하는 사람

※ 연간 교육이므로 당해 연도 12월 31일 기준으로 그 기간에 교육이 어려운 자를 말함

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-25', 303, 'https://www.129.go.kr/faq/faq00.do?pageIndex=33#faq12339', '0858db2a8e066b354be155fc9ccd0528ae97c2bf7ffceca6804320142e27d2de'),
('12800', 'faq129-20261010', '노인장애인', '노인장기요양제도', '방문요양서비스 이용은 누가 할 수 있나요?', '방문요양서비스 이용 대상자는 아래와 같습니다.

- 장기요양급여 수급자(1~5등급)

- 심신이 허약하거나 장애가 있는 65세 이상의 자(이용자로부터 이용비용의 전부를 수납 받아 운영하는 시설의 경우에는 60세 이상의 자)로서 가정에서의 보호가 필요한 자

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-25', 242, 'https://www.129.go.kr/faq/faq00.do?pageIndex=33#faq12800', 'da7a08389fb852fa0610c030da45ad916c2ea91ce17d2906086bbbb1e746b31b'),
('1589', 'faq129-20261010', '인구아동', '기초연금사업', '국민연금을 받고 있으면 기초연금을 받을 수 없나요?', '국민연금을 수령하고 있다고 해서 기초연금을 받지 못하는 것은 아닙니다.

국민연금액을 소득으로 반영하며, 소득과 재산을 조사하여 소득인정액 요건을 충족하면 기초연금 대상자로 선정하여 기초연금을 지급할 수 있습니다.

다만, 수령하는 국민연금액이 기준연금액의 150%(''26년 기준 524,550원)을 초과할 경우 국민연금 가입기간이 반영된 국민연금 소득재분배급여액(A급여액) 등에 따라 수령할 수 있는 기초연금 급여액이 결정됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-20', 17127, 'https://www.129.go.kr/faq/faq00.do?pageIndex=34#faq1589', '653eba401f212760f11d822af5854c680c77de55d6ab382f40f303883f53a68b'),
('970', 'faq129-20261010', '인구아동', '출산정책', '(난임시술비) 지급 기준은 어떻게 되나요?', '난임부부 시술비 지급기준은 다음과 같습니다.

1. 지급 범위

- 시술시작일부터 임신낭을 확인(또는 혈액·소변검사일)한 시술종료일까지 소요된 시술비용에 대해 지급

2. 시술종류 및 시술비 지원 상한액

적용대상 |
지원한도 |

체외수정(1~20회) |
신선배아 |
최대 110만원 |

동결배아 |
최대 50만원 |

인공수정(1~5회) |
최대 30만원 |

* 난임부부 시술비 지원사업 외 추가 지원은 지자체별 상이할 수 있으므로 관할 보건소로 문의

3. 지급액 계산

(일부·전액본인부담금) 본인부담금 합계액의 90%에 해당하는 금액에 대해 지급 가능

(비급여) 배아동결비 최대 30만원, 착상유도제 및 유산방지제 각각 최대 20만원, 냉동난자 해동비 최대 30만원까지 지급 가능

(지원금 합계) 상기 본인부담금 합계액의 90% 및 비급여 금액의 합산액은 지급상한액을 넘을 수 없음

* 청구 항목에 따라 지급액이 전부 지급되는 것이 아님에 유의

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-02-20', 4732, 'https://www.129.go.kr/faq/faq00.do?pageIndex=34#faq970', '2a0b9c987097bb0e3b509e3972d6ca4d6ba87a47924895bf1e0eb6ba99362634'),
('17520', 'faq129-20261010', '노인장애인', '장애인등록', '14세 미만 장애인에 대해 모바일 장애인등록증 발급이 제한되는 이유는 무엇인가요?', '14세 미만인 장애인의 모바일 장애인등록증 발급을 위해서는 개인정보보호법 제22조2에 따라 법정대리인의 동의가 필요합니다.

하지만 현재 모바일 신분증 시스템에서는 법정대리인 및 그의 동의 확인이 불가하므로, 14세 미만 장애인에 대한 모바일 장애인등록증 발급을 제한하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-19', 29, 'https://www.129.go.kr/faq/faq00.do?pageIndex=34#faq17520', '8c66eab6d3137ab0be40d73cec0890e196e880234c96d3c146623e8e7cc330e4'),
('17521', 'faq129-20261010', '노인장애인', '장애인등록', '14세 이상 미성년 장애인의 모바일 장애인등록증은 부모 명의 휴대폰에 발급받을 수 있나요?', '14세 이상 미성년 장애인이라도 부모 명의 스마트폰에 모바일 장애인등록증을 발급받을 수 없습니다. 모바일 장애인등록증은 본인 명의 스마트폰 1대에만 발급받을 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-19', 27, 'https://www.129.go.kr/faq/faq00.do?pageIndex=34#faq17521', '22ca70abdeaf537030a45c14fb69676616d8f193e850e270fb18c4e54425cbf9'),
('3486', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금은 얼마를 받을 수 있나요?', '2026년 1월부터 기초연금액은 월 최대 349,700원 입니다.

다만, 국민연금액, 배우자의 기초연금 수급여부 등에 따라 기초연금액이 일부 감경될 수 있고, 인상된 연금액 차이로 인해 저소득 수급자와 일반 수급자 간 발생할 수 있는 소득역전을 최소화하기 위해 가구의 소득인정액에 따라서 기초연금액을 일부 감액하여 지급할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 문의주시기 바랍니다.', '2026-02-11', 3762, 'https://www.129.go.kr/faq/faq00.do?pageIndex=34#faq3486', 'a2acf068e2fdec5d41cada0e82bcb3e4f3f3d0ceea2b9435c88c919e152aaefd'),
('1515', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 선정기준이 어떻게 되나요?', '2026년 기초연금 선정기준액은 단독가구 2,470,000원 / 부부가구 3,952,000원 입니다.

소득인정액(소득평가액 + 재산의 소득환산액)이 선정기준액 이하에 해당될 때 지원 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-11', 3208, 'https://www.129.go.kr/faq/faq00.do?pageIndex=34#faq1515', 'cd68969af68e2ac19fbb3aa6e98068ebb0e0eace8495a4161574b93ddf3a342e'),
('9033', 'faq129-20261010', '보건의료', '건강정책', '대규모점포 사이의 연결지상 통로도 시설의 일부로 보아 금연구역에 포함되나요?', '대규모점포에서 건물과 건물 사이의 연결 지상통로는 대규모점포의 일부로서 국민건강증진법 제9조제4항제18호에 따라 금연구역 지정 대상입니다.

「유통산업발전법」이 대규모점포(제2조제3호)라는 개념을 설정한 이유는 일정 범위 내에 있는 점포의 집단을 일체로 보아 이에 대해 이 법 내에서 또는 다른 법령에서 특별한 취급 내지 규율을 할 필요가 있기 때문이며,

「유통산업발전법」제2조제3호가목 및 「유통산업발전법 시행령」제3조제2항에 따르면 둘 이상의 건물이 대규모점포를 구성하려면 건물 간의 가장 가까운 거리가 50미터 이내이고, 소비자가 통행할 수 있는 지하도 또는 지상통로가 설치되어 있어 하나의 대규모점포로 기능할 수 있어야만 합니다.

건물이 복수인 경우 이처럼 지하도나 지상통로는 대규모점포를 이루기 위한 필수요건이 되며, 「유통산업발전법 시행령」제3조제2항은 이러한 통로로 인해 비로소 여러 건물이 하나의 대규모점포로 기능하게 된다고 말하고 있는바, 여기에서 지하도나 지상통로를 대규모점포의 일부로 보아야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-02-05', 795, 'https://www.129.go.kr/faq/faq00.do?pageIndex=34#faq9033', '98f35a2e0b54d655eb28f6ddc1878dc3fa18bc0d8698909a7a55f0313ecdd721'),
('17500', 'faq129-20261010', '보건의료', '보건의료정책', '의료법 시행규칙 별표3에서 수술실을 갖춰야하는 대상 의원으로 전신마취 하에 수술을 하는 경우로 규정하고 있는데, 전신마취란 어떤 마취를 의미하는지?', '전신마취란 주로 외과(外科)의 큰 수술을 할 경우, 일시적으로 중추신경을 억제하여 온몸의 감각이나 의식을 마비시키는 마취의 한 종류로 환자의 자발호흡을 억제하는 수술이며,

환자의 자발호흡은 유지하면서 통증 경감을 위해 시행하는 정맥(수면)마취는 제외됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129) 로 연락주시기 바랍니다.', '2026-02-05', 46, 'https://www.129.go.kr/faq/faq00.do?pageIndex=34#faq17500', '98805e6fbbb1988979cf428a95dbe353f69537c027cdd7299787b7e13b1faea5'),
('9292', 'faq129-20261010', '보건의료', '건강보험정책', '병원에서 진단서 등 서류 발급 시 임신·출산진료비 바우처 사용이 가능한가요?', '임신·출산진료비 바우처는 진단서 등 서류 발급 시에는 사용이 불가하며, 진료비 및 약제·치료재료 구입비용으로만 사용이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-02-04', 814, 'https://www.129.go.kr/faq/faq00.do?pageIndex=34#faq9292', '0322d559d827730fc606384f2cd165f586f5fe18e3a44ce45152be4b580a866e'),
('17482', 'faq129-20261010', '보건의료', '건강보험정책', '임신·출산 진료비 바우처는 신청만 하면 사용이 가능한가요?', '아닙니다. 임신·출산 진료비 바우처 사용은 이용권(국민행복카드)이 있어야 가능하며, 이용권(국민행복카드) 발급은 카드사에서 신청하시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-02-04', 28, 'https://www.129.go.kr/faq/faq00.do?pageIndex=34#faq17482', '053e0620f0370cd94beec5bc1e8dd75017116890ddb8746ce842de0f4fc96a63');
