INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('14003', 'faq129-20261010', '노인장애인', '노인장기요양제도', '요양보호사가 될 수 없는 결격사유 기준은 어떻게 되나요?', '다음 각 호에 해당하는 사람은 요양보호사가 될 수 없습니다.

1. 「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」제3조제1호에 따른 정신질환자. 다만, 전문의가 요양보호사로서 적합하다고 인정하는 사람은 그러하지 아니하다.

2. 마약­·대마 또는 항정신성의약품 중독자

3. 피성년후견인

4. 금고 이상의 형을 선고받고 그 형의 집행이 끝나거나(집행이 끝난 것으로 보는 경우를 포함한다) 집행이 면제되지 아니한 사람

4의2. 금고 이상의 형의 집행유예를 선고받고 그 유예기간 중에 있는 사람

5. 법원의 판결에 따라 자격이 정지 또는 상실된 사람

6. 요양보호사의 자격이 취소된 날부터 1년이 경과되지 아니한 사람

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 문의주시기 바랍니다.', '2026-02-03', 76, 'https://www.129.go.kr/faq/faq00.do?pageIndex=35#faq14003', '091e65c12ee8331d006aafaa10492bb6bd7c04dae3aaebf0436e0341b401b1e7'),
('16119', 'faq129-20261010', '보건의료', '건강정책', '장애인 구강진료센터는 어디에 있나요?', '장애인구강진료센터 설치 현황은

보건복지부 누리집 접속(www.mohw.go.kr) > 정책 > 건강 > 구강건강 > ''장애인구강진료센터 상세보기''를 통해 확인 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-02-03', 64, 'https://www.129.go.kr/faq/faq00.do?pageIndex=35#faq16119', '81bd8f9e8f7f0c5ca2b6cfe4bca6ddf13aa04d1feac3102f39c14e09de3584c2'),
('16780', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인 자립자금 대여 추천통지서 유효기간이 정해져 있나요?', '장애인 자립자금 대여사업의 ''복지대상자 자금대여 결정(추천)통지서'' 유효기간은 결정일로부터 6개월입니다. 단, 장애인자동차 구입자금 목적으로 발급받은 통지서는 2개월*입니다.

* 2026년 국민은행의 신규 자립자금 대여 실행은 4월 1일부터 가능하므로, 2025년 12월~2026년 2월에 발급된 장애인자동차 구입자금용 추천통지서는 2026년 4월 30일까지 유효한 것으로 간주

장애인 자립자금 대여 대상자로 추천된 경우, 필요한 구비서류를 갖추어 유효기간 내 금융기관으로 자금대여 심사를 받으시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-02-03', 61, 'https://www.129.go.kr/faq/faq00.do?pageIndex=35#faq16780', '7bbc5f9f0ef3671c692519b157737e3f763871e115b45022a1249b51a7dfa408'),
('2551', 'faq129-20261010', '보건의료', '보건산업정책', '외국인환자유치란 무엇인가요?', '외국인 환자 유치란 외국인환자의 국내 의료기관 이용 증진을 위하여 진료예약·계약 체결 및 그 대리, 외국인환자에 대한 진료정보 제공 및 교통·숙박 안내 등 진료에 관련된 편의를 제공하는 활동을 말합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-02-02', 2780, 'https://www.129.go.kr/faq/faq00.do?pageIndex=35#faq2551', 'aeaf0a2cb6b97483e814a32b090c88de40048855bb9ce0c267ce0f30f4a05cdc'),
('4888', 'faq129-20261010', '노인장애인', '장애인활동지원', '장애인활동지원 특별지원급여는 언제 신청 가능한가요?', '장애인활동지원의 특별지원급여는 주소지 읍·면·동 주민센터로 신청하면 신청 내용에 따른 구비서류 등을 확인하여 수급요건에 해당하는 경우 지급됩니다.

특별지원급여 사유에 따라 신청시기는 다음과 같습니다.

- 출산 : 출산예정일 3개월 전부터 출산일로부터 6개월 이내

※유·사산의 경우 사유 발생일로 부터 1개월 이내

- 자립준비 : 시설 퇴소 예정일 2개월전부터 퇴소일로부터 6개월 이내

- 보호자일시부재 : 사유 발생 전 또는 발생한 날로부터 7일 이내

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-29', 2076, 'https://www.129.go.kr/faq/faq00.do?pageIndex=35#faq4888', 'a30d0bc966baef6d55f0547c539e47fea7eda19dc2f88d6e6dd5e5c2026ae28c'),
('5534', 'faq129-20261010', '노인장애인', '장애인활동지원', '장애인공동생활가정(그룹홈)에 입소한 장애인도 장애인활동지원 신청이 가능한가요?', '장애인공동생활가정(그룹홈)과 장애인단기거주시설의 경우, 「국민기초생활보장법 시행규칙」 제41조의3에 따른 보장시설에 포함되지 않으므로 해당 시설에 거주하는 장애인은 활동지원급여 신청이 가능합니다.

다만, 이중급여 제한 등으로 시설 내 활동지원급여 이용은 불가하여 시설 밖에서 이용한다는 시설장이 서명한 확인서(임의 양식) 등 증빙이 필요합니다.

(확인서는 당초계획과 변경이 없는 경우 6개월 간 유효하고, 변경사항이 발생하였거나 6개월이 경과된 경우에는 다시 확인서를 제출하여야 합니다.)

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-29', 2799, 'https://www.129.go.kr/faq/faq00.do?pageIndex=35#faq5534', 'fdc2e393dcf606cfdd6847964dd7e6d67e7f8934fa783e9c8124e200f20c2e18'),
('8490', 'faq129-20261010', '노인장애인', '노인복지사업', '노인맞춤돌봄서비스는 월 몇시간 이용할 수 있나요?', '노인맞춤돌봄서비스는 선정 조사 및 서비스 상담을 통해 사회-신체-정신영역의 돌봄 필요도에 따라 중점돌봄군, 일반돌봄군으로 선정하여 서비스가 제공됩니다.

* 중점돌봄군(월 20시간 이상~40시간 미만 직접서비스), 일반돌봄군(월 16시간 미만 직접서비스)

필요한 경우 연계서비스 및 특화서비스 제공 가능

또한 통합돌봄체계에 따라 의료기관 퇴원 후 집중 돌봄이 필요한 노인에게는 ''퇴원 후 돌봄군’으로 월 44시간 이하 퇴원환자 단기집중서비스를 제공받으실 수 있습니다. (2026년 신설)

더 자세한 시항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-29', 1312, 'https://www.129.go.kr/faq/faq00.do?pageIndex=35#faq8490', '05084f3169c2200e51a1ba2e2d485205296ba3cb365372050e513ee5123c0472'),
('8792', 'faq129-20261010', '노인장애인', '장애아동가족지원', '소득기준 초과해도 장애아돌봄서비스 이용이 가능한가요?', '연간 1,200시간 이내로 이용하는 경우, 기준중위소득 120% 이하 가정은 종전과 같이 본인부담 없이 무료로 이용이 가능하며, 소득기준 120%초과 가정은 이용료의 40%(시간당 5,120원)를 본인부담하여 이용이 가능합니다.

또한, 연간 1,200시간 초과 이용을 원할 경우 소득수준 상관없이 전액 본인부담(시간당 12,800원)으로 서비스 이용이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-29', 1199, 'https://www.129.go.kr/faq/faq00.do?pageIndex=35#faq8792', '92d2a9e1f18eab6a422cc9b1bca38b96cb793779acd397b47f8097dc813b4cca'),
('12578', 'faq129-20261010', '노인장애인', '장애인활동지원', '외국인도 활동지원사 교육 이수 시 채용 가능한가요?', '장애인 활동지원사 교육을 이수한 외국인의 경우에도「출입국관리법 시행령」제12조 체류자격 중 F-2, F-4, F-5, F-6, H-1, H-2인 경우에만 채용 및 근무가 가능합니다.

활동지원기관은 외국인을 활동지원사로 채용하려는 경우 외국인등록증 또는 거소신고증으로 체류자격 등 출입국 관계법령 위반 여부를 확인하여야 합니다.

또한 수급자의 권익 보호를 위하여 활동지원사로 채용하려는 외국인의 결격사유 해당 여부와 서비스 내용을 고려한 의사소통 가능 여부 등을 확인하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-29', 250, 'https://www.129.go.kr/faq/faq00.do?pageIndex=35#faq12578', 'b16fc2602a413511201f3f320a28c2be62f15ed0d85edfae25d21ddf65ea945f'),
('14620', 'faq129-20261010', '노인장애인', '장애인등록', '장애등록시 장애진단서 발급비용으로 지원되는 금액이 얼마인가요?', '장애정도심사를 위해 장애정도심사용 진단서를 제출하는 자가 지원 대상인지 여부를 확인한 후, 지원 대상(기초생활 수급자, 차상위계층 등)인 경우 영수증 제시 요청하여 금액 확인 후 지적·­자폐성­·정신장애 4만원, 그 외 장애 1만 5천원 한도 내에서 지급합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-29', 155, 'https://www.129.go.kr/faq/faq00.do?pageIndex=35#faq14620', '8b837d2eb9872c309e5e21fd631ab99ef09bfb0ed1d96a69ff8b992d07263acf'),
('15001', 'faq129-20261010', '노인장애인', '장애인등록', '장애진단서 발급비용도 압류방지통장으로 받을 수 있나요?', '2024년 11월 22일부터 저소득장애인 진단서 발급비 및 검사비 지원금이 압류방지통장으로 지급 가능합니다.

진단서 발급비 지원대상에 해당하는 등록 장애인이 이미 압류방지통장(신한은행, 농협은행, 경남은행, 기업은행, 아이엠뱅크,신협중앙회)을 보유하고 있는 경우에 압류방지통장을 이용하여 진단비를 지급받을 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다', '2026-01-29', 135, 'https://www.129.go.kr/faq/faq00.do?pageIndex=36#faq15001', '6abee3c005cd3210f52671fa4d52ac84a7f0844adeadc4afac5ec92fb4c8f3c3'),
('1494', 'faq129-20261010', '노인장애인', '장애인활동지원', '보장시설 퇴소 예정인데 장애인활동지원 사전신청이 가능한가요?', '­「국민기초생활보장법」 제32조에 따른 보장시설에 입소 중이나 2개월 이내 퇴소 예정으로 자립생활을 준비하고 있는 경우에는 퇴소 후 바로 활동지원을 이용할 수 있도록 퇴소 2개월 전에 활동지원급여를 사전신청할 수 있습니다.

사전신청 시 활동지원급여 사전신청 확인서와 기타 추가 입증서류를 제출해야 하고, 사전신청을 하였더라도 급여 이용은 시설 퇴소 이후에 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-29', 2060, 'https://www.129.go.kr/faq/faq00.do?pageIndex=36#faq1494', 'ef94d828916bbc951631b4d8927bebe4ca5043e5c1840a64c65632f7d53278ee'),
('1507', 'faq129-20261010', '노인장애인', '장애아동가족지원', '장애아돌봄서비스는 어떤 지원을 받을수 있나요?', '일정한 교육과정을 수료한 돌보미에게 연간 1,200시간 범위내에서 장애아동 가정 등에서 돌봄서비스를 지원 받을 수 있으며, 연간 1,200시간을 초과하여 사용하는 경우 전액 본인이 부담하여 이용할 수 있습니다.

더 자세한 사항은 보건복지상담센터 (국번없이 ☎129)로 문의주시기 바랍니다.', '2026-01-29', 2342, 'https://www.129.go.kr/faq/faq00.do?pageIndex=36#faq1507', 'e85597359dc81324d958ee8318d5751da9f693ec6c165b28319be540717879cc'),
('2861', 'faq129-20261010', '노인장애인', '노인장기요양제도', '장기요양기관 종사자에게 지급되는 장기근속 장려금이란 무엇인가요?', '장기요양 서비스 질 향상 및 종사자의 처우 개선 차원에서 1년* 이상 동일기관에서 하나의 직종으로 계속 근무하고 있는 종사자에게 장기근속 장려금을 지급합니다.

*3년 → 1년으로 완화(26년)

근속기간과 서비스 질 간의 상관관계가 상대적으로 큰 요양보호사, 사회복지사, 간호(조무)사, 물리(작업)치료사 등 수급자에게 직접 서비스를 제공하는 직종과 급식을 전량 직접 조리하여 제공하는 노인요양시설, 노인요양공동생활가정, 주.야간보호기관, 단기보호기관에 근무하는 영양사와 조리원을 대상으로 지급합니다.

또한, 26년부터 세탁물을 전량 자체 처리하는 노인요양시설에 근무하는 위생원도 장기근속 장려금 지급 대상이 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 문의주시기 바랍니다.', '2026-01-28', 6527, 'https://www.129.go.kr/faq/faq00.do?pageIndex=36#faq2861', 'e243d2e7095eb1a64b7d23b448d166994d33483071bd4a449e6739908b60958b'),
('3345', 'faq129-20261010', '노인장애인', '노인장기요양제도', '장기요양인정을 받은 경우 유효기간이 있나요?', '장기요양인정서의 유효기간은 2년으로 합니다.

유효기간 종료 예정자로 장기요양인정이 갱신된 경우 등급별 장기요양인정의 유효기간은 다음과 같습니다.

1. 장기요양 1등급 : 5년

2. 장기요양 2등급 ~ 4등급 : 4년

3. 장기요양 5등급 및 인지지원등급 : 2년

위 기준에도 불구하고 장기요양등급판정위원회에서 장기요양 신청인의 심신상태 등을 고려하여 장기요양인정 유효기간을 6개월 범위에서 늘리거나 줄일 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 문의주시기 바랍니다.', '2026-01-28', 6168, 'https://www.129.go.kr/faq/faq00.do?pageIndex=36#faq3345', '97b0ab4fc903d604eceb3894232fb65e9f28213a96ecc2c5c6ed1acd185f9f0f'),
('3346', 'faq129-20261010', '노인장애인', '노인장기요양제도', '외국인도 요양보호사 양성교육을 받을 수 있나요?', '외국인도 체류조건, 체류기한 등 출입국관리법령 등에 위반되지 않는 아래의 비자 소지자인 경우에 요양보호사 교육 이수가 가능합니다.

