('4896', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인 보조기기 교부 신청이 가능한 품목이 어떻게 되나요?', '장애인보조기기 교부사업은 저소득 장애인에게 일상생활에 필요한 장애인보조기기를 지원하는 사업입니다.

다음의 46개 품목의 보조기기 중 지원품목별 장애유형에 해당하는 장애인에게 교부가 필요하다고 판단되는 보조기기를 지원합니다.

① 시각 장애인 : 음성유도장치(리모컨), 음성시계, 영상 확대 비디오(독서확대기), OCR 장치 및 OCR 소프트웨어, DAISY 플레이어 및 전자책 리더, 키보드(모바일제어 특수키보드), 텍스트 음성변환(TTS)장치 및 소프트웨어, 촉각시계, 점자훈련용 보조기기

② 심장·호흡기 장애인 : 욕창 예방용 방석, 욕창예방 매트리스

③ 청각 장애인: 신호장치, 진동시계, 소리증폭기, 다기능 의사소통시스템(영상전화기)

④ 지체·뇌병변 장애인 : 보행차(롤레이터, 탁자형, 좌석형), 기립틀 및 기립을 위한 지지대 , 목욕의자, 휴대용 경사로, 이동변기, 독립형 변기 팔 지지대 및 등지지대, 환경제어장치, 안전손잡이, 유모차용 이동보조기기, 바닥 특수앉기 자세유지용 장치(피더시트), 목욕용 미끄럼 방지용품, 차량 내 착석을 위한 좌석과 방석 ­ 액세서리 ­ 개조용품(장애인용 카시트), 수동 조작용 팔 지지대, 전동칫솔(흡입기능이 있는 전동칫솔에 한함)

⑤ 지체·뇌병변·심장·호흡기 장애인 : 미끄럼 및 회전을 위한 보조기기, 장애인용 의복 및 신발, 휠체어 액세서리, 전동침대, 소변수집장치, 개인 비상 경보시스템(낙상알림기), 독서용 탁자, 책상 및 기립형 책상

⑥ 뇌병변·지적·자폐성·청각·언어 장애인 : 대화용장치

⑦ 뇌병변장애인 : 전자기기 작동 및 제어를 위한 보조기기용 액세서리(스위치)

⑧ 지체·뇌병변·지적·자폐성 장애인 : 기억 지원 보조기기

⑨ 지체·뇌병변·자폐성 장애인 : 음식 섭취용 보조기기(5개 품목)

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-28', 2431, 'https://www.129.go.kr/faq/faq00.do?pageIndex=36#faq4896', '2d681248bd1aca1cb532783b4a996988f029d7622521a4d22ceeb494b67595f0'),
('6339', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급복지지원 신고의무자 집합교육용 강의자료는 어디에서 받아볼 수 있나요?', '집합교육용 자료는 보건복지부 홈페이지*에서 내려받기 가능합니다.

* 보건복지부(www.mohw.go.kr) → 정보 → 연구/조사/발간자료 “2026년 긴급지원 신고의무 교육 동영상 게재 및 교육안내”

