('6512', 'faq129-20261010', '사회복지', '긴급지원사업', '2026년 초 A기관에서 신고의무자 교육을 받은 뒤, 몇 달 후에 B기관으로 이직한 경우 해당 교육을 다시 받아야 하나요?', '해당 종사자가 이전 기관(A)에서 2026년도 신고의무 교육을 이수하였다면 그 증빙자료를 변경된 근무지(B)의 기관장에게 제출할 경우, 변경된 근무지(B)의 기관장은 해당 종사자에 대한 2026년 긴급지원 신고의무 교육을 실시하지 않아도 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-28', 1281, 'https://www.129.go.kr/faq/faq00.do?pageIndex=36#faq6512', '71f8350ca318b3c30d6bd3bf7ab9972aea41f30b6428ada9909e6bcf29ae7ce3'),
('11155', 'faq129-20261010', '사회복지', '긴급지원사업', '2026년도 긴급지원 신고의무 교육은 언제까지 완료해야 하며, 결과보고서는 언제, 어디로 제출해야 하나요?', '2026년도긴급지원신고의무교육은’26. 12. 31.까지 이수 완료해야 합니다.

- 기관·시설장은 향후 중앙행정기관 및 지자체에서 안내한 신고의무 교육결과보고서 제출기한까지 교육 결과보고서를 작성하여 증빙자료*와 함께 해당 기관·시설을 관할하는 중앙행정기관 및 지자체 등의 사업부서**에 제출하시면 됩니다.

* (증빙자료) 집합교육 사진 및 서명부 또는 사이버교육 이수증 등

** (예시) 어린이집은 시·군·구의 어린이집 담당부서, 학원 등은 시·군·구의 교육지원청, 대학 등은 교육부에 제출

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-28', 678, 'https://www.129.go.kr/faq/faq00.do?pageIndex=36#faq11155', '42d15cc359bc7de850a084590feca558330b0fa2bc1e12affa2dcfdb18177271');
