('12357', 'faq129-20261010', '노인장애인', '장애아동가족지원', '언어발달지원 서비스는 언제까지 지원 받을 수 있나요?', '언어발달지원서비스는 시각·청각·언어·지적·자폐성·뇌병변 등록장애 부모 및 등록장애 조손가정의 12세 미만의 비장애 아동에게 언어발달진단서비스, 언어재활서비스 등을 지원하는 제도로 지원 대상자의 연령이 12세가 되는 달까지 지원합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-28', 379, 'https://www.129.go.kr/faq/faq00.do?pageIndex=37#faq12357', '9a419891a792075e4757b74c68ce817c91432792a139ad1b8eb7d9c552a4fa72'),
('1526', 'faq129-20261010', '노인장애인', '장애인활동지원', '의료기관에 입원 중인 경우 활동지원급여 이용이 가능한가요?', '장애인활동지원 수급자가 의료기관에 60일을 초과하여 입원한 경우에는 활동지원급여 이용이 제한됩니다.

입원기간은 퇴원 후 질병의 악화 또는 재발이나, 다른 질병에 의한 입원 등 특별한 사정이 없는 한 당해년도 전·후의 입원기간을 가산하여 산정합니다.

다만, 입원기간이 60일 이내인 경우에는 의료기관 내에서 활동보조 서비스 범위내의 급여 제공은 허용되며, 의료행위와 연관된 급여는 제공할 수는 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-28', 3520, 'https://www.129.go.kr/faq/faq00.do?pageIndex=37#faq1526', 'cba3738e8638890d6ad240d8c7184ac57f8a1c88bfceaaee2f3af370cd6dbe06'),
('1356', 'faq129-20261010', '노인장애인', '노인장기요양제도', '치매전담형 장기요양기관은 누가 이용할 수 있나요?', '치매전담형 장기요양기관 이용 대상자는 다음과 같습니다.

1. 의사소견서에 ''치매상병''이 기재되어 있거나, 최근 2년 이내 치매진료내역이 있는 2등급*~4등급 수급자

* 2등급자 중 노인장기요양보험법 시행령 제6조제1호에 따라 심신상태나 거동상태 등이 현저하게 불편한 자는 제외

2. 5등급 수급자

3. 인지원등급 수급자(주야간보호 내 치매전담실에 한함)

더 자세한 사항은 보건복지상담센터 (국번없이 ☎129)로 문의주시기 바랍니다.', '2026-01-28', 1495, 'https://www.129.go.kr/faq/faq00.do?pageIndex=37#faq1356', '476ff4ab35bf94a0de77dbf8d7ac770c697d1f426e6bc2fec459a220e5b99ef6'),
('916', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급생계지원의 지원기간은 어떻게 되나요?', '긴급생계지원은 위기상황에 처한 분들에게 일시적으로 신속하게 단기 지원을 통해 도움을 드리고자 하는 제도로 지원이 적정하다고 확인되면 3회(3개월) 생계지원을 받을 수 있습니다.

다만, 3개월의 지원에도 불구하고, 위기상황이 계속되어 추가연장이 필요하다고 인정하는 경우에는 긴급지원심의위원회의 심의를 통해 3개월 범위내에서 생계지원을 추가 연장 지원을 받을 수있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-28', 21462, 'https://www.129.go.kr/faq/faq00.do?pageIndex=37#faq916', '0f86c6ca3804e62f405c670e04d5e2cd41ed60a312a04ef9467e3545c3374038'),
('4891', 'faq129-20261010', '노인장애인', '장애인활동지원', '장애인활동지원 특별지원급여의 월한도액은 얼마인가요?', '장애인활동지원의 특별지원급여 사유에 따른 월 한도액은 다음과 같습니다.

- 출산의 월한도액은 1,385,000원

- 자립준비의 월한도액은 349,000원

- 보호자일시부재의 경우 월한도액은 349,000원

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 1847, 'https://www.129.go.kr/faq/faq00.do?pageIndex=37#faq4891', '8d55f7525a42c4592c6e7aec2190f54ccbac3cdabb357dff5c7a7d01db7b367a'),
('5270', 'faq129-20261010', '노인장애인', '장애인연금(수당)', '장애인연금 선정기준액은 어떻게 산정되나요?', '장애인연금 선정기준액은 보건복지부장관이 매년 중증장애인 및 그 배우자의 소득·재산 수준과 생활실태, 물가상승률 등을 고려하여 전년도 12월31일까지 결정·고시하고, 당해연도 1월1일부터 12월31일까지 적용하게 됩니다.

2026년 장애인연금 선정기준액은 단독가구 140만원, 부부가구 224만원 입니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 2717, 'https://www.129.go.kr/faq/faq00.do?pageIndex=37#faq5270', 'ea45b696aca2dc0d665caaea961ebbae74a8c2c9e08b6198648097e5d98ffeec'),
('6739', 'faq129-20261010', '노인장애인', '노인장기요양제도', '장기요양 가족휴가제가 무엇인가요?', '장기요양 가족휴가제란 1,2등급 수급자 또는 치매가 있는수급자를 돌보는 가족이 여행 등으로 일시적 휴식이 필요한 경우 월 한도액과 관계없이 1년에 12일 이내에 단기보호 또는 종일 방문요양을 이용할 수 있는 제도입니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 3676, 'https://www.129.go.kr/faq/faq00.do?pageIndex=37#faq6739', '71344abfcc63dae28eca6f09cd722ea1c7ce0cb007416d09c507c7458d30f550'),
('9131', 'faq129-20261010', '노인장애인', '장애인활동지원', '장애인 활동지원사도 보수교육을 받아야 하나요?', '활동지원기관은 활동지원사 역량 강화와 급여 질 향상을 위해 매년 소속 활동지원사를 대상으로 주기적인 보수교육을 실시하여야 합니다.

또한, 활동지원사 교육 이수 후 2년이상 서비스 제공이력이 없었던 사람(활동지원사로 근무하였다가 2년이상 서비스 제공이력이 없었던 사람 포함)을 활동지원사로 채용할 경우 4시간의 보수교육 실시 후 서비스를 제공하도록 하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 1718, 'https://www.129.go.kr/faq/faq00.do?pageIndex=37#faq9131', 'd1e1b0d36b3967f8a4f644df4addd0fd7aa3367ea646caf13b511bd8f563e909'),
('10515', 'faq129-20261010', '노인장애인', '장애인연금(수당)', '장애인연금은 누가 받을 수 있나요?', '장애인연금은 18세 이상의 「장애인연금법」 제2조제1호에 따른 중증장애인(종전 1급, 2급, 3급 중복장애*)이 신청 가능하고, 본인과 배우자의 소득과 재산을 조사해서 선정기준액 이하일때 지원 가능합니다.

* 종전 3급 중복장애: 종전 3급에 해당하는 장애와 추가 장애를 하나 이상 가진 자

2026년 장애인연금 선정기준액은 단독가구 140만원, 부부가구 224만원 입니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 1009, 'https://www.129.go.kr/faq/faq00.do?pageIndex=37#faq10515', 'ad30405426226be54c6ef0f760571aeaddaf47e5f41419762dcb9c2cbb719c7a'),
('11414', 'faq129-20261010', '노인장애인', '장애인등록', '장애인등록증으로 지역 상관없이 지하철 무임승차를 바로 할 수 있나요?', '2023년 4월 1일부터 전국호환 교통카드 기능이 있는 장애인등록증으로 전국 지하철 탑승구에서 등록장애인이 무임태그하고 지하철을 이용할 수 있습니다.

교통카드 기능이 있는 장애인등록증은 금융기능(신용, 직불)이 있는 일반 금융카드형 또는 하이패스 기능 추가되어 있는 통합 금융카드형을 발급 받으면 전국 지하철 무임승차가 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 1870, 'https://www.129.go.kr/faq/faq00.do?pageIndex=37#faq11414', 'bda9196443e674cb26a80cc763eddef206ee25ca810544be6c391d285826d665'),
('12560', 'faq129-20261010', '노인장애인', '장애아동가족지원', '발달재활서비스 대상자의 본인부담금을 제공기관에서 지원해줄 수 있나요?', '발달재활서비스 대상자의 바우처 지원액(총 구매력 월 26만원)에서 소득기준에 따라 본인부담금은 면제~최대 8만원까지 발생합니다.

발달재활서비스 바우처의 해당 본인부담금은 국비, 지방비 및 제공기관에서 지원할 수 없도록 규정하고 있습니다.

따라서 소득기준에 따라 정해진 본인부담금을 제공기관에서 추가 지원할 수 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 408, 'https://www.129.go.kr/faq/faq00.do?pageIndex=38#faq12560', '6c1369727ffc4ce1880b05532fd9023d184219c0fb5c309292580cc146dfbc8e'),
('12599', 'faq129-20261010', '노인장애인', '장애인활동지원', '2인 이상의 활동지원사가 동일한 이용자에게 동시에 서비스를 제공할 수 있나요?', '활동지원 수급자의 신체·정신적 상태 또는 목욕 도움 등 급여 내용 상 활동지원사 1인 만으로 급여제공이 어려워 수급자 등의 신청에 따라 동일 기관의 활동지원사 2인이 활동지원급여를 제공할 수 있습니다.

급여비용은 활동지원사별로 각각 산정할 수 있으며, 각 활동지원사별로 1회 방문 당 3시간 범위 내에서 급여비용의 100%로 산정합니다. 이 경우 수급자 등의 동의를 얻고 그 내용을 활동지원급여 제공기록지 등에 기재하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 335, 'https://www.129.go.kr/faq/faq00.do?pageIndex=38#faq12599', '7eb28fdb0d6ef77372badfcfd471f091c68d386d7401e1481cc9dddaf89e8d51'),
('12617', 'faq129-20261010', '노인장애인', '장애인활동지원', '장애인활동지원 가산수당 대상이 어떻게 되나요?', '서비스 이용에 어려움을 겪는 것으로 인정되는 최중증 수급자에게 서비스를 제공하는 활동지원사의 급여비용에 대해 추가적인 수당을 지원해주는 제도입니다.

【가산수당 대상】

1) 1순위 대상 수급자: 서비스지원 종합조사 결과 기능제한 영역 합산점수가 성인 426점 이상, 아동 327점 이상인 사람

2) 2순위 대상 수급자: 다음 어느 하나에 해당되고 2개월 이상 활동지원사 연계가 되지 않거나 3개월간 6회 이상 활동지원사가 교체된 수급자 중 예산 등을 고려하여 지자체에서 결정

- 기존 인정점수 440점 이상으로 1순위 대상자였으나 갱신 후 1순위에 미해당

- 발달장애인으로 공격성, 폭력성, 돌발행동 등 행동장애가 심하여 활동보조서비스 제공에 현저한 곤란이 있음

- 와상, 사지마비 및 수급자 특성 등으로 대소변 처리, 목욕, 이동 등 활동보조서비스 제공에 현저한 곤란이 있음

- 기타 이에 준하는 사유가 있다고 시·군·구에서 인정

【가산수당 금액】

① 매일 일반적으로 제공하는 경우 -가산수당 3,300원

② 22시 이후 6시 이전 심야에 제공하는 경우-가산수당 4,950원

③ 관공서의 공휴일에 관한 규정에 의한 공휴일과 근로자의 날에 제공하는 경우-가산수당 4,950원

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 607, 'https://www.129.go.kr/faq/faq00.do?pageIndex=38#faq12617', '3fe261383a3ac984c561a0d9f538d47a2c49cb50ed645a026b290286393e82a3'),
('12980', 'faq129-20261010', '노인장애인', '장애인등록', '사망한 장애인에 대해서도 장애인증명서 발급이 가능한가요?', '사망장애인의 가족이 연말정산 등을 위해 전국 읍­면­동 장애인 담당부서에 신청하면 신청자의 가족관계 등을 확인하여 장애인증명서를 발급 받을 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 219, 'https://www.129.go.kr/faq/faq00.do?pageIndex=38#faq12980', 'a0496aa4ed84aa93607137271c2b26c2972dbd96ac9cee3b57a74933fabaac3d'),
('14031', 'faq129-20261010', '노인장애인', '장애아동가족지원', '발달재활서비스는 본인부담금이 있나요?', '발달재활서비스는 장애아동 1인당 바우처지원액과 본인부담금 포함해서 월 26만원을 바우처로 지원합니다.

본인부담금은 서비스 대상자의 소득기준에 따라 다음과 같이 차등해서 결정됩니다.

- 기초생활수급자(생계 또는 의료급여): 본인부담금 면제 (바우처 지원액 26만원)

- 차상위계층 : 본인부담금 2만원 (바우처 지원액 24만원)

- 차상위계층 초과 ~기준 중위소득 65%이하 : 본인부담금 4만원 (바우처 지원액 22만원)

- 기준 중위소득 65%초과~120%이하 : 본인부담금 6만원 (바우처 지원액 20만원)

- 기준 중위소득 120%초과~180%이하 : 본인부담금 8만원 (바우처 지원액 18만원)

더 자세한 사항은 보건복지상담센터 (국번없이 ☎129)로 문의주시기 바랍니다.', '2026-01-27', 57, 'https://www.129.go.kr/faq/faq00.do?pageIndex=38#faq14031', '1535c9ca1082940f40bb6bfe48c2e7fd878c952b751ea5eb4fb903f376c90fe7'),
('14619', 'faq129-20261010', '노인장애인', '장애인등록', '장애인 명의 계좌가 없는데, 장애정도 심사용 진단서 발급비 등 지원 받을 수 있나요?', '장애정도 심사용 진단서 발급 및 검사비 지원 대상 장애인 본인 명의 계좌가 없는 경우 보호자* 계좌로 입금 가능합니다.

* 보호자의 범위 : 법정대리인(미성년자의 친권자, 성년후견인, 한정후견인 등) 또는 장애인을 사실상 보호하고 있는 자(장애인과 주소가 같은 배우자, 직계존·비속, 직계존·비속의 배우자, 형제·자매, 형제·자매의 배우자 등), 장애인을 보호하고 있는 사회복지시설의 장

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 125, 'https://www.129.go.kr/faq/faq00.do?pageIndex=38#faq14619', 'a617c1b341054c6a5378f4f03eb2173ea494f015c750e065619d66c5084f26f5'),
('14621', 'faq129-20261010', '노인장애인', '장애인등록', '장애정도 심사용 진단서 발급비 및 검사비 지원은 여러 번 받을 수 있나요?', '1인당 지원 횟수에 제한은 없으나, 형평성과 예산의 범위를 고려하여 지원하고 있습니다.

다만, 동일부위, 동일 장애유형에 대하여 연간 1회만 지원 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 124, 'https://www.129.go.kr/faq/faq00.do?pageIndex=38#faq14621', 'dc21c3689435e94dae5e6bb98d88f58b2dd736696314b27e5738beaa141aecb1'),
('17460', 'faq129-20261010', '노인장애인', '장애인등록', '모바일 장애인등록증은 어떻게 발급받나요?', '2026년 1월 22일부터 모바일 장애인등록증 발급이 가능합니다. 모바일 장애인등록증 발급을 받으려면 신분증과 본인 명의 스마트폰을 가지고 가까운 행정복지센터에 방문하시면 됩니다.

발급 방식에는 두가지가 있습니다. 첫번째 방법은 기존 실물 장애인등록증에 기초하여 QR촬영을 이용하는 방법이고, 두번째 방법은 새로 발급받은 IC등록증을 이용하는 방법입니다.

▲ QR촬영 방식의 경우 신청 당일에 모바일 장애인등록증 발급이 완료됩니다. QR의 유효시간이 5분이므로, QR(서면)을 받은 즉시 그 자리에서 모바일 장애인등록증 발급 절차를 진행해야 합니다.

▲ IC등록증을 이용하는 방식의 경우 먼저 행정복지센터에 방문하여 IC등록증 발급을 신청하고(신청일부터 열흘 정도 후에 방문 또는 우편 수령), 수령 후에 기간 제한 없이 어디서나 휴대폰 뒷면에 접촉하여 모바일 장애인등록증을 발급받을 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 35, 'https://www.129.go.kr/faq/faq00.do?pageIndex=38#faq17460', 'a2e54d74dc835ab5d590d89354b146b2f732e777ca5f1160c8d5e38b2b5b1952'),
('17461', 'faq129-20261010', '노인장애인', '장애인등록', '등록된 장애인이면 누구나 제한 없이 모바일 장애인등록증을 발급받을 수 있나요?', '14세 미만 장애인은 모바일 장애인등록증을 발급받을 수 없습니다.

또한, 14세 이상의 미성년자, 지적·자폐성·정신 장애인이 모바일 장애인등록증을 신청하고자 하는 경우에는 법정대리인 또는 보호자의 동의를 받아야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 38, 'https://www.129.go.kr/faq/faq00.do?pageIndex=38#faq17461', '62d96936d818f11688910b25fca460b2724a137518ea137140f06bcad645dc9e'),
('1452', 'faq129-20261010', '노인장애인', '장애인연금(수당)', '장애인연금은 얼마나 지원되나요?', '장애인연금은 기초급여와 부가급여로 구분되며, 기초급여와 부가급여를 합하여 지급됩니다.

○ 기초급여 : 18~64세 중증장애인에게 지원 (※ 65세 이상은 미지원)

- 기초생활수급자로서 생계·의료.주거.교육급여수급자 349,700원(감액없는 최고의 지급액 기준)

- 차상위계층 및 차상위초과자는 소득인정액에 따라 2만원~ 349,700원 차등 지원

○ 부가급여

- 65세 미만 : 기초생활수급자로서 생계·의료급여수급자 9만원, 주거·교육급여 수급자 등 차상위계층 8만원, 차상위 초과자 3만원 각각 지원

- 65세 이상 : 기초생활수급자로서 생계·의료급여수급자 439,700원, 주거·교육급여 수급자 등 차상위계층 8만원, 차상위 초과자 5만원 각각 지원

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 18750, 'https://www.129.go.kr/faq/faq00.do?pageIndex=38#faq1452', 'd8b19896678b972507b985870021de8492d48df16395d7e1e63da5b1d781cfc7');
