INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('1463', 'faq129-20261010', '노인장애인', '장애인연금(수당)', '장애인연금은 매년 인상되나요?', '장애인연금은 매년 그 전년도의 기초급여액에 전전년도 대비 전년도의 전국소비자물가변동률을 반영하여 인상하고 있으며, 소비자물가변동률이 하락하는 경우에는 그 만큼 인하될 수도 있습니다.

○ 기초급여 : 18~64세 중증장애인에게 지원 (※ 65세 이상은 미지원)

- 기초생활수급자로서 생계·의료.주거.교육급여수급자 349,700원(감액없는 최고의 지급액 기준)

- 차상위계층 및 차상위초과자는 소득인정액에 따라 2만원~ 349,700원 차등 지원

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 3021, 'https://www.129.go.kr/faq/faq00.do?pageIndex=39#faq1463', '6523a043db03157704766ab77f5a7942fd810316dc9e22be3715d22c2a13af86'),
('1547', 'faq129-20261010', '노인장애인', '장애아동가족지원', '발달재활서비스 이용시에 본인부담금은 서비스 받을 만큼만 입금하면 되나요?', '발달재활서비스는 장애아동 1인당 월 26만원(본인부담금 포함)의 바우처를 제공합니다.

본인부담금은 전액을 제공기관에 사전 납부하여야하며, 이용자의 이용중단 또는 서비스 미제공시에 이용자의 요청에 따라 미이용한 횟수에 해당하는 본인부담금은 제공기관으로부터 환급받으실 수 있습니다.

더 자세한 사항은 보건복지상담센터 (국번없이 ☎129)로 문의주시기 바랍니다.', '2026-01-27', 2764, 'https://www.129.go.kr/faq/faq00.do?pageIndex=39#faq1547', '745089872052a0f84c5f718d20b6b2a92f22e73797526051f5ac80c28401e055'),
('1319', 'faq129-20261010', '노인장애인', '노인장기요양제도', '복지용구로 어떤 품목을 지원받을 수 있나요?', '복지용구는 수급자의 일상생활·신체활동 지원 및 인지기능의 유지향상에 필요한 용구를 제공하는 급여로서 보건복지부 장관이 고시한 품목을 구입 또는 대여방식으로 이용할 수 있습니다.

- 구입 품목 : 이동변기, 목욕의자, 성인용 보행기, 안전손잡이, 미끄럼방지용품, 간이변기, 지팡이, 욕창예방방석, 자세변환용구, 요실금 팬티, 기저귀센서,

구강세척기, 배회감지기, 고관절보호대, 낙상알림시스템

- 대여품목 : 수동휠체어, 전동침대, 수동침대, 이동욕조, 목욕리프트, 배회감지기

- 구입 또는 대여품목 : 욕창예방매트리스, 경사로(실내용, 실외용), 이승보조기기, 대화형 정서지원기기

더 자세한 사항은 보건복지상담센터 (국번없이 ☎129)로 문의주시기 바랍니다.', '2026-01-27', 2284, 'https://www.129.go.kr/faq/faq00.do?pageIndex=39#faq1319', '8c775495d3a0bf5db48457029b0a2a5753dbf2880314ba81da1c2e6cdd516f54'),
('1471', 'faq129-20261010', '노인장애인', '장애인연금(수당)', '근로소득이 있어도 장애인연금을 받을수 있나요?', '장애인연금은 본인과 배우자의 소득과 재산을 조사해서 선정기준액 이하일 경우 지원이 가능합니다.

※ 2026년 선정기준액 : 단독가구 140만원, 부부가구 224만원

소득인정액은 소득평가액과 재산의 소득환산액을 합산한 금액으로 상시근로소득의 경우 근로소득 공제 후 남은 금액을 반영합니다.

※ 2026년 상시근로소득 공제금액: 상시근로소득 금액 중 95만원 공제 후 30% 추가공제

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2026-01-27', 4041, 'https://www.129.go.kr/faq/faq00.do?pageIndex=39#faq1471', '2f46eedeb405dcffecb3636b6ed0167c1eff6f69315b7d4cfbb7a2074fdaa2f3'),
('9034', 'faq129-20261010', '보건의료', '건강정책', '연면적 1,000㎡ 이상의 복합용도의 건축물 등의 차양막, 비가림막 등의 하부가 금연구역에 해당되나요?', '차양막(캐노피, 비가림막, 어닝 등)의 하부는 금연구역에 포함하지 않습니다.

- 국민건강증진법 제9조제4항제16호는 일정한 건축물*을 대상으로 금연구역으로 지정하고 있습니다.

* 「건축법」상의 건축물이란, 토지에 정착하는 공작물 중 지붕과 기둥 또는 벽이 있는 것과 이에 딸린 시설물, 지하나 고가(高架)의 공작물에 설치하는 사무소•공연장•점포•차고•창고, 그 밖에 대통령령으로 정하는 것을 뜻함

- 건축물은 원칙적으로 위와 같이 공작물일 것, 토지에 정착할 것, 지붕 및 기둥•벽이 있을 것이라는 기본 개념 요소를 갖추어야 하는데, 차양막, 캐노피, 비가림막, 어닝 등은 ''토지에 정착''이라는 요소를 갖춘 것으로 보기 어렵습니다.

※ 예) 지붕의 연장인 처마 자체는 건축물의 일부이지만, 그 아래의 빈 공간을 실내, 즉 건축물의 일부로 보기 어려움.

- 따라서 「건축법」의 일반적인 법리에 의지하는 한도 내에서 차양막, 캐노피, 비가림막, 어닝 등의 하부 공간을 국민건강증진법 제9조제4항제16호의 ''건축물''에 해당하는 것으로 보기 어렵습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-22', 1947, 'https://www.129.go.kr/faq/faq00.do?pageIndex=39#faq9034', 'aaf681d8061c072d895c6588ec535ef977f4a950261f70abea4741ccf036a253'),
('17441', 'faq129-20261010', '보건의료', '보건의료정책', '의료기관세탁물 중 ''환자와 접촉하는 의료기관 종사자가 근무 중 착용하는 의류''의 명확한 범위는 어떻게 규정되나요?', '① 수술실, 중환자실, 응급실, 격리병실, 무균치료실에서 진료, 간호, 검체채취 등을 직접 수행하여 혈액 등 감염가능성이 있는 물질로 오염이 의심되는 종사자의 근무복(적용시기 ''22.1.1.)

② 입원실, 임상검사실, 방사선실, 물리치료실, 회복실 또는 이와 유사한 장소에서 혈액 등 감염가능성이 있는 물질로 오염된 종사자의 근무복*(적용시기 ''22.1.1.)

* 「의료기관세탁물 관리규칙」 제2조제2호에 따라 환자의 피•고름•배설물•분비물 등에 오염된 의료기관세탁물은 ''오염세탁물''로서 의료기관세탁물 관리규칙에 따라 처리해야 하므로, 오염된 근무복 또한 의료기관 또는 처리업자를 통하여 세탁하여야 함

③ 그 외 의료기관 내에서 보건의료인 등이 착용한 근무복 중 의료기관 내부위원회(감염관리위원회, 산업안전위원회 등) 등을 통하여 감염 우려가 있을 것으로 판단된 근무복(적용시기 ''22.7.1.)

④ 다만, 환자의 진료•처치 등의 의료행위를 담당하지 않고 외래 공간 등에서 방문자와 일정 거리를 두어 단순히 접수, 수납, 상담(안내) 등의 업무를 수행하는 외래 근무자의 근무복은 일반세탁물로 처리할 수 있겠습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-22', 61, 'https://www.129.go.kr/faq/faq00.do?pageIndex=39#faq17441', '7b4b1036eef3cadcdfb5eae68466e883fd6ddea086cd1350448a4c007b2522e0'),
('6338', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급복지지원 신고의무자 사이버 교육은 지정된 사이트에서만 받을 수 있나요?', '사이버교육은 보건복지부에서 위탁·운영하는 기관의 사이트를 이용하거나 각 기관·시설 등의 온라인학습시스템에 보건복지부 동영상 교육자료를 탑재*해 2026.12.31.까지 이수하시면 됩니다.

* 기관·시설장의 책임하에 운영하되 [신고의무 교육결과보고서(서식 1)]와 함께 증빙자료 제출

<사이버교육 이수 사이트>

1. 한국보건복지인재원 의무교육 (https://in.kohi.or.kr)

- 과목명 : 긴급복지지원 신고의무교육

- 교육대상 : 전 국민

2. 중앙교육연수원 원격연수지원센터 (https://www.neti.go.kr)

- 과목명 : 긴급복지지원 신고의무교육

- 교육대상 : 교원, 교육전문직, 학교관계자

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-21', 57647, 'https://www.129.go.kr/faq/faq00.do?pageIndex=39#faq6338', '69e2e7bc59ab2e00027550fc6e247e3af54610f66ce3b6af66fc6758dd766c30'),
('11154', 'faq129-20261010', '사회복지', '긴급지원사업', '보건복지부에서 제작한 동영상 교육자료를 각 기관·시설 등의 온라인학습시스템에 탑재해 활용해도 될까요?', '공공누리(공공저작물 자유이용허락 라이센스) 제4유형 기준(출처표시, 상업적 이용 금지, 변경 금지)을 준수하는 범위 내에서 해당 자료를 각 기관·시설 등의 온라인학습시스템에 탑재하여 ‘26. 12. 31.까지 활용 가능합니다.

- 기관·시설장의 책임(확인)하에 별도 계약한 민간기관­업체의 교육 사이트 내에 보건복지부 동영상 교육자료를 탑재해 이수하는 경우에는

① 기관·시설장은 탑재된 자료가 출처가 표시된 보건복지부 동영상 교육자료인지 반드시 확인하고,

② 해당 위탁기관(업체)에서는 기관·시설 등에 긴급지원 신고의무 교육비를 청구하지 않아야 하며, 교육 수료자에게 수료증(또는 이수증)을 발급해야 합니다.

※ 상기 준수 사항 외 자료 탑재를 위한 별도 협의 절차는 없으며, 신고의무 교육결과보고서(서식1호 양식) 및 증빙자료 제출 필요

※ 위 내용은 ‘26년 교육자료에 관한 것으로 향후 운영현황, 교육결과에 따라 변동 가능

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-21', 423, 'https://www.129.go.kr/faq/faq00.do?pageIndex=39#faq11154', 'b450d14f6d1da96274500d2eb346e22cd66ebee7dab79c12a78df9c577004ae7'),
('11174', 'faq129-20261010', '사회복지', '긴급지원사업', '2022년부터 지방의회 인사권이 분리되었는데 이 경우 지방의회에서 근무하는 지방공무원들은 어디에 교육 결과를 제출하나요?', '「지방공무원법」시행(’22.1.21.)에 따라 지자체의 장과 지방의회의장에게 지방공무원의 임용과 승진 등 인사권이 있습니다.

- 따라서 지방의회(시·도, 시군구)의 장은 「지방공무원법」에 따른 지방의회 소속 지방공무원에게 ‘2026년 긴급지원 신고의무 교육’을 연말(’26.12.31.)까지 사이버교육 또는 집합교육으로 실시하고, 교육결과는 소관 중앙행정기관인 행정안전부(지방인사제도과)에 제출하여 주시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-21', 370, 'https://www.129.go.kr/faq/faq00.do?pageIndex=39#faq11174', '16bd9778a452d85670d6d6fe0f955f51fbaa7c36f01bc8e7ecec1df3a89ae51d'),
('13797', 'faq129-20261010', '사회복지', '긴급지원사업', '휴·폐업한 경우에도 2025년 긴급복지원 신고의무 교육결과를 제출해야 하나요?', '‘26.12.31 기준으로 휴업 중이거나 폐업상태라면 교육결과 제출대상에서 제외됩니다.(총 기관 수에서도 제외). 다만, 당해연도에 휴업 후 재개업 했다면 당해연도의 교육결과 제출대상이 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-21', 29, 'https://www.129.go.kr/faq/faq00.do?pageIndex=39#faq13797', '5b329182eeee729ff10b598ee149ba6818eea207216e33f899c1f13cd2262f29'),
('17420', 'faq129-20261010', '보건의료', '공공보건정책', '외국인근로자등 의료지원 시 난민인정을 신청한 자 등의 신원확인은 어떻게 해야 하나요?', '국립중앙의료원 공공보건의료지원센터의 외국인 근로자등 의료지원 사업 담당자에게 신원 확인을 요청하시면 됩니다. 신원확인이 가능한 서류(예: 외국인등록증, 여권 등)를 담당자에게 보내주시면 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-21', 26, 'https://www.129.go.kr/faq/faq00.do?pageIndex=40#faq17420', '9df2ebfa9a162f4a6267d3a83b53a87f9555c80ad87d13ee1055a00ce8e6d2cb'),
('17440', 'faq129-20261010', '보건의료', '공공보건정책', '외국인근로자, E-9 비자로 입국하여 비자만료 후 불법 체류하였고, 사업수행 의료기관에 입원하여 치료 중 사망하였습니다. 사망 후에도 외국인근로자등 의료지원 대상자에 포함이 되나요?', '사망 후 사후처리 시 발생하는 비용은 지원받을 수 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-21', 29, 'https://www.129.go.kr/faq/faq00.do?pageIndex=40#faq17440', 'ffbb22993d6ce45ed6082b7b670afceb2fd975966ddffffb309cdc66e0e1b602'),
('17380', 'faq129-20261010', '보건의료', '건강정책', '한국인 영양소 섭취기준은 어떻게 확인할 수 있나요?', '2010년 국민영양관리법 제정 이후 2015년부터 5년주기로 제,개정 되고있으며, 보건복지부 누리집에서 확인가능합니다.

* 보건복지부 > 정보 > 연구/조사/발간자료 > 2025 한국인 영양소 섭취기준

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-12', 30, 'https://www.129.go.kr/faq/faq00.do?pageIndex=40#faq17380', '7de3d88f8244cd73e3de7c4b9235d045d805577a145979d4ae658e70dafe0fa0'),
('14419', 'faq129-20261010', '보건의료', '보건산업정책', '외국인환자 유치기관 등록에 대한 문의는 어디로 해야 하나요?', '2021년 1월부터 외국인 환자 유치기관 등록 등 사무는 유치기관 사업장 소재지 관할 시/도에서 업무를 수행하고 있으며,

문의처는 아래 ''바로가기''를 클릭하면 확인이 가능합니다.

☞ 바로가기

(www.medicalkorea.or.kr/korp/intro/registration.do)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-08', 64, 'https://www.129.go.kr/faq/faq00.do?pageIndex=40#faq14419', 'ec553b6105d8531b004f23937d017bf92924a65fab85125843cecd9cb1cd68e2'),
('8831', 'faq129-20261010', '사회복지', '긴급지원사업', '경기도 고양시에 거주하고 있는데, 긴급지원 신청 시 재산기준액이 얼마인가요?', '2022년 1월 13일부터 경기 고양시, 용인시, 수원시, 경남 창원시는 특례시로 승격되어 대도시 기준을 적용합니다.

2026년 기준으로 대도시 재산기준은 2억 4100만원입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-06', 713, 'https://www.129.go.kr/faq/faq00.do?pageIndex=40#faq8831', '2aedcbabbac0e59c06ee849b7009251e39103750829979cc9f025a7acafd2a63'),
('10734', 'faq129-20261010', '사회복지', '긴급지원사업', '재외국민도 긴급생계지원 신청이 가능한가요?', '재외국민은 긴급지원 대상자에 해당되지 않아 신청이 어려습니다.

다만, 국내에 30일 이상 거주할 목적으로 입국 시 신고받아 주민등록을 재등록하거나, 주민등록이 말소되지 않은 재외국민거주자가 실제 생계가 곤란하여 필요하다고 시군구청장이 인정하는 경우 가구원으로서 포함 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-06', 561, 'https://www.129.go.kr/faq/faq00.do?pageIndex=40#faq10734', '861dc100d6aa6070483a169849c05b7fc880d014ce5f490818e7f5c2b9091c8c'),
('14013', 'faq129-20261010', '사회복지', '긴급지원사업', '재외국민도 긴급의료지원 신청이 가능한가요?', '재외국민은 긴급지원 대상자에 해당되지 않아 신청이 어려습니다.

다만, 국내에 30일 이상 거주할 목적으로 입국 시 신고받아 주민등록을 재등록하거나, 주민등록이 말소되지 않은 재외국민거주자가 실제 생계곤란하여 보호가 필요하다고 시군구청장이 인정하는 경우 가구원으로서 포함 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-06', 67, 'https://www.129.go.kr/faq/faq00.do?pageIndex=40#faq14013', 'a9aa7aaf0a4d4868cbf83fc31fb0779705bd3949b16fd8dfa1b0b8c0185c0d74'),
('15139', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급주거지원 신청대상은 누구인가요?', '위기상황*의 발생으로 임시거소 제공 또는 주거비 지원이 필요하다고 신청대상이며, 소득, 재산, 금융재산 기준 또한 충족하여야 합니다.

* 화재 및 산사태, 풍수해 등 천재지변, 경매•공매•재개발에 따른 강제철거 등으로 거주지에서 강제로 나가게 되는 경우 등

< 긴급주거 지원기준 : 아래 주거지원 한도액 내 실비지원이며, 임시거소 제공자에게 지급 >

○ 대 도 시 : (1-2인) 398,900원 / (3-4인) 662,500원 / (5-6인) 874,100원

○ 중소도시 : (1-2인) 299,100원 / (3-4인) 435,600원 / (5-6인) 574,200원

○ 농 어 촌 : (1-2인) 189,000원 / (3-4인) 250,500원 / (5-6인) 330,000원

* 가구구성원이 7인 이상인 경우, 1인 증가시마다 대도시 105,800원, 중소도시 69,300원, 농어촌 39,800원씩 추가 지급

< 긴급주거 지원기간 >

1개월 지원이 원칙이며, 시•군•구청장의 연장결정에 따라 2개월 연장지원 가능하며,

3개월의 지원에도 불구하고 위기상황이 계속되는 경우에는 긴급지원심의위원회 심의를 거쳐 9개월 범위에서 추가 연장가능

<긴급주거지원 신청방법>

위기상황 발생으로 위기에 처한 긴급지원대상자와 친족, 그 밖의 관계인은 읍면동 주민센터, 시군구청 또는 보건복지상담센터 ☎ 129로 신청합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-06', 1042, 'https://www.129.go.kr/faq/faq00.do?pageIndex=40#faq15139', 'c66762a745f840fd6d8fd9502ab8cdc97798595b62a092b1be4a00f8092aeda5'),
('16400', 'faq129-20261010', '사회복지', '긴급지원사업', '경기도 화성시에 거주하고 있는데 긴급생계지원 신청 할 경우 재산 기준액이 얼마인가요?', '경기도 화성시가 2025년 1월 1일자로 화성특례시로 승격되면서 긴급지원의 재산기준은 대도시 기준을 적용합니다.

2026년 기준으로 대도시 재산기준은 2억 4100만원입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-06', 25, 'https://www.129.go.kr/faq/faq00.do?pageIndex=40#faq16400', '1cba9f941a98fbfac3ab7564cd7c1fc6ac6333bd7339ac3a73b484125bbfaff9'),
('17360', 'faq129-20261010', '보건의료', '건강보험정책', '차상위본인부담경감대상자 지원은 신청 후 처리기간은 얼마나 소요되나요?', '시군구는 신청세대 및 부양의무자에 대하여 조사를 실시한 후 부득이한 사유가 없는 한 신청 결과를 신청일부터 30일 이내에 국민건강보험공단에 통보하고, 공단은 7일 이내 그 결과를 신청인에게 통보하도록 하고 있습니다.

* 기간연장: 관할 지역 이외 지역에 거주하는 부양의무자에 대한 소득 조사, 서류보완 등 특별한 사유가 있는 경우 30일을 연장할 수 있음.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-06', 114, 'https://www.129.go.kr/faq/faq00.do?pageIndex=40#faq17360', 'db361c4a78729d423f38e6ed16f987dc0e27b8d7ff5150afb4e62d2b9e074be8');
