INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('861', 'faq129-20261010', '사회복지', '긴급지원사업', '작년에 출소의 위기사유로 긴급생계지원을 받았는데, 오늘 다시 출소하게 되었는데 긴급생계지원을 받을 수 있나요?', '긴급지원이 종료되면 동일한 위기상황으로 인하여는 다시 지원할 수 없으나, 지원이 종료된 때로부터 2년이 경과한 후에는 동일한 사유로 다시 지원할 수 있습니다.

단, 생계지원에 한해 동일 위기상황이라도 2년 경과 시 지원 가능합니다.

작년 긴급생계지원이 종료된지 2년이 지났다면 출소의 위기사유로 다시 긴급생계지원을 요청해보실 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-06', 3006, 'https://www.129.go.kr/faq/faq00.do?pageIndex=41#faq861', '1097cec3b38ff36421233bfa1c5a2809ec81bfcccec63866e5c8fad7205ba621'),
('867', 'faq129-20261010', '사회복지', '긴급지원사업', '형집행정지자인데 긴급생계지원 신청 가능한가요?', '만기출소자, 가석방자, 형집행정지자 등은 교정시설 출소에 해당하며, 6개월이상 구금 후 출소한 경우라면 신청 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-06', 2550, 'https://www.129.go.kr/faq/faq00.do?pageIndex=41#faq867', '32ff4879f17af3610aca7269b71194a038d1f63ea644cb3bb156e6c275501b29'),
('868', 'faq129-20261010', '사회복지', '긴급지원사업', '교도소 출소자인데 생계비를 지원받을 수 있나요?', '교정시설에서 출소한 자가 생계가 곤란하여 긴급복지지원을 요청할 경우 다음의 요건을 모두 충족해야합니다.

① 출소자 중 가족이 없거나 가족과의 관계가 단절된 경우 또는 가족이 미성년인 자녀(20세 이하의 중­고등학교 및 대학교 재학생 포함)나 미성년인 형제자매, 65세 이상인 자, 장애의 정도가 심한 장애인, 산정특례 대상인 중증·희귀·중증난치질환자로만 구성되는 경우

② 구금기간이 6개월 이상이고 출소일로부터 6개월 이내 긴급지원을 요청한 경우

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-06', 15169, 'https://www.129.go.kr/faq/faq00.do?pageIndex=41#faq868', '463950642f0d81849337f26a4cb42a766ddbb199cbf0ad191ae494057f242f90'),
('7230', 'faq129-20261010', '보건의료', '보건의료정책', '상급종합병원, 종합병원, 병원, 한방병원의 간호간병통합서비스 병동의 1인실에 입원하면 입원료가 어떻게 산정되나요?', '「국민건강보험 요양급여의 기준에 관한 규칙」 별표2 [비급여대상]에 따라, 상급종합병원, 종합병원, 병원, 한방병원의 1인실을 이용하는 경우 입원료(입원관리료, 간호·간병료) 전액이 비급여 대상이므로 환자가 모두 부담하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2026-01-02', 4641, 'https://www.129.go.kr/faq/faq00.do?pageIndex=41#faq7230', 'bc9329f26eaca2ecf37237345239329500ceb281b412540905e888b23b402f74'),
('15620', 'faq129-20261010', '노인장애인', '장애인복지사업', '모든 사업주가 장애인 정보접근권 보장을 위한 장벽없는 키오스크를 설치해야하나요?', '「장애인차별금지법」 제15조 제3항, 제4항과 같은법 시행령 제10조의2에 따라 키오스크를 설치·운영하는 공공·민간의 모든 현장은 장애인의 비장애인과 동등한 정보접근권 보장을 위해 장벽 없는 키오스크 의무를 부담합니다.

다만, 소규모 근린생활시설(바닥면적 50㎡ 미만), 소상공인(소상공인기본법 제2조제1항), 테이블오더형의 소형제품(화면 대각선 길이 28㎝ 이하)의 경우에는 ① 과학기술정보통신부의 접근성 검증기준을 준수한 키오스크 및 음성안내장치 설치, ② 키오스크와 호환되는 보조기기 또는 소프트웨어의 설치, ③ 보조인력의 배치와 호출벨의 설치 중 어느 한 가지를 이행하면 「장애인차별금지법」상의 장애인을 위한 장벽 없는 키오스크 의무를 모두 이행한 것이 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-30', 111, 'https://www.129.go.kr/faq/faq00.do?pageIndex=41#faq15620', 'acc714dab1578e62061e2696ab584586222ddc00bb8d0f9127bb77e1cfc68c90'),
