('15580', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인 정보접근권 보장을 위한 장벽 없는 키오스크를 왜 설치해야 하나요?', '정보통신기술의 발달로 무인정보단말기(키오스크) 개발 및 보급이 확대되었으나, 장애인이 이용 가능하도록 편의를 제공하지 못하여 불편함을 겪게 됨으로써 장애인과 비장애인의 차별이 발생하여 장애인이 키오스크나 모바일앱 사용시 비장애인과 동등하게 접근하고 이용할 수 있도록 정당한 편의를 제공하여 장애를 이유로 차별받지 않도록 하기 위함입니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-24', 145, 'https://www.129.go.kr/faq/faq00.do?pageIndex=41#faq15580', '854962ab40df2eade285196d68b0158fad004a0a230613c7273cd2a4322bae40'),
('15581', 'faq129-20261010', '노인장애인', '장애인복지사업', '키오스크란 무엇인가요?', '「장애인차별금지법」 제15조 제3항은 무인정보단말기 즉, 키오스크는 터치스크린 등 전자적 방식으로 정보를 화면에 표시하여 제공하거나 서류발급, 주문·결제 등을 처리하는 기기를 말한다고 규정합니다.

키오스크는 터치스크린 인터페이스를 기반으로 하여 기기 자체 내에 사용자 정보 입력을 통한 정보 처리와 결과 출력의 정보 처리 프로세스가 내장된 기기를 의미합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-24', 99, 'https://www.129.go.kr/faq/faq00.do?pageIndex=42#faq15581', '92078540fbfc4940eaa165e5dbbf92fdde5b04ddb464b475fc5d3940bb9d2773'),
('15621', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인 정보접근권을 위한 장벽을 없애기 위해 키오스크에 어떤 편의를 제공하여야 하나요?', '장애인 정보접근권 보장을 위한 장벽 없는 키오스크는 과학기술정보통신부 관련 고시*에 따른 접근성 검증기준을 준수한 제품으로 설치하고, 시각장애인이 키오스크의 위치를 알 수 있도록 음성으로 위치를 안내하는 음성안내장치를 설치하여야 합니다.

* 「장애인­·고령자 등의 정보 접근 및 이용 편의 증진을 위한 고시」로 검증기준을 준수한 키오스크 현황은 “무인정보단말기UI플랫폼”에서 확인할 수 있음

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-24', 86, 'https://www.129.go.kr/faq/faq00.do?pageIndex=42#faq15621', '14a6104bc4a592d8a0c67f07d5d2a0fc3fa9e0b28794fbe10b604adf32ed99f3'),
('17242', 'faq129-20261010', '노인장애인', '장애인복지사업', '키오스크 운영을 하지 않는 사업장에도 장벽없는 키오스크를 설치해야 하나요?', '「장애인차별금지법」 제15조 제3항, 제4항과 같은법 시행령 제10조의2에 따라 키오스크를 설치·운영하는 공공·민간의 모든 현장은 장애인의 비장애인과 동등한 정보접근권 보장을 위해 장벽 없는 키오스크 의무를 부담합니다.

장벽 없는 키오스크를 통한 장애인의 비장애인과 동등한 정보접근권 보장의무는 키오스크를 설치·운영하는 재화·용역 등 제공자에 부과되는 것으로 키오스크를 설치하지 않은 현장은 의무 대상이 아닙니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-24', 29, 'https://www.129.go.kr/faq/faq00.do?pageIndex=42#faq17242', 'e5364a692d437a4c06eeaf6a1aceedf7974e76c0cf83072bdd3dd55290658578'),
('17243', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인 정보접근권 보장을 위한 장벽 없는 키오스크 제도는 언제부터 시행되나요?', '「장애인차별금지법 시행령」 [별표 2의2]에 따라 공공기관, 교육기관, 의료기관, 공공기관 소유 재산 임차인, 교통수단 또는 여객기설 운영자, 금융회사에 대해서는 2024년 1월 28일부터, 복지시설, 대규모 문화예술사업자, 상시 100명 이상의 근로자 사용 사업자에 대해서는 2024년 7월 28일부터, 관광사업자, 상시 100명 미만의 근로자를 사용하는 사업자에 대해서는 2025년 1월 28일부터 단계적으로 적용·시행되었습니다.

다만, 각각의 적용일 이전에 이미 설치한 무인정보단말기를 운영 중인 재화·용역 등의 제공자에 대해서는 유예기간을 두어 2026년 1월 28일부터 장벽 없는 키오스크 제도가 적용됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-24', 33, 'https://www.129.go.kr/faq/faq00.do?pageIndex=42#faq17243', 'aae5d388c6c8fbe293d740c90e5c2028378c6dbf616a3bd089d93d22ef9558be'),
('17244', 'faq129-20261010', '노인장애인', '장애인복지사업', '키오스크 안에 호출기능이 탑재되어 있으면 따로 호출벨 설치하지 않아도 되는지?', '「장애인차별금지법 시행령」 제10조의2 제3항에 따라 ①바닥면적 50제곱미터 미만의 소규모 근린생활시설, ②「소상공인기본법」 제2조 제1항의 소상공인 또는 ③테이블오더형 소형제품에 대하여 ▲일반 무인정보단말기에 호환되는 보조기기 또는 소프트웨어를 설치하거나 ▲보조인력을 배치하고 호출벨을 설치하면 「장애인차별금지법」상의 장애인을 위한 장벽 없는 키오스크 의무를 모두 이행한 것이 됩니다.

이때 보조인력을 배치하는 경우에는 호출벨을 반드시 설치하여야 하며, 호출벨은 무인정보단말기의 위치, 사용법, 고장 등으로 이용지원이 필요할 때 요청할 수 있는 호출장치를 의미하는 것으로 키오스크 옆에 1대씩 설치되어야 합니다. 그러므로 키오스크 기능에 직원을 호출할 수 있는 기능이 있더라도 장벽 없는 키오스크의 취지는 키오스크에 대한 접근 자체가 어려운 장애인 사용자를 위한 정보접근권의 보장에 있기 때문에 물리적인 호출벨이 별도로 설치되어야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-24', 32, 'https://www.129.go.kr/faq/faq00.do?pageIndex=42#faq17244', '00ba53a8ef4e1e3a0167773c299cdc05917af95bae21177e14ac73fec2782beb'),
('17260', 'faq129-20261010', '노인장애인', '장애인복지사업', '장벽없는 키오스크 설치 의무 대상인데 장벽을 없애기 위한 편의를 제공하지 않으면 어떤 불이익 있나요?', '장벽 없는 키오스크를 위한 편의를 제공하지 않으면 그 사실을 아는 모든 국민은 국가인권위원회에 진정을 접수할 수 있고 시정권고와 시정명령을 거쳐 과태료(최대 3천만원)가 부과될 수 있 있습니다.

또한, 「장애인차별금지법」을 위반한 차별행위에 대하여 민·형사상 책임을 부담할 수 있고, 재판 과정에서 차별행위가 아니라는 점을 적극적으로 입증하지 않는 한 손해배상책임이 인정되며, 악의적인 경우에는 3년 이하의 징역 또는 3천만 원 이하의 벌금이 선고될 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-24', 33, 'https://www.129.go.kr/faq/faq00.do?pageIndex=42#faq17260', 'b60299c758c8577a953ccbc51345f8fe89ac79ac2afc10c9b2034a411ec93942'),
('17261', 'faq129-20261010', '노인장애인', '장애인복지사업', '장벽 없는 키오스크의 예외적 조치내용 중 호환되는 보조기기 또는 소프트웨어는 무엇을 의미하나요?', '호환되는 보조기기 또는 소프트웨어는 이어잭, 탈부착 점자키패드, 스크린리더 또는 QR코드·NFC태그 등을 통해 앱 또는 웹으로 연결, 스마트폰을 활용해서 무인정보단말기 정보에 접근하는 장치를 의미합니다. 이러한 보조기기 또는 소프트웨어 중 어느 하나를 설치하면 장벽 없는 키오스크 의무를 이행한 것이 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-24', 32, 'https://www.129.go.kr/faq/faq00.do?pageIndex=42#faq17261', 'd72b8b678dc1e70f8954d83def4f7d5cb86304e66d2d4ab47708b0426e560958'),
('17262', 'faq129-20261010', '노인장애인', '장애인복지사업', '외부인 출입이 금지되는 회사 내 구내식당에도 장벽없는 키오스크 설치를 하여야 하나요?', '업종을 불문하고 공공과 민간의 모든 키오스크 설치 현장은 장벽 없는 키오스크 의무를 부담합니다.

업무의 종류, 성격이나 설치 장소의 성격 등을 기준으로 할 때 장애인이 가까운 시일 내에 이용할 가능성이 없거나 적다는 사유는 장벽없는 키오스크의 예외 사유로 고려되지 않습니다. 따라서 회사에 장애인 근로자가 재직 중이지 않고 외부인 출입이 통제되어 장애인이 직원 식당을 이용할 가능성이 없다고 하더라도 직원 식당 내 장벽 없는 키오스크 의무가 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-24', 29, 'https://www.129.go.kr/faq/faq00.do?pageIndex=42#faq17262', '241cca612cac1499909c5ecd647ee8e57a97030843535543bb8ba4d01f5308bb'),
('17221', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급지원 요청자 가구의 금융재산 중, 자산형성지원사업인 디딤씨앗통장이 확인된 경우, 디딤씨앗통장의 금융재산도 포함하는지?', '디딤씨앗통장, 내일키움통장, 희망플러스통장 등 정부, 지자체 예산을 통한 유사 자산형성지원사업의 경우, 가입기간 중 본인 저축액은 금융재산에서 차감합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-12-12', 27, 'https://www.129.go.kr/faq/faq00.do?pageIndex=42#faq17221', 'e1f8e8050d3c63296d5dcda7ed9ffbfb96207c1f0c73e6805aa68d5d5bf93b27'),
('11294', 'faq129-20261010', '보건의료', '건강정책', '영양플러스사업 참여 영야의 경우(0-5개월) 완전모유수유를 하면 대상자가 되어도 식품 패키지로 공급할 것이 없는데도 대상자 자격을 갖는 건가요?', '네, 그렇습니다.

식품패키지로 공급할 내용은 없지만 영아는 대상자격이 있으므로, 보호자는 영양교육에 참여하여야 합니다.

생후 6개월이 되어 식품패키지2로 전환되면 쌀, 달걀, 당근 및 감자를 공급합니다.

대신 완전모유수유를 하는 영아의 어머니(완전모유수유부)는 더 많은 식품이 지원되며, 사업에도 더 오래 참여할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-12-11', 510, 'https://www.129.go.kr/faq/faq00.do?pageIndex=42#faq11294', 'ecd0c407fcd3a820f94b6e262165dd9bfebcf7504e823d14935fffe3d0eabcea');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('17200', 'faq129-20261010', '보건의료', '보건의료정책', '교육생에게 허위의 교육이수 확인증을 발급하는 간호조무사 교육훈련기관을 알게 된 경우에 신고 및 처리 방법', '한국간호교육평가원으로 지정•평가 기준 관련 신고가 접수될 경우, 「간호조무사 교육훈련기관 지정•평가 운영지침」에 따라 수시점검을 실시합니다(''2021. 6. 기준)

단, 수시점검 기준에 부합하지 않은 경우 점검이 제한될 수 있습니다.

- 지정•평가 기준 관련 신고가 접수될 경우, 「간호조무사 교육훈련기관 지정•평가 운영지침」에 따라 수시점검을 실시할 수 있으며, 한국간호교육평가원의 수시점검 결과를 토대로 보건복지부에 교육훈련기관 지정취소 상신 또는 형사 고발 등의 조치 가능

- 다만, 아래와 같은 경우 점검이 제한될 수 있음

1. 익명

2. 구두의견

3. 해고•징계 등에 관한 내용

4. 민원 내용을 증빙할 수 있는 사진 등 구체적인 증빙자료가 없는 경우

* 공익제보의 경우 익명 제보는 가능하나 반드시 확인 가능한 증빙자료를 제출해야 함

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-12-11', 79, 'https://www.129.go.kr/faq/faq00.do?pageIndex=43#faq17200', 'ac2841d23b5c9360b15b7be2e6c63596a76e880fc3407e3091134f9b1470c5e6'),
('17220', 'faq129-20261010', '사회복지', '긴급지원사업', '금융재산이 압류된 경우 어떻게 산정하는지?', '압류된 재산이라도 압류를 풀면 사용 가능함에 따라 본인의 재산으로 산정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-12-11', 19, 'https://www.129.go.kr/faq/faq00.do?pageIndex=43#faq17220', 'cddbf56381c478f8ddfcbf99a7be08af01c2ccd3355551921d8d9d122079e704'),
('6313', 'faq129-20261010', '보건의료', '공공보건정책', '난민인정을 받아 건강보험에 가입이 가능하지만, 건강보험료를 납부하지 않거나 또는 미납하여 건강보험 자격을 상실하였습니다. 외국인근로자 등 의료지원 사업에서 지원이 가능한가요?', '외국인근로자 등 의료지원사업 대상이 아닙니다.

건강보험 자격취득/가입이 가능하다면 건강보험료를 납부하고 건강보험을 적용받아야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-12-03', 1860, 'https://www.129.go.kr/faq/faq00.do?pageIndex=43#faq6313', '98edd1a1443109ad10b35055d40020d2fc9a9d3ac86fdcc21ae3ffe1d16bb25a'),
('6314', 'faq129-20261010', '보건의료', '공공보건정책', '상해, 교통사고 등으로 발생한 질병(질환)도 외국인근로자 등 의료지원 사업에서 지원을 받을 수 있나요?', '가해로 인한 상해가 발생한 경우는 지원범위에 포함되지 않습니다.

단, 가해자로부터 피해보상을 받는 것이 불가함이 확인된 경우에 한하여 지원받을 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-12-03', 835, 'https://www.129.go.kr/faq/faq00.do?pageIndex=43#faq6314', 'd95bc41ad52b4ffe877301f9d8e08f9f1b5b6327e17d12eb1eabdd9f91c5dcfb'),
('8470', 'faq129-20261010', '인구아동', '부모급여', '(영아수당) 영아수당은 무엇인가요?', '2022년 시행되어 만 2세 미만 영아(2022년 1월 1일 이후 출생아)에게 현금 30만원 또는 바우처(보육료,

종일제 아이돌봄)를 지원한 제도입니다.

2023년부터는 부모급여로 변경되어 현금 지급 시 0세아(0~11개월)는 70만원, 1세아(12~23개월)는

35만원 지원했었고, 24년부터는 부모급여액이 인상되어 0세아(0~11개월)는 100만원, 1세아(12~23개월)는

50만원 지원하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-12-03', 960, 'https://www.129.go.kr/faq/faq00.do?pageIndex=43#faq8470', 'e3c1d1245fee3d0fbba03de72cb1a8dee3e895efa7ad80bf561431a63f06a4ea'),
('5013', 'faq129-20261010', '노인장애인', '장애인등록', '장애인증명서는 어디서 발급 받을 수 있나요?', '장애인증명서는 전국 읍면동 주민센터 방문신청 또는 무인민원발급기에서 발급하거나 복지로(www.bokjiro.go.kr), 정부24(www.gov.kr)에서도 발급 가능합니다.

방문신청 또는 복지로, 정부24 신청의 경우 주민등록번호 뒷번호, 주·부장애 정보, 종합장애정도의 표시 여부를 선택하여 발급 가능합니다.

※ 무인발급기의 경우 기재사항 선택 기능 미시행

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-02', 17026, 'https://www.129.go.kr/faq/faq00.do?pageIndex=43#faq5013', '6670bdc1c51a1c28c555856aa904317e429b0ab70ae606b25827350883894651'),
('6451', 'faq129-20261010', '노인장애인', '장애인편의증진(표지)', '장애인의 가족 명의 차량에 장애인자동차표지 발급이 가능한가요?', '「장애인복지법 시행규칙」제26조에 따라 장애인 본인 또는 장애인과 『주민등록법』 제7조에 따른 주민등록표상의 주소를 같이 하면서 함께 거주하는 아래 각호의 명의로 등록하여 주로 장애인이 사용하는 자동차 1대에 대해서 장애인자동차표지 발급이 가능합니다.

1) 배우자, 직계혈족 또는 형제자매

2) 직계혈족의 배우자, 배우자의 직계혈족 또는 배우자의 형제자매

3) 형제자매의 배우자 또는 형제자매의 자녀

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-02', 2799, 'https://www.129.go.kr/faq/faq00.do?pageIndex=43#faq6451', '66daa45c945ef13d873166c6df9ee41e01115b765b1bbf272573ea66a6f527bf'),
('14681', 'faq129-20261010', '보건의료', '건강정책', '건강검진 결과는 어떻게 확인할 수 있나요?', '건강검진결과는 검진을 실시한 검진기관에서 검진완료일로부터 15일 이내에 우편, 이메일, 모바일 등의 방법으로 수검자에게 통보하여 드립니다.

(영유아건강검진, 구강검진 및 생활습관평가를 실시한 검진기관은 수검자에게 결과통보서를 직접 교부하여야 하나, 전산오류, 기기고장 등 부득이한 경우에는 우편, 이메일, 모바일 등으로 통보할 수 있음)

또한, 검진기관에서 검진비를 청구해 지급이 완료된 경우에는 건강보험공단 홈페이지에서 별도의 회원가입 절차없이 공동·금융인증서 또는 간편인증(민간인증서)을 통헌 본인인증 후 건강검진 결과를 즉시 조회 및 출력할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-12-02', 92, 'https://www.129.go.kr/faq/faq00.do?pageIndex=43#faq14681', '3107d673a4a570896efb0e1d1fff50b49ddcab827711342df4415e99a5fefe13'),
('14879', 'faq129-20261010', '보건의료', '건강정책', '일반건강검진 항목에는 어떤 것들이 있나요?', '일반건강검진 항목은 모든 검진 대상자를 대상으로 실시하는 문진 및 신체계측, 흉부방사선 촬영, 혈액검사(콜레스테롤 4종검사 제외), 요검사, 구강검진이 있으며

연령 및 대상자별로 실시하는 콜레스테롤 4종검사, 심뇌혈관질환 위험평가, 인지기능장애 검사, B형 간염검사, 구강 치면세균막 검사, 골밀도 검사, 노인신체기능검사, 생활습관평가, 정신건강검사가 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-12-02', 142, 'https://www.129.go.kr/faq/faq00.do?pageIndex=43#faq14879', '9093adf8dbc86752291979dda3ec5faa80f6b80ab3f63ce3d0c19b4d841a24cb'),
('17140', 'faq129-20261010', '노인장애인', '장애인편의증진(표지)', '장애인이 근무하는 법인회사 차량으로 주차표지 발급이 가능한가요?', '「장애인·노인·임산부 등의 편의증진 보장에 관한 법률 시행령」 제7조의3제1항제3호에서 정한 법인·­단체가 아닌 영리법인 명의 자동차는 주차표지 발급이 어렵습니다.

다만, 보행상 장애인 직원 등이 사용 가능하도록 휠체어 탑승장비 등을 갖춘 개조*한 법인(개인사업자 포함)명의 자동차 또는 임차­리스 자동차로 해당 자동차의 주 사용자가 보행상 장애인임이 확인된다면 주차표지 발급이 가능합니다.

* 장애인 전용차량 개조 : 족동식 핸들, 휠체어 운전석, 핸드컨트롤러 부착 등 차량으로 장애유형에 맞게 장애인이 운전 또는 탑승할 수 있도록 차량구조 등을 적법하게 변경한 차량

※ 「장애인·노인·임산부 등의 편의증진 보장에 관한 법률 시행령」 제7조의3제1항

3. 다음 각 목의 어느 하나에 해당하는 자동차. 이 경우 법인격이 없는 시설ㆍ단체인 경우에는 그 대표자의 명의로 등록한 자동차로 한다.

가. 「장애인복지법」 제58조에 따른 장애인복지시설(이하 “장애인복지시설”이라 한다)의 명의로 등록하여 장애인복지사업에 사용하는 자동차

나. 「장애인복지법」 제63조에 따른 장애인복지단체(이하 “장애인복지단체”라 한다)의 명의로 등록하여 장애인복지사업에 사용하는 자동차

다. 지방자치단체의 명의로 등록하여 장애인복지시설이나 장애인복지단체가 장애인복지사업에 사용하는 자동차

라. 「노인복지법」 제34조에 따른 노인의료복지시설의 명의로 등록하여 노인복지사업에 사용하는 자동차

마. 「장애인 등에 대한 특수교육법」 제28조제5항에 따라 각급학교의 명의로 등록하여 장애인의 통학을 위하여 사용하는 자동차

바. 「영유아보육법」 제26조에 따라 장애아를 전담하는 어린이집의 명의로 등록하여 장애아보육사업에 사용하는 자동차

사. 「교통약자의 이동편의 증진법」 제16조에 따른 특별교통수단으로서 장애인의 이동편의를 위하여 사용하는 자동차

아. 법인ㆍ단체나 시설 등이 가목부터 사목까지의 용도에 사용하기 위하여 1년 이상의 기간을 정하여 시설대여를 받거나 임차하여 사용하는 자동차

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-02', 59, 'https://www.129.go.kr/faq/faq00.do?pageIndex=43#faq17140', 'd8a78c261a639fae5557d9514485f9ff7e4c31250e244a95ddc37eda895504f7'),
('17143', 'faq129-20261010', '노인장애인', '장애인등록', '장애인증명서에 주민번호 앞자리만 표기해서 발급 가능한가요?', '장애인의 필요에 따라 장애인증명서에 ▲ 주민등록번호 뒷번호, ▲ 주장애유형 및 장애정도, ▲ 부장애 유형 및 장애정도, ▲ 종합장애정도 표시 여부를 선택하여 발급할 수 있습니다.

* 무인발급기의 경우 기재사항 선택 기능 미시행

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-02', 26, 'https://www.129.go.kr/faq/faq00.do?pageIndex=44#faq17143', '47148be441064d92dd5a03d868e62e0c6c6316b9196130398b29a123ca94c367'),
('1443', 'faq129-20261010', '노인장애인', '장애인편의증진(표지)', '활동지원사 명의 차량을 장애인이 사용하는 경우에도 표지 발급 가능한가요?', '「장애인복지법 시행규칙」제26조에 따라 장애인 본인 또는 장애인과 『주민등록법』 제7조에 따른 주민등록표상의 주소를 같이 하면서 함께 거주하는 아래 각호의 명의로 등록하여 주로 장애인이 사용하는 자동차 1대에 대해서 장애인자동차표지 발급이 가능합니다.

1) 배우자, 직계혈족 또는 형제자매

2) 직계혈족의 배우자, 배우자의 직계혈족 또는 배우자의 형제자매

3) 형제자매의 배우자 또는 형제자매의 자녀

따라서 장애인 명의 차량이나 장애인과 같이 거주하는 보호자 명의 차량이 아닌 활동지원사 명의 차량은 표지 발급 대상이 아닙니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-02', 2359, 'https://www.129.go.kr/faq/faq00.do?pageIndex=44#faq1443', 'd2fb3fe7a7033ca8fe12346c273dfbbacea7b4d3a81123a43b6e00c37650a84c'),
('17142', 'faq129-20261010', '노인장애인', '장애인복지사업', '발달장애인 재산관리 지원서비스는 누가 이용할 수 있나요?', '발달장애인 재산관리 지원서비스 이용대상자 기준은 아래와 같습니다

- 19세 이상 「장애인복지법」상 등록된 발달장애인(지적·자폐성) 중 위탁할 수 있는 재산이 있는 자

- 19세 이상 「장애인복지법」상 등록된 발달장애인(지적·자폐성)의 보호자로, 소유한 재산을 발달장애인을 위해서 위탁할 의사가 있는 자

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-01', 23, 'https://www.129.go.kr/faq/faq00.do?pageIndex=44#faq17142', '75741ce2c73abb9d464bc3a1042011ee3f8fbf50a3d8547782384257186e52eb'),
('17144', 'faq129-20261010', '노인장애인', '장애인등록', '사진이 있는 장애인증명서 발급이 가능한가요?', '장애인증명서는 증명서에 기재된 정보 주체가 등록된 장애인임을 확인하는 용도입니다.

이에 따라 그 목적에 맞는 정보만을 표시하고자 불필요한 사진 정보가 삭제되도록 2024. 7. 1.일 부터 「장애인복지법 시행규칙 별지 제9호 장애인증명서」 서식이 개정되었습니다.

다만, 장애인등록증 발급받기 전 사진이 부착된 ''장애인등록증 발급신청 확인서''를 발급 요청하면 장애인등록증 발급 전*까지 사용할 수 있습니다.

* 발급일로 부터 30일 내 사용 가능

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-12-01', 30, 'https://www.129.go.kr/faq/faq00.do?pageIndex=44#faq17144', 'd1040249c191e04428471a443bf4a4f5814136f5986c6df6df068b7a1d796686'),
('17141', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애 미등록 아동은 발달장애인 부모상담지원을 받을 수 없나요?', '자녀가 영유아(9세 미만)의 경우, 장애등록이 되어 있지 않더라도 발달장애(지적·자폐성)가 의심된다는 발달재활서비스 의뢰서 또는 최근 6개월 이내 발행된 의사소견서(진단서)로 제출을 통해 발달장애인 부모상담지원 서비스를 받을 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-11-28', 25, 'https://www.129.go.kr/faq/faq00.do?pageIndex=44#faq17141', '3ee9cab763d58548622a299371b15da5876738b650d9abb3abb84ceea3ac337d'),
('17100', 'faq129-20261010', '사회복지', '긴급지원사업', '치료단계상 불가피하게 퇴원 후 다시 재입원하였을 경우 긴급의료지원 가능한지?', '긴급의료지원은 입원에서 퇴원까지 검사, 치료에 소요된 비용 일체를 지원합니다.

따라서, 퇴원 후 동일 질병으로 재진료를 받는 경우 단기지원의 원칙에 따라 지원 대상에서 제외됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-11-20', 16, 'https://www.129.go.kr/faq/faq00.do?pageIndex=44#faq17100', 'e6fb75f3c8ecab35b23101ab7766d914b45c26b6a3e8302c0a317bb43a84365b'),
('17101', 'faq129-20261010', '사회복지', '긴급지원사업', '자녀가 직업군인인데 가구원 수에 포함이 되나요?', '직업군인의 경우는 법률상 의무를 이행하는 것이 아니라. 직업을 선택한 것으로 그 복무성격이 다르므로 조사가구원 및 보장가구원으로 봅니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-11-20', 11, 'https://www.129.go.kr/faq/faq00.do?pageIndex=44#faq17101', '60b50b09492fb0bf9ec78e7bc9aff982f0e28ff1a4cc5bf6ffb51955ff5528bc'),
('17043', 'faq129-20261010', '사회복지', '자활사업', '자활근로 유형 중 시간제 자활근로는 무엇인가요?', '시간제 자활근로란, 돌봄, 간병, 건강 등의 사유로 종일 일자리 참여가 어려운 저소득층을 위한 자활근로사업입니다.

근무시간은 일 4시간 근무가 원칙이며, 오전/오후 교대 근무 또는 일과시간 내 근무시간 선택 등 사업실시기관과 협의 하에 근무시간을 결정하게 됩니다.

더 자세한 사항인 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-11-17', 519, 'https://www.129.go.kr/faq/faq00.do?pageIndex=44#faq17043', '73d5a70be3a4ebcc209a96f8bf7ce06dc55a90b682482b63dd6509dcea4faf7a'),
('17044', 'faq129-20261010', '사회복지', '자활사업', '청년자립도전자활사업단이 무엇인가요?', '자활사업에 참여하는 청년들이 맞춤형 자립지원을 통해 스스로 개인의 변화와 성장을 이끌어내고 공동체성을 회복하는 것에 중점을 맞춘 사업단 입니다.

○ 참여 대상자 : 18~39세의 신규 자활 참여자 또는 참여기간 3년 이내 기존 참여자

○ 사업단 참여기간 : 최대 3년

○ 근로조건 : 1일 8시간, 주5일 참여

○ 급여기준 : 시장진입형 자활근로 기준

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-11-17', 291, 'https://www.129.go.kr/faq/faq00.do?pageIndex=44#faq17044', 'ee67d337ce54f69a02164db7c1b6747d661eb8ce3e80edbee5815645a9c64253'),
('17080', 'faq129-20261010', '사회복지', '자활사업', '자활성공지원금이 무엇인가요?', '자활성공지원금은 자활근로에 참여하던 생계급여 수급자가 민간시장으로 취·창업하여 생계급여를 탈수급한 경우 지원하고 있으며, 지급요건은 다음과 같습니다.

【① 자활근로참여이력 + ② 민간시장 취·창업 + ③ 생계급여 탈수급 + ④ 일정기간(6개월·1년) 경과】

지원금은 장기근속 유도를 위해 근속기간에 따라 아래와 같이 차등지급하게 되므로, 취·창업 후 12개월 근속 시 총 150만원을 지급받을 수 있습니다.

○ 6개월 근속 시 1회차 50만원

○ 12개월 근속 시 2회차 100만원

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-11-17', 442, 'https://www.129.go.kr/faq/faq00.do?pageIndex=44#faq17080', '8949c419667bcbf450b75574a9567550aa52643b2010eabf43388b55a714bad7');
