INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('6312', 'faq129-20261010', '보건의료', '공공보건정책', '외국인근로자 등 의료지원 사업 대상자가 되는 노숙인의 기준은 어떻게 되나요?', '기본적으로 노숙인은 우리나라 국민(한국국적)으로 간주합니다.

보통 응급실로 경찰이 인계하여 들어오는 경우가 많으며,

① 주민등록 말소가 확인되고

② 응급의료기금 행려자 지원처리가 불가능한 경우에 한하여 지원이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-11-10', 910, 'https://www.129.go.kr/faq/faq00.do?pageIndex=45#faq6312', 'b21c88354b371b2d3aeadc3be48c600f0954562cec826cec717860e80f05d562'),
('6315', 'faq129-20261010', '보건의료', '공공보건정책', '국적 취득 전 결혼이민자인데 외국인근로자 등 의료지원 사업 대상자가 될 수 있나요?', '국적 취득 전 결혼이민자로 의료지원을 받기 위해서는 해당자가 가출, 피신 등의 상태로서 건강보험 미가입 상태이거나, 피부양자로 등록되어 있더라도 거주지 보안 등을 우려하여 보험을 적용받기 곤란한 상태에 한하여 지원받을 수 있습니다(관련단체확인서 필요).

국적 취득 전 결혼이민자라도 ''외국인근로자'' 지원 요건을 충족하는 경우에는 ''외국인근로자''로 간주하여 의료지원이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-11-10', 1040, 'https://www.129.go.kr/faq/faq00.do?pageIndex=45#faq6315', '55aa97afd95d8a2a50d7146a13583efdf90fd5bf77fe987591a92220ccc14e6c'),
('17041', 'faq129-20261010', '보건의료', '건강정책', '공동주택 금연구역 신청시, 꼭 세대주가 동의해야하나요?', '입주자 대표 또는 공동주택 관리자가 세대주 2분의 1 이상의 서명을 받아 특별자치시장·특별자치도지사·시장·군수·구청장(이하 시·군·구)에 제출해야합니다.

이때, 법적 요건에 따른 지정 및 지정 이후 과태료(의무)가 따르는 사항으로 세대주 서명을 원칙으로 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-11-06', 31, 'https://www.129.go.kr/faq/faq00.do?pageIndex=45#faq17041', '7b30ee81b3fb578dd0304ffe0d3dfdfe7058bfbcf17ba530a5bf6784001e2c42'),
('17045', 'faq129-20261010', '보건의료', '건강보험정책', '대리처방의 경우도 본인확인을 해야 하나요?', '대리처방의 경우 환자가 아닌 대리인에 대한 본인확인을 실시해야 됩니다.

대리처방은 환자의 의식불명, 거동곤란 등의 사유로 대리인이 의료법 적용을 받아 약제를 대신 처방받은 제도로, 환자 및 대리인의 신분증, 가족관계증명서를 지참해야 하고 대리인에 대한 본인확인이 필요합니다.

- 대리처방은 「의료법」 제17조의2, 「의료법 시행령」 제10조의2, 「의료법 시행규칙」 제11조의2에 의거하여 요건에 맞게 실시함.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-11-06', 83, 'https://www.129.go.kr/faq/faq00.do?pageIndex=45#faq17045', '9d8be2a4c98abc498349ff1477f2a7ae6c8450d67ad5afcda05eca786ba8ceb4'),
('2330', 'faq129-20261010', '보건의료', '건강보험정책', '재난적의료비 지원 신청 후 지급결정까지는 얼마나 소요되나요?', '재난적의료비 지원사업은 신청일부터 30일 이내 지급여부를 통보하도록 하고 있습니다.

다만, 서류의 미비 등 보완이 필요한 경우 또는 개별심사 대상에 해당될 경우 또는 제출된 구비서류 미비 등의 경우에는 60일 이내 지급여부를 통보합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-11-06', 4131, 'https://www.129.go.kr/faq/faq00.do?pageIndex=45#faq2330', '0d5e912ab4affce492094c9c35e0c47dd0bcfcc4e03ed4e0f64ab4a8447b578d'),
('17040', 'faq129-20261010', '보건의료', '건강정책', '공동주택 금연구역 신청요건이 어떻게 되나요?', '공동주택 거주 세대 중 2분의1 이상이 그 공동주택의 복도, 계단, 엘리베이터 및 지하주차장 4곳 전부 또는 4곳 중 일부를 특별자치시장·특별자치도지사·시장·군수·구청장에 금연구역으로 지정하여 줄 것을 신청하면, 금연구역으로 의무 지정합니다.

* 적용 대상 공동주택 범위 : 「주택법」 제2조제3호에 따른 아파트, 연립주택, 다세대주택을 전부 포함

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-11-03', 22, 'https://www.129.go.kr/faq/faq00.do?pageIndex=45#faq17040', '0208a3228f6375f31ace8154aec81816ce5ab5332e6b5f93f613c055cec7b1cc'),
('17042', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁조정중재원의 감정부에서 하는 역할은 무엇입니까?', '감정부에서는 조정(중재)에 필요한 사실조사, 의료행위 등에 대한 과실유무 및 인과관계의 규명, 후유장애 발생 여부 등 확인과 다른 기관에서 의뢰한 의료사고에 대한 감정업무 등을 수행하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-11-03', 57, 'https://www.129.go.kr/faq/faq00.do?pageIndex=45#faq17042', '273de04b30179dd84c6d74fe26c065b1db880a6812b7979c04e5be0e23575693'),
('17060', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁조정중재원의 조정부가 하는 역할은 무엇입니까?', '조정부에서는 의료분쟁의 조정결정 및 중재판정, 의료사고로 인한 손해액 산정, 조정조서 작성 등의 업무를 수행하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-11-03', 36, 'https://www.129.go.kr/faq/faq00.do?pageIndex=45#faq17060', '7785be8dbef87f76bb1bbadb97eb0efcb1cb800fbce00bdbfd305ac3c4038bbe'),
('17000', 'faq129-20261010', '노인장애인', '장애인복지사업', '발달장애인 재산관리 지원서비스는 무엇인가요?', '발달장애인 본인 또는 가족 등의 재산(금전)을 발달장애인의 욕구와 선호에 따라 안전하게 보관 및 사용하도록 지원하는 서비스입니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다', '2025-10-31', 37, 'https://www.129.go.kr/faq/faq00.do?pageIndex=45#faq17000', 'fc3b5ca161c30d9f90b81072e4be153ea9d7bf5a1cdce61507f79dcfded5aaf6'),
('17002', 'faq129-20261010', '노인장애인', '장애인복지사업', '영주권자(F-5)로 장애등록한 아동의 부모도 발달장애인 부모상담 지원서비스 신청이 가능한가요?', '장애인복지법 제32조의2(재외동포 및 외국인의 장애인등록)에 따라 장애등록한 외국인은 발달장애인 부모상담 지원 대상에서 제외되므로 영주권자(F-5)로 장애등록한 발달장애인의 부모는 발달장애인 부모상담 지원서비스 신청이 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-10-31', 26, 'https://www.129.go.kr/faq/faq00.do?pageIndex=45#faq17002', 'f411827adc6cf93bc11014d5a37a458a150d1d92bb21cdc04a468288fcf2590b'),
('17020', 'faq129-20261010', '노인장애인', '장애인활동지원', '활동지원사의 결격사유가 있나요?', '장애인활동 지원에 관한 법률 제29조에서 활동지원사의 결격사유를 정하고 있습니다. 또한, 결격사유와 별도로 활동지원급여수급자 등은 활동지원사가 될 수 없습니다.

<활동지원사의 결격사유>

- 「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」 제3조제1호에 따른 정신질환자(전문의가 활동지원사로 적합하다고 인정하는 사람은 제외)

- 마약·대마 또는 향정신성 의약품 중독자

- 피성년후견인 또는 피한정후견인

- 금고 이상의 형을 선고받고 그 형의 집행이 끝나지 아니하였거나 그 집행을 받지아니하기로 확정되지 아니한 사람

- 「성폭력범죄의 처벌 등에 관한 특례법」 제3조부터 제10조까지 및 제15조에 규정된 죄로 금고 이상의 형을 선고받은 사람

- 「장애인활동 지원에 관한 법률」 제30조제1항제2호에 해당하여 활동지원인력 자격이 취소된 날부터 1년이 지나지 아니한 사람

- 「장애인활동 지원에 관한 법률」 제30조제1항제3호부터 제5호까지에 해당하여 활동지원인력 자격이 취소된 날로부터 2년이 지나지 아니한 사람

<결격사유 외 활동지원사가 될 수 없는 사람>

- 활동지원급여 수급자, 장기요양급여 수급자

- 활동지원기관이 아닌 사회복지시설의 장 또는 종사자

- 「노인장기요양보험법」 상 재가장기요양기관의 장 또는 종사자(장기요양요원은 제외)

- 활동지원기관의 장, 관리책임자, 전담관리인력 등 활동지원인력이 아닌 활동지원기관 종사자

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-10-30', 58, 'https://www.129.go.kr/faq/faq00.do?pageIndex=46#faq17020', '85e29b8c445a06bd08d5322fe23cfc5af64ae8f8f0d10608f941acf67e9c3ae1'),
('17001', 'faq129-20261010', '노인장애인', '장애인활동지원', '어린이집 교사로 근무하는 자도 활동지원사가 될 수 있나요?', '장애인활동지원 인력기준에서 활동지원기관이 아닌 사회복지시설의 장 또는 종사자는 활동지원인력이 될 수 없다고 규정하고 있습니다.

「영유아보육법」에 따른 어린이집은 사회복지시설에 해당되므로 어린이집 종사자는 활동지원인력이 될 수 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-10-29', 43, 'https://www.129.go.kr/faq/faq00.do?pageIndex=46#faq17001', '49018053ebc60ac451410a3100e1b19d7cf98e806ca1a8eb3a844fff0b3b3d49'),
('16861', 'faq129-20261010', '보건의료', '건강보험정책', '응급환자가 입원했을 때 본인확인 대상이 되나요?', '응급환자는 진료의 연속성을 따져 응급처치 후 입원 시 본인확인 예외 대상이 됩니다.

다만, 퇴원 이후 입원과 동일 상병에 따른 외래진료 시에는 본인확인 대상이 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-10-17', 148, 'https://www.129.go.kr/faq/faq00.do?pageIndex=46#faq16861', '1efe30d75f8efd45908fccea2ea8012d3f62349988b9e48dc2b50cd0bcf334ab'),
('16920', 'faq129-20261010', '보건의료', '건강정책', '간접흡연 노출 피해자 및 흡연자들을 위해 흡연부스를 설치 해주세요', '「국민건강증진법」 제9조제4항에 따라 흡연실은 해당 시설의 소유자·점유자 및 관리자가 재량에 따라 설치·운영하도록 규정하고 있습니다.

따라서 흡연실 설치 여부는 해당 시설의 관리자가 이용자 특성 등을 고려하여 설치 여부를 결정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-10-17', 56, 'https://www.129.go.kr/faq/faq00.do?pageIndex=46#faq16920', '52c74791b6ac2618646b79bb29c8d65b338b110d6de8ca19ab8e19ee4cf93552'),
('16940', 'faq129-20261010', '보건의료', '건강정책', '금연구역 내 개별 법령에서 제외 규정된 시설이 있는 경우 해당 구역도 금연구역인가요?', '연면적 1,000㎡ 이상 복합용도의 건축물은 시설 전체가 금연구역이므로 유흥주점, 단란주점 등 개별 법령에서 제외 규정된 시설이더라도 1,000㎡ 이상 복합용도 건축물에 있는 경우 금연구역에 포함됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-10-17', 29, 'https://www.129.go.kr/faq/faq00.do?pageIndex=46#faq16940', '487c76d850132f8b5d057a018a4cb0e510e0cb33ed4a21644993919a0ad42b0d'),
('16900', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁조정중재원에 조정신청을 하고자 하는 신청인이 미성년자인 경우 어떻게 해야 합니까?', '그 부모가 법정대리인으로서 신청을 해야 합니다.

신청인(환자)이 미성년자인 경우 참고적으로 법에 대리인이 될 수 있는 자를 규정하고 있는데 그 사항은 아래와 같습니다.

① 당사자의 법정대리인, 배우자, 직계존비속 또는 형제자매

② 당사자인 법인의 임직원

③ 변호사

④ 당사자로부터 서면으로 대리권을 수여받은 자(단, ①에 해당하는 자가 없는 경우에 한함)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-10-10', 72, 'https://www.129.go.kr/faq/faq00.do?pageIndex=46#faq16900', '3b45260334efaa4e04f01aebcc9b1a0d11f2255310749ec28304d655fae3f84d'),
('16901', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁조정중재원의 조정신청 효력은 언제부터 발생하며, 조정신청을 할 수 없는 경우는 언제입니까?', '조정신청은 필수서류인 ''조정신청서'', ''조정(중재)신청서 별지'', ''개인(민감)정보수집 이용처리동의서'', ''신청인의 신분증 사본'', ''통장 사본'', ''위임장(대리인의 경우)''이 구비되고 조정신청 수수료가 완납된 경우에 효력이 발생합니다.

조정신청을 할 수 없는 각하 사유는 아래와 같습니다.

① 이미 법원에 동일한 사건에 대한 소가 제기된 경우

② 이미 소비자분쟁조정위원회(한국소비자원)에 분쟁조정이 신청된 경우

③ 조정신청 자체로서 의료사고가 아닌 것이 명백한 경우

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-10-10', 41, 'https://www.129.go.kr/faq/faq00.do?pageIndex=46#faq16901', 'e1f59a0b9500b9c0ca883ec5c45c0f29786b1207392b30d72fe7f5cda95ba61e'),
('13677', 'faq129-20261010', '보건의료', '건강보험정책', '정신·한방병원에서 발생한 의료비도 재난적의료비 지원 사업에서 지원이 되나요?', '정신병원(정신건강의학과 포함), 한방병원(한방과 포함)에서 발생한 의료비는 진료를 받은 사람 중 질환 특성과 의료적 필요성 등을 고려하여 지원여부 심의가 필요한 경우로 개별심사를 통해 선별 지원합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-10-02', 236, 'https://www.129.go.kr/faq/faq00.do?pageIndex=46#faq13677', '92c0990f83ee79c30be778d146241fb8e83521bbd1d8b2478166f62502f58561'),
('16860', 'faq129-20261010', '보건의료', '공공보건정책', '외국인 근로자등 의료지원사업에서 받을 수 있는 지원서비스 범위는 무엇인가요?', '① 입원 및 외래 수술, 산전 진찰 지원, ② 외국인 근로자의 자녀·국적 취득 전 결혼 이민자 및 난민 인정을 신청한 자의 자녀(만 18세 미만)의 외래진료를 지원받을 수 있습니다. 단, 외국인 근로자의 배우자는 산전진찰 및 분만관련 의료비에 한하여 지원됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-10-01', 39, 'https://www.129.go.kr/faq/faq00.do?pageIndex=46#faq16860', '2e5b63942a75eaf82ab63cd65405cf78ef8919f4896f899ca2b0e8b083641a67'),
('16880', 'faq129-20261010', '보건의료', '공공보건정책', '외국인 근로자등 의료지원 사업을 통해 건강보험 급여 및 비급여 항목 모두 지원받을 수 있나요?', '건강보험 급여 항목에서 발생한 총 진료비의 90%(단, 식대는 80% 지원, 20% 본인부담)를 지원받을 수 있습니다. 상급병상 이용에 따라 추가 부담되는 입원료, 호스피스, 간호·간병통합서비스 병동 입원료 등은 지원 대상에서 제외됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-10-01', 30, 'https://www.129.go.kr/faq/faq00.do?pageIndex=46#faq16880', '24e87ed734e7488cfadce62c962b78ef780c86a953188ab5498fee87bc6f1067');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('16803', 'faq129-20261010', '사회복지', '긴급지원사업', '법인을 운영하다가 폐업(해산)한 경우에도 휴·폐업의 위기상황으로 긴급지원 요청이 가능한지?', '법인이 사업에서 얻는 소득은 법인의 소득이 되고, 임원 등의 개인 소득이 될 수는 없으므로

법인의 폐업(해산)을 개인사업장의 휴­폐업으로 인정하기는 어려습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-09-24', 8, 'https://www.129.go.kr/faq/faq00.do?pageIndex=47#faq16803', 'c26668fab9e01bb460ce513c6ddab513eb0adaa6f40a3c3274f9551b07fb7d67'),
('16801', 'faq129-20261010', '노인장애인', '노인장기요양제도', '복지용구사업소 시설장은 상근해야 하나요?', '「노인복지법 시행규칙」 [별표9] 재가노인복지시설의 시설기준 및 직원배치기준에 따라 시설장의 상근규정에서 ''복지용구를 제공하거나 대여하는 시설에 두는 시설장은 제외한다''고 명시하고 있습니다.

따라서 복지용구의 시설장의 상근의무는 규정하고 있지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-09-23', 57, 'https://www.129.go.kr/faq/faq00.do?pageIndex=47#faq16801', '24135e68d64a2266b5daae42a8cc5285e3b6569e285d23dcf643ab3350ecc468'),
('16802', 'faq129-20261010', '노인장애인', '장애인복지사업', '출퇴근용 자동차를 먼저 구입한 후 장애인 자립자금 대여를 신청해도 되나요?', '장애인 자립자금 대여목적에 따른 출퇴근용 자동차 구입비의 경우, 반드시 자동차 구입 전에 대여신청하여 대여기관으로부터 받은 융자금으로 자동차를 구입하여야 합니다. (별도 자금으로 자동차 구입 후, 대여 융자금으로 상환하는 방식 불가)

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-09-23', 67, 'https://www.129.go.kr/faq/faq00.do?pageIndex=47#faq16802', '0623497745ad6f1e38dbf40d6fefa7bbb159f33ac0d56971cbe19a451e741e96'),
('16781', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인자립자금 대여사업은 대출 한도액이 정해져 있나요?', '장애인 자립자금 대여사업의 대출한도액은 아래와 같습니다.

○ 무보증 대출* : 가구당 1,200만원 이하(단, 생업용 및 출퇴근용 자동차 구입자금의 경우 특수설비 부착시 1,500만원 이내)

* 무보증 대출 요건 : 기존 대출금(신용대출 및 현금서비스 이용 합계액)이 2천만원 이하인 자 중,

연간 재산세 납세실적이 2만원 이상인 자 또는 연간 소득이 600만원 이상인 자

○ 담보 대출 : 담보 범위 내(5,000만원 이하)

※ 출퇴근용 자동차 구입자금의 대여는 한도액 이내에서 자동차 구입 실제 가격 이하를 융자

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-09-22', 44, 'https://www.129.go.kr/faq/faq00.do?pageIndex=47#faq16781', '3112a9c23b7252c6ea4a9b449c17efa21a7c0775c3d7ae324b0243109fd28478'),
('8426', 'faq129-20261010', '인구아동', '아동분야사업', '(입양) 입양가정 아동이면 모두 입양아동 양육수당을 받을 수 있나요?', '입양아동 양육수당은 ­국내입양에 관한 특별법­에 따라 보호대상아동을 국내입양한 가정에 입양아동이 만18세가 되는 날(수급권이 상실된 날)이 속한 달까지 매달 20일, 20만원을 지급합니다.

* 국내입양에 관한 특별법­에 의해 입양된 아동이 이후 ­민법­에 의해 다른 가정에 재입양 된 경우는 지급대상

* ­국내입양에 관한 특별법­ 제30조(입양의 당사자 중 일방이 외국인인 경우)에 따라 양부모가 되려는 사람이 외국인이며, 우리나라 보호대상아동(복수국적도 해당)을 국내입양한 경우에도 입양아동 양육수당 지급 가능

* ­민법­에 따른 입양, ­국제입양에 관한 법률­ 에 따른 국제입양(국내에서 국외로 입양, 아동의 일상거소를 외국에서 국내로 이동하는 입양)은 지급대상 아님

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-09-10', 499, 'https://www.129.go.kr/faq/faq00.do?pageIndex=47#faq8426', '19604b7270fb048da5c56ad573ad661007ce4dec463759fcf42283a7cc959e65'),
('16760', 'faq129-20261010', '보건의료', '건강보험정책', '요양기관 본인확인 시 주민등록번호가 없는 건강보험증, 신여권도 본인확인 수단으로 인정하나요?', '건강보험증은 본인확인 수단(국민건강보험법 제12조 제4항)으로 인정이 가능하며,

신여권의 경우 여권정보증명서를 첨부하면 인정이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-09-08', 69, 'https://www.129.go.kr/faq/faq00.do?pageIndex=47#faq16760', 'f777a3815c3602b4b2eddfe8d88338ac8bb85848a6f3d49ce61e939b8926a8e2'),
('16721', 'faq129-20261010', '인구아동', '사회복지시설', '사회복지시설 운영위원회의 구성은 어떻게 하나요?', '사회복지시설 운영위원회의 구성은 사회복지사업법 제36조 제2항 및 시행규칙 제24조1항에 따라 다음과 같이 구성합니다.

○ 위원회는 위원장 1인을 포함하여 5인 이상 15인 이하의 위원으로 구성하고, 법 제36조제2항 각 호 중 같은 호에 해당하는 위원이 2명을 초과해서는 아니 됨(각 호의 위원당 2명까지 가능)

­○ 위원회의 위원은 아래에 해당하는 자 중에서 관할 시장·군수·구청장이 임명 또는 위촉

- 시설의 장

- 시설 거주자(이용자) 대표

- 시설 거주자(이용자) 보호자의 대표

- 시설 종사자의 대표

- 해당 시군구 소속의 사회복지업무를 담당하는 공무원

- 후원자 대표 또는 지역주민

- 공익단체에서 추천한 사람

- 그 밖에 시설의 운영 또는 사회복지에 관하여 전문적인 지식과 경험이 풍부한 자

○ 위원장은 호선, 위원의 임기는 3년으로 하되 연임할 수 있고 보궐위원의 임기는 전임자의 잔임 기간으로 함

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-09-03', 28, 'https://www.129.go.kr/faq/faq00.do?pageIndex=47#faq16721', '819218075bf29df146b7eb283337847d9cdd59d589fa36563d2fc5d15ca04aed'),
('16740', 'faq129-20261010', '사회복지', '긴급지원사업', '신용불량으로 통장을 사용할 수 없는 경우 어떻게 긴급셍계지원을 받을 수 있는지?', '긴급지원 대상자 선정 후 즉시 「긴급지원대상자 증명서」를 발급받아서 시중은행•우체국•신렵•새마을금고 등 금융권에 압류방지전용통장을 개설하여 해당 통장으로 지급받을 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-09-03', 32, 'https://www.129.go.kr/faq/faq00.do?pageIndex=47#faq16740', 'c4a2ac862f1f611b524880a0750b93859075b07df89c07acb94a2f65c193699b'),
('10517', 'faq129-20261010', '노인장애인', '장애인등록', '장애정도 심사 진행상태를 확인할 수 있나요?', '국민연금공단 홈페이지에 접속하여 장애등록심사 진행상태 조회에서 확인 가능합니다.

- 접속경로 : 국민연금홈페이지(www.nps.or.kr) → 전자민원 → 개인 → 조회 → ‘장애정도심사 진행상태 조회''

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-09-02', 1334, 'https://www.129.go.kr/faq/faq00.do?pageIndex=47#faq10517', '1046cf15661d96569217def8c53031677a6c93e90d0b2a0dca14448e93351141'),
('12197', 'faq129-20261010', '보건의료', '건강정책', '영유아 발달 정밀검사비 지원금액이 어떻게 되나요?', '­영유아 발달 정밀검사비 지원금액은 아래와 같습니다.

- 기초생활수급자(의료·주거·생계), 차상위계층：최대 40만원

- 건강보험가입자 및 피부양자：최대 20만원

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-09-02', 215, 'https://www.129.go.kr/faq/faq00.do?pageIndex=47#faq12197', '53899c82bad0cab910b362acb143beeba51ad9c325e15479e32fedafd5bb1141'),
('16700', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁중재원에 조정신청 시 의료사고에 관여된 의료기관(의료인)이 둘 이상인 경우 누구를 상대로 신청해야 합니까?', '신청인이 판단하기에 둘 이상이라고 생각되는 경우 각각 피신청인으로 지정하여 조정신청을 할 수 있습니다.

이런 경우 피신청인 복수신청서 또는 각각의 조정신청서를 제출하시면 됩니다.

또한, 같은 사건에 피신청인이 2인 이상인 경우에는 1개의 사건으로 간주하여 접수가 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-09-02', 46, 'https://www.129.go.kr/faq/faq00.do?pageIndex=48#faq16700', 'c0a50c327e108e56bf7bd69f95bf7a36756bdd9423e4337cc7739160119cfff8'),
('16720', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁조정중재원에 조정신청을 하려면 변호사를 대리인으로 선임해야 하는지요?', '변호사를 반드시 대리인으로 선임할 필요는 없으며, 신청인의 판단에 따라 대리인 선임도 가능합니다.

의료분쟁 조정신청은 당사자 또는 그 대리인이 할 수 있습니다.

대리인으로 선임될 수 있는 사람은 다음과 같습니다.

① 당사자의 법정대리인, 배우자, 직계존비속 또는 형제자매

② 당사자인 법인의 임직원

③ 변호사

④ ①에 해당하는 사람이 없는 경우에는 당사로부터 서명으로 대리권을 수여받은 자

대리 신청의 경우에는 대리권을 증명할 수 있는 위임장을 제출하여야 하며 위임장에는 당사자와의 관계를 확인할 수 있는 서류를 첨부하여야 합니다.

조정절차는 소송과는 달리 의료행위 사실관계, 감정이 대부분을 차지하고 서면진술 보다는 자유로운 진술도 가능하므로 당사자가 절차를 진행할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-09-02', 34, 'https://www.129.go.kr/faq/faq00.do?pageIndex=48#faq16720', 'b2f4482b36ac6c35206441cef68c2bc9a4da23bd1126f4f1da6a0d9f8105c44f'),
('7914', 'faq129-20261010', '보건의료', '공공보건정책', '건강보험가입자가 21년 6월 이전 암진단으로 암환자의료비 지원사업 대상자인데, 의료급여수급권자로 변경되는 경우 지원 한도는 연간 300만원으로 확대되나요?', '그렇습니다.

의료급여수급권자 기준 연간 최대한도 300만원 내에 지원 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-09-01', 1276, 'https://www.129.go.kr/faq/faq00.do?pageIndex=48#faq7914', '6b17bf202f85cc1b788fc6493f43b657a168e2f9287c0daa266d55755763cb1c'),
('7917', 'faq129-20261010', '보건의료', '공공보건정책', '건강보험가입자로 21년 6월 이전에 진단 또는 검진 수검 이력이 있어 암환자의료비 지원사업 지원대상자에 해당된다면 지원 연도의 1월 건강보험료 기준도 확인해야 하나요?', '그렇습니다.

차상위 및 의료급여 암환자의 원활한 지원금 지급을 위해 건강보험가입자 하위 50%에 대한 지원은 ''21.6.30에 종료하였으나, 유예기간을 두어 해당자에 한해 한시적으로 지원합니다.

성인 건강보험가입자에 대해서는 2021년 6월까지 국가암검진 수검(비용지원 대상자 외 본인부담금 발생자 ''공단검진'' 포함)을 한 사람 중, ''1차 검진일''로부터 만 2년 이내에 암을 진단받은 경우로서 해당연도 1월 1일 기준 부양자의 건강보험료 납부액(기준액)이 기준에 적합할 시 지원이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-09-01', 909, 'https://www.129.go.kr/faq/faq00.do?pageIndex=48#faq7917', '7a7fd46b77354502b23c961722c6edc920392511e4116ce58e0cddcaf98c85ac'),
('14803', 'faq129-20261010', '노인장애인', '장애인활동지원', '장애인활동지원 제한적 가족급여 제공하는 가족도 활동지원사의 자격을 갖추어야 하나요?', '장애인활동지원 서비스는 활동지원사 자격이 있는 자에 의하여 제공되어야 하므로 가족급여를 제공하는 가족도 활동지원사 교육을 수료하는 등 자격을 갖추어야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-29', 160, 'https://www.129.go.kr/faq/faq00.do?pageIndex=48#faq14803', '21b58458f67cbefdf9c712ae98a0dce8cc0bf30083211c6925b9c05d7b2ac41a'),
('14999', 'faq129-20261010', '노인장애인', '장애인활동지원', '장애인활동지원 제한적 가족급여는 한 번 신청하면 계속 이용할 수 있나요?', '「장애인활동지원에 관한 법률 시행령」 제21조제4호에 따른 활동지원 제한적 가족급여 대상자로 선정된 이후에도 매달 등록된 활동지원기관에 활동지원사 연계를 신청해야하며, 매월 활동지원사 연계 요청을 하지 않거나, 부적절한 미연계 요청 또는 고의로 미연계를 유도하는 경우 다음 달부터 가족급여 이용이 종료될 수 있습니다.

또한, 영 제21조제4호에 따른 가족급여 수급자는 1년 주기로 재승인을 받아야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-29', 197, 'https://www.129.go.kr/faq/faq00.do?pageIndex=48#faq14999', '537f617d2d9abb4f714f88ecbc480e8c15a8b355b040d2105936664ccd424a9d'),
('16680', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인 치과주치의 시범사업이 무엇인가요?', '구강관리가 필요한 중증장애인, 뇌병변·정신 경증장애인이 치과주치의로 등록한 치과의사 1인을 선택하여 예방적 진료, 구강보건교육 등 포괄적으로 구강관리서비스를 받는 제도입니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-29', 51, 'https://www.129.go.kr/faq/faq00.do?pageIndex=48#faq16680', 'd5877fe5cea8b7d90057466e194c947a7fe7f000479852eba94b8ca9a75c2de3'),
('16683', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인 거주시설 입소자도 발달장애인 긴급돌봄서비스를 이용할 수 있나요?', '「장애인복지법」 제58조(장애인 복지시설)에 따른 장애인 거주시설에 입소한 발달장애인은 제외대상에 해당됩니다.

다만, 평일에만 이용 가능한 장애인공동생활가정 입소자의 경우 발달장애인 긴급돌봄 이용사유 등 입소요건에 충족되면 주말동안 이용이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-29', 29, 'https://www.129.go.kr/faq/faq00.do?pageIndex=48#faq16683', '92d566a786f5120b5998a3ef6eee6a906fca670da797f5102dfc3722c3503718'),
('16684', 'faq129-20261010', '노인장애인', '장애인복지사업', '보호자의 갑작스러운 사망으로 무연고자가 된 경우 발달장애인 긴급돌봄서비스 이용이 가능한가요?', '무연고 발달장애인은 생계를 같이 하는 보호자가 없는 독거 발달장애인으로, 보호자의 긴급상황으로 인한 돌봄 공백 사유가 발생하지 않는 자로 서비스 제외대상입니다.

단, 보호자의 갑작스러운 사망으로 무연고자가 된 발달장애인은 돌봄 공백이 발생하여 타 서비스 연계가 필요한 경우, 서비스 연계 과정에서 일시적으로 서비스 이용이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-29', 50, 'https://www.129.go.kr/faq/faq00.do?pageIndex=48#faq16684', '1dd718b72f05a18c568c4da47e94e35d4832f8e2060fecdd858d3abf8ab2f1b1'),
('1565', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인 건강주치의 시범사업이 무엇인가요?', '장애인 건강주치의는 장애의 정도가 심한 장애인(중증장애인)이 거주지역 또는 이용하던 의료기관의 의사 1인을 일반건강 관리의사 또는 주장애 관리의사로 선택하여 만성질환(일반건강관리) 또는 장애 관련 건강상태(주장애관리)등을 지속적이고 포괄적으로 관리받는 제도입니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-29', 1722, 'https://www.129.go.kr/faq/faq00.do?pageIndex=48#faq1565', 'b007f3b0488223f526641c13ee5193195b113855d2f638ca10aac7c820db78d3');
