INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('1567', 'faq129-20261010', '노인장애인', '장애인복지사업', '시범사업에 참여중인 건강주치의 및 의료기관은 어디서 확인하나요?', '국민건강보험공단 홈페이지에서 시범사업에 참여 중인 건강 주치의와 시범기관(의료기관) 정보를 확인할 수 있습니다.

*국민건강보험공단(http://nhis.or.kr)홈페이지 → 건강기관 /병(의)원찾기 → 특성별 기관찾기 → 장애인 건강(치과)주치의 의료기관 찾기

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-29', 1746, 'https://www.129.go.kr/faq/faq00.do?pageIndex=49#faq1567', '5f75f62ab5e96f8ea4027a4e4789ed4c6a7219b09cb92385677fcc5dbfb31d0a'),
('1572', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애친화 건강검진기관은 어디인가요?', '장애친화 건강검진 기관 공모를 통해 2023년까지 총 30개 의료기관을 지정하였으며, 그 중 다음 20개 의료기관이 서비스를 개시하였습니다.
* [서울] 서울의료원, 국립재활원, [대전] 대청병원, [경기] 경기도의료원수원병원, 성남시의료원, [강원] 원주의료원, [경북] 안동의료원, 경북권역재활병원, [경남] 마산의료원, 양산부산대학교병원, 조은금강병원, [제주] 의료법인중앙재단 제주중앙병원, 제주서귀포의료원, [부산] 부산의료원, 부산성모병원, 연제일신병원, 좋은삼성병원, [인천] 인천의료원, [충북] 청주의료원, [전남] 순천의료원

** 건강보험공단 홈페이지(www.nhis.or.kr) 검진기관 찿기에서 ''장애친화 검진기관'' 확인 가능

또한, 국가건강검진 사업을 수행하는 공공보건의료기관을 장애인 건강검진기관으로 당연 지정하는 「장애인 건강권 및 의료접근성 보장에 관한 법률」이 2023년 12월 14일부터 시행되어 공공보건의료기관 80개소가 당연 지정되었습니다. (2026년까지 장애인 건강검진기관 지정기준을 갖추도록 함)

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-29', 2650, 'https://www.129.go.kr/faq/faq00.do?pageIndex=49#faq1572', 'dd6b49080e6112d56258dcb0782f2dbc141d8eb0d0e574f4e88b186b547914d8'),
('1436', 'faq129-20261010', '노인장애인', '장애인연금(수당)', '기초생활수급자인 장애아동의 경우 장애아동수당은 언제부터 지급되나요?', '생계, 의료급여 수급자라고 해도 장애아동수당을 신청해야 신청일이 속한 달부터 장애아동수당이 지급되었지만 「장애인복지법」이 개정·시행되어 2025년 4월 22일 이후부터 기초생활보장 생계급여 또는 의료급여를 받는 등록 장애아동에게는 별도 신청하지 않아도 장애아동수당을 지급받을 수 있습니다.

* 법 개정규정 시행일 이후 생계, 의료급여를 받는 장애아동부터 적용됨

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-29', 1871, 'https://www.129.go.kr/faq/faq00.do?pageIndex=49#faq1436', 'f2677f12c7325c4c08bb399c7bf08b835e7595e18d319b630458339db231b0a0'),
('15959', 'faq129-20261010', '노인장애인', '장애인복지사업', '발달장애인 긴급돌봄서비스는 누가 받을 수 있나요?', '6세 이상 65세 미만의 발달장애인* 중 보호자의 치료.입원, 경조사, 심리적 소진 등 긴급상황 발생으로 일시돌봄이 필요한 경우 지원이 가능합니다.

* 「장애인복지법」상 지적·자폐성 장애인으로 등록된 자로서 지적장애 또는 자폐성 장애를 부장애로 가진 경우도 포함

단, 다음에 해당하는 경우에는 지원 대상에서 제외됩니다.

- 장애인거주시설에 입소한 발달장애인

- 의료기구·장비 사용 등 전문적 의료지원이 필요한 발달장애인

- ­감염병의 예방 및 관리에 관한 법률­ 제2조제1호에 따른 감염병 질환이 있는 발달장애인

- 보호자가 부재한 무연고 발달장애인

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-28', 58, 'https://www.129.go.kr/faq/faq00.do?pageIndex=49#faq15959', '6c07800a2563da13113d73faa1fce9dc6eebdae5decf0704cb1fc140394217b2'),
('16661', 'faq129-20261010', '노인장애인', '장애인복지사업', '보호자 여행의 사유로 발달장애인 긴급돌봄서비스 이용 가능한가요?', '단순 여행의 사유로 하는 이용신청은 불가합니다.

다만, 심리적 소진으로 인한 경우 최근 6개월 이내의 정신건강의학과 진단 및 소견서, 진료기록확인서 또는 발달장애인 부모상담지원 서비스 제공인력의 소견서 등 증빙서류 제출을 통해 이용 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-28', 23, 'https://www.129.go.kr/faq/faq00.do?pageIndex=49#faq16661', '289603d99f30271df71138d0621930f2a6e0a6eba80c0ad2f517efb4a18faa2f'),
('16660', 'faq129-20261010', '사회복지', '긴급지원사업', '건강보험자격이 없는 경우에도 긴급의료지원 가능한가요?', '건강보험자격이 없더라도 긴급의료지원 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-08-25', 17, 'https://www.129.go.kr/faq/faq00.do?pageIndex=49#faq16660', '4eb6cf6492db465d8fe222b16df621c14caef9aeedd97a18e30a9596d8d78d65'),
('16640', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급의료지원 요청시 간호간병 통합서비스를 이용할 경우 지원이 가능한지?', '간호간병 통합서비스는 전액 요양급여(건강보험적용)로 제공되는 입원 서비스이며, 해당 서비스를 이용하는 경우도 긴급의료지원이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-08-22', 14, 'https://www.129.go.kr/faq/faq00.do?pageIndex=49#faq16640', '88b83b5e9311e443b3e5f46c838f0e9b4a1b34e966dd223f66e86758599b41f7'),
('16641', 'faq129-20261010', '사회복지', '긴급지원사업', '감염 및 전염으로 인해 1인실(비급여)에 입원한 경우 긴급의료지원이 가능한지?', '원칙적으로 비급여 입원료는 지원하지 않습니다.

그러나, 진단서에 감염성 또는 전염병으로 인해 1인실 사용이 불가피한 사유가 명시되어 있다면 비급여의료비라 할지라도 예외적으로 지원 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-08-22', 7, 'https://www.129.go.kr/faq/faq00.do?pageIndex=49#faq16641', '33392135ff2af3b78d334177d18930bb3d71e8ea2b71a1851c2ef08dc289e194'),
('16600', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁조정중재원의 자동개시 사건의 경우 피신청인인 의료기관(의료인)이 이의신청할 수 있는 수단(방법)은 없습니까?', '자동개시 요건에 따른 조정절차가 개시된 경우 조정신청서를 송달받은 피신청인은

1. 신청인이 조정신청 전에 의료사고를 이유로 「의료법」 제12제2항을 위반하는 행위 또는 「형법」 제314조제1항에 해당하는 행위를 한 경우

2. 거짓된 사실 또는 사실관계로 조정신청을 한 것이 명백한 경우

3. 그 밖에 보건복지부령으로 정하는 사유로 해당되는 경우

조정절차의 개시에 대하여 송달받은 날부터 14일 이내에 위원장에게 이의신청을 할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-08-21', 43, 'https://www.129.go.kr/faq/faq00.do?pageIndex=49#faq16600', '7ccfe147f56d5fb227bc5314069d9b6ef36124b6e0735b23e39d64db85d03c3b'),
('16620', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁조정중재원에 조정을 신청한 신청인이 부득이한 사정으로 1차 조정기일에 참석하지 못하는 경우, 조정신청은 취하한 것으로 간주됩니까?', '신청인이 조정기일에 참석하지 못하더라도 취하한 것으로 간주되지는 않습니다.

다만, 의료중재원의 조정기간이 90일 이내(최대 120일)로 짧은 관계로 차회 조정심리기일을 다시 지정하는 것은 각 사건의 진행경과 등에 따라 다를 수 있습니다.

신청인이 2회에 걸쳐 출석하지 않을 경우에는 각하 사유에 해당됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-08-21', 41, 'https://www.129.go.kr/faq/faq00.do?pageIndex=49#faq16620', '37ddd9a4de21f8e992a0cf3b1af9a7e23cb3803df4afb86de129f55ffa33045c'),
('14020', 'faq129-20261010', '노인장애인', '장애인복지사업', '최중증 발달장애인 통합돌봄서비스가 무엇인가요?', '최중증 발달장애인 통합돌봄 서비스는 도전행동(자해·타해)이 심해 기존 돌봄서비스를 받기 곤란했던 발달장애인(지적·자폐성)에게 맞춤형으로 1:1 돌봄 서비스를 제공하는 사업입니다.

서비스 유형은 야간돌봄을 포함한 24시간 개별 1:1 지원서비스, 낮활동 서비스로 주간 개별 1:1 지원서비스, 주간 그룹 1:1 지원서비스로 제공하게 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-12', 47, 'https://www.129.go.kr/faq/faq00.do?pageIndex=50#faq14020', 'cb5bb509c8bd5f05f5d51a429ca8fc39ac9b5fd31d66c83fcfe0a9718326087d'),
('14038', 'faq129-20261010', '노인장애인', '장애인복지사업', '최중증 발달장애인 통합돌봄서비스는 어떤 서비스를 지원받게 되나요?', '최중증 발달장애인 통합돌봄 선정기준에 따라 다음의 3가지 서비스 중 적합한 서비스에 배치하여 1:1 맞춤형 서비스를 제공하게 됩니다.

1) 24시간 개별 1:1 지원 : 낮활동지원 및 야간 주거지원을 통한 24시간 돌봄서비스 지원

2) 주간 개별 1:1 지원 : 시설 보강 및 전문인력 지원을 통한 개별화된 개입과 이용자 특성에 맞는 맞춤형 낮 활동 서비스 제공

3) 주간 그룹 1:1 지원 : 사회서비스 이용권(바우처)을 통한 그룹형 1:1 낮 활동 서비스 제공

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-12', 93, 'https://www.129.go.kr/faq/faq00.do?pageIndex=50#faq14038', '9b1df652aadbf05a86a125fe4504b6207143f8c0f6fa3e15eb376f6ad46d30cc'),
('16202', 'faq129-20261010', '노인장애인', '노인장기요양제도', '노인요양시설에 CCTV 를 설치하지 않을 수 있나요?', '노인의료복지시설(노인요양시설, 노인요양공동생활가정)은 노인학대 방지 등 수급자의 안전을 위하여 폐쇄회로 텔레비전(CCTV)를 설치·관리하여야 합니다.

다만, 장기요양기관을 운영하는 자가 수급자 전원 또는 그 보호자 전원의 동의를 받아 시·군·구청장에게 신고한 경우 CCTV를 설치하지 않을 수 있습니다.

수급자 전원 또는 그 보호자 전원의 동의를 받아 CCTV를 미설치 시설의 신고를 받은 시·군·구청은 1년의 범위에서 미설치 기간(면제 기간)을 정해 장기요양기관 운영자에게 통보하게 됩니다.

자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-12', 37, 'https://www.129.go.kr/faq/faq00.do?pageIndex=50#faq16202', 'a67d5fb60db4a120cd038fafa729df3165e6348307266cde4229866765beb234'),
('16560', 'faq129-20261010', '사회복지', '긴급지원사업', '고비용이 요구되는 치과치료 중 틀니나 임플란트도 긴급의료지원 가능한지?', '치과 질환 중 틀니•임플란트•치아교정•치주염 등의 단순치료는 지원이 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-08-08', 28, 'https://www.129.go.kr/faq/faq00.do?pageIndex=50#faq16560', '65b21162789c855bb00a85e7fbab09d10d89788e44b4997edc7357dcf0e83aef'),
('16540', 'faq129-20261010', '보건의료', '공공보건정책', '간암 검진 대상자는 누구인가요?', '간암검진은 40세 이상 남녀 중 다음의 기준을 충족한 경우 대상입니다.

- 해당연도 전 2년간 간암발생고위험군 해당자

※ 간암발생고위험군은 간경변증, B형 간염항원 양성, C형 간염항체 양성, B형 또는 C형 간염 바이러스에 의한 만성 간질환 환자로서 해당하는 질병분류코드로 의료이용을 한 경우 대상자로 선정함

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-08-05', 41, 'https://www.129.go.kr/faq/faq00.do?pageIndex=50#faq16540', 'fc16686ee3040d2a08bce9af377f2f9309704dd4f6b75a7938803201224456ff'),
('16541', 'faq129-20261010', '보건의료', '공공보건정책', '국가암검진 후 결과통보는 언제까지 받을 수 있나요?', '암검진실시기준 고시에서 정하는 바에 따라 국가암검진기관은 암검진을 완료한 후 수검자의 암검진 결과를 검진일로부터 15일 이내에 우편, 이메일, 모바일 등으로 통보하도록 하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-08-05', 33, 'https://www.129.go.kr/faq/faq00.do?pageIndex=50#faq16541', '884ae210bcbdaf7c6a45fa53b31ce72f60e49c28e173f70a9691fdba8ec81a7a'),
('14420', 'faq129-20261010', '보건의료', '건강정책', '전국에 있는 지역보건기관(보건소, 보건지소, 보건진료소) 현황을 알 수 있을까요?', '전국 지역보건기관 현황은 아래의 경로를 통해 확인이 가능합니다. .

- 보건복지부 누리집 > 정보 > 현황 > ''지역보건의료기관'' 검색 후 확인

- 건강보험심사평가원 누리집 > 전체메뉴 > 의료정보 > 병원·약국 찾기 > 병원·약국 종류별 찾기 > 종류선택 > 보건기관

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-08-04', 151, 'https://www.129.go.kr/faq/faq00.do?pageIndex=50#faq14420', 'e0d671a86c8300acb4d10a8533524cd9d274250d42d6d3ec25614ed81030573e'),
('16520', 'faq129-20261010', '보건의료', '건강정책', '이미용사 면허 재발급시 필요한 구비서류는 뭐가 있나요?', '- 면허증 재교부 신청서(시행규칙 제10호 서식)

- 면허증 원본(기재사항이 변경되거나 헐어 못쓰게 된 경우)

- 사진 1매(최근 6월 이내의 3.5­4.5cm 탈모 정면 상반신 사진)

면허 최초 발급 관할 또는 현 소재지 관할 등의 여부와 관계 없이 전국 시,군,구로 신청가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-08-04', 28, 'https://www.129.go.kr/faq/faq00.do?pageIndex=50#faq16520', '6e0ea0e2ef53ef48397c896e2dc48281890c99d807b7ebc8ad8e926a4418d71c'),
('7490', 'faq129-20261010', '인구아동', '기초연금사업', '자녀와의 임대차계약서로 임대보증금 부채 인정이 가능한가요?', '기초연금 산정 시 자녀와의 임대차계약은 임대보증금 부채 인정 불가합니다.

2007년 10월 15일 이후 ''기초연금 수급자 또는 그 배우자''와 ''직계 존·비속 및 그 배우자, 형제자매 및 그 배우자'' 간에 체결한 ''임대차계약서''에 따른 임대보증금은 부채로 인정되지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-01', 1798, 'https://www.129.go.kr/faq/faq00.do?pageIndex=50#faq7490', '96f4f744e34f3851dfe11dc2fe15764c777a661ea158404889c3da9674d707b6'),
('11215', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금은 언제부터 신청이 가능한가요?', '기초연금은 신청자격이 있는자(대한민국 국적을 가지고 주민등록상 65세 이상인 자)가 65세 생일이 속하는 달의 1개월 전 초일부터 신청이 가능합니다

※ 수급자로 결정된 경우 신청일이 속한 달부터 기초연금 지급. 단, 사전신청자는 생일이 도래한 월부터 지급

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-01', 453, 'https://www.129.go.kr/faq/faq00.do?pageIndex=50#faq11215', '827615911847e68a8b0754e722874f824e1501e49dd8a24cdf06c0b8b1705946');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('11517', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 대상자 선정할 때 실업급여도 소득에 포함되나요?', '기초연금은 「고용보험법」에 의한 실업급여는 기초연금 소득인정액 산정시 소득으로 반영하지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-01', 909, 'https://www.129.go.kr/faq/faq00.do?pageIndex=51#faq11517', '1ea628bb2e7f99e9032740a4144e500ef60a9aae5a0dcc8b516f35850715bbf1'),
('12798', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금에서 공동명의로 되어 있는 자동차 재산산정은 어떻게 하나요?', '기초연금에서는 수급(권)자와 공동명의 자동차인 경우 소유 지분율을 적용하지 않고 수급(권)자의 재산으로 전액 산정합니다

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-01', 292, 'https://www.129.go.kr/faq/faq00.do?pageIndex=51#faq12798', '6186f9c227d946063cd3fa2b015b202c05e711e4e03daabd02f1100c32709fcd'),
('13139', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 수령 중 사망한 경우 언제까지 지급되나요?', '기초연금은 대상자로 결정되어 기초연금 수령 중 사망한 경우 사망한 날이 속하는 달까지 지급하고 중지됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-01', 74, 'https://www.129.go.kr/faq/faq00.do?pageIndex=51#faq13139', 'cca316fde773c373830a57ff5576a6b041bdfa8d3d46774718bab4ead76d7590'),
('13501', 'faq129-20261010', '보건의료', '건강보험정책', '재난적의료비 지원사업은 요양병원에서 발생한 의료비도 지원이 되나요?', '요양병원에서 발생한 의료비는 지원이 제외됩니다.

다만, 질환특성(의료적 필요성)을 고려하여 지원여부 판단이 필요한 경우로 의료최고도* 환자로서 증빙서류(세부내역서 등)를 통해 소명된 경우 심의를 통해 지원이 가능할 수 있습니다.

*ADL이 11점 이상이면서 혼수, 중심정맥영양, 인공호흡기 중 하나 이상에 해당하는 경우(진료비 영수증 세부내역서에 의료최고도가 표기된 경우)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-08-01', 331, 'https://www.129.go.kr/faq/faq00.do?pageIndex=51#faq13501', 'cbe88bea31f64fe3c3216eb07339ffb7acfc7a85904a7c5c47476423a3bf9fbe'),
('16500', 'faq129-20261010', '보건의료', '건강보험정책', '비급여로 진료 받는 환자에 대해서도 본인확인을 해야 하나요?', '비급여 진료의 경우 본인확인 대상이 아닙니다.

"요양기관은 가입자 또는 피부양자에게 요양급여를 실시하는 경우 본인여부 및 그 자격을 확인하여야 한다."고 국민건강보험법 제12조 제4항에 명시되어 있어, 국민건강보험법 제41조제2항제1호에 따라 요양급여를 실시하는 경우 즉 건강보험을 적용하는 경우 본인확인 대상입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-08-01', 143, 'https://www.129.go.kr/faq/faq00.do?pageIndex=51#faq16500', 'ec95022d135d3b18bb293e20c12b39ba45c9fdfeceb6724359a89842826773e9'),
('1585', 'faq129-20261010', '인구아동', '기초연금사업', '부부가 별거 중인데 단독으로 기초연금을 신청할 수 없나요?', '기초연금은 신청자와 그 배우자를 가구원으로 구성하여 소득­재산을 조사하므로 신청 시에는 혼인관계에 있는 배우자의 동의가 필요하고 배우자의 소득­재산도 포함하게 됩니다.

다만, 사실상 이혼 관계에 있다면 배우자 없이 단독가구로 조사하여 지원여부를 결정할 수 있습니다.

사실상 이혼으로 인정받기 위해서는 본인 및 배우자 모두 사실이혼 상태에 동의해야하며, 자녀 등이 확인해준 ''사실(이)혼 관계 확인서''를 제출하셔야 합니다.

이때 주민등록상 주소지가 동일하거나, 함께 생활 또는 거주하는 경우 혼인관계가 유지된 것으로 간주하여 사실이혼이 불인정됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-01', 13799, 'https://www.129.go.kr/faq/faq00.do?pageIndex=51#faq1585', '4320474b10d2252b96959235c71b50aa29c398a84146f96aa749bd9802913c3b'),
('1598', 'faq129-20261010', '인구아동', '기초연금사업', '종중의 토지가 기초연금 신청자명의로 등기된 경우 재산에 포함되나요?', '기초연금은 종중의 재산이더라도 개인명의로 등기한 경우에는 등기 명의자의 재산으로 반영됩니다. 단, 판결 또는 종중정관 등으로 종중재산임이 확인된 경우 재산산정에서 제외 가능합니다.

또한, 관할 시·군·구에서 비법인단체 ''부동산등기용 등록번호''를 부여받아 종중명의로 변경하는 경우에도 재산산정 제외 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-01', 2059, 'https://www.129.go.kr/faq/faq00.do?pageIndex=51#faq1598', 'a0585489a2e91f9d5131ce0ba1647aa1ae3d638b7c53ed095008112f0c895e6a'),
('1600', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금의 금융재산 조회범위와 기준은 어떻게 되나요?', '기초연금에서 금융재산 조사를 위한 조회범위 및 산정기준은 다음과 같이 반영됩니다.

1. 보통예금, 저축예금, 자유저축예금 등 요구불예금 : 3개월 이내 평균잔액

2. 정기예금, 정기적금, 정기저축 등 저축성예금 : 잔액 또는 총 납입액

3. 주식, 수익증권, 출자금, 출자지분：최종 시세가액

4. 채권, 어음, 수표, 채무증서, 신주인수권 증서：액면가액

5. 연금저축：정기적으로 지급되는 금액 또는 최종 잔액

6. 보험증권：해약하는 경우 지급받게 될 환급금 또는 최근 1년 이내에 지급된 보험금

7. 연금보험：해약하는 경우 지급받게 될 환급금 또는 정기적으로 지급되는 금액

※ 연금상품(보험, 저축, 신탁)은 연금 개시 후 정기적으로 지급받는 월 수령액이 조회되며, 연금소득으로만 산정

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-01', 5044, 'https://www.129.go.kr/faq/faq00.do?pageIndex=51#faq1600', '4b405ce41b0e6e69c1d2cf4119fe18e1e3bab1e5ff9e9d8740af78d98c12ee3e'),
('1628', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 신청자 명의 토지가 도로부지인 경우 재산에서 제외되나요?', '기초연금은 소유권이 제한되는 도시계획 도로부지라 하더라도 개인 명의의 토지이므로 재산으로 반영합니다.

재산을 사용·수익·처분하는데 제약이 있거나 사회통념상 경제적 가치가 없다고 하더라도 재산으로 산정 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-01', 1421, 'https://www.129.go.kr/faq/faq00.do?pageIndex=51#faq1628', '42980afc6d9d9c432db898bcbfed9954f44f458cb24acdd8c7acd47efa74193e'),
('1629', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 수급자가 퇴사하면 반영되었던 근로소득은 어떻게 산정 하나요?', '기초연금 산정시 상시근로소득은 공적자료로 조회되는 ''연간소득액을 기준으로 평균한 소득(금액)''을 반영합니다.

단, 근로상태가 변경된 경우 변경된 상태를 반영한 월 소득액을 산정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-01', 1836, 'https://www.129.go.kr/faq/faq00.do?pageIndex=51#faq1629', 'd739db65763019e844484ca1cbaf324386878b2c6649cc9fe786840d0bf21d38'),
('1606', 'faq129-20261010', '인구아동', '기초연금사업', '거주불명등록자도 기초연금을 신청할 수 있나요?', '기초연금은 거주불명등록이 되어 있더라도 기초연금 신청이 가능합니다.

전국 읍·면·동 주민센터 또는 행정복지센터, 국민연금공단 지사에서 신청하실 수 있으며 선정기준에 적합한 경우 기초연금을 지급받으실 수 있습니다.

다만, 수급자로 선정된 후 소재여부가 확인되지 않으면 기초연금 지급이 정지 될 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-08-01', 4354, 'https://www.129.go.kr/faq/faq00.do?pageIndex=52#faq1606', 'd7f348eba81e9c940bd94717c40d2551578b882037d7b37b503c5e4143ee3364'),
('6852', 'faq129-20261010', '인구아동', '기초연금사업', '이혼신고 없이 세대분리된 경우 사실이혼 인정이 가능한가요?', '기초연금 사업에서 법률혼 부부가 이혼신고를 하지 않고 사실이혼에 모두 동의하더라도 주민등록상 주소지가 동일하거나 함께 생활 또는 거주하는 경우 혼인관계가 유지되는 것으로 간주하여 사실이혼을 인정되지 않을 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-07-31', 2575, 'https://www.129.go.kr/faq/faq00.do?pageIndex=52#faq6852', '1caef638b4a906d794616c9ad2d6268a825f7a131f8193f2fb92ce52bdaed998'),
('16480', 'faq129-20261010', '사회복지', '긴급지원사업', '중한 질병 및 부상으로 무급 휴직상태인 경우 긴급생계지원 신청 가능한지?', '중한 질병 또는 부상으로 근로를 할 수 없어 소득을 상실하여 생계가 곤란한 경우 긴급지원 신청이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-31', 28, 'https://www.129.go.kr/faq/faq00.do?pageIndex=52#faq16480', 'a8e87009c17b3cbea816a6ac088843ed0194df7e1b3f683a7e0a9c7013ce4aeb'),
('16481', 'faq129-20261010', '사회복지', '긴급지원사업', '현역으로 군입대한 자녀는 가구원 수에 포함을 하는지요?', '법률상 의무이행을 위해 다른 곳에서 거주하고 있는 현역 군인에 대해서는 조사가구원에서 제외하고, 보장가구원에서도 제외합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다..', '2025-07-31', 8, 'https://www.129.go.kr/faq/faq00.do?pageIndex=52#faq16481', 'bee7bcb3a72f7cabf660efeb205e4453832976e8dd520ce17b7157d4b856b507'),
('16440', 'faq129-20261010', '사회복지', '긴급지원사업', '사회복지시설의 사회복무요원은 긴급복지 신고의무자 교육대상인가요?', '사회복무요원은 종사자가 아니므로 원칙적으로 교육대상자는 아닙니다. 다만, 시설이용자와 상담업무를 진행하는 경우에는 교육이수를 권고합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-28', 6, 'https://www.129.go.kr/faq/faq00.do?pageIndex=52#faq16440', 'c19fd4385108119c536eabbc911005ba28d6f326cd3be5f4180aec14f91da27f'),
('16460', 'faq129-20261010', '사회복지', '긴급지원사업', '사회복지시설에서 노인일자리 등 정부일자리사업의 참여자로 근무중인 경우에도 긴급복지 신고의무자 교육대상인가요?', '노인일자리 등 정부일자리사업 참여자는 사회복지사업법에 따른 사회복지시설의 종사자로 보기 어려우므로 교육대상이 아닙니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-28', 11, 'https://www.129.go.kr/faq/faq00.do?pageIndex=52#faq16460', '3d52867b490feb72aacee8d6c9e06bea1dbb6a6e6830fe6951101443d7effb7f'),
('16420', 'faq129-20261010', '사회복지', '긴급지원사업', '중한 질병 및 부상으로 유급 휴직상태인 경우 긴급생계지원 신청 가능한가요?', '중한 질병 및 부상으로 근로를 할 수 없어 소득을 상실하더라도 실업급여, 보험금 등을 받고 있는 경우에는 지원대상에서 제외하므로 휴직급여를 받는다면 소득상실이 아닌 소득감소로 보기 떄문에 긴급지원 위기사유로 인정하기 어렵습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-24', 13, 'https://www.129.go.kr/faq/faq00.do?pageIndex=52#faq16420', '3b3b9b93f642b133c6021953f02a0597cebc4325d0241d8017e19b75166d1d5d'),
('16002', 'faq129-20261010', '사회복지', '자활사업', '차상위 자활 참여자격은 어떻게 되나요?', '차상위자활은 근로능력이 있고 소득인정액이 기준 중위소득 50% 이하인 비수급자가 신청하여 참여 가능합니다.

만 65세 이상의 경우 지역 및 개인 여건(예산·자원, 참여자·대기자 규모 및 대기기간, 근로능력 등)을 종합적으로 고려하여 시·군·구청장의 판단에 따라 참여가 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-18', 845, 'https://www.129.go.kr/faq/faq00.do?pageIndex=52#faq16002', 'ac823b08b668bc4dd6efdd49cc190c3bb8b4c74066f6b8c50decca6b11ab983c'),
('16003', 'faq129-20261010', '사회복지', '자활사업', '자활참여자가 태아검진 시 유급휴가 부여 가능한가요?', '2025년부터 임신한 여성 자활 참여자가 「모자보건법」 제10조에 따른 임산부 정기건강진단을 받을 경우, 각 회마다 4시간의 유급휴가 처리가 가능합니다.

- 임신 28주까지 : 4주마다 1회

- 임신 29주에서 36주까지 : 2주마다 1회

- 임신 37주 이후 : 1주마다 1회

임산부가 「장애인복지법」에 따른 장애인인 경우, 만 35세 이상인 경우, 다태아를 임신한 경우 또는 의사가 고위험 임신으로 판단한 경우 횟수 추가 인정이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-18', 199, 'https://www.129.go.kr/faq/faq00.do?pageIndex=52#faq16003', 'a50b69bf22d70c8dd803e63fba32323c017e5a5e5953408ebb3a59245b3380db'),
('16001', 'faq129-20261010', '사회복지', '기초생활보장사업', '수급자가 이자소득이 있을 경우 소득으로 반영하나요?', '이자소득이란, 예금·­주식·­채권의 이자와 배당 또는 할인으로 발생하는 소득으로서 차세대사회보장정보시스템을 통해 조회되는 이자소득에서 이자소득 공제액 24만원을 차감한 금액을 이자소득으로 반영하고 있으며,

이자소득 발생 적금­저축 등의 가입기간을 확인(계약원장사본, 통장사본, 해지영수증 등) 하여 12개월 초과 상품인 경우에는 초과된 개월수(월단위산정)만큼 연간 최대 24만원(월2만원)범위 내에서 추가 공제도 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-11', 916, 'https://www.129.go.kr/faq/faq00.do?pageIndex=52#faq16001', '35df028e63ce1fef3831e24c8f3a265d67d0058b0a69d6c40e8fc8609a7b2bdd');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('16242', 'faq129-20261010', '사회복지', '의료급여사업', '전동휠체어 지원 이후 전지교체가 필요한 경우, 신청기간이 정해져 있나요?', '전동휠체어 또는 의료용 스쿠터 지급 대상자가 해당 보조기기를 지속적으로 사용한 경우, 보조기기 최종 구입일로부터 1년 6개월 경과 후 전지지원이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-07-11', 206, 'https://www.129.go.kr/faq/faq00.do?pageIndex=53#faq16242', '61fc78d66b8e9f9bba1b7709b82ffc827cf708a7e41d1a0a0db889e29bbb593c'),
('16260', 'faq129-20261010', '사회복지', '자산형성지원통장사업', '해외에서 발생한 근로·사업소득으로 청년내일저축계좌 가입이 가능한가요?', '청년내일저축계좌는 청년이 꾸준히 근로활동을 하는 경우 가입 가능하며 국내에서의 근로활동만 인정 가능하므로 해외에서 발생한 근로·사업 소득으로는 가입이 불가합니다.

자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-11', 169, 'https://www.129.go.kr/faq/faq00.do?pageIndex=53#faq16260', '497aa230b3f7be0b63339038a9c17ad233bf4cd52b49d71481b2c4849d11b6c5'),
('16280', 'faq129-20261010', '사회복지', '기초생활보장사업', '수급자의 대학생 근로소득공제 적용기간이 개정되었나요?', '2025년 7월 1일부터 대학생(휴학, 입학·졸업유예 포함)의 근로(사업)소득 공제 적용기간이 최대 6년(누적)으로 제한됩니다.

근로(사업)소득 공제 적용기간 6년은 25년 7월 1일부터 기산하며 동 기간에 군입대 복무기간은 산입하지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-11', 438, 'https://www.129.go.kr/faq/faq00.do?pageIndex=53#faq16280', '99b90a717b7f6aba617ce1f56c483b0008263c50e0a44472d22af53e65323b22'),
('16380', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁조정중재원에 조정신청 후 처리결과로는 어떤 유형이 있는지요?', '신청인이 조정을 신청한 후에는 ''합의'', ''조정결정'', ''조정을 하지 아니하는 결정'', ''취하'', ''각하'' 등의 처리결과가 있을 수 있습니다.

''합의''는 말 그대로 조정 중에 신청인과 피신청인이 합의를 하는 것이며, 양 당사자가 합의한 내용에 따라 작성된 조정조서는 재판상 화해와 같은 효력이 있습니다.

''조정을 하지 아니하는 결정''은 「의료사고 피해구제 및 의료분쟁 조정 등에 관한 법률」 제33조의3에 따라, 신청인이 정당한 사유 없이 조정을 기피하는 등 그 조정신청이 이유 없다고 인정하는 경우, 신청인이 거짓된 사실로 조정신청을 하거나 부당한 목적으로 조정신청을 한 것으로 인정하는 경우, 사건의 성질상 조정에 적당하지 아니한 경우에 조정부에서 내리는 결정입니다.

''취하''는 신청인이 신청한 조정사건을 도로 거두는 것을 말합니다.

''각하''는 피신청인이 조정신청서를 송달받은 날부터 14일 이내에 조정절차에 응하고자 하는 의사를 통지하지 않거나, 다음과 같은 경우에 내려지는 결정 유형입니다.

- 이미 법원에 소가 제기되어 있거나 소비자분쟁조정위원회에 분쟁조정이 신청된 사항과 동일한 내용의 조정신청을 한 경우

- 조정신청이 있은 후에 법원에 소가 제기된 경우

- 조정신청의 대상이 의료사고로 인한 것이 아님이 명백한 경우

- 조정신청의 대상이 법 시행 전에 종료된 의료행위 등으로 인하여 발생한 의료사고에 해당하는 경우

- 신청인이 2회 이상의 보정요구에 응하지 아니하거나 보정할 수 없는 경우

- 신청인이 조사에 응하지 아니하거나 2회 이상의 출석요구에 응하지 아니한 경우

- 신청인이 조정신청 후에 의료사고를 이유로 의료법 제12조제2항을 위반하는 행위를 하거나 또는 형법 제314조제1항에 해당하는 행위를 한 경우

- 당사자의 소재불명, 연락두절 기타 조정절차를 진행할 수 없는 경우

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-09', 71, 'https://www.129.go.kr/faq/faq00.do?pageIndex=53#faq16380', 'c505836c1a927e6d358c86eddbd6cde1abdf3720f868e5ad7013e8c067d92bd9'),
('16381', 'faq129-20261010', '보건의료', '보건의료정책', '민사소송을 제기한 상태에서 의료중재원에도 조정을 신청할 수 있습니까?', '민사소송을 이미 제기한 상태에서 의료중재원에도 조정을 신청하려는 경우에는 「의료사고 피해구제 및 의료분쟁 조정 등에 관한 법률」 제27조제3항에 의거 각하 사유에 해당되므로 조정신청을 할 수 없습니다.

또한 같은 사유로 소비자분쟁조정위원회(한국소비자원)에 분쟁조정이 신청된 경우에도 각하 사유에 해당됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-09', 60, 'https://www.129.go.kr/faq/faq00.do?pageIndex=53#faq16381', '844cde2fadcdd6b7b7063784150a83c6308460b79144ec157d0ef2e606a81366'),
('16340', 'faq129-20261010', '보건의료', '공공보건정책', '헌혈은 어디에서 할 수 있나요?', '네. 대한적십자사 혈액관리본부 누리집 - [헌혈참여] - [헌혈의집 찾기]에서 헌혈의집을 검색하고 [상세보기]를 통해서 헌혈의 집별로 가능한 헌혈 종류 및 헌혈의 집 운영시간 등을 확인하실 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-07', 28, 'https://www.129.go.kr/faq/faq00.do?pageIndex=53#faq16340', 'a66caaa84592fe7c430cf1fa61edf02273b32881ce371649fb50c6f4c2c8eec3'),
('16341', 'faq129-20261010', '보건의료', '공공보건정책', '유전자 검사기관은 어디서 확인할 수 있나요?', '네. 유전자검사기관 현황은 공공데이터포털(data.go.kr)에서 "유전자검사기관 현황"을 검색하시면 [질병관리청_유전자검사기관현황]을 확인하실 수 있습니다.

해당 자료는 생명윤리 및 안전에 관한 법률 제49조에 따라 질병관리청에 신고된 유전자검사기관에 대한 데이터입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-07', 41, 'https://www.129.go.kr/faq/faq00.do?pageIndex=53#faq16341', 'a431d65749a8771fc9872b3824dddfc235260f879c78678531ec23554effbd28'),
('16342', 'faq129-20261010', '사회복지', '의료급여사업', '장애인 보조기기 내구연한은 처방일부터 산정하나요?', '장애인보조기기의 내구연한은 “구입일”이 기준일이므로, 구입일로부터 내구연한을 산정합니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-07-07', 128, 'https://www.129.go.kr/faq/faq00.do?pageIndex=53#faq16342', '7834734f99c9d161c093952b7b83f5a0579bcee80515082ed66f2f9a4b7645c1'),
('16360', 'faq129-20261010', '사회복지', '의료급여사업', '장애인 보조기기 처방전은 주소지 소재 의료기관에서만 받을 수 있나요?', '장애인보조기기 처방전은 신청자 거주지와 동일한 시도내에 있는 병의원 처방전만 인정됩니다.

다만, 평소 이용하는 병의원임을 입증하는 경우 타 시도 소재 병의원 처방전도 인정 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-07-07', 75, 'https://www.129.go.kr/faq/faq00.do?pageIndex=53#faq16360', '8097778c1bef5849afe3f86f98bc8232ffeec882077553404cf75d1dfa727483'),
('16241', 'faq129-20261010', '인구아동', '기초연금사업', '''기초연금 수급자 확인서''를 대리로 발급받을 수 있나요?', '''기초연금 수급자 확인서''를 위임 발급받고자 하는 경우에는 ‘위임받는 자(대리인)의 신분증’과 ''증명서 발급 위임장 및 법정대리인등 동의서(공통서식 별지 제17호 서식)''를 제출하여 신청 가능합니다.

* 수급자(위임자) 본인에게 ''기초연금 수급자 확인서'' 관련 위임여부(위임사실, 본인자필 서명)와 제출처, 제출용도 등을 유선으로 확인

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-04', 15, 'https://www.129.go.kr/faq/faq00.do?pageIndex=53#faq16241', '30bca48a39f0d2a337a43c60c9ff850fa05f1b6edac51bc96ec94d70d424da57'),
('16240', 'faq129-20261010', '인구아동', '기초연금사업', '''기초연금 수급자 확인서'' 발급은 어떻게 하나요?', '''기초연금 수급자 확인서''는 전국 읍면동 주민센터 방문신청 또는 본인이 복지로(www.bokjiro.go.kr)에 접속하여 온라인신청으로 즉시 발급 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-03', 23, 'https://www.129.go.kr/faq/faq00.do?pageIndex=54#faq16240', '02a6e72fe6ce3dae71a8b6c31749c0f4275fc3b50bb344852a60e51c3b33e6ff'),
('14010', 'faq129-20261010', '보건의료', '건강정책', '아동치과주치의 건강보험 시범사업이 무엇인가요?', '아동이 등록된 주치의를 학기별* 1회 정기적으로 방문하여 문진·시진·검사를 통해 치아의 발육 및 건강상태를 확인하고, 구강검진 결과에 따라 구강건강 관리교육, 예방서비스를 받는 지속적이고 포괄적인 아동 구강건강관리제도로 2024년 7월 ~ 2027년 2월 (2년 8개월) 까지 실시합니다.

* 1학기(3월~8월), 2학기(9월~다음년도 2월)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-01', 49, 'https://www.129.go.kr/faq/faq00.do?pageIndex=54#faq14010', '059a64b2d56bc355bbb09378c21b13cea002d5549fdf2a9cf53fd1a004f2931e'),
('16203', 'faq129-20261010', '노인장애인', '노인장기요양제도', '노인요양시설이 있는 건물 엘리베이터에도 CCTV를 설치해야하나요?', '노인요양시설에서 자체 운영하는 엘리베이터는 필수로 설치해야합니다.

다만, 상가건물 또는 다세대 주택 등에서 운영하여 건물 내 불특정 다수가 공용으로 이용하는 엘리베이터는 필수 설치장소에서 제외됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-07-01', 42, 'https://www.129.go.kr/faq/faq00.do?pageIndex=54#faq16203', '29071a65b107482c5a649830644eabfd3a68cb28680ed8de4a25cb5a8cf486a0'),
('16300', 'faq129-20261010', '보건의료', '건강정책', '아동치과주치의 시범사업 지역으로 전학 온 아동도 서비스 신청이 가능한가요?', '네. 시범사업 참여기간 2024년 7월 ~ 2027년 2월(2년 8개월)내에 전학 온 학생은 건보공단에 신청서 등과 재학 증명서를 제출하여 아동치과주치의 서비스 신청을 하면 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-07-01', 18, 'https://www.129.go.kr/faq/faq00.do?pageIndex=54#faq16300', 'cdb93320b6b36c8dbd0a582cdfb697123e8760ead2df3d086f0443dd912b62f0'),
('16201', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인 보조견표지 발급 대상이 어떻게 되나요?', '보건복지부장관이 고시하는 시설기준에 해당하는 장애인 보조견 전문훈련기관에서 훈련 중이거나 훈련을 이수한 장애인 보조견이 표지 발급대상에 해당합니다.

전문훈련기관의 장이 해당 훈련기관에서 훈련중이거나 훈련을 이수한 장애인 보조견에 대하여 보조견표지의 발급을 신청할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-06-30', 46, 'https://www.129.go.kr/faq/faq00.do?pageIndex=54#faq16201', '94a4e992de5acaebc0e0fb17bbba6578a744a9e55c8d915dd5807ea0545d4f0e'),
('16221', 'faq129-20261010', '노인장애인', '노인장기요양제도', '노인의료복지시설에서 CCTV를 반드시 설치해야 하는 곳은 어디인가요?', '노인의료복지시설의 각 공동거실(침실과 연결되는 복도 포함), 침실, 현관(외부에서 출입이 가능한 출입로), 물리(작업)치료실, 프로그램실, 식당, 시설 자체 운영 엘리베이터에 1대 이상씩 설치하여햐 합니다.

- 다만, 침실은 수급자 전원 또는 그 보호자 전원의 동의를 받은 경우에만 촬영할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다', '2025-06-30', 27, 'https://www.129.go.kr/faq/faq00.do?pageIndex=54#faq16221', 'e306825bfccde38f8334edfeea8d0e316389240b9a6c04db0afca26c49075a42'),
('16200', 'faq129-20261010', '노인장애인', '노인장기요양제도', '모든 장기요양기관은 CCTV 설치가 의무인가요?', '「노인장기요양보험법」 제31조에 따라 장기요양기관으로 지정을 받은 노인요양시설 및 노인요양공동생활가정이 의무설치 적용 기관입니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-06-25', 26, 'https://www.129.go.kr/faq/faq00.do?pageIndex=54#faq16200', '0b1a89fc1de1fca932bd2df776500a9bcff07757c6f2eaeba2b257c57fe150b0'),
('16220', 'faq129-20261010', '노인장애인', '장애인복지사업', '청소년 발달장애인 방과후 활동서비스 외국인도 신청이 가능한가요?', '「장애인복지법」제32조의2(재외동포 및 외국인의 장애인 등록)에 따라 장애등록한 재외동포 및 외국인의 경우는 신청대상에서 제외됩니다.

다만, 예외적으로 난민법 제2조제2호에 따른 난민인정자로서 「장애인복지법」상 장애인으로 등록한 외국인은 방과후 활동서비스 신청 자격이 있습니다

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-06-25', 27, 'https://www.129.go.kr/faq/faq00.do?pageIndex=54#faq16220', '7c6dbd3e862488311f15229cb1da0164b6e03ea929625008234cb022430daedb'),
('4090', 'faq129-20261010', '노인장애인', '장애인복지사업', '청소년 발달장애인 방과후 활동서비스 신청자격은 어떻게 되나요?', '청소년 발달장애인 방과후 활동서비스는 6세 이상 18세 미만의 「장애인복지법」상 등록된 지적 및 자폐성장애인이 신청 가능합니다.

18세 이상의 재학생의 경우에는 주간활동서비스(단축형, 기본형에 한함)와 방과후활동서비스(재학증명서 필수) 중 선택하여 이용 가능합니다. (중복이용불가)

다만, 지역아동센터, 다함께돌봄센터, 청소년 방과후 아카데미, 장애인 거주시설 입소자(장애인공동생활가정 거주자는 가능), 장애인 주간보호시설 등 다른 유사 복지서비스 이용자는 신청대상에서 제외됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 문의주시기 바랍니다.', '2025-06-24', 2224, 'https://www.129.go.kr/faq/faq00.do?pageIndex=54#faq4090', 'd613380eceb571f10e7a9e2e5e54397c0eb2f171d845250d58e51198d1f66be5'),
('4107', 'faq129-20261010', '노인장애인', '장애인복지사업', '청소년 발달장애인 방과후 활동서비스란 무엇인가요?', '청소년 발달장애인 방과후 활동서비스는 청소년 발달장애인에게 방과후 돌봄 사각지대를 해소하고 다양한 프로그램을 통해 사회성 증진 및 가족의 돌봄부담을 경감하며, 의미있는 여가활동 및 성인기 자립준비 지원을 목적으로 지원되는 서비스 입니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-06-24', 1996, 'https://www.129.go.kr/faq/faq00.do?pageIndex=54#faq4107', '9cdbbf488791236d9567b42eea112d46088f9db3b9ef9106470f7a771ee669d3');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('4109', 'faq129-20261010', '노인장애인', '장애인복지사업', '청소년 발달장애인 방과후 활동서비스 이용시간은 어떻게 되나요?', '지역 내 방과후활동 제공기관과 상담을 통해 이용자 인원(2~4인)과 프로그램 등을 협의하여 월 바우처 급여량 한도(월 66시간)내에서 월~토(09시~21시) 선택적으로 사용 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 문의주시기 바랍니다', '2025-06-24', 1643, 'https://www.129.go.kr/faq/faq00.do?pageIndex=55#faq4109', 'e51e7375db7d703f69b93499cb1cb86eef58a8bd4fd73d1f00916a73c6739a81'),
('4110', 'faq129-20261010', '노인장애인', '장애인복지사업', '청소년 발달장애인 방과후 활동서비스의 본인부담금은 얼마인가요?', '청소년 발달장애인 방과후 활동서비스의 기본단가는 시간당 16,620원으로 그룹별(2~4인)로 단가를 달리 적용하여 바우처 지원금으로 운영하고 있으며, 바우처 이용에 따른 별도 본인부담금은 없습니다.

다만, 서비스 이용 중 점심식사가 제공되거나 송영서비스가 제공되는 경우 실비 수준의 비용이 발생할 수도 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 문의주시기 바랍니다.', '2025-06-24', 1889, 'https://www.129.go.kr/faq/faq00.do?pageIndex=55#faq4110', 'becd807a0ceee4d018b4a253da374c5b2e173cecbd13ffacba52a4dd9f6cf6c4'),
('9351', 'faq129-20261010', '노인장애인', '장애인복지사업', '청소년 발달장애인 방과후활동서비스 대상자가 되면 어떤 서비스를 받을 수 있나요?', '청소년 발달장애인 방과후활동서비스 프로그램은 청소년 발달장애인이 방과후에 의미있는 활동에 대하여 자기주도적으로 참여하면서 다양한 여가생활을 누리고 성인기 자립준비에 도움이 되는 프로그램을 제공합니다.

2~4인 그룹별로 지역사회 내에서 취미·여가, 자립준비, 관람·체험, 자조활동 등 이용자의 욕구를 고려한 다양한 프로그램을 제공합니다. 대상자는 지정된 방과후활동 제공기관과 상담을 통해 이용자 그룹 및 프로그램 등을 협의하여 서비스를 이용하실 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-06-24', 934, 'https://www.129.go.kr/faq/faq00.do?pageIndex=55#faq9351', '93d3d272090edffb269d77f51a237cb44f88cf30dc4302f5ac0e3ea33d9bca9a'),
('16159', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁조정중재원에 조정신청을 할 수 있는 기간은 언제까지 입니까?', '한국의료분쟁조정중재원에 조정신청을 할 수 있는 기간은 의료사고의 원인이 된 행위가 종료된 날부터 10년, 손해 및 가해자를 안 날부터 3년 이내로 규정하고 있습니다.

만일 이 기간을 경과하면 한국의료분쟁조정중재원을 이용한 피해구제 절차는 이용할 수 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-06-19', 59, 'https://www.129.go.kr/faq/faq00.do?pageIndex=55#faq16159', '612f98770fcb331e3a201c4f907207162f3f0b0cc38717f896ce3c644e39d5c3'),
('16179', 'faq129-20261010', '보건의료', '공공보건정책', '헌혈을 하면 봉사시간을 받을 수 있나요?', '헌혈을 하면 헌혈종류에 상관없이 1회당 4시간의 봉사시간을 인정 받을 수 있습니다.

단, 사회복지 자원봉사 인정기준 시행계획에 따라 2010년 7월 1일 이후 헌혈만 봉사시간이 인정됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-06-18', 32, 'https://www.129.go.kr/faq/faq00.do?pageIndex=55#faq16179', '6c21435ad9597f53cb2efa6b48b155c027f81038ba0e162078907bd6a927057d'),
('16199', 'faq129-20261010', '보건의료', '공공보건정책', '헌혈증서의 사용에 유효기간이 있습니까?', '헌혈증서에는 유효기간이 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-06-18', 30, 'https://www.129.go.kr/faq/faq00.do?pageIndex=55#faq16199', 'dcfe91094bed0e6593ef4cdc7434fc348f24ac8fab4be1e21c899b281861dd82'),
('16139', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁조정중재원에서 조정이 불성립된 경우에는 어떠한 구제절차를 밟아야 합니까?', '조정이 불성립된 경우에는 신청인은 법원에 소를 제기하여 피해구제 절차를 밟을 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-06-17', 37, 'https://www.129.go.kr/faq/faq00.do?pageIndex=55#faq16139', '984754a705c36ff9290c4bc5d901977fc8a8d59710072447d60dd448c511e898'),
('13077', 'faq129-20261010', '보건의료', '건강정책', '장애인 구강진료센터란 무엇인가요?', '장애인 구강진료센터는 장애인 구강건강수준 향상 및 치과진료 접근성 향상을 위해, 치과병원 또는 종합병원 등에 장애인구강진료센터 설치비 및 운영비를 지원하고, 센터에서 진료받은 장애인 환자의 비급여진료비 일부를 지원합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-06-10', 90, 'https://www.129.go.kr/faq/faq00.do?pageIndex=55#faq13077', '700b07d61caa45373c38869fa377728c2f1a8f64428febc1bc6fcb1cf429dcc0'),
('16084', 'faq129-20261010', '노인장애인', '장애인복지사업', '발달장애인과 주소지 다른 보호자 입원 시에도 긴급돌봄서비스 신청이 가능한가요?', '발달장애인 긴급돌봄서비스를 신청할 수 있는 자격으로 ''치료·입원, 경조사, 심리적 소진 등 긴급 상황 발생으로 발달장애인 돌봄이 어려운 보호자''란 지원대상 발달장애인과 주민등록 상 동일 세대를 구성하고 실제로 생계와 거주를 같이 하면서 실질적으로 발달장애인을 돌보는 가족(2촌 이내)을 의미합니다.

다만, 불가피한 사유로 별도 세대를 구성하고 있거나 2촌 밖의 친족이더라도 실제로 생계와 거주를 같이 하고 해당 보호자가 실직적 주 돌봄자인 것으로 확인되면 예외적으로 이용이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-05-30', 33, 'https://www.129.go.kr/faq/faq00.do?pageIndex=55#faq16084', 'ae20a9280d356ffb7490b7ef2d70741681e00a3127b43f1b465df6d0c5433bba'),
('16082', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인 보조견 동반출입을 거부할 수 있나요?', '누구든지 보조견표지를 붙인 장애인 보조견을 동반한 장애인이 대중교통수단을 이용하거나 공공장소, 숙박시설 및 식품접객업소 등 여러 사람이 다니거나 모이는 곳에 출입하려는 때에는 정당한 사유* 없이 거부하여서는 안됩니다.

지정된 전문훈련기관에 종사하는 장애인 보조견 훈련자 또는 장애인 보조견 훈련 관련 자원봉사자가 보조견표지를 붙인 장애인 보조견을 동반한 경우에도 거부하여서는 안됩니다.

*정당한사유란?

1. 의료법 제3조제2항 각 호에 따른 의료기관의 무균실, 수술실 등의 감염관리를 위하여 필요한 경우

2. 식품위생법 제2조제12호에 따른 집단급식소의 조리장·보관시설(창고) 또는 같은 법 시행령 제21조제8호 각 목의 어느 하나에 해당하는 식품접객업 영업소의 조리장·보관시설(창고)의 위생관리를 위하여 필요한 경우

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-05-28', 22, 'https://www.129.go.kr/faq/faq00.do?pageIndex=55#faq16082', '865379fd78c42b41205eb120bdc7904c70baee2d8b45c971402fbdee8639c176'),
('16083', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인보조견 출입을 거부하면 과태료가 부과되나요?', '장애인복지법 제40조제3항을 위반하여 ''보조견표지''를 붙인 장애인보조견을 동반한 장애인, 장애인 보조견 훈련자 또는 장애인 보조견 훈련 관련 자원봉사자의 출입을 정당한 사유없이 거부한 자는 300만원 이하의 과태료가 부과됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-05-28', 21, 'https://www.129.go.kr/faq/faq00.do?pageIndex=56#faq16083', '128a188fa9fd25a86216d9cd1c21eae3d3ab98af2b131687246d031b36b4b43d'),
('16085', 'faq129-20261010', '노인장애인', '장애인복지사업', '여성장애인 출산비용은 어떻게 신청하나요?', '여성장애인 출산비용은 방문 및 온라인으로 신청 가능합니다.

○ 방문신청 : 여성장애인의 주민등록지를 관할하는 읍·면·동 주민센터, 민간신청기관*

*민간신청기관 12개소(23''년 12월 기준)

○ 온라인 신청(간편인증 또는 공동·금융인증서 인증 필요)

- 복지로 온라인신청 : 복지로 사이트 접속하여 여성장애인 출산비용지원 신청

- 정부24 온라인 신청 : 정부24 사이트 접속하여 임신·출산 관련 서비스 통합처리 신청

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-05-28', 30, 'https://www.129.go.kr/faq/faq00.do?pageIndex=56#faq16085', '24831ac94f20a393bfbeefe252afc838f4a706f9b60a1019a9fc25e01e0906c0'),
('16099', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인일자리에 참여했었는데 반복적으로 연속 참여가 가능한가요?', '장애인일자리는 연속하여 최대 2년까지만 허용되며, 2년 초과 시 1년간(1.1.~12.31.) 참여가 제한됩니다.

다만 아래와 같은 예외 대상의 경우 2년을 초과하여 참여가 가능합니다.

1, 장애정도가 심한 장애인

2. 국민기초생활보장법에 따른 국민기초생활수급자

3. 65세 이상인 사람

* 65세 이상인 사람 중 최근 3년간 연속참여자에 대해서는 선발 득점 총점의 5% 이상 감점

4. 장애인일자리사업 행정업무 지원을 위한 전담지원 행정도우미

5. 전문자격이 필요한 특화형 일자리 사업에 참여하는 사람

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-05-28', 48, 'https://www.129.go.kr/faq/faq00.do?pageIndex=56#faq16099', 'e8e2e0e2bf9ddb4e9a6486d0b74c43e2a4c06bfcf7bc2a0ce22f466db999d484'),
('16100', 'faq129-20261010', '노인장애인', '노인복지사업', '산분장지에 사망자의 이름 등을 기록한 표지를 설치해도 되나요?', '산분장지에 사망자 및 연고자의 이름 등을 기록한 표지를 설치할 수 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-05-28', 33, 'https://www.129.go.kr/faq/faq00.do?pageIndex=56#faq16100', '90c8b94704b3243d85b1fb908c23adcab9733f04ed2e517a6abec9781c6ea8f3'),
('16080', 'faq129-20261010', '인구아동', '출산정책', '(난자·정자 냉동지원) 영구 불임 예상 난자·정자 냉동지원 금액은 어떻게 되나요?', '영구 불임 예상 난자·정자 냉동지원 내용은 다음과 같습니다.

○ 지원 범위 : 검사, 과배란유도, 생식세포(난자·정자) 채취, 동결, 보관비용 일부 지원

- 생식세포 동결·보존과 관련된 비용이면 지원 금액 한도 내 지원 가능

※ 지원제외 : 입원료, 생식세포 동결·보존과 관련 없는 검사료, 연장 보관료 등

○ 지원 횟수 : 생애 1회

○ 지원 금액 : 본인부담금의 50%, 여) 최대 200만 원, 남) 최대 30만 원

○ 생명윤리 및 안전에 관한 법률상 허용되는 범위에서 지원

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-05-27', 24, 'https://www.129.go.kr/faq/faq00.do?pageIndex=56#faq16080', '749390540401dc0df82f03bb6fbf60f7911b79d89750223431956105e5d24f26'),
('16081', 'faq129-20261010', '인구아동', '출산정책', '(난자·정자 냉동지원) 영구 불임 예상 난자·정자 냉동지원 신청방법은 어떻게 되나요?', '영구 불임 예상 난자·정자 냉동지원 신청방법은 다음과 같습니다.

○ 신청 기간

- 생식세포 채취일로부터 6개월

※ 2025. 1. 1.을 포함하여 그 이후에 생식세포를 채취한 자일 것

○ 신청 방법

- 방문 신청 : 주민등록상 주소지 관할 보건소

- 온라인 신청 : e보건소(e-health.go.kr)

* e보건소 인증서 로그인(가입 불필요) 후 ''영구 불임 예상 난자·정자 냉동 지원'' 신청

○ 구비 서류

- 영구 불임 예상 난자·정자 냉동 지원 신청서

- 개인정보 수집·이용 및 행정정보 공동이용 동의서

- 신청인 본인 명의의 통장사본

(아래 서류는 의료기관에 요청)

- 모자보건법 시행령 제14조에 따른 의학적 사유 해당 여부에 관한 의사의 진단서

- 영구 불임 예상 난자·정자 동결·보존 확인서

- 외래 진료비 계산서·영수증

- 진료비 세부산정내역(세부내역서)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-05-27', 14, 'https://www.129.go.kr/faq/faq00.do?pageIndex=56#faq16081', '0f6ffc8cd69d914edda79db21c2c71ab8f1bc0f63d4a4ed9782609bf282eaf66'),
('2390', 'faq129-20261010', '인구아동', '지역사회서비스투자사업', '문화관광부 스포츠바우처 사업과 중복이용 가능한가요?', '문화체육관광부 스포츠바우처 사업과 지역사회서비스 투자사업 중 노인 맞춤형 운동 서비스, 장애인­산모 등 건강취약계층 운동 서비스, (비만)아동 건강관리 서비스는 유사 중복사업으로 동일 기간내 중복 수혜 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-05-27', 2522, 'https://www.129.go.kr/faq/faq00.do?pageIndex=56#faq2390', 'd4a29d90c573b317f60c0d152c0af073ba168121a7b52a93a8c2d1fe412229a1'),
('16059', 'faq129-20261010', '인구아동', '출산정책', '(난자·정자 냉동지원) 영구 불임 예상 난자·정자 냉동지원 대상은 어떻게 되나요?', '영구 불임 예상 난자·정자 냉동지원 대상은 다음과 같습니다.

1. 모자보건법 시행령 제14조에 해당하는 의학적 사유에 의한 생식건강의 손상으로 영구 불임이 예상되는 자

※ 생식세포 채취일이 2025. 1. 1.을 포함하여 그 이후일 것

[의학적 사유 : 모자보건법 시행령 제14조]

1. 유착성자궁부속기절제술, 2. 부속기종양적출술, 3. 난소부분절제술, 4. 고환적출술, 5. 고환악성종양적출술, 6. 부고환적출술, 7. 항암치료(항암제 투여, 복부 및 골반 부위 포함 방사선 치료, 면역 억제 치료), 8. 염색체 이상(터너증후군, 클라인펠터증후군, 균형전이에 따른 생식기 기능 저하) |

- 의학적 사유는 열거된 수술·치료에 해당된다고 인정할 수 있다면 폭넓게 인정

※ 항호르몬치료(내분비치료) 치료도 항암치료에 포함

- 열거된 수술·치료를 진행할 예정이거나, 진행 완료 후에도 생식기능 보전이 필요한 경우 지원 가능

2. 주민등록이 되어 있는 대한민국 국적 소유자(주민등록 말소자, 재외국민 주민등록자는 대상에서 제외)이면서, 건강보험 가입이 확인되는 자

※ 재외국민 주민등록 관련 법령 : 주민등록법 제6조, 제24조 참조

더 자세한 사항은 보건복지상담센터 (국번없이 129)로 연락주시기 바랍니다.', '2025-05-26', 17, 'https://www.129.go.kr/faq/faq00.do?pageIndex=56#faq16059', '56563a846b6c8e656aeac3d70498b5b57ac20fab4ba6405921702242f384d785'),
('4701', 'faq129-20261010', '인구아동', '산모신생아건강관리지원사업', '산모신생아 서비스는 하루에 몇 시간 제공되나요?', '바우처 서비스는 1일 8시간 제공(휴게시간 포함 9시간)되며, 서비스 제공시간은 09시부터 18시까지 연속해서 제공하는 것이 원칙입니다.

다만, 이용자와 제공자 간 합의가 있는 경우 계약에 반영하여 서비스 시작·종료시간을 달리 정할수 있습니다.

더 자세한 사항은 보건복지상담센터 (국번없이 129)로 연락주시기 바랍니다.', '2025-05-21', 1787, 'https://www.129.go.kr/faq/faq00.do?pageIndex=56#faq4701', '7c18a427ca6fe332a1fd963f61ab9df24acdb8692fda89ec5038d99e9be74d9d'),
('4713', 'faq129-20261010', '인구아동', '산모신생아건강관리지원사업', '외국인도 산모신생아 제공인력으로 근로할 수 있나요?', '외국인은 「출입국관리법」 시행령에서 정한 체류자격 비자*를 가진 자에 한해 참여가 가능합니다.

* 체류자격 비자 : 거주(F-2), 재외동포(F-4), 영주(F-5), 결혼이민(F-6), 방문취업(H-2) 비자

