INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('4722', 'faq129-20261010', '인구아동', '산모신생아건강관리지원사업', '산모신생아 제공인력으로 일할 수 있는 자격은 어떻게 되나요?', '만18세 이상으로 「아동복지법」제26의2제2에 따른 아동학대 예방교육 및 보건복지부장관이 고시한 ''산모·신생아 방문서비스 제공인력 교육과정''을 이수한 자 중 제공인력의 결격사유*에 해당하지 않아야 제공인력으로 활동 가능합니다.

* 모자보건법 제15조의19(결격사유)의 각 호에 해당하지 않는 자.

산모신생아 방문서비스 제공인력 교육과정 중 교육시간은 신규자와 경력자를 구분하여 다음과 같습니다.

○ 신규자 과정 → 총 60시간(이론28, 실기32)

○ 경력자 과정 → 총 40시간(이론15, 실기25)

더 자세한 사항은 보건복지상담센터 (국번없이 129)로 연락주시기 바랍니다', '2025-05-21', 1373, 'https://www.129.go.kr/faq/faq00.do?pageIndex=57#faq4722', 'be12a3f3f123cfd685839882ad014d120d479f72dcf7cbf2301e65521e21168f'),
('4723', 'faq129-20261010', '인구아동', '산모신생아건강관리지원사업', '산모신생아 서비스 신청시 국민행복카드 발급을 받아야 하나요?', '산모신생아건강관리 지원을 받기 위해서는 국민행복카드가 필요합니다. 기 소지한 국민행복카드가 없다면 국민행복카드 발급을 받아야 이용 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2025-05-21', 1230, 'https://www.129.go.kr/faq/faq00.do?pageIndex=57#faq4723', '3b30aa415007238da404802abc336e256256cf68569465b5a8772e68b3e0a1a0'),
('15999', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁조정중재원에 의료분쟁 관련 상담을 하려면 어떻게 해야 하나요?', '의료분쟁 상담센터는 국번없이 1670-2545입니다.

오전 9시부터 오후 6시까지(점심시간 12시 ~ 13시 제외) 언제든지 전화주시면 무료로 상담을 받을 수 있습니다.

공휴일 또는 주말의 경우에는 우리 원 홈페이지 온라인 상담에 문의글을 남겨 두시면 익일 업무개시 일에 상담을 받으실 수 있습니다. 이외에도 팩스 또는 우편 상담도 가능합니다. 상세한 상담을 원하실 경우에는 의료중재원에 직접 방문하여 상담을 하실 수도 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-05-21', 73, 'https://www.129.go.kr/faq/faq00.do?pageIndex=57#faq15999', '9bec270b7a52fa9b597140885f318e95b320dbf2e39f8ed9279b31736c646aa1'),
('16039', 'faq129-20261010', '보건의료', '건강정책', '숙박업 영업신고 대상여부 판단은 어떻게 하나요?', '공중위생관리법에 따른 숙박업 영업신고 대상 여부는 아래의 판단기준에 따릅니다.

○ 판단기준

- 불특정 다수인이 잠을 자고 머물 수 있도록 시설 및 설비를 제공하고 위생관리서비스를 제공(법 제2조)

- 비교적 단기간을 예정(장기투숙도 가능), 영리성, 계속·반복성, 내부설비, 요금체계 등 각종 요소를 종합적으로 판단(법제처 유권해석 및 각종 판례)

- 명칭이 아닌 실질을 판단(숙박이 주목적인 자에게 숙박공간과 숙박서비스 제공 시 숙박업에 해당)

※ 참고 사례

- 육군훈련소에서 잠을 자지 않는 면회객 휴식공간 운영: X

- 특정인 한정 숙박시설 제공의 경우(미공군 단기숙소, 회사 기숙사): X

- ‘고시원’은 원칙적으로: X

- ‘파티룸’, ‘다이어트 합숙소’, ‘일주일 이하의 단기임대’ 등 실질적으로 숙박인 경우: O

- 특정목적(프로그램) 운영을 위해 부수적으로 숙박이 이루어지는 경우: X

(예:종교활동을 위한 기도원, 템플스테이, 24시간 학습을 위한 독서실, 고시원, 자연공원법에 따른 자연학습장)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-05-20', 91, 'https://www.129.go.kr/faq/faq00.do?pageIndex=57#faq16039', '739e91babcfde813d2a444e45b3aba7a8ee96c8280b7eef6eba2b460131b5253'),
('16040', 'faq129-20261010', '보건의료', '건강정책', '세탁업 영업신고 대상여부 판단은 어떻게 하나요?', '공중위생관리법에 따른 세탁업 영업신고 대상 여부는 아래의 판단기준에 따릅니다.

○ 판단기준

-불특정 다수인에게 의류 기타 섬유제품이나 피혁제품 등의 세탁 위생관리 서비스를 제공

※ 참고 사례

- 셀프 세탁소, 코인 빨래방 (손님 스스로 세탁)은 미해당

- 세탁 중개점(수거, 배달만 할 뿐 본­지점에서 세탁처리)은 미해당, 본­지점은 해당

* 위 2개의 형태라고 하더라도, 실제로 유기용제 등을 사용하여 세탁, 오염제거 처리 등을 하는 경우에는 세탁업에 해당

- 특정 세탁물만 처리하는 경우(불특정다수를 대상으로 세탁영업을 하는 것이 아니라, 헬스장­리조트 등으로부터 위탁받아 체육복­침대시트 등만 세탁처리)는 미해당

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-05-20', 70, 'https://www.129.go.kr/faq/faq00.do?pageIndex=57#faq16040', 'a003c76709e0cea235fcc1f24a622720249fc558d496e368d7347b11c9265d27'),
('9334', 'faq129-20261010', '보건의료', '건강보험정책', '차상위 본인부담경감대상자 지원사업은 무엇인가요?', '차상위 본인부담경감대상자 지원사업은 희귀질환, 중증난치질환, 중증질환자, 6개월 이상 치료를 받고 있거나 치료가 필요한 사람 또는 18세 미만 아동 중 세대의 소득인정액이 기준 중위소득의 50% 이하이고, 부양요건을 충족하는 자에 대해 요양급여비용 중 본인이 부담하는 본인부담금을 경감하여 주는 사업입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-05-15', 1177, 'https://www.129.go.kr/faq/faq00.do?pageIndex=57#faq9334', 'e4ca63dd25fb72dc091d089444e6c8f6a81467e0d4959adbd6029e549e53f349'),
('9587', 'faq129-20261010', '인구아동', '아동분야사업', '(입양) 입양숙려기간 모자지원은 어떤 지원이 이루어지나요?', '입양숙려기간 모자지원은 다음 서비스 중 선택하여 지원합니다.

구 분 |
지원내용 |
지원단가 |

­­ ♦ 가정 내 보호 지원

|
