­ ♦ 1주 산후조리원 이용료 지원 |
­ ♦ 최대 1,400,000원(25년 개정)

♦ 1주 이용료가 1,400천원 미만인 산후조리원의 경우, 실비 지원

※ 아동 생필품비 및 생모 식료품비 등 포함 |

* 산후지원인력 : 가정방문서비스 제공기관에 소속되어 있는 자, 산후관리사 자격증을 갖춘 자

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-05-14', 393, 'https://www.129.go.kr/faq/faq00.do?pageIndex=57#faq9587', 'a031cffe2324aa65942bef2cbd9b633046dd9886076e570618b4e603ccc78949'),
('1151', 'faq129-20261010', '인구아동', '아동분야사업', '(입양) 입양가정은 어떤 지원을 받을 수 있나요?', '입양가정은 신청을 통해 아동이 18세가 될 때까지 월 20만원의 입양아동 양육수당을 지원받을 수 있습니다.

장애아동을 국내 입양한 가정의 경우에는 만 18세가 될 때까지 장애의 정도가 심한 장애인 721천원(25년 개정), 장애의 정도가 심하지 않은 장애인 등 그 외 지원대상 634천원(25년 개정)의 양육보조금을 지원받을 수 있으며, 연간 260만원 한도 내 의료비도 지원받을 수 있습니다.

※ 장애의 정도가 심한 장애인 : 기존 장애등급 1급~3급

※ 장애의 정도가 심하지 않은 장애인 : 기존 장애등급 4급~6급

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-05-14', 3183, 'https://www.129.go.kr/faq/faq00.do?pageIndex=57#faq1151', '8792b816fc5af760280e502b6655d54faac83e62acbca31dece87bec9607dffd'),
('16019', 'faq129-20261010', '보건의료', '공공보건정책', '모든 병원에서 호스피스·완화의료를 이용할 수 있나요?', '호스피스·완화의료는 호스피스전문병원에서 이용할 수 있습니다.

호스피스전문병원은 일정한 인력, 시설, 장비등의 기준을 갖춘 의료기관이 보건복지부장관에게 신청하여 심사를 통해 지정을 받을 수 있습니다. 호스피스전문병원이 제공하는 호스피스 서비스는 입원형, 가정형, 자문형으로 나뉩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-05-09', 80, 'https://www.129.go.kr/faq/faq00.do?pageIndex=57#faq16019', '1c74b22d5edba6deb37493d5f3b43c4e5755b8be9eee33a3c8ebdaa07474eb4a'),
('15961', 'faq129-20261010', '노인장애인', '장애인복지사업', '발달장애인 긴급돌봄서비스는 어디로 신청하나요?', '발달장애인 및 보호자 주소지 권역 내 지역발달장애인지원센터의 홈페이지* 또는 유선전화** 를 통해 신청 가능합니다.

* www.broso.or.kr > ''발달장애인 긴급돌봄서비스 이용신청''

** 평일 주간(9:00~18:00)에는 주민등록상(발달장애인 및 보호자) 주소지 관할 내 소재한 지역발달장애인지원센터, 평일 야간(18:00~24:00)­­·주말­­·공휴일에는 발달장애인 긴급돌봄센터로 입소 신청

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-05-08', 31, 'https://www.129.go.kr/faq/faq00.do?pageIndex=57#faq15961', 'a9f589fb330265976012e34060d93066fe0854225334cd5154ab5da93976c445'),
('15939', 'faq129-20261010', '노인장애인', '장애인복지사업', '발달장애인 긴급돌봄서비스란 무엇인가요?', '발달장애인 보호자의 치료·입원, 경조사, 심리적 소진 등 긴급한 상황 발생 시 일시적(7일 이내)으로 돌봄을 지원하는 서비스 입니다.

발달장애인 보호자의 긴급한 상황으로 인한 돌봄 위기에 대처하고, 가족의 심리적 소진 방지를 통한 일시적 휴식을 지원하게 되고, 24시간 돌봄 지원체계를 마련하여 발달장애인 당사자에게 가족과 유사한 돌봄을 지원하고 가정 기반의 일상생활 및 사회활동 참여 유지할 수 있도록 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-05-07', 35, 'https://www.129.go.kr/faq/faq00.do?pageIndex=58#faq15939', '4359d6492ad60987a4ea504ee8cd3b0fd5ecd5feb858f9720163289f7cb37e7c'),
('15940', 'faq129-20261010', '노인장애인', '장애인복지사업', '발달장애인 긴급돌봄서비스는 본인부담금이 있나요?', '1일 이용료는 15,000원이며, 1일 식비는 15,000원(5,000원 X 3끼)입니다.

국민기초생활수급자 및 차상위계층의 경우는 별도 이용료를 지불하지 않아도 되지만, 식비는 지불해야합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-05-07', 27, 'https://www.129.go.kr/faq/faq00.do?pageIndex=58#faq15940', 'ca2a1a27baa3a352058795a3fd4d8cf28f0777d78b106f8092c673a753cec929'),
('15979', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁조정중재원에 분쟁조정 신청 시 처리기간은 얼마나 걸립니까?', '의료중재원의 조정 및 중재는 일반적으로 90일(최대 120일) 이내에 처리가 되도록 규정하고 있습니다.

다만, 이렇게 신속한 처리가 가능하기 위해서는 신청인의 관련 증빙자료가 필요합니다. 이에 관련 자료를 꼼꼼히 준비하여 조정에 참여하시기 바랍니다.

* 조정(중재)에 도움이 되는 증빙자료

1. 해당 의료기관의 진료기록 일체, 영상물

2. 이송 의료기관의 진료기록 일체, 영상물, 진단서(후유장애 진단 포함)

3. 치료비 영수증

4. 소득 관련 자료

5. 시술 전후 사진

6. 기타 관련 자료 등

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-05-01', 74, 'https://www.129.go.kr/faq/faq00.do?pageIndex=58#faq15979', 'bd3f2d3ba2199bd33df52711ac5b28efb893056fa63c3a9db989489b9d7f0847'),
('16000', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁조정중재원에서는 2012년 4월 8일 이전에 시행된 의료행위로 인해 발생된 의료사고도 접수 및 처리가 가능합니까?', '의료중재원에서는 법 시행(12.4.8.) 후 최초로 종료된 의료행위 등으로 인하여 발생된 의료사고부터 적용하도록 법에 규정되어 있는 관계로, 법 시행 이전에 시행된 의료행위로 인해 발생된 의료사고는 신청을 할 수 없습니다.

12.4.8 이전 사건은 한국소비자원이나 대한법률구조공단 등에 관련사항에 대한 피해구제 상담은 가능하오니 참고하시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-05-01', 26, 'https://www.129.go.kr/faq/faq00.do?pageIndex=58#faq16000', 'b435af092efce4b01806d7c03ff3d8a289255e5153581df9d5b46e098da2acb7'),
('15960', 'faq129-20261010', '노인장애인', '장애인복지사업', '발달장애인 긴급돌봄서비스 입소일수는 어떻게 되나요?', '발달장애인 긴급돌봄서비스는 긴급돌봄 상황에 따라 아래와 같이 입소 일수가 결정되며, 해당하는 경우 신청 시 증빙서류가 필요합니다.

