더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-04-29', 20, 'https://www.129.go.kr/faq/faq00.do?pageIndex=58#faq15960', 'f54b2b7ea561cb84e6837c467070a603b1fe17c7172d1c042b1a72a696edb587'),
('15962', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁조정중재원에 조정을 신청한 후의 처리절차는 어떻게 됩니까?', '조정신청이 접수되면 의료중재원에서 피신청인에게 조정신청서와 조정(중재)신청서 별지를 송달하여 14일 이내에 조정참여 의사를 확인하며, 피신청인이 조정에 참여한 경우 신청인으로부터 받은 조정신청서, 조정(중재)신청서 별지, 관련 자료와 피신청인을 상대로 조사 및 확인할 사실, 자료 등을 근거로 감정(과실 및 인과관계의 유무), 손해배상 검토 등을 거쳐 신청인과 피신청인에게 조정결정을 통한 해결을 권유하게 됩니다.

여기에 소요되는 기간은 법에 90일을 규정하고 있으나 1회에 한하여 30일까지 연장할 수 있어, 최대 120일 이내의 해결을 목표로 하고 있습니다.

다만, 후유장애 확정 등 보다 정확한 검사 및 사실조사, 검토가 요구되는 사건의 경우에는 관련 자료를 구비하는데 소요되는 시간 등은 본 기간에 산입하지 않고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-28', 40, 'https://www.129.go.kr/faq/faq00.do?pageIndex=58#faq15962', 'bf0c2ed11f0aacffc263f6e69d89c36d9898387fe7ddb8c454c9b13203a93eb2'),
('15941', 'faq129-20261010', '노인장애인', '장애인연금(수당)', '장애아동수당 지급일은 언제인가요?', '장애아동수당은 매월 20일에 지급됩니다. 다만, 지급일이 토요일이나 공휴일이면 그 전날에 지급됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-04-25', 48, 'https://www.129.go.kr/faq/faq00.do?pageIndex=58#faq15941', '1db9f7a1162c735dc2afb12406b183b5d39e84e44359fed5776a943a368392a3'),
('15381', 'faq129-20261010', '사회복지', '의료급여사업', '국가무형유산 보유자로 타법 의료급여 선정시, 국가유산청 지원금을 소득으로 반영하나요?', '국가무형유산 보유자 타법 의료급여 선정시, 월정전승지원금 등 국가유산청 지원금은 소득으로 반영하지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-04-15', 132, 'https://www.129.go.kr/faq/faq00.do?pageIndex=58#faq15381', '1e69e88796adfee43b0d8dc84164f07f8e933bb4b5e173e4ef1eece2b72c1898'),
('15399', 'faq129-20261010', '사회복지', '의료급여사업', '5·18 민주화운동 관련자로 타법 의료급여 선정시, 소득·재산 기준을 적용하나요?', '5·18 민주화운동 관련자가 타법 의료급여 신청시, 소득·재산 기준은 적용하지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-04-15', 109, 'https://www.129.go.kr/faq/faq00.do?pageIndex=58#faq15399', '0f6a145e5d2683fabb36b6b6b36f39ce0b5e7511ed55bddd757eed5c36b11c42'),
('15579', 'faq129-20261010', '사회복지', '의료급여사업', '의료급여 자격 득실을 확인할 수 있는 서류가 있나요?', '의료급여 수급자 또는 수급자였던 사람이 의료급여 이력 확인을 원할 경우, 의료급여 자격득실 확인서를 발급받을 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-04-15', 293, 'https://www.129.go.kr/faq/faq00.do?pageIndex=58#faq15579', '117aa2184445297bf436c619db41b820c2ddd9934a5c948ec645d0e054ad2c7d');
