INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('15659', 'faq129-20261010', '사회복지', '의료급여사업', '요양비 지급 신청을 인터넷으로 할수 있나요?', '요양비는 방문 또는 온라인(복지로)으로 신청할 수 있습니다.

*복지로(www.bokjiro.go.kr) → 서비스 신청 → 의료급여

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-04-15', 172, 'https://www.129.go.kr/faq/faq00.do?pageIndex=59#faq15659', '102b3f5605f212ab20f14c52566eabbd297f34f30f748fcf756a1d8b7f5c5439'),
('15679', 'faq129-20261010', '사회복지', '자활사업', '자활근로 참여자도 임신기 근로시간 단축이 가능한가요?', '2025년부터 임신 12주 이내 또는 32주 이후에 있는 여성 근로자는 1일 2시간 범위에서 휴식이나 병원 진료 등을 위한 모성보호시간 사용이 가능합니다.

임신기 근로시간 단축은 전일제(1일 8시간 근무) 참여자에 대해서만 적용하는 것이 원칙이나, 1일 근로시간이 8시간 미만인 참여자의 경우 1일 근로시간이 6시간이 되도록 단축 허용이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-15', 84, 'https://www.129.go.kr/faq/faq00.do?pageIndex=59#faq15679', 'f906f81e6fd283cdb0381f25a402059c098ab70ea0e51879b0c53b1a5ea8bf34'),
('15680', 'faq129-20261010', '사회복지', '자활사업', '자활근로 참여자도 육아기 근로시간 단축이 가능한가요?', '만12세 이하 또는 초등학교 6학년 이하의 자녀를 가진 참여자는 12개월 범위내에서 자녀돌봄, 육아 등을 위해 1일 최대 2시간의 육아시간 사용이 가능합니다.

육아기 근로시간 단축은 전일제(1일 8시간 근무) 참여자에 대해서만 적용하는 것이 원칙이나 1일 근로시간 8시간 미만인 참여자의 경우 1일 근로시간이 6시간이 되도록 단축 허용이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-15', 83, 'https://www.129.go.kr/faq/faq00.do?pageIndex=59#faq15680', '4d3dbd7a78525c8349e3c0199b06bc5b34199fe095709912bc09b5ef5160d502'),
('15803', 'faq129-20261010', '사회복지', '의료급여사업', '국가유공자 의료급여 대상이 보장시설에 입소하는 경우, 타법 의료급여 자격이 유지되나요?', '타법 의료급여 수급자가 시설에 입소하여 보장시설수급자로 선정되어도 타법 의료급여 자격은 유지 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-04-15', 87, 'https://www.129.go.kr/faq/faq00.do?pageIndex=59#faq15803', '1f4a0d816028665eda22cbb5b9a7262eee177aa8d401f6e5999d0a40793f0961'),
('15839', 'faq129-20261010', '사회복지', '자활사업', '자활근로 참여자도 가족돌봄 휴가를 사용할 수 있나요?', '2025년부터 자활 참여자의 모성보호 및 저출생 지원을 위해 가족돌봄유급휴가가 신설되었습니다. 미성년자녀 또는 장애인 자녀를 돌보는 경우 사용가능하며 해당 참여자의 자녀수에 1을 더한 일수까지 연간 유급휴가로 사용 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-15', 117, 'https://www.129.go.kr/faq/faq00.do?pageIndex=59#faq15839', '189ebb16bba48f46b8d115c192a5e5398a7fd372e213e8906b60beab44e911a2'),
('15840', 'faq129-20261010', '사회복지', '자활사업', '자활근로 참여자가 난임치료를 위해 유급휴가를 사용할 수 있나요?', '2025년부터 자활 참여자의 모성보호 및 저출생 지원을 위해 참여자가 인공수정 또는 체외수정 등 난임치료를 위해 휴가를 청구하는 경우 최초 2일을 유급휴가로 적용합니다. 단, 유급 2일 외 난임치료를 위한 휴가는 무급 병가 처리됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-15', 53, 'https://www.129.go.kr/faq/faq00.do?pageIndex=59#faq15840', '38582daf9e39c78d342d4f80ee05356eba72be0fba95b241ff199877a8d9279d'),
('15859', 'faq129-20261010', '사회복지', '자활사업', '자활근로참여자도 출산전후휴가급여를 받을 수 있나요?', '10개월 이상 자활근로 사업에 참여하고 있는 의료­·주거·교육급여 수급자 및 차상위 여성이 임신­·출산으로 인하여 자활사업 참여를 중단하게 될 경우 최근 6개월 평균 자활근로 급여(실비 및 반장 수당 제외)에 해당하는 금액을 3개월 간 지급합니다. 임신 사실을 안 날로부터 출산 후 6월 이내까지 신청할 수 있으며 신청 기간이 경과할 경우 급여는 지급하지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-15', 62, 'https://www.129.go.kr/faq/faq00.do?pageIndex=59#faq15859', '9465dfb88a405850d7b64a8b8fe356c9abf2372b46398e565024a3e6f1e583dd'),
('15900', 'faq129-20261010', '사회복지', '기초생활보장사업', '수급자격이 중지된 사람도 수급자증명서 발급이 가능한가요?', '수급자격이 중지된 자가 수급 이력 증빙자료를 요청하는 경우 수급이력확인서로 발급이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-04-15', 423, 'https://www.129.go.kr/faq/faq00.do?pageIndex=59#faq15900', '077c45ba9604dc4ecd0a95da817f3474edd4450ff3e8871f8f2e7f8199a405c8'),
('15919', 'faq129-20261010', '사회복지', '기초생활보장사업', '수급자가 사망하여 사망한 자의 장제(장례)에 필요한 증빙을 요청할 경우 수급자 증명서 발급이 가능한가요?', '기초생활수급자가 사망한 경우 수급자격이 중지되므로 수급자증명서는 발급되지 않고, 수급이력 확인서로 발급이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-04-15', 345, 'https://www.129.go.kr/faq/faq00.do?pageIndex=59#faq15919', 'ba5842dc92b65648934815f21d454a371a4b5cea05f6240d2765be050ce7dcc1'),
('6310', 'faq129-20261010', '보건의료', '공공보건정책', '외국인근로자 등 의료지원 사업의 지원대상자는 어디에서 진료를 받아야 하나요?', '국립중앙의료원, 전국 지방의료원, 적십자병원 및 시·도지사가 사업시행 의료기관으로 지정한 의료기관에서 진료를 받으실 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-11', 1082, 'https://www.129.go.kr/faq/faq00.do?pageIndex=59#faq6310', 'b72964e943155a86cfadced416ce6757a80078bace1d30098c2fdf47144ae50b'),
('15879', 'faq129-20261010', '보건의료', '공공보건정책', '호스피스 완화의료 서비스는 암환자만 받을 수 있나요?', '아닙니다. 호스피스 완화의료는 암환자 이외에도 만성호흡부전, 만성간경화, 후천성면역결핍증, 만성폐쇄성 호흡기질환으로 말기 진단을 받은 경우에 이용할 수 있습니다.

단, 호스피스 전문병원의 호스피스병동에 입원하는 경우는 암환자만 가능하며, 다른 질환을 가지고 있는 경우는 가정형이나 자문형 호스피스 서비스를 이용할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-11', 57, 'https://www.129.go.kr/faq/faq00.do?pageIndex=60#faq15879', 'e33deb60b8825ad1214b8fbb8dd1244522d36992d2dd02601718dc595fffb125'),
('4703', 'faq129-20261010', '인구아동', '산모신생아건강관리지원사업', '친정모가 제공인력으로 산모에게 서비스를 제공할 수 있나요?', '산모신생아건강관리 제공기관은 이용자가 선택한 서비스 상품, 제공인력 배치 상황, 이용자 요구사항 등을 종합적으로 고려하여 적합한 제공인력을 이용자와 매칭 하여야 함에 따라 제공인력이 이용자와 가족 관계에 있는 경우에도 해당 서비스를 제공할 수 있습니다

산모가 보건소로 산모신생아건강관리 바우처 신청을 하여 정부지원을 받는 대상이라면(예외지원 포함) 제공기관에서 근무 중인 친정모가 자녀에게 서비스 가능합니다. 다만, 자녀에게 서비스를 제공하는 친정모는 산모신생아건강관리사 자격을 갖추고 제공기관의 제공인력으로 근무하고 있을 때 가능합니다.

더 자세한 사항은 보건복지상담센터 (국번없이 129)로 연락주시기 바랍니다.', '2025-04-10', 1361, 'https://www.129.go.kr/faq/faq00.do?pageIndex=60#faq4703', 'a7e62733eea3e4a118c70ddb39e067fdaeb57f9e0e7ca5239878f1d943c4ffb2'),
('6336', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '제공인력으로 참여시 제출서류 중 건강진단서는 유효기간이 있나요?', '가사간병서비스 제공인력이 제출하는 건강진단서는 채용일 기준으로 1년 이내 판정된 진단서를 제출해야합니다. 단, 마약류 진단서는 채용일 기준 6개월 이내 진단·발급된 것만 인정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2025-04-10', 1524, 'https://www.129.go.kr/faq/faq00.do?pageIndex=60#faq6336', '4ccddb4f6ea065a2dd9ec889bbca306759d00cac62164a1a257ef9d5cfe14db5'),
('7115', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '선정결과 또는 지원중지에 이의가 있는 경우 이의신청이 가능한가요?', '네, 이의신청 가능합니다.

- 이의신청 기한 : 이용자 선정 결과 또는 지원 중지 등을 통보 받은 날로부터 60일 이내

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-10', 955, 'https://www.129.go.kr/faq/faq00.do?pageIndex=60#faq7115', '106fd868f11de72d79a4cbff92495b3e20a7fb5144e82f5c3da0e4ce34e6a559'),
('7910', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '서비스 제공계약서 작성시, 필수 사항이 있나요?', '가사간병서비스 서비스 제공계약은 서비스 이용자와 서비스 제공기관이 계약 당사자가 되어 서비스 제공에 관한 상세 사항을 상호 합의하여 법규 및 지침의 취지를 벗어나지 않는 범위 내에서 계약 당사자는 계약의 내용을 자유롭게 구성할 수 있습니다.

서비스 제공계약서 작성 시 필수 사항은 아래와 같습니다.

① 계약기간 ② 서비스 내용 ③ 계약금액 (총 서비스가격, 정부지원금, 본인부담금) ④ 제공시간, 제공요일 ⑤ 제공인력 ⑥ 손해배상책임

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-10', 1043, 'https://www.129.go.kr/faq/faq00.do?pageIndex=60#faq7910', '67f2c723b92a7a65baa2c370f14ab5695eeaeba6f08ae0f6752eacba13d4ca09'),
('8711', 'faq129-20261010', '인구아동', '산모신생아건강관리지원사업', '서비스 이용 중인데 바우처 유효기간이 따로 있나요?', '산모신생아 건강관리지원사업의 바우처 유효기간은 원칙적으로 출산일로부터 90일 이내입니다.

* 단, 삼태아 이상 "연장"에 한하여 출산일로부터 100일 이내

임신16주 이후 발생한 유산•사산의 경우 확인일로부터 60일 이내입니다.

* 단, 삼태아 이상 "연장"은 확인일로부터 100일 이내

예외적으로 미숙아, 선천성이상아 출산 등으로 입원한 경우는 신생아의 퇴원일로부터 90일 이내(단, 삼태아 이상 "연장"은 퇴원일로부터 100일 이내)이며, 이 경우에도 출산일로부터 2년 경과하면 바우처는 소멸합니다.

* 바우처 잔량이 있는 경우라도 바우처 유효기간이 경과하면 바우처는 소멸

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시길 바랍니다.', '2025-04-10', 502, 'https://www.129.go.kr/faq/faq00.do?pageIndex=60#faq8711', 'b958fbf8fbfa71925a4939529ddfa5db7c51578fff72301d30b2b9d62c08d91b'),
('11696', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '서비스 신청후 장기간 이용하지 않으면 중지 되나요?', '가사간병방문지원사업은 연속하여 2개월 간 서비스를 이용하지 않은 경우 이용자격이 시·군·구청장 직권으로 중지될 수 있습니다.

더 자세한 문의 사항은 보건복지상담센터(국번없이 129)로 문의하여 주시기 바랍니다.', '2025-04-10', 358, 'https://www.129.go.kr/faq/faq00.do?pageIndex=60#faq11696', '67e8964a7c41db9c6ba5d6d12ebd2c172c2024e5be0505711c55a3f830b0deba'),
('12637', 'faq129-20261010', '인구아동', '산모신생아건강관리지원사업', '미숙아, 선천성 이상아 등으로 입원한 경우, 바우처 유효기간은 어떻게 되나요?', '미숙아, 선천성 이상아 출산 등으로 입원한 경우는 퇴원일로부터 90일(삼태아 이상 ''연장''은 퇴원일로부터 100일 이내)까지입니다.

단, 이 경우에도 출산일로부터 2년이 경과하면 바우처는 소멸됩니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-04-10', 220, 'https://www.129.go.kr/faq/faq00.do?pageIndex=60#faq12637', 'c861af9af2aee795b6570576205be7ef0d339a1779f314829b53de8315940ad9'),
('14053', 'faq129-20261010', '보건의료', '건강보험정책', '장애인 보조기기 구입 금액을 지원 받고자 하는데 대상자 등 기준이 있나요?', '장애인보조기기는 의지 및 보조기, 휠체어, 보청기 등 품목에 대해 지원되며, 보조기기별 지급기준이 상이하니 건강보험공단 홈페이지*에서 품목별 대상자 기준 등을 확인하시기 바랍니다.

* 국민건강보험공단 홈페이지 > 정책.제도 > 건강보험 제도안내 > (키워드) 보조기기로 검색

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-10', 113, 'https://www.129.go.kr/faq/faq00.do?pageIndex=60#faq14053', 'ae448b67777cf58cdbcbf81ae48d087b91c1b61ff3721790a9a9ae56d1160746'),
('14234', 'faq129-20261010', '인구아동', '출산정책', '(임신사전건강관리) 신청시 구비서류는 어떻게 되나요?', '임신사전건강관리 사업 신청서류는 다음과 같습니다.

○ 내국인

- 임신 사전건강관리 지원 신청서

- 개인정보 수집.이용 및 제3자 제공 동의서

- 신청자 주민등록등본(또는 행정정보공동이용 사전동의서)

※ 온라인 신청 시 제출서류 없음(전자적 정보 기재 및 제공 동의 진행)

※ 15~19세 부부 대상자, 신청자 주민등록상 혼인관계가 확인되지 않는 경우 혼인 증명서류*추가 제출

* 혼인관계증명서, 청첩장, 예식장영수증, 사실혼 확인보증서(보증인 2인의 신분증 사본 각 1부) 중 1부

○ 외국인

- 임신 사전건강관리 지원 신청서

- 개인정보 수집.이용 및 제3자 제공 동의서

- 신청일 기준 외국인등록사실 증명 또는 국내거소신고사실증명(또는 행정정보 공동이용 사전동의서)

- 내국인 배우자의 주민등록등본( 또는 배우자의 행정정보 공동이용 사전동의서)

- 내국인 배우자와 주민등록등본상 혼인관계가 확인되지 않는 경우 혼인 증명서류*추가 제출

* 혼인관계증명서, 청첩장, 예식장영수증, 사실혼 확인보증서(보증인 2인의 신분증 사본 각 1부) 중 1부

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-10', 15, 'https://www.129.go.kr/faq/faq00.do?pageIndex=60#faq14234', '24c839c044dd72dcf961d6400a9459838c99c82c184785b21f9b018d40ec836b');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('14305', 'faq129-20261010', '인구아동', '출산정책', '(선천성 대사이상 환아) 특수식이는 어떻게 지원하나요?', '선천성 대상이상 환아 특수식이는 확진검사 결과 선천성 대사이상 및 희귀 등 기타 질환으로 진단받고 특수식이 섭취가 필요한 19세 미만 환아를 대상으로 특수조제분유와 저단백햇반을 지원합니다.

보호자가 신청하면 보건소에서는 진단서(소견서)에 명시된 필요량을 확인하고, 질환별 특수식이 지원기준에 따라 지급받을 수 있도록 처리합니다.

* (정기적 진단서 제출) 최초 제출월 기준 매 1년마다 제출

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-10', 13, 'https://www.129.go.kr/faq/faq00.do?pageIndex=61#faq14305', 'cfc188bed8fe47d6980acb5a8311578de13c5667b5352984c6740a43adb605b8'),
('15519', 'faq129-20261010', '사회복지', '기초생활보장사업', '65세 노인인 수급(권)자가 근로·사업소득이 있을 경우 소득공제가 되나요?', '2025년 1월부터 65세 이상 노인(1960년 12월 31일 이전 출생자) 수급(권)자의 근로 및 사업소득은 20만원 공제 후 나머지 금액에 대해 30%를 추가 공제하여 소득반영하도록 개정되었습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-10', 335, 'https://www.129.go.kr/faq/faq00.do?pageIndex=61#faq15519', '2f11e231f1acf70ac9af00bb7964025e2d4e384c852b8b2a8f66a6eb116faeac'),
('15599', 'faq129-20261010', '사회복지', '의료급여사업', '의료급여 상한일수 적용을 위한 일수 산정 시 투약일수도 포함되나요?', '의료급여일수는 매년 1월 1일부터 12월 31일까지의 입원일수, 투약일수, 투약 없이 외래로 의료급여를 받는 경우의 급여일수를 합하여 산정합니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-04-10', 93, 'https://www.129.go.kr/faq/faq00.do?pageIndex=61#faq15599', '19f1dcc107fa3229ac4cbf1f901c2ec5c38c4b1c9702b5875f53e36dd4c9a560'),
('2423', 'faq129-20261010', '인구아동', '지역사회서비스투자사업', '제공기관 등록 신청은 어디로 하나요?', '사회서비스를 제공하고자 하는 대표자는 사업장 주 소재지 관할 시·군·구 사업 담당과로 신청할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-10', 2253, 'https://www.129.go.kr/faq/faq00.do?pageIndex=61#faq2423', '637a9c11f3cfc79c888b00f601f2dcd92f4ebb7046b77436bb2f50ce1cc2251a'),
('2391', 'faq129-20261010', '인구아동', '산모신생아건강관리지원사업', '임신하면 언제든지 신청할 수 있나요?', '산모신생아 건강관리지원사업은 출산 예정일 40일 전부터 출산일로부터 60일까지 신청할 수 있습니다.

임신 16주 이후 발생한 유산•사산의 경우 확인일로부터 30일 이내 신청 가능합니다. (의사소견서•확인서 또는 사산(사태)증명서 첨부)

미숙아, ­선천성 이상아 출산 등으로 입원한 경우에는 신생아의 퇴원일로부터 30일 이내 신청가능합니다. (입­퇴원일이 명시된 진단서, 의사소견서, 입퇴원 확인서 등 첨부)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2025-04-10', 1205, 'https://www.129.go.kr/faq/faq00.do?pageIndex=61#faq2391', '74e31eb70c8c7a65ae4121ad74115fa1b9eaf348a501fa5af917a02e5842c25b'),
('2443', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '65세 이상입니다. 서비스 신청 가능한가요?', '가사간병서비스는 만 65세 미만의 기중중위소득 70% 이하 계층을 대상으로 합니다.

65세 이상인 경우, 장기요양 또는 노인맞춤돌봄서비스를 통해 지원 여부를 확인하셔야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2025-04-10', 3702, 'https://www.129.go.kr/faq/faq00.do?pageIndex=61#faq2443', '21e754f1340fedc74e881f9d30551219d91b3c025a66f353083903f596c06c32'),
('2444', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '장애인활동지원을 신청시 등급하향이 예상될 경우, 가사간병서비스 신청 가능한가요?', '장애인활동지원 서비스 대상자는 활동지원 서비스를 우선 활용하도록 하고 있습니다.

단, 장애인활동지원서비스 미신청자 및 등급판정 제외자는 가사·간병서비스 신청 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2025-04-10', 1731, 'https://www.129.go.kr/faq/faq00.do?pageIndex=61#faq2444', '8d7cffe395d690c094b52f706d8c979989cf14ab7bc9e2dcf73dfc63c0dc8949'),
('2446', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '보장시설 수급자도 시설 안에서 서비스 이용이 가능한가요?', '보장시설 입소자는 지원대상에서 제외되므로 서비스가 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2025-04-10', 1313, 'https://www.129.go.kr/faq/faq00.do?pageIndex=61#faq2446', '1c763d90759ef09b7f17ffe773837745590dd4680232fa6a8a8cd368b4a629db'),
('15899', 'faq129-20261010', '보건의료', '건강보험정책', '본인부담 차등화 적용 시 보건소 외래진료도 외래진료 횟수에 포함되나요?', '네. 차등화 적용 대상자가 보건소, 보건지소, 보건진료소의 외래진료를 본 경우에도 외래진료 횟수에 포함되며 본인부담률이 90%로 적용됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-04-07', 45, 'https://www.129.go.kr/faq/faq00.do?pageIndex=61#faq15899', '832794cf321e7b8620e6ae9c31d8b248e01a01f7810591efc7388bea419f3cab'),
('15779', 'faq129-20261010', '노인장애인', '노인복지사업', '해양산분 시 고인의 사진이나 유품을 같이 던져도 되나요?', '다른 선박의 항행·어업행위, 수산동식물의 양식 등을 방해하지 않도록 골분과 생화만을 뿌릴 수 있습니다.

따라서, 그 밖의 용기나 유품 등을 해양으로 배출해서는 안됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-03-28', 41, 'https://www.129.go.kr/faq/faq00.do?pageIndex=61#faq15779', '39e87e3f737c77f02c7e4e2c2125b008ee62413adbeb9ab7c5d1c19d44bf1851'),
('15780', 'faq129-20261010', '노인장애인', '노인복지사업', '해수욕장 또는 항구에서 산분장이 가능한가요?', '화장한 유골의 골분을 해양에 뿌리는 경우, 육지의 해안선으로부터 5km 이상 떨어진 곳에서 가능합니다.

따라서 해수욕장이나 항구에서는 산분장이 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-03-28', 29, 'https://www.129.go.kr/faq/faq00.do?pageIndex=62#faq15780', '88217e143189bc2314c8f25224aab6e135d08c9d6e89890e3ea071c5734c49d8'),
('15799', 'faq129-20261010', '노인장애인', '노인복지사업', '강에도 산분장을 할 수 있나요?', '「장사 등에 관한 법률 시행령」 제2조에 따라 산분장은 ①해양, ②화장한 유골의 골분을 뿌릴 수 있는 시설 또는 장소가 마련된 묘지·화장시설·봉안시설·자연장지에만 가능하도록 규정하고 있습니다.

따라서 강에는 산분장을 할 수 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-03-28', 35, 'https://www.129.go.kr/faq/faq00.do?pageIndex=62#faq15799', '3994cd6681a5e025c14b080a86f7f22cad382e93511081a01382eb657966b923'),
('15801', 'faq129-20261010', '노인장애인', '장애인복지사업', '­장애 등록한 외국인도 장애인일자리 참여 가능한가요?', '「장애인복지법」 제32조의2에 따라 ­장애등록한 외국인도 장애인일자리 참여를 희망하는 경우 참여 신청 가능합니다.

단, 장애인 일자리 유형별 선발 기준에 따른 참여자 선발과정을 통해 참여 여부가 결정됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-03-28', 39, 'https://www.129.go.kr/faq/faq00.do?pageIndex=62#faq15801', '8fffd6a7373c4d87d15c127aa85f34686e227d55bde79f9dd4cb1a485cdfbe59'),
('15802', 'faq129-20261010', '노인장애인', '노인복지사업', '화장한 유골의 산분은 어디에서 할 수 있나요?', '산분은 장사시설(묘지, 화장시설, 봉안시설, 자연장지)로 관할 지자체에 설치신고 또는 허가를 받고 산분을 할 수 있는 장소나 시설을 마련한 경우에만 가능하며, 장사시설로 신고·허가 받지 않은 경우(장사시설이 아닌 경우) 산분은 제한됩니다.

또한 해양산분은 육지의 해안선으로부터 5㎞ 이상 떨어진 해양에서 가능하나, 다음의 어느 하나에 해당하는 구역 또는 해역은 제외됩니다.

- 「해양환경관리법」 제15조제1항에 따른 환경관리해역

- 「해양생태계의 보전 및 관리에 관한 법률」 제25조제1항에 따른 해양보호구역

- 「어장관리법」 제5조제1항에 따른 어장관리해역

- 「항만법」 제2조제4호에 따른 항만구역 중 수상구역

- 「수산자원관리법」 제46조제1항에 따른 보호수면 및 같은 법 제48조제1항에 따른 수산자원관리수면

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-03-28', 57, 'https://www.129.go.kr/faq/faq00.do?pageIndex=62#faq15802', '93d0c9ee18cc869ace31f841722cec932fb3a2b5e37cef70c45cf41e0ca3f61d'),
('15759', 'faq129-20261010', '인구아동', '부모급여', '신청 시 통지기한은 어떻게 되나요?', '부모급여는 신청을 접수한 날로부터 30일 이내에 통지합니다. 단, 보호자 판단·변경 등 보장결정에 시일을 요하는 특별한 사유가 있는 경우, 그 사유를 명시하여 60일 이내에 통지할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-03-25', 38, 'https://www.129.go.kr/faq/faq00.do?pageIndex=62#faq15759', '4a54f39a4a61d1b933f56bea7ac950c2ae8f7e012d35e136629cf43ce1dbcb4b'),
('6238', 'faq129-20261010', '보건의료', '보건의료정책', '의료분쟁조정중재원에 조정을 신청하는 것은 법원에 소송을 제기하는 것과 어떤 점이 다른가요?', '의료중재원의 조정절차는 원칙적으로 90일(120일) 이라는 짧은 기간에 처리결과가 나오고 조정신청 수수료 외에는 비용이 거의 들지 않습니다.

그리고 조정 및 감정위원은 현직 판•검사, 변호사, 의료인, 대학교수, 비영리 민간단체로 구성되어 있어 의학적•법률적 검토와 함께 양 당사자가 적절한 합의를 할 수 있도록 도움을 드리고 있습니다.

그러나 조정의 성격상 양 당사자의 합의가 전제되어야 하므로 법원처럼 당사자를 기속시킬 수 있는 사법적 판단을 내릴 수는 없습니다.

(단, ''중재''의 경우는 기속력이 있음) 이에 반해 법원에서의 소송은 당사자의 합의와 무관하게 최종적인 판단을 내려 주는 장점이 있으나,

시간이 오래 걸리고 비용이 많이 든다는 단점이 있습니다.

의료사고로 인해 피해를 받은 사람은 조정절차와 소송절차 각각의 장단점을 고려하여 청구절차를 선택하시면 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-03-19', 931, 'https://www.129.go.kr/faq/faq00.do?pageIndex=62#faq6238', '8514c7db6eb5a66ea21fcc1f9f6e6401efc5859e230a1c6b7c30909894670725'),
('15739', 'faq129-20261010', '보건의료', '보건의료정책', '의료사고와 의료분쟁의 정확한 의미는 무엇인가요?', '''의료사고''란 보건의료인이 환자에 대하여 실시하는 진단•검사•치료•의약품의 처방 및 조제 등의 행위로 인하여 사람의 생명•신체 및 재산에 대하여 피해가 발생한 경우를 말하며 이로 인한 다툼을 ''의료분쟁''이라 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-03-19', 91, 'https://www.129.go.kr/faq/faq00.do?pageIndex=62#faq15739', 'ea9842d1304e097eb29bfed142ba247368aa735ab4759f73fbd3bcb8918b5854'),
('13922', 'faq129-20261010', '인구아동', '출산정책', '(임신사전건강관리) 청구방법과 청구시 구비서류는 어떻게 되나요?', '임신사전건강관리 지원은 주소지 보건소 또는 e보건소 온라인 신청 후 검사의뢰서 발급 받아 3개월 이내 참여의료기관에서 검사를 받고, 검사일로부터 1개월 이내 보건소 또는 e보건소에 청구해야 합니다. 청구시 제출서류는 다음과 같습니다.

○ 방문 청구 : 보건소(주민등록상 주소지 관할 보건소)

- 임신 사전건강관리 지원사업 검사비 청구서

- 외래 진료비 계산서•영수증

- 진료비 세부산정내역(세부내역서)

- 신청인 (청구인) 본인 명의의 통장사본 1부

○ 온라인 청구 : e보건소(e-health.go.kr)

- ''의료비 지원 - 신청현황조회'' 인증서 로그인 → ''임신사전건강관리지원'' 청구

- ①청구 내용 작성, ②구비서류(영수증, 세부내역서, 통장사본) 첨부

*파일 첨부 시, 이미지(jpg 등) 또는 PDF 형식으로 첨부

* 신청권자 : 지원 대상에 해당하는 본인 (대리 신청 불가)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-03-17', 15, 'https://www.129.go.kr/faq/faq00.do?pageIndex=62#faq13922', '59dab94ca6d75f3a6973eefd644226c3104a9126c1e703464da44681fd7ba222'),
('15719', 'faq129-20261010', '인구아동', '출산정책', '(임신사전건강관리) 지원대상은 어떻게 되나요?', '임신사전건강관리지원사업의 대상자는 아래와 같습니다.

♦ 지원 대상

- 모든 20~49세 남녀 중 검사 희망자(결혼, 자녀 여부 무관)

* 15~19세 남녀 중 부부 (예비부부, 사실혼 포함)

* 내국인 배우자가 있는 외국인 지원 가능(별도 비자 조건 없음)

* 주민등록지(주민등록을 한 재외국민, 외국인등록 포함)를 기준으로 관할 보건소에서 지원 가능

♦ 지원 횟수

- 주요 주기별 1회, 최대 3회 지원

* 29세 이하(제1주기), 30~34세(제2주기), 35~49세(제3주기) 주기별 1회, 최대 3회 지원

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-03-17', 9, 'https://www.129.go.kr/faq/faq00.do?pageIndex=62#faq15719', 'e7299d3a553a50587973e41e6a52649ad5c1a56f10839ec2fb1b62cae8c6f60a'),
('7117', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '가사간병서비스대상자가 만65세가 되는 경우, 생일이 속한달까지 이용가능한가요?', '만 65세미만 대상이나, 이용중 만 65세에 도달하는경우 생일이 속한 해당 월 말일 24:00까지 서비스 이용이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-03-14', 855, 'https://www.129.go.kr/faq/faq00.do?pageIndex=62#faq7117', '4960b79131fa764816ea50d49ecef067a5776d650a4e92c9ea2e35e86687ff15');
