INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('15639', 'faq129-20261010', '인구아동', '디딤씨앗통장', '본인적립금과 정부 매칭금 잔액 조회를 할 수 있나요?', '디딤씨앗통장 본인적립금과 정부 매칭금 잔액 조회 가능합니다.

1. 신한은행 앱 설치 - 구글 플레이스토어 또는 애플 앱스토어에 "신한 쏠(SOL)" 검색

2. 메인화면 우측 하단 전체메뉴 → 특화라운지 → 디딤씨앗 정보조회

3. 정보입력 - 아동 성명, 생년월일, 계좌번호, 고객번호(통장 앞면에서 확인) 입력 후 본인적립금(디딤씨앗 적립예금 계좌조회)과 정부매칭금(디딤씨앗 국공채증권투자신탁)계좌 조회

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2025-03-14', 36, 'https://www.129.go.kr/faq/faq00.do?pageIndex=63#faq15639', 'dfad9d3c630df0e3f345b84388ae5b4b3e87354456cb0394d2350541d393178b'),
('8032', 'faq129-20261010', '보건의료', '건강보험정책', '치석제거 급여 대상 확인은 어떻게 할 수 있나요?', '치석제거 급여대상 여부는 건강보험공단 홈페이지 및 모바일 앱에서 본인인증 후 확인 할 수 있습니다.

- 건강보험공단 홈페이지 > 민원서비스 > 서비스찾기 > 치석제거 진료정보 조회

- 모바일 앱(The건강보험) > 민원여기요 > 조회 > 치석제거 진료정보

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-03-12', 2319, 'https://www.129.go.kr/faq/faq00.do?pageIndex=63#faq8032', '6edba03675ff2b2fa8e1502fc73afa3e170f36f6d7a22ac3fbe702451307f06c'),
('15622', 'faq129-20261010', '노인장애인', '노인복지사업', '응급안전안심서비스 노인 2인가구의 질환과 거동 불편 여부는 어떻게 확인하나요?', '65세 이상 노인 2인으로 구성되며 ''기초생활수급자, 차상위, 기초연금수급자'' 가구 중 아래 요건 하나를 충족한 경우 응급안전안심서비스를 신청할 수 있습니다.

- 한 명이 질환(당뇨, 혈압, 뇌졸증 및 치매 등)을 앓고 있거나 거동이 불편한 경우

- 2인 모두 75세 이상인 경우

이 때 질환과 거동 불편 여부는 병원 진단서 등 질환, 거동 여부를 확인할 수 있는 서류를 제출하여 확인합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-03-06', 91, 'https://www.129.go.kr/faq/faq00.do?pageIndex=63#faq15622', '93096c9a1ea0c2cd25243f5a8bcfab77c862240f2c3b5d8e950bda78f2b9147c'),
('3483', 'faq129-20261010', '노인장애인', '장애인복지사업', '청소년 발달장애인은 주간활동서비스를 받을 수 없나요?', '발달장애인 주간활동서비스는 학교 졸업 이후 복지사각지대에 놓인 성인 발달장애인을 위한 제도입니다.

18세 미만인 경우 주간활동서비스 지원대상이 아닙니다.

6세 이상~18세 미만의 발달장애인은 청소년 발달장애인 방과후활동서비스 신청이 가능하며, 18세 이상의 초·중·고·전공과 재학생의 경우 주간활동서비스(기본형에 한함)와 방과후활동서비스(재학증명서 제출 필요) 중 하나를 선택해서 이용이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-03-05', 1966, 'https://www.129.go.kr/faq/faq00.do?pageIndex=63#faq3483', 'f299d027065a2b769f785e5e61e83efc0056933cf9803c754cb914de5343ec8d'),
('15619', 'faq129-20261010', '노인장애인', '노인장기요양제도', '노인요양시설의 와상 수급자도 결핵검사를 받아야하나요?', '노인요양시설 입소자는 연 1회 이상의 결핵검진을 포함한 건강진단을 하여야 하므로 와상 수급자라고 하더라도 결핵 검사를 포함한 건강진단을 연 1회 이상 실시하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-03-05', 28, 'https://www.129.go.kr/faq/faq00.do?pageIndex=63#faq15619', '2c13ea95336747076b53e3f590c7d92e0a6b29740af725d75f753aeb4bb7fe0f'),
('1485', 'faq129-20261010', '노인장애인', '장애인복지사업', '발달장애인 주간활동지원서비스 신청 대상은 어떻게 되나요?', '18세 이상의 「장애인복지법」상 등록된 지적 및 자폐성 장애인이 신청 대상입니다.

※ 장애인 당사자 및 가구의 소득수준과 무관하게 신청 가능

단, 다음에 해당하는 경우에는 신청 대상에서 제외됩니다.

① 「장애인복지법」 제32조의2(재외동포 및 외국인의 장애인 등록)에 따라 장애등록한 재외동포 및 외국인

② 방과후활동서비스 이용자(18세 이상 재학생의 경우 주간활동서비스(기본형에 한함)과 방과후활동서비스 중 선택하여 이용 가능)

③ 취업자

④ 「장애인복지법」 제58조(장애인 복지시설)에 따른 장애인 거주시설*에 입소한 자

* 장애유형별 거주시설, 중증장애인 거주시설, 장애인 단기거주시설

⑤ 「평생교육법」 제20조의2(장애인평생교육시설등의 설치)에 따른 장애인평생 교육시설 등에서 주기적으로 낮 시간 서비스를 이용하는 자

⑥ 장애인 주간보호시설(센터) 이용자

⑦ 「장애인 고용촉진 및 직업재활법」 제9조부터 제19조의2까지에 따른 취업지원 등 직업재활 서비스 이용자

⑧ 「장애인복지법」 제21조(직업), 「장애인복지법시행령 제13조의 2(장애인일자리 사업 실시)에 따른 장애인일자리사업 참여자

⑨ 그 밖에 국가나 지방자치단체로부터 주간활동서비스와 유사한 낮시간 지원 서비스를 받는 자

※ ③, ⑤, ⑦, ⑧, ⑨번에 해당하는 사람이 주20시간(월80시간)이내 근로 또는 이용하는 경우 기본형 주간활동서비스 이용 가능

※ 기존 서비스를 중지할 것을 전제로 주간활동서비스를 신청할 수 있음

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-03-05', 1936, 'https://www.129.go.kr/faq/faq00.do?pageIndex=63#faq1485', '43e211e95a1a5bde19f4ca383ae8d781007e74087d1baa9128a104bd1a9134ef'),
('15582', 'faq129-20261010', '보건의료', '보건의료정책', '한국의료분쟁조정중재원에서는 어떤 일을 하나요?', '한국의료분쟁조정중재원은 의료사고 피해자(환자)에 대한 신속•공정한 피해구제와 의료인의 안정적인 진료환경 조성을 목적으로 설립된 보건복지부 산하 공공기관이며, 주로 의료사고에 대한 무료상담과 이에 따라 조정신청 된 사건에 대한 감정업무(사실조사•인과관계•과실규명) 및 조정업무(손해배상산정) 등을 통하여 당사자 간의 합의•조정•중재를 진행하고 있습니다.

이외에도 다른 기관으로부터 의뢰된 감정에 대한 수탁감정업무, 조정결정 후 합의미수금에 대한 손해배상대불, 불가항력적인 의료사고에 대한 보상업무도 수행하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-02-27', 57, 'https://www.129.go.kr/faq/faq00.do?pageIndex=63#faq15582', '79bca2ab49e4e415676d743da37b2b0fb8c99c678327d3ec66551283de93883b'),
('15640', 'faq129-20261010', '보건의료', '보건의료정책', '의료인 또는 의료기관도 한국의료분쟁조정중재원으로 의료분쟁 조정을 신청할 수 있나요?', '법은 의료사고로 인한 피해를 신속•공정하게 구제하고 보건의료인의 안정적인 진료환경 조성을 목적으로 하고 있으며, 이와 관련한 분쟁의 조정은 이해 당사자인 환자와 의료인(보건의료기관) 모두가 신청을 할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-02-27', 53, 'https://www.129.go.kr/faq/faq00.do?pageIndex=63#faq15640', '61b9529bcbc0604dac83b21c4d1139ced4f49cadc128ead8870e2c8f4924d816'),
('1609', 'faq129-20261010', '노인장애인', '노인복지사업', '''자연장''이란 무엇인가요?', '자연장이란 화장한 유골의 골분을 수목, 화초, 잔디 등의 밑이나 주변에 묻거나 해양 등 정해진 구역에 뿌려 장사하는 것을 말합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-02-26', 1898, 'https://www.129.go.kr/faq/faq00.do?pageIndex=63#faq1609', '31a9db4769139c5bb60d77597e44972df469f7182e4b0821619aaf6e36588cae'),
('14078', 'faq129-20261010', '노인장애인', '장애인복지사업', '발달장애인 부모상담지원 사업은 누가 신청할 수 있나요?', '발달장애인 부모상담지원사업은 「장애인복지법」상 지적·자폐성 장애인으로 등록된 자녀의 부모 및 보호자가 지원 대상입니다. 발달장애인 자녀의 부모 동시에 지원도 가능합니다.

우선적으로 부모를 지원하는 것이 원칙이나, 발달장애인과 거주를 같이하면서 부모를 대신하여 발달장애인을 돌보는 보호자(2촌 이내)도 이용 가능합니다.

자녀가 영유아(9세 미만)의 경우, 장애등록이 되어 있지 않더라도 발달장애(지적·자폐성)가 의심된다는 최근 6개월 이내 발행된 발달재활서비스 의뢰서 또는 최근 6개월 이내 발행된 의사소견서(진단서)로 대체 가능합니다. 대상자로 선정된 이후 이용기간 중에 9세 도래되는 경우 9세가 되는 달까지 지원됩니다.

더 자세한 사항은 보건복지상담센터 (국번없이 ☎129)로 문의주시기 바랍니다.', '2025-02-25', 42, 'https://www.129.go.kr/faq/faq00.do?pageIndex=63#faq14078', '221443f659b303b4cd1cc4fea6ef6d45d944c4c54491a6dfe9d5f1ef56efdbcc'),
('8370', 'faq129-20261010', '인구아동', '지역사회서비스투자사업', '지역사회바우처 제공기관이 폐업을 하려면 신고해야하나요?', '사회서비스 제공자는 영업의 전부 또는 일부를 휴업하거나 폐업하려는 경우, 등록 시·­군·­구에 휴·­폐업을 신고하여야 합니다.

휴·폐업 예정 2개월 전까지 폐업·­휴업 신고서에 기존 이용자에 대한 조치계획서 및 사회서비스 제공자 등록증을 첨부하여 제출 하여야하며, 이용자 및 이용자의 보호자에게 서면, 전화로 휴·­폐업 사실을 통보해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-02-24', 534, 'https://www.129.go.kr/faq/faq00.do?pageIndex=64#faq8370', '423415d2c129092dbc439391099bb574f87a53d4615b6fe9e0b8adacfcd7e9a3'),
('8390', 'faq129-20261010', '인구아동', '지역사회서비스투자사업', '지역사회서비스 제공기관을 타인에게 양도 가능한가요?', '사회서비스 제공자가 타인에게 영업을 양도하거나, 사망하거나, 법인의 합병이 발생한 경우, 그 양수인·상속인 또는 합병 후 존속 법인이나 합병으로 설립되는 법인이 종전 제공자의 지위를 승계받을 수 있습니다.

지위 승계자는 1개월 이내 제공자 지위승계 신고서와 승계내용 입증서류를 첨부하여 시장·군·구청장에게 제출하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-02-24', 388, 'https://www.129.go.kr/faq/faq00.do?pageIndex=64#faq8390', 'e541b8a5877adb7d0949dee98410360d46120d3c10ea5f82f086be1d56d38b2d'),
('8512', 'faq129-20261010', '인구아동', '지역사회서비스투자사업', '고유번호증 제출로 지역사회바우처 제공자 등록이 가능한가요?', '지역사회바우처 제공자 등록 시 제출서류는 ''사회서비스 제공자 등록신청서(별지제1호서식)'', 등록기준을 충족하는지를 확인할 수 있는 서류로 규정하고 있습니다.

사회서비스 제공자 등록 신청 시 사업자등록증과 고유번호증을 별도로 구분하지 않으므로, 고유번호증 제출로도 사회서비스 제공자 등록이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-02-24', 567, 'https://www.129.go.kr/faq/faq00.do?pageIndex=64#faq8512', '351bf6ba449a300d29d5280c30f2b7b49558f80d12030d20f89b63a081b4ddfe'),
('10195', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '제공기관을 폐업하고자합니다. 어떻게 해야하나요?', '가사·간병서비스 제공자는 영업의 전부 또는 일부를 휴업하거나 폐업하려는 경우, 휴·­폐업 예정 2개월 전까지 폐업·휴업 신고서(기존 이용자에 대한 조치계획서 첨부)를 시장­·군수·­구청장에게 제출해야 합니다.

또한, 제공자는 이용자 및 이용자의 보호자에게 문서 또는 구두로 휴­·폐업 사실을 통보해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2025-02-24', 523, 'https://www.129.go.kr/faq/faq00.do?pageIndex=64#faq10195', '933de216f1efa321fc7e9105906d6806e3541d64f84df0ed5949349f91405bd3'),
('10214', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '가사간병서비스 제공기관명칭을 변경하려고 합니다. 어떻게 해야 하나요?', '가사·간병서비스 제공기관의 등록사항(제공기관명칭, 사업자등록번호, 지급계좌, 소재지, 연락처 등)을 변경하려는 제공자는

변경사항이 발생한 날부터 14일 이내에 제공자 등록사항 변경신청서를 시장­·군수·구청장에게 제출해야합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-02-24', 386, 'https://www.129.go.kr/faq/faq00.do?pageIndex=64#faq10214', '14a965639f56f6692a83d6af77f2fbe5abd0e7e86a9894c447251e19c4462da3'),
('10215', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '가사간병서비스 이용시 회당 최소 이용시간이 정해져 있나요?', '가사간병서비스 이용시 1회 방문 시 서비스 제공시간은 최소 2시간 이상을 원칙으로 합니다.

*(예시) 주 5시간씩 서비를 제공하는 경우 - 월요일 2시간, 수요일 3시간 (O) / 월요일 2시간, 수요일 1.5시간, 금요일 1.5시간 (X)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-02-24', 467, 'https://www.129.go.kr/faq/faq00.do?pageIndex=64#faq10215', 'd2a32aa1b51d734fb21a8c75e81b1ed0086c923b415155acd07aff975139b5ce'),
('2441', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '기초수급자, 차상위 자격이 없는데 가사간병서비스를 신청할수 있나요?', '가사간병방문지원사업은 만65세 미만의 기준중위소득 70% 이하 계층으로 가사·간병서비스가 필요한 자를 대상으로 지원합니다.

생계·의료·주거·교육급여 수급자, 차상위계층은 별도 조사 없이 신청 가능하고, 공식 확인된 자산·소득조사 자료가 없는 신청자의 경우 가구원 수를 산출한 뒤 ''소득·재산조사''를 실시하여 소득기준(기준중위소득 70% 이하) 적합 여부를 판단합니다.

단독으로 일상생활이 불가하여 서비스 지원이 필요한 경우 주소지 관할 동주민센터로 신청하시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-02-24', 2450, 'https://www.129.go.kr/faq/faq00.do?pageIndex=64#faq2441', '9bf2b7d4463a8f59341942c35857581cdc7f2894dbe67dd5fbedf4f96e917de0'),
('1162', 'faq129-20261010', '인구아동', '디딤씨앗통장', '디딤씨앗통장 가입대상은 누구인가요?', '디딤씨앗통장(아동발달지원계좌)은 취약계층 아동의 사회진출시 소요되는 초기비용 마련을 목적으로 하며, 지원대상은 다음과 같습니다.

① 보호대상아동 : 0세~17세 보호대상아동(아동복지시설 보호아동, 가정위탁 보호아동, 일시보호시설 아동, 장애인생활시설 아동, 소년소녀가정 아동)

② 0세~17세 기초생활수급가구 아동 : 중위소득 50% 이하의 수급 가구(생계, 의료, 주거, 교육급여) 아동

③ 0세~17세 차상위계층 아동(25년1월부터 차상위계층 아동까지 확대) : 차상위장애인, 차상위자활, 차상위본인부담경감대상자, 차상위계층 확인, 한부모가정(모자가족, 조손가족, 부자가족, 청소년한부모모자가족, 청소년한부모부자가족)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-02-24', 1521, 'https://www.129.go.kr/faq/faq00.do?pageIndex=64#faq1162', '37b9208325cbd0ab760c0291347e3b6ae25f6465c5768db306ba670a4568a9b2'),
('6274', 'faq129-20261010', '보건의료', '공공보건정책', '외국인근로자 등 의료지원 사업의 지원대상은 누구인가요?', '노숙인, 외국인근로자 및 그 자녀(18세 미만), 국적 취득 전 결혼이민자 및 그 자녀(18세 미만), 난민인정을 신청한 자와 그 자녀(18세 미만) 중에서 건강보험, 의료급여 등 의료보장제도에 의해서도 의료혜택을 받을 수 없는 분들을 대상으로 지원기준에 적합한 경우 의료비의 일부를 지원합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-02-21', 1185, 'https://www.129.go.kr/faq/faq00.do?pageIndex=64#faq6274', '62447c894edf4b2c99f38eb2a8cec948599686eaeaa684b9f1058cccfd47a318'),
('6311', 'faq129-20261010', '보건의료', '공공보건정책', '외국인근로자 등 의료지원 사업 대상인 ''외국인근로자'' 기준은 어떻게 되나요?', '외국인근로자의 경우 ① 신원이 확인되고, ② 국내 체류기간이 90일 이상이며, ③ 국내에서 질병이 발병하였고, ④ 전·현직 근로사실이 있으며, ⑤ 건강보험 등에 가입이 불가능한 경우에 한하여 지원할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-02-21', 1592, 'https://www.129.go.kr/faq/faq00.do?pageIndex=64#faq6311', '89ca72f6acf22ca5f73aea5bbc4a90046fb72e37fce2df28094d23055fec8065');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('15559', 'faq129-20261010', '보건의료', '건강정책', '사회복지시설 입소자도 영양플러스 사업 대상으로 지원을 받을 수 있나요?', '영양플러스사업은 가정단위에 대한 지원이 주 내용이므로 사회복지 시설 입소자는 제외됩니다.

다만, 한부모가족복지시설 입소자는 기준 충족시 지원 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-02-19', 41, 'https://www.129.go.kr/faq/faq00.do?pageIndex=65#faq15559', 'ab671948238cb1b43ddd7f4d4821ca28880c33d60f1070df8bc1fe9b41d9e9e2'),
('2478', 'faq129-20261010', '보건의료', '건강정책', '영양플러스사업의 목적은 무엇인가요?', '영양플러스 사업은 임신·출산·수유로 인해 영양 측면의 위험성이 높은 임산부(임신부,출산부,수유부)의 건강과 태아 및 영유아의 미래건강을 위해 맞춤 영양교육 및 영양지원을 실시하는 것을 목적으로 하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-02-19', 2265, 'https://www.129.go.kr/faq/faq00.do?pageIndex=65#faq2478', '44dcabc6917db9c2f2d6b9fae08bd0e6983b7dacda5bc8beb4d1cdd44201157b'),
('15459', 'faq129-20261010', '사회복지', '의료급여사업', '타법 의료급여 수급자가 정부해외인턴사업에 참여하여 해외에 체류하는 경우 수급자격이 중지되나요?', '타법 의료급여 수급자가 정부해외인턴사업 참여로 해외에 체류하는 경우에는 91일째 부터 보장가구원에서 제외되며, 의료급여 상실처리 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-02-11', 115, 'https://www.129.go.kr/faq/faq00.do?pageIndex=65#faq15459', '078dde7090362d838677454a923b314283f8667d885c15fa39ceedc607e26685'),
('15460', 'faq129-20261010', '사회복지', '의료급여사업', '북한이탈주민 의료급여 수급중인 가구원이 사망한 경우, 의료급여 자격이 유지 되나요?', '북한이탈주민으로 의료급여 수급을 받는 가구내 가구원이 사망한 경우, 잔여 가구원 중 북한이탈주민이 포함되어 있는 경우에는 계속 의료급여 자격이 유지됩니다.

잔여 가구원 중 북한이탈주민이 포함되어 있지 않은 경우에는 가구주 사망 다음날로 모두 자격상실 처리됩니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2025-02-11', 66, 'https://www.129.go.kr/faq/faq00.do?pageIndex=65#faq15460', '39092d71e62e2a57bf94af54de233cfbf0071cf5d354e11228e4d5c8c1487a9a'),
('14206', 'faq129-20261010', '보건의료', '건강보험정책', '상병수당이란?', '상병수당이란 근로자가 업무와 관련 없는 부상·질병으로 경제활동이 어려운 경우 치료에 집중할 수 있도록 소득을 보전하는 제도로 `25.1.1. 기준 총 8개 지역*에서 시행 중에 있습니다.

* 대구 달서구, 경기 안양시, 경기 용인시, 전북 익산시, 강원도 원주시, 충북 충주시, 전북 전주시, 충남 홍성군

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-02-04', 193, 'https://www.129.go.kr/faq/faq00.do?pageIndex=65#faq14206', '4f1ca51d9f9f41fbb50cc67359432f7d51266ca1ce129c3d9a73b00915c77459'),
('15479', 'faq129-20261010', '보건의료', '보건의료정책', '보험회사가 약국으로 환자의 조제내역을 알려달라고 하는 경우 알려줘도 되나요?', '안됩니다.

조제내역과 같은 개인정보를 제3자인 보험회사에게 제공하는 경우에는 원칙적으로 환자의 동의를 받아야 합니다.

보험회사는 자동차손해배상 보장법 제14조(진료기록의 열람 등)에 근거하여, 자동차보험진료수가를 청구 받으면 그 의료기관에 대하여 관계 진료기록의 열람을 청구할 수 있지만, 약국은 의료법 제3조에서 규율하는 의료기관이 아니므로, 개인정보보호법 제18조제2항제2호의 ''다른 법률에 특별한 규정이 있는 경우''에 해당되지 않습니다.

* 필요하다면 (정보주체의 동의를 받아) 환자 본인이나 보호자와 직접 연락할 수 있도록 조치를 취해 주는 것이 바람직합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2025-01-31', 103, 'https://www.129.go.kr/faq/faq00.do?pageIndex=65#faq15479', '977b5d40103ba20fce6925e0b626340b4bd51332213780eb392453b0b1c78e8a'),
('15480', 'faq129-20261010', '보건의료', '보건의료정책', '약국 폐업 시 조제기록부 등 개인정보 처리는 어떻게 해야 하나요?', '약국을 폐업하는 경우 개인정보보호법 제21조에 근거하여, 개인정보의 보유목적이 달성된 것으로 보아, 보유하고 있는 개인정보는 파기하는 것을 원칙으로 합니다.

단, 조제기록부, 처방전, 요양급여청구서류 등 약사법 및 국민건강보험에 의해 일정기간 보관이 의무화된 정보는 약국 대표자가 의무기간 동안 보관해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2025-01-31', 99, 'https://www.129.go.kr/faq/faq00.do?pageIndex=65#faq15480', '269f773cae5f676babc0001c72d2d1345a3702e78aedcb53cac9ba56cfac5b85'),
('13985', 'faq129-20261010', '보건의료', '건강정책', '담뱃갑 경고그림 및 문구는 몇 년 주기로 교체하나요?', '담뱃갑 경고그림 및 문구는 2년 주기로 교체합니다.

제5기 경고그림 및 문구는 24년 12월 23일 ~ 26년 12월 22일까지 입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-01-24', 81, 'https://www.129.go.kr/faq/faq00.do?pageIndex=65#faq13985', '0cf075e47c3aaa3a8980620dc23929906e90d9e95e3767511c8a1481bc07d828'),
('15419', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인학대 신고의무자 교육을 집합교육으로 실시할 경우 강사 자격 기준이 있나요?', '강사에 대한 별도 자격 기준은 없습니다. 다만, 교육 내용은 법령에서 규정한 내용이 모두 포함되어야 합니다.

[장애인복지법 시행령 제36조의6]

① 장애인학대 및 장애인 대상 성범죄의 예방 및 신고의무에 관한 법령

② 장애인학대 및 장애인 대상 성범죄의 발견 시 신고 방법

③ 장애인학대로 인하여 피해를 입은 장애인 보호 절차

④ 장애인학대 및 장애인 대상 성범죄 사례

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-23', 30, 'https://www.129.go.kr/faq/faq00.do?pageIndex=65#faq15419', 'f187a6bf261f5b0802c3a81abf3dea343b69481459196bbe08b63e912cffd363'),
('15420', 'faq129-20261010', '노인장애인', '노인장기요양제도', '요양보호사도 보수교육을 받아야 하나요?', '요양보호사 보수교육 대상자는 장기요양기관*에 소속되어 근무 중인 요양보호사로 매 2년마다 8시간 이상의 보수교육을 이수하여야 합니다.

출생연도를 기준으로 홀수년도 출생자는 홀수연도에, 짝수년도 출생자는 짝수연도에 보수교육 이수 대상입니다. 다만, 노인복지법 제39조의2제2항에 따른 요양보호사 자격시험에 합격한 지 2년이 지나지 않은 사람은 요양보호사 보수교육 면제대상입니다.

* 장기요양기관이란 시설급여(노인요양시설 등) 및 재가급여(방문요양·목욕, 주야간보호, 단기보호)를 제공하는 기관으로 「노인장기요양보험법」 제31조에 따라 지정 받은 기관

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-23', 69, 'https://www.129.go.kr/faq/faq00.do?pageIndex=65#faq15420', 'c95397122e265f44a4bf252cf42ae68d46832f63a3790e56f38985bcb54735d8'),
('15439', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인학대 신고의무자 교육 대상 중 종사자의 범위가 어떻게 되나요?', '종사자의 범위를 일률적으로 규정하기는 어렵습니다.

다만, 현재 장애인학대 신고의무자 제도의 취지를 고려할 때 해당 시설에 근무하고 있는 직원(정직원, 계약직, 시간제 등 포함, 다만, 휴직자는 제외), 외부에서 파견 온 상주 인원, 용역 직원 등이 모두 포함될 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-23', 23, 'https://www.129.go.kr/faq/faq00.do?pageIndex=66#faq15439', '31a5addb8075d2d5467019d5ae1ebd0509b937e9399188482ccf5df7d57ae5c7'),
('15440', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인학대 신고의무자 교육을 서면으로 교육한 것도 인정되나요?', '「장애인복지법 시행령」 제36조의 6 제4항에 따라 집합교육 또는 인터넷 강의 등을 활용한 원격교육으로 할 수 있습니다. 단순히 서면 자료 배포만으로 교육을 실시했다고 보기는 어렵습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-23', 22, 'https://www.129.go.kr/faq/faq00.do?pageIndex=66#faq15440', '02caf2b2a0b0f206b2b1e1978696ee589d146e724f6a4964ca3435ae5e253593'),
('15441', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인식개선교육, 장애인학대 신고의무자 교육, 직장 내 인식개선교육이 같은 교육인가요?', '「장애인복지법」제25조에 따른 사회적 인식개선교육, 「장애인복지법」 제59조의4에 따른 신고의무에 관한 교육, 「장애인고용촉진 및 직업재활법」 제5조의2에 따른 직장 내 장애인 인식개선교육은 모두 다른 교육으로 각각 교육을 실시하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-23', 30, 'https://www.129.go.kr/faq/faq00.do?pageIndex=66#faq15441', '6f2374ce97066aa4dd3cd2b19a94ea9d360bd99fb77cbd226068fb8297209b0f'),
('15442', 'faq129-20261010', '노인장애인', '노인복지사업', '화장(火葬)을 할 수 있는 장소가 정해져 있나요?', '누구든지 「장사 등에 관한 법률」에 따른 화장시설 외의 시설 또는 장소에서 화장을 해서는 안됩니다.

다만, 보건위생상의 위해가 없는 다음의 경우에는 화장시설 외의 장소에서도 화장을 할 수 있습니다.

- 사찰 경내에서 다비의식으로 화장을 하는 경우

- 화장시설이 설치되지 않은 도서지역에서 「감염병 예방 및 관리에 관한 법률」 제2조에 따른 감염병으로 사망한 시신에 대하여 시장·군수·구청장이 감염병의 확산을 방지하기 위하여 긴급한 조치가 필요하다고 인정하는 경우

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-22', 48, 'https://www.129.go.kr/faq/faq00.do?pageIndex=66#faq15442', '7e3958e27218a150e92834f86eb0f5a046f2649367a32fdb323bb1843359d80f'),
('8371', 'faq129-20261010', '인구아동', '지역사회서비스투자사업', '지역사회바우처 서비스제공 후 제공기록지를 작성해야하나요?', '지역사회바우처 제공인력은 제공한 서비스의 구체적인 내용을 서비스 제공 기록지에 기록해야 합니다.

서비스 제공 후 제공 기록지를 작성하지 않거나 기록하지 않은 사항에 대하여는 서비스 제공인정이 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-01-20', 572, 'https://www.129.go.kr/faq/faq00.do?pageIndex=66#faq8371', '3c33c4a7fd07360cf80ba170ad9e72a0e6f04f03f4f49fd54ef476fee9c099f4'),
('7492', 'faq129-20261010', '인구아동', '기초연금사업', '주민등록번호가 정정되었는데 그동안 지급받지 못했던 기초연금을 받을 수 있나요?', '주민등록번호 정정 전 기초연금을 신청하지 않은 기간에 대해서는 소급하여 지급하지 않습니다.

「기초연금법」제10조와 「기초연금법 시행령」제13조 규정에 따라 기초연금을 지급받기 위해서는 관련 서류를 관할 읍·면·동 주민센터 또는 국민연금공단에 신청해야 하며, 동 신청을 통해 관할 지자체는 신청 당시의 소득과 재산을 조사하여 그 결과가 선정기준에 부합할 경우 수급자로 결정하여 급여를 지급하게 됩니다.

따라서, 기초연금을 신청하지 않은 기간에 사실상 연령이 만65세 이상이었다는 사실만으로는 기초연금 수급 자격이 있었다고 볼 수 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-14', 1364, 'https://www.129.go.kr/faq/faq00.do?pageIndex=66#faq7492', '6b933fdae093f2340bbc780b0113dfd061d48658cbf5e6bf89fb7a284a8923a9'),
('7610', 'faq129-20261010', '인구아동', '기초연금사업', '사망한 수급자의 형제자매도 미지급 기초연금에 대한 지급 청구권이 있나요?', '기초연금법 제15조에 따라 사망한 수급자의 형제자매는 생계 및 주거를 같이 하였어도 미지급 청구권자로 인정되지 않습니다.

미지급 기초연금의 지급 청구권자는 수급자의 사망 당시 생계를 같이한 부양의무자(배우자, 직계혈족 및 그 배우자)로 한정되어 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-14', 1879, 'https://www.129.go.kr/faq/faq00.do?pageIndex=66#faq7610', '22fd319e78e79bb1ac1d6829f81e117b5679e91b59867be7fb780efcaf88194a'),
('7630', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 사전신청 안내문을 못받아서 신청을 늦게한 경우 신청 이전의 급여를 지급받을 수 있나요?', '­「기초연금법­」제 10조 및 「기초연금법 시행령­」제13조에 따라 기초연금을 받고자 하는 분은 관련서류를 구비해 관할 지자체 또는 국민연금공단 지사에 신청해야 합니다.

신청을 통해 관할 지자체는 신청 당시의 소득과 재산을 조사하여 그 결과가 선정기준에 부합할 경우 수급자로 결정하여 연금을 지급하므로 신청 전의 수급기간에는 수급 자격이 있다고 볼 수 없으므로 소급 지급할 수 없습니다.

기초연금 사전 신청 안내문은 신청자의 편의를 위해 관할 지자체 또는 국민연금공단에서 발송하는 것으로, 신청안내문을 받지 못했다 하더라도 기초연금을 신청하지 않은 경우에는 신청 이 전 시점으로 소급하여 지급할 수 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-14', 2236, 'https://www.129.go.kr/faq/faq00.do?pageIndex=66#faq7630', 'e0cc8ad1ec944eef2f94d5b5d204f407899faa53b933c3eae083d37e871ea0e5'),
('8150', 'faq129-20261010', '인구아동', '기초연금사업', '복수국적자도 기초연금을 신청할 수 있나요?', '복수국적자인 만 65세 이상 어르신이 국내에 거주하고 주민등록이 되어 있는 경우에는 기초연금을 신청할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-14', 3816, 'https://www.129.go.kr/faq/faq00.do?pageIndex=66#faq8150', '3a25af8cef570f13499ebf3f47b9649ba4185882663492b417757237994cdc1d'),
('14960', 'faq129-20261010', '보건의료', '공공보건정책', '모든 의료기관에서 연명의료를 유보하거나 중단할 수 있나요?', '모든 의료기관에서 연명의료를 유보하거나 중단할 수 있는 것은 아닙니다.

연명의료의 유보,중단은 의료기관윤리위원회를 설치한 의료기관에서만 가능합니다.

의료기관윤리위원회가 설치된 의료기관은 국립연명의료관리기관 누리집(www.lst.go.kr)에서 확인할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-01-14', 108, 'https://www.129.go.kr/faq/faq00.do?pageIndex=66#faq14960', '4785bd00e7e458c05fb625bf7ca89199b80717d61b96e6e8e8a914730f4816aa');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('14980', 'faq129-20261010', '보건의료', '공공보건정책', '사전연명의료의향서 작성 후에 변경이나 철회가 가능한가요?', '사전연명의료의향서 작성 후에 언제든지 변경 및 철회가 가능합니다.

가까운 등록기관을 방문하여 철회 신청을 하거나, 국립연명의료관리기관 누리집(www.lst.go.kr) ''나의 사전연명의료의향서 조회하기''에서 공동·금융인증서를 통해 로그인하여 직접 철회할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-01-14', 86, 'https://www.129.go.kr/faq/faq00.do?pageIndex=67#faq14980', '60510dcc2deae4142f34d5a81f6614a9bd1e1d6f2b634add0f2a62b08bd30ce4'),
('1588', 'faq129-20261010', '인구아동', '기초연금사업', '기초생활수급자로 받는 급여액도 기초연금 산정 시 소득반영 하나요?', '기초연금 산정 시 「국민기초생활보장법」에 의한 기초생활보장급여는 소득에 포함하지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-14', 1593, 'https://www.129.go.kr/faq/faq00.do?pageIndex=67#faq1588', 'd9b86e850db5f42d5ab9e21b3df5c3a9a2a40cc35204b0b1a3b5e12f63f48599'),
('1592', 'faq129-20261010', '인구아동', '기초연금사업', '자녀와 같이 거주하면 기초연금을 지원받기 어려운가요?', '기초연금은 신청자와 그 배우자가 조사대상이므로 함께 거주하는 자녀에 대해서는 조사를 하지 않습니다.

다만, 자녀 소유의 고가주택(시가표준액 6억 이상)에 거주하는 경우에는 임차료에 상응하여 해당 주택 시가표준액의 연 0.78%를 무료임차소득으로 반영합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-14', 9545, 'https://www.129.go.kr/faq/faq00.do?pageIndex=67#faq1592', '008edf6db6c6474a5588d9b8922f50f4d3c391082aebb2e973921da691479ae3'),
('1596', 'faq129-20261010', '인구아동', '기초연금사업', '기초연금 재산 산정 시 주식도 포함되나요?', '기초연금 신청자 및 배우자 명의의 주식(비상장주식 포함), 수익증권, 출자금, 출자지분에 대해서 최종 시세가액을 금융재산으로 산정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-14', 5078, 'https://www.129.go.kr/faq/faq00.do?pageIndex=67#faq1596', '21d2ca409b7d26c1b53345943e6498d019e92281863a02f43a737437e9d3f23f'),
('1597', 'faq129-20261010', '인구아동', '기초연금사업', '임대보증금은 돌려줄 금액인데 주택 가격에서 차감해주나요?', '임대보증금은 임대를 준 부동산의 시가표준액 50% 범위 내에서 부채로 차감이 가능합니다. 다만, 부채로 인정받기 위해서는 전세권 설정등기가 되어있거나 확정일자를 받은 임대차계약서 사본을 제출하셔야 합니다.

* 주택, 상가 등을 여러 채 보유한 경우라도 한 채에 한해서만 임대보증금을 부채로 인정

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-14', 2401, 'https://www.129.go.kr/faq/faq00.do?pageIndex=67#faq1597', 'd0f2c41adce3c02f27d2ba4334b22fb12e4ba53e96d4c417b93736709bafcebb'),
('1605', 'faq129-20261010', '인구아동', '기초연금사업', '임차보증금은 소득·재산 조사에서 어떻게 반영되나요?', '임차보증금의 경우 원칙적으로 확정일자를 받거나 전세권설정 된 임대차계약서를 제출하여 임대차계약서의 보증금을 재산으로 반영합니다.

다만, 임차보증금 중 주거를 목적으로하는 주택 전·월세의 경우 적용률(0.95)을 곱하여 재산으로 산정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-14', 2743, 'https://www.129.go.kr/faq/faq00.do?pageIndex=67#faq1605', 'cda959ae9ad50b1417f9e225bf058afc10667f952be02416718cec0387ec282d'),
('2436', 'faq129-20261010', '인구아동', '산모신생아건강관리지원사업', '산후조리원을 먼저 이용 후 산모신생아 건강관리지원을 이용해도 되나요?', '산후조리원 이용 후 산모신생아 건강관리지원 서비스 이용을 원할 경우 별도 제한은 없습니다.

다만, 해당 사업에서는 바우처 유효기간이 있으므로 출산일로부터 90일 이내 사용하시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2025-01-14', 1226, 'https://www.129.go.kr/faq/faq00.do?pageIndex=67#faq2436', 'd76bd68ad413a18890455768ebe994838cc4a38dc73045e8bfcdf40b4ca7203d'),
('5490', 'faq129-20261010', '노인장애인', '장애아동가족지원', '장애등록 안된 영유아의 경우 언제 발급받은 발달재활서비스의뢰서를 제출할 수 있나요?', '발달재활서비스는 18세 미만으로 「장애인복지법」상 시각·청각·언어·지적·자폐성·뇌병변 장애로 등록된 장애아동을 대상으로 하고 있습니다. 다만, 9세 미만*의 경우 시각·청각·언어·지적·자폐성·뇌병변 장애로 예견되어 발달재활서비스가 필요하다고 인정한 발달재활서비스 의뢰서 및 검사자료로 대체 가능합니다.

* 「장애아동 복지지원법」제2조 개정으로 2025년 1월 3일부터 장애 미등록아동의 발달재활서비스 지원 연령이 6세미만에서 9세 미만으로 확대됨

이때 아동의 발달속도 등을 감안하여 발달재활서비스 의뢰서 및 검사자료는 신청일 기준으로 최근 6개월 이내 발급한 것을 인정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-13', 2041, 'https://www.129.go.kr/faq/faq00.do?pageIndex=67#faq5490', '1c233a1dd1d64ec24248c356ee90555a2cd41e87de97a8f26a4c70975b9dc3a0'),
('15279', 'faq129-20261010', '사회복지', '자활사업', '정신질환도 근로능력평가가 가능한가요?', '정신신경계 질환의 경우 3개월 이상 충분한 치료를 시행하였음에도 불구하고 증상이 지속되는 경우 근로능력평가가 가능합니다. 정신건강의학과 전문의가 발급한 근로능력평가용 진단서와 최근 2개월간의 진료기록지를 첨부하여 읍·면·동주민센터로 신청 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-01-13', 442, 'https://www.129.go.kr/faq/faq00.do?pageIndex=67#faq15279', '07a0953fa89796664b9039e12207b45bd49d376975d9ab9a918bc0e595b5edb4'),
('15379', 'faq129-20261010', '보건의료', '공공보건정책', '사전연명의료의향서는 외국인도 작성할 수 있나요?', '사전연명의료의향서는 책임 있는 의사결정을 할 수 있는 19세 이상의 성인인 경우 작성 할 수 있습니다.

외국인도 여권 또는 외국인등록증을 제시하고 작성할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-01-10', 54, 'https://www.129.go.kr/faq/faq00.do?pageIndex=67#faq15379', '1f5be0ad68cd0c9c0ab97575b443d65eba8d48343ddbac7c4e0467efcda16d55'),
('15380', 'faq129-20261010', '보건의료', '공공보건정책', '사전연명의료의향서는 어디서 작성하나요?', '사전연명의료의향서 작성을 위해서는 사전연명의료의향서 등록기관을 방문하셔야 합니다.

등록기관 지정확인은 국립연명의료관리기관 누리집(www.lst.go.kr) > 사전연명의료의향서 > 작성가능기관 에서 지역별로 조회해 보실 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-01-10', 74, 'https://www.129.go.kr/faq/faq00.do?pageIndex=68#faq15380', '763ef8ac5a5aa2865418feebeb14ef13891e32d61b66be0738dc8c2469f4070c'),
('11879', 'faq129-20261010', '노인장애인', '장애인연금(수당)', '기초연금을 받고 있는데 장애인연금도 받을 수 있나요?', '장애인연금법에 따른 중증장애인으로 소득과 재산조사를 통해서 장애인연금 대상자 선정기준에 충족이 되는 경우 장애인연금 지급이 가능합니다. 다만, 장애인연금은 기초급여와 부가급여로 나뉘어 있습니다.

65세 이상의 경우는 부가급여만 지급이 가능합니다

부가급여는 장애로 인해 추가로 드는 비용의 전부 또는 일부를 보전해주기 위해 지급하는 급여로 추가 지출비용 보전 성격의 급여이며, 장애인연금 수급자 중 국민기초생활수급자(생계,의료), 차상위계층, 차상위초과자로 구분하여 지급합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-08', 1265, 'https://www.129.go.kr/faq/faq00.do?pageIndex=68#faq11879', '2709ffabb24d01a3a39ce625d0f580bd045cf5772ea018249caaba566939b60d'),
('14008', 'faq129-20261010', '노인장애인', '장애인연금(수당)', '장애아동수당 신청은 어떻게 하나요?', '장애아동수당은 전국 가까운 읍·면·동 주민센터에서 방문신청 가능합니다.

또한, 복지로(www.bokjiro.go.kr )홈페이지에서 온라인 신청도 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다', '2025-01-08', 59, 'https://www.129.go.kr/faq/faq00.do?pageIndex=68#faq14008', 'fd25c1ab5c8242db7b90159b4f9f8b235fd7b8d583bb9bb606fbc841740cedfb'),
('1538', 'faq129-20261010', '노인장애인', '장애아동가족지원', '장애등록이 되어야 발달재활서비스 신청이 가능한가요?', '발달재활서비스는 18세 미만으로 「장애인복지법」상 시각·청각·언어·지적·자폐성·뇌병변 장애로 등록된 장애아동을 대상으로 하고 있습니다.

다만, 9세 미만의 경우 시각·청각·언어·지적·자폐성·뇌병변 장애로 예견되어 발달재활서비스가 필요하다고 인정한 발달재활서비스 의뢰서* 및 검사자료로 대체 가능합니다.

* 장애유형별 전문의가 검사자료를 토대로 진단한 경우 인정가능하며 발달재활서비스 의뢰서 및 검사자료는 신청일 기준 최근 6개월이내 발급한 것을 인정

이때 연령은 신청일을 기준으로 판정하되 대상자로 선정된 후 사업기간 중 9세 도래시에는 9세가 되는 달까지 지원 가능합니다.

더 자세한 사항은 보건복지상담센터 (국번없이 ☎129)로 문의주시기 바랍니다.', '2025-01-08', 2246, 'https://www.129.go.kr/faq/faq00.do?pageIndex=68#faq1538', 'd3ac6a9934fc4d047a4c429d526cedf876c104a38ab69c45cfc171123411323f'),
('1543', 'faq129-20261010', '노인장애인', '장애아동가족지원', '발달재활서비스는 언제까지 지원받을 수 있나요?', '발달재활서비스 지원 대상 장애아동이 18세가 되는 달까지 지원합니다.

※ 장애등록이 안된 대상자가 9세 도래시에는 9세가 되는 달까지 지원

다만, 발달재활서비스 지원 대상 장애아동이 「초­·중등교육법」 제2조에 따른 학교에 재학 중인(휴학생은 제외) 경우에는 20세가 되는 달까지 지원을 연장(18세 이상인 경우도 신청 가능)하되, 20세 도래하기 전에 학교를 졸업하는 경우에는 졸업하는 달까지 인정하여 지원됩니다. (재학증명서 첨부)

더 자세한 사항은 보건복지상담센터 (국번없이 ☎129)로 문의주시기 바랍니다.', '2025-01-08', 1717, 'https://www.129.go.kr/faq/faq00.do?pageIndex=68#faq1543', '3388175bea0ba794e44be764a7e61e0b9acf3503f3f094c7949966582e4198f9'),
('7271', 'faq129-20261010', '사회복지', '긴급지원사업', '2년전 이혼했는데, 긴급생계지원 신청 가능한가요?', '이혼으로 소득이 현저하게 감소하여 생계가 곤란하고, 소득과 재산이 정해진 기준에 충족할 경우 긴급생계지원이 가능합니다.

다만, 이혼으로 인한 위기사유 발생시점은 이혼날 날로부터 12개월 이내이므로 동기간을 경과한 경우 지원 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-01-07', 4084, 'https://www.129.go.kr/faq/faq00.do?pageIndex=68#faq7271', '35bb8d38af19b360e030a09ddf6730b8a8e80f2817f959d747391a90b28c26ca'),
('8461', 'faq129-20261010', '사회복지', '긴급지원사업', '전업주부로 주소득자인 남편과 협의 이혼의 절차 중에 있는 경우인데. ‘이혼으로 소득이 현저히 감소한 경우’의 위기사유로 신청이 가능한가요?', '협의 이혼은 ‘신청서 제출 → 숙려기간(1~3개월) → 협의 이혼’이 이루어지는 과정으로 재판으로 장기간 소요되는 이혼 소송과는 다름으로 협의 이혼 완료 이후 요청이 가능합니다.

다만, 미성년자녀가 있는 가정의 협의이혼인 경우 3개월의 숙려기간 동안 생계곤란으로 긴급지원 요청할 경우 시·군·구청에서 전반적 상황을 고려하여 지원의 필요성이 있다면 지원 가능합니다.

* 배우자의 소득수준, 소득•재산•금융재산 선정기준 충족 가능성 등을 종합적으로 판단하여 지원여부 결정

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-01-07', 1575, 'https://www.129.go.kr/faq/faq00.do?pageIndex=68#faq8461', '7f1ec732b9d120371a825b39a595fc0940b333c4e41a49ac14671bf07329f383'),
('9730', 'faq129-20261010', '사회복지', '긴급지원사업', '이혼 소송 중인데, 긴급생계지원 신청 가능한가요?', '이혼소송 중으로 사실상 가족관계가 단절되어 생계가 곤란한 경우도 이혼의 위기상황으로 신청이 가능합니다.

※ 배우자의 소득수준, 소득•재산•금융재산 선정기준 충족 가능성 등을 종합적으로 판단하여 지원여부 결정

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2025-01-07', 1355, 'https://www.129.go.kr/faq/faq00.do?pageIndex=68#faq9730', 'ea0355f1600d82cf6de8084280be1a5f6e77b0f297de645fa8e94393c4e9b3dd'),
('3383', 'faq129-20261010', '인구아동', '기초연금사업', '재건축으로 인해 금융기관에서 받은 이주비 대출금은 부채로 인정가능한가요?', '신청자(수급자) 명의로 금융기관에서 이주비를 대출 받은 경우 금융기관 부채여부를 확인하여 부채로 반영합니다.

또한 재건축으로 취득한 조합원입주권은 증빙서류를 제출받아 기존 건물(토지)의 평가액에 청산금을 정산한 금액으로 재산산정 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-03', 1557, 'https://www.129.go.kr/faq/faq00.do?pageIndex=68#faq3383', '731d8b241ef39a0acf1e45ed5247e6af2363ee9d3fd9bbf0094ac61d5ef0cf39'),
('6355', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '제공인력으로 채용 후에도 건강진단서를 제출해야 하나요?', '제공인력으로 채용 후 매 1년마다 건강진단서를 새로 발급받아 제출해야 합니다.

채용 후 매 1년마다 새로이 제출하는 건강진단서는 해당 회계연도 내에 판정된 것에 한합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-01-03', 1073, 'https://www.129.go.kr/faq/faq00.do?pageIndex=68#faq6355', '78b4b4811c247eee7d6b663913728cb16a6fe0b7617518625d32879d38520bd9');
