INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('7771', 'faq129-20261010', '인구아동', '기초연금사업', '증여로 인해 기초연금을 받지 못하고 있는데. 증여재산의 산정기간이 너무 과도하지 않나요?', '증여에 대한 재산산정은 노인이 현 자산상태를 유지하는 것을 전제하여 고의적인 재산의 축소를 위해 자녀에게 증여하여 수급자로 되는 등의 부적정 수급을 방지하기 위한 것입니다.

기초연금법 시행으로 2011년 7월 1일 이후 재산을 증여하거나 처분한 경우 증여일(또는 처분일)로부터 타재산증가분, 본인소비분, 자연적 소비금액을 차감한 나머지 재산의 가액이 소진될때까지 기타(증여)재산으로 산정하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-03', 3872, 'https://www.129.go.kr/faq/faq00.do?pageIndex=69#faq7771', 'b9737d08f56a662c5f43ffe2fe2f753f1227b52bcaac7eaf8a97b61e0ea0eced'),
('8173', 'faq129-20261010', '인구아동', '지역사회서비스투자사업', '서비스 이용 중 차상위가구로 변동된 경우 등급 조정이 가능한가요?', '서비스 이용 중 세대구성 및 소득 등에 변경사항이 있는 경우 지자체로 이의신청할 수 있습니다.

조사 결과 자격변동이 있다면 익월부터 정부지원금 및 본인부담금이 조정됩니다.

(단, 서비스 지원기간 중 바우처가 1회 생성되는 사업은 등급조정 불가)

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-01-03', 326, 'https://www.129.go.kr/faq/faq00.do?pageIndex=69#faq8173', '494f0213880fead4fd1749235f39eccc4f9693326b66a8249d53a120f39898fb'),
('8193', 'faq129-20261010', '인구아동', '지역사회서비스투자사업', '서비스 이용 중 타지역으로 이사하는 경우 어떻게 되나요?', '서비스 이용 중 다른 지역으로 전출할 경우, 기존 지역에서 취득한 이용자 자격은 상실되므로 전입지에서 재심사하여 선정될 경우 이용이 가능합니다.

재신청 가능여부 및 잔여기간 혹은 전체 서비스 제공여부는 예산 여건, 신청자의 서비스 이용내역 등을 검토하여 해당 전입지 시·­군­·구청장이 자율적으로 결정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-01-03', 488, 'https://www.129.go.kr/faq/faq00.do?pageIndex=69#faq8193', '7706243cc67733976d0969267a77f580c7185e000ab570720105379521e436ab'),
('8613', 'faq129-20261010', '인구아동', '기초연금사업', '리스·렌탈 자동차도 어르신의 재산으로 산정하나요?', '리스·렌탈 자동차는 구매를 통한 소유가 아닌 계약에 따른 임차에 해당하므로 관련 ''임대차계약서''를 제출받고, 임차보증금만 일반재산으로 산정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-03', 1019, 'https://www.129.go.kr/faq/faq00.do?pageIndex=69#faq8613', '1bf112cedd1197bc8b5d44adb1d2bbf1785007e8d1b652004b767385a02eaec7'),
('4941', 'faq129-20261010', '인구아동', '기초연금사업', '압류대상자로 기초연금을 국민연금 안심통장으로 받을 수 있나요?', '국민연금과 기초연금의 지급기관과 금융기관이 상이하므로 기초연금을 국민연금 안심통장으로 지급 받을 수 없습니다.

국민연금 급여는 국민연금 안심통장으로, 기초연금 등 사회보장 급여는 압류방지 전용통장(명칭:행복지킴이 통장)을 사용해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2025-01-02', 6017, 'https://www.129.go.kr/faq/faq00.do?pageIndex=69#faq4941', '53eb7fcb9d86ba4276c052fa40e8780f3e78ba3fc1d1d623fc992653a87456b3'),
('6334', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '가사간병방문지원사업을 받을 수 있는 대상은 어떻게 되나요?', '가사·간병방문지원사업의 지원대상자는,

만 65세 미만의 기준중위소득 70% 이하 계층으로 아래에 해당하는 사람으로 가사·간병 서비스가 필요한 자입니다.

① 장애정도가 심한 장애인

② 6개월 이상 치료를 요하는 중증질환자

(보건복지부장관이 고시한 중증질환 상병 해당자로, 최근 3개월 이내 발행된 진단서 또는 소견서 첨부)

③ 희귀난치성질환자

(보건복지부장관이 고시한 희귀난치성 질환 상병 해당자로, 진단서 또는 소견서 첨부, 단, "행복이음"을 통해 산정특례 등록여부 확인이 가능한 경우에는 관련 자료로 대체 가능)

④ 소년소녀가정, 조손가정, 한부모가정(법정보호세대)

* 이 경우, 서비스 대상자는 자녀·손자녀가 됨

⑤ 만 65세 미만의 의료급여수급자 중 장기입원 사례관리 퇴원자

⑥ 기타 시·군·구청장의 예산의 범위 내에서 장애 정도가 심하지 않은 장애인,질환 및 부상으로 인한 장기치료자 등 가사·간병서비스가 필요하다고 인정하는 자

- 단, 위 대상에 해당하는 경우(만65세 미만의 의료급여수급자 중 장기입원 사례관리 퇴원자 제외)라도 단독으로 일상생활이 가능하거나 실제 생활을 함께 하는 부양가족이 있는 경우는 선정 지양

- 장애인활동지원 등급판정을 받은 자는 활동지원서비스를 우선 활용(만 65세 미만의 의료급여 수급자 중 장기입원 사례관리 퇴원자 제외)

* 장애인 활동지원서비스 미신청자 및 등급판정 제외자는 가사간병 방문지원서비스 신청 가능

- 만 12세 이하 아동 양육보조를 주목적으로 가사·간병 서비스를 신청하는 소년소녀가정, 조손가정, 한부모가정은 여성가족부 시행 ''아이돌봄서비스''를 우선 사용하도록 권고

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-01-02', 796, 'https://www.129.go.kr/faq/faq00.do?pageIndex=69#faq6334', 'f7d89f2276c4a90f20b99ba7efd55939e5b769eb435fa2a7d280825463ccb74e'),
('15341', 'faq129-20261010', '인구아동', '기초연금사업', '종중재산으로 등기할 수 없는 과수원을 재산 산정에서 제외할 수 있나요?', '일반적으로 종중재산 중 부동산의 경우 해당 시­군­구에서 비법인단체 부동산 등기용 등록번호를 받아 등기소에 등기한 경우에만 재산산정에서 제외하며. 법원 판결, 종중정관 등으로 종중재산임을 확인할 수 있는 경우 재산산정에서 제외 가능합니다.

다만, 종중재산으로 등기할 수 없는 농지(전­·답·­과수원)에 한해서는 합유등기로 변경 등기 완료 시 재산산정에서 제외합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2025-01-02', 9, 'https://www.129.go.kr/faq/faq00.do?pageIndex=69#faq15341', '35ed6be747a35e1133dc15cd73dc6c6bd5eb4054c55f68c9ef0ea0d1fc26e9b3'),
('1604', 'faq129-20261010', '인구아동', '기초연금사업', '거주지의 월세 미납금이 임차보증금에서 차감되었는데, 재산산정을 어떻게 하나요?', '월세를 미납하여 임차보증금에서 미납금이 차감되었다고 하더라도 미납금을 재산에서 제외하는 경우 개인간 부채를 인정하는 결과이므로, 당초의 임차계약서 상의 보증금을 재산으로 산정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다..', '2025-01-02', 1730, 'https://www.129.go.kr/faq/faq00.do?pageIndex=69#faq1604', '51910f4c98799991254ba3c9c416a40c7c1699493bc2c0ce867f2c30ee6d0a04'),
('15299', 'faq129-20261010', '노인장애인', '장애인복지사업', '전국민 마음투자 사업 대상자인데 발달장애인 부모상담지원 사업 신청이 가능한가요?', '다른법령(또는 국가 예산)에 따라 발달장애인 부모상담지원 사업과 유사한 서비스를 받고 있는 경우 신청 제외대상입니다.

전국민 마음투자 사업으로 이미 심리상담서비스를 지원을 받고 있다면 발달장애인 부모상담지원 사업을 중복으로 받을수는 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-12-31', 68, 'https://www.129.go.kr/faq/faq00.do?pageIndex=69#faq15299', '9287f5114504029f3747978da7b262a550790907ae0868f479432fdb26033de3'),
('15320', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인일자리 사업에 참여중인데 발달장애인 주간활동서비스 신청이 가능한가요?', '「장애인복지법」 제21조(직업), 「장애인복지법시행령 제13조의 2(장애인일자리 사업 실시)에 따른 장애인일자리사업 참여자는 발달장애인 주간활동서비스 신청을 할 수 없습니다. 다만, 주20시간(월80시간) 이내 단기근로자는 기본형(월 132시간)에 한해 주간활동서비스 이용이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-12-31', 49, 'https://www.129.go.kr/faq/faq00.do?pageIndex=69#faq15320', 'cac116067f0972dd54f6d263df5465deec69020b4e7c996a4ff32a5bf0cc925e'),
('15339', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인 공동생활가정 입주자가 장애인 주간이용시설을 이용할 수 있나요?', '장애인 공동생활가정 입주자는 낮 시간에 장애인복지관, 직장 및 교육기관, 기타 지역사회 활동기관 등을 이용하는 것을 원칙으로 하되, 필요한 경우 장애인 주간이용시설을 이용할 수 있습니다. 다만, 질병 등 특별한 사유가 있는 경우에는 제외할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-12-31', 32, 'https://www.129.go.kr/faq/faq00.do?pageIndex=70#faq15339', '3ab85351d12a2bb3352f641b8ec26230bbb027ba09bb39bbaf21801a70fdf579'),
('15340', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인 단기거주시설 입소자가 장애인 주간이용시설을 이용할 수 있나요?', '시설입소자의 경우 장애인 주간이용시설 이용은 제한됩니다.

다만, 다음의 경우에는 예외적으로 이용할 수 있습니다.

1. 단기거주시설의 휴무일

2. 보호자의 일시적 부재 등으로 인한 단기(연중 1개월 이내) 이용자로 단기 입소 전 주간이용시설 이용자인 경우

3. 지자체장이 중복 수급이 아닌 것으로 인정한 경우

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-12-31', 26, 'https://www.129.go.kr/faq/faq00.do?pageIndex=70#faq15340', '0317cde7394a2648ac6c1a292ab26f82e45435a67b2d79b72399a737c0ce23e4'),
('15300', 'faq129-20261010', '노인장애인', '장애인복지사업', '외국인으로 장애등록한 대상자도 장애인보조기기 교부를 받을 수 있나요?', '아래 조건을 충족하는 장애등록 외국인의 경우에는 가능합니다.

- 장애유형: 장애인복지법에 따른 등록장애인으로 지원품목별 장애유형에 해당되는 ''지체, 뇌병변, 시각, 청각, 심장, 호흡기, 언어, 자폐성, 지적장애인''

- 소득기준: 국민기초생활보장법상 생계, 의료, 주거, 교육급여 수급자 및 차상위계층

- 교부대상: 서비스 지원 종합조사에서 보조기기 필요(적격) 판정된 자

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-12-30', 30, 'https://www.129.go.kr/faq/faq00.do?pageIndex=70#faq15300', '6f971aa7e286a6c38df05dfdbf89667b3f07e8adbcb7335eb461d8918cb2b2d5'),
('15319', 'faq129-20261010', '노인장애인', '노인복지사업', '독거노인으로 응급안전안심서비스 이용 중 자녀와 함께 살게 된 경우 어떻게 되나요?', '응급안전안심서비스 이용 중 대상자 가구 변경으로 인하여 자격을 상실하는 경우 서비스 종결사유에 해당합니다.

이러한 사유로 서비스를 받을 수 없은 경우 서비스 대상자 또는 보호자로부터 ''응급안전안심서비스 대상자 종결(중지) 신청서''를 받고 응급안전안심서비스는 종결처리 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-12-30', 79, 'https://www.129.go.kr/faq/faq00.do?pageIndex=70#faq15319', '578a257c24aa7ade2d85971a068cd55b0e0f9f8e041b635350ab2f00fe747f4b'),
('2448', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '서비스 지원기간은 어떻게 되나요?', '서비스 대상자로 결정된 날로부터 1년이며, 시·군·구의 재판정 절차를 통해 1년 단위로 연장 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-26', 1265, 'https://www.129.go.kr/faq/faq00.do?pageIndex=70#faq2448', '8c2001ec8fb7926857f124e3c07d49cf4257a78233c593fc448efc45c99e7563'),
('4726', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '한 달에 몇 시간 이용할 수 있나요?', '생계·의료·주거·교육 수급자 및 차상위 계층, 기준중위소득 70% 이하 계층의 경우 월 24시간 또는 월 27시간 중 선택이 가능하며, 의료급여수급자 중 장기입원 사례관리 퇴원자는 월 40시간 이용이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-24', 1378, 'https://www.129.go.kr/faq/faq00.do?pageIndex=70#faq4726', 'fe22e4fae59302da01749f3652f8c8e06002481bb75f7363f5c00136275267d2'),
('4729', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '서비스 이용 중에 장애인활동지원서비스를 신청하면 가사간병서비스는 바로 중지 되나요?', '장애인활동지원서비스 지원 결정 시 중지되므로, 지원 결정 전까지는 가사간병서비스 이용이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-24', 1655, 'https://www.129.go.kr/faq/faq00.do?pageIndex=70#faq4729', '7c04c48ea54b7634fbd528a3c25682f17778c479ff867ad6fd2214a5f1bcafc4'),
('4750', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '주민등록지 제공기관만 이용해야 하나요?', '이용자는 본인의 주소지에 상관없이 시­·도 내에 등록된 제공기관 중 이용이 편리한 기관을 선택하여 서비스를 신청할 수 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-24', 1183, 'https://www.129.go.kr/faq/faq00.do?pageIndex=70#faq4750', '3cda0fabe1d277e708f17225d821d5ca5d113851d839d2630178e8d3083f2b27'),
('6053', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '의료기관에서 퇴원한 당일부터 서비스 이용이 가능한가요?', '의료기관에 입원 중인 경우 서비스 제외 대상자이나, 입원 기간 동안만 서비스 이용이 불가한 것으로 입·퇴원일은 서비스 이용 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-24', 706, 'https://www.129.go.kr/faq/faq00.do?pageIndex=70#faq6053', 'b93c2e5582dea06eff30cdc752b3ffdd40a755a5447ddb9f29809a7112d5ec6b'),
('6332', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '서비스 대상자가 서비스 이용을 포기 하는 경우 본인부담금 환급되나요?', '서비스이용 중지 요청을 한 경우, 환급신청 절차 없이 한국사회보장정보원에서 해당 대상자의 환급계좌로 60일이내 본인부담금 잔액이 환급 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2024-12-24', 833, 'https://www.129.go.kr/faq/faq00.do?pageIndex=70#faq6332', 'c0b7d407d9b35ebf1fc54e1b0def7e4ba0d6fac8bf2fe7baa9ebb976a8350fd4');
