INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('2394', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '제공기관으로 등록하고자 합니다. 어디로 등록신청 해야 하나요?', '제공기관 등록은 사업장 주 소재지 관할 시·군·구로 등록신청해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2024-12-24', 1481, 'https://www.129.go.kr/faq/faq00.do?pageIndex=71#faq2394', 'd2f28a3d8bb9b10f03ba9b1717113fb3a4d889fa7a9b5e6dfb98347bd92e221a'),
('2449', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '제공인력으로 참여하고자합니다. 자격조건이 있나요?', '제공인력 자격조건은 만 18세 이상으로 노인복지법에 따른 요양보호사 자격취득자입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2024-12-24', 1250, 'https://www.129.go.kr/faq/faq00.do?pageIndex=71#faq2449', '8fb040bb2dc1dc9173dfeac963a412acbef11ca79bcee955f8cded7e5d7cde7a'),
('4727', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '자녀가 아이돌봄서비스를 이용 중 인데 모친도 가사간병서비스 이용이 가능한가요?', '동일 가구 내에서 여성가족부의 “아이돌봄서비스”와 가사·간병 서비스를 모두 이용하는 경우, 제공인력의 업무를 각각 대상자 관련 서비스로 제한하여 중복수급을 하지 않는다면 지원 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-23', 1361, 'https://www.129.go.kr/faq/faq00.do?pageIndex=71#faq4727', '638f757b95d9e86d630b55cbb3a5bea00bd5c3d1663ebdfb042ae8f566c3ab49'),
('4735', 'faq129-20261010', '인구아동', '가사간병방문지원사업', '본인부담금 납부방법은 어떻게 되나요?', '바우처 카드 또는 결정통지서에 명시된 지정계좌에 납부하시면 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-23', 1421, 'https://www.129.go.kr/faq/faq00.do?pageIndex=71#faq4735', '871c02cfb70b41e9d7e97598ba9dae62fe45e0c1ac0350012396d56528c63741'),
('15219', 'faq129-20261010', '보건의료', '건강보험정책', '본인부담 차등화 적용 시 외래진료 횟수에 약국 이용 횟수도 포함되나요?', '아닙니다. 의료기관 외래이용 횟수만 산정하므로 약국을 방문한 이용 횟수 및 투약 조제일수는 포함되지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-23', 113, 'https://www.129.go.kr/faq/faq00.do?pageIndex=71#faq15219', '7c4dbd0d16898a4724f8cedd4cc83777f05289a8497d7cdbb2bc4ab751b3434f'),
('15220', 'faq129-20261010', '보건의료', '건강보험정책', '임신부 외래 진료시 본인부담 경감 적용기간은 어떻게 되나요?', '임신부 외래 진료시 본인부담 경감 적용기간은 임신이 확인된 이후 임신이 유지되는 기간에 적용되며, 유산, 사산으로 인한 시술(또는 수술)을 위한 외래진료 당일을 포함합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-23', 41, 'https://www.129.go.kr/faq/faq00.do?pageIndex=71#faq15220', 'af09034350237b0b64f27813910e8479330031d4f7401499644fc1321288b9d3'),
('15221', 'faq129-20261010', '위기대응', '자살예방', '24년부터 기존의 정신건강상담전화(1577-0199) 등 다른 전화번호는 상담이 불가능한지?', '2024년1월1일부터 자살예방상담은 109로 모두 통합되었으며, 정신건강상담전화(1577-0199), 청소년전화(1388), 여성긴급전화(1366) 등은 종전과 같이 본연의 역할에 따라 담당 분야 상담을 수행하고 있습니다.', '2024-12-23', 21068, 'https://www.129.go.kr/faq/faq00.do?pageIndex=71#faq15221', 'aae273234c42a3aba010c7220615c3902b758b0d8f40ebea3104eb28ede8b638'),
('15222', 'faq129-20261010', '위기대응', '자살예방', '자살예방 상담 과정에서 개인정보가 수집되는지?', '자살예방상담전화(109) 또는 “마들랜” 상담 과정에서 별도 동의 없이는 개인정보를 수집하지 않습니다.', '2024-12-23', 11274, 'https://www.129.go.kr/faq/faq00.do?pageIndex=71#faq15222', '2de473879841ce56fca9ea21ef3b06978aa65d96da8d72d5ca7ad4f2e90f3e3f'),
('15223', 'faq129-20261010', '위기대응', '자살예방', '자살예방 상담 내용에 대한 비밀이 보장되는지?', '○ 자살예방상담전화(109) 또는 “마들랜” 상담 과정에서 상담 내용은 기본적으로 비밀이 보장됩니다.

○ 다만 상담 대상자가 위급한 경우 다른 기관 등으로 도움을 요청할 수 있습니다.', '2024-12-23', 42555, 'https://www.129.go.kr/faq/faq00.do?pageIndex=71#faq15223', '7818fca68aa5499e3afc407ce672e3325df5b53dca59322847debf2a3186ae61'),
('15224', 'faq129-20261010', '위기대응', '자살예방', '자살 예방 상담 후 별도의 후속 조치가 있는지?', '상담 과정에서 위험성이 높은 수준이라고 판단되는 경우에는 본인 동의를 받은 후 주소지 지역의 정신건강복지센터 또는 자살예방센터 등으로 연계되어, 추가적인 대면상담과 사례 관리 서비스 등을 받을 수 있습니다.', '2024-12-23', 28435, 'https://www.129.go.kr/faq/faq00.do?pageIndex=71#faq15224', '855a833a2a2de2d0402b76aaf668a889a39fd2e64d075aa731997e282a7a198f'),
('15239', 'faq129-20261010', '위기대응', '자살예방', 'SNS기반의 자살예방 상담 “마들랜” 서비스 이용 방법은?', '자살예방상담전화(109)와 같이 365일, 24시간 상담창구로써 운영중이며, 카카오톡, 어플리케이션, 문자메세지를 통해 상담할 수 있습니다. 구체적인 접속 방법은 109 웹사이트 내 마들랜 안내 페이지(www.129.go.kr/109/etc/madlan)를 참조하시기 바랍니다.', '2024-12-23', 10499, 'https://www.129.go.kr/faq/faq00.do?pageIndex=72#faq15239', '172806cd4c8b9345a750791969258988e33cbc92a5811a9e0ef3856f66e07449'),
('6892', 'faq129-20261010', '인구아동', '사회복지시설', '사회복지시설 설치·신고는 어디로 하나요?', '사회복지시설 설치·신고는 국가 또는 지방자치단체 외의 자가 시설을 설치­·운영하고자 하는 때에는 시장­·군수·­구청장에게 신고하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-18', 1634, 'https://www.129.go.kr/faq/faq00.do?pageIndex=72#faq6892', '6236546f8910b344c4d210151d4bc6812731d6220a9ef973ba0edfa750a5bd32'),
('7190', 'faq129-20261010', '인구아동', '사회복지시설', '사회복지시설 폐지신고는 어디로 하나요?', '사회복지시설을 폐지하고자 하는 경우에는 폐지 3개월 전까지 ''사회복지시설(휴지, 재개, 폐지)신고서''를 포함한 구비서류를 갖추어 시장·­군수·­구청장에게 신고하여야 합니다.

구비서류(시행규칙 제26조제1항)는 다음과 같습니다.

- 시설의 폐지사유서(법인의 경우 폐지를 결의한 이사회의 회의록 사본) 1부

- 시설거주자에 대한 조치계획서(시설 거주자 자립 지원 또는 전원조치 등 포함) 1부

- 시설 이용자가 납부한 시설 이용료 및 사용료의 반환조치계획서 1부

- 보조금­후원금의 사용 결과 보고서와 이를 재원으로 조성한 잔여재산 반환조치 계획서 1부

- 시설의 재산에 관한 사용 또는 처분계획서 1부

- 사회복지시설 신고증 1부

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-18', 2432, 'https://www.129.go.kr/faq/faq00.do?pageIndex=72#faq7190', 'b5dd93fa8c59f4b04fc5b081619bf477457f14db6083827f8f0ba252547995d5'),
('7151', 'faq129-20261010', '인구아동', '사회복지시설', '사회복지시설 설치 시 고유번호증 또는 사업자등록증을 발급받아야 하나요?', '사회복지시설을 설치­운영하거나 국공립 사회복지시설을 위탁 받아 운영할 경우 「부가가치세법」, 「법인세법」 등 관련 법령에 따라 각 시설별로 별도의 고유번호증 또는 사업자등록증을 발급받도록 하고 있습니다.

법인이 설치­운영(수탁 포함)하는 시설의 경우 “법인명(단체명)”에 법인명칭을 기재하거나 법인명칭과 시설명칭을 병기하는 형태 등으로 고유번호증(사업자등록증) 발급을 세무관서에 신청할 수 있으며(권고사항),

고유번호증 또는 사업자등록증 신청 및 발급 절차에 대해서는 국세청(☎ 126) 또는 관할 세무서에 문의하시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-17', 5357, 'https://www.129.go.kr/faq/faq00.do?pageIndex=72#faq7151', '8b9c96346ccf99507e523622713e67ca05dad707d79a79520dfc59dd54e8bca9'),
('2457', 'faq129-20261010', '인구아동', '사회복지시설', '사회복지시설의 시설장은 상근의무가 있나요?', '사회복지시설의 장은 「사회복지사업법」제35조에 따라 상근의무가 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-17', 4031, 'https://www.129.go.kr/faq/faq00.do?pageIndex=72#faq2457', '93995726498e4762269b878950bd5cd3d50d8e566f91f741051e0ef57acf06d0'),
('2458', 'faq129-20261010', '인구아동', '사회복지시설', '사회복지시설 종사자도 정년제가 있나요?', '사회복지시설은 근로계약, 취업규칙 등에 따라 시설장 및 종사자의 정년을 정할 수 있으므로, 시설 사유화의식 탈피 및 조직쇄신 차원에서 정년제 실시를 권고하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-17', 2567, 'https://www.129.go.kr/faq/faq00.do?pageIndex=72#faq2458', 'd990186c3565af68f728750406803a86f9249752511ff39020b3b991da200161'),
('2459', 'faq129-20261010', '인구아동', '사회복지시설', '사회복지시설 관리안내 지침 및 종사자 인건비 가이드라인을 어디에서 확인할 수 있나요?', '사회복지시설 관리안내 지침 및 종사자 인건비 가이드라인은 보건복지부 홈페이지(www.mohw.go.kr)에서 확인가능합니다.

* 경로 : 홈 > 정보 > 법인/시설/단체

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-17', 4112, 'https://www.129.go.kr/faq/faq00.do?pageIndex=72#faq2459', 'bcc16a9ca0e7ea0c27cc05523b6e311645f6ea9b578aaa287ed0fc9330c6fa5a'),
('15063', 'faq129-20261010', '인구아동', '부모급여', '월중 어린이집에 입소나 퇴소시 전액 지원받지 못한 부모급여(바우처)는 어떻게 지원되나요?', '0,1세 아동이 어린이집을 월 중 입·퇴소 하는 경우, 보육료는 일할계산되어 어린이집에 지급됩니다. 따라서 부모보육료와 어린이집에 지원된 금액의 차액을 보호자에게 다음월 지급이나, 특별한 사유가 없는 경우에는 다음월 20일까지 아동 소재지 시·군·구에서 지급합니다.

* 보육료 차액의 경우, 보호자 결제 유무 상관 없이 다음월 지급하지만 보육료 정산금 및 상·하위반 편성에 따른 차액의 경우 보호자가 결제해야 결제월의 다음월에 지급 가능

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-11', 117, 'https://www.129.go.kr/faq/faq00.do?pageIndex=72#faq15063', 'ad07ff0d01421dc8a09bb719e9f12ba6483bd0a406715c77b22ebca2cf163075'),
('15159', 'faq129-20261010', '보건의료', '보건의료정책', '모든 약국에서 환자의 개인정보 수집이용 동의서를 꼭 받아야 하나요?', '아닙니다.

약국에 따라 수집하는 개인정보의 종류를 확인하고, 개인정보 수집이용 목적에 따라 동의서의 징구여부를 결정해야 합니다.

약국에서 법령에 따라 필요한 정보(처방전 정보, 조제정보 및 요양 급여청구정보)만 처리하신다면, 원칙적으로 동의서를 받아야할 필요가 없습니다.

그러나 고객관리정보나 홈페이지 회원정보 등과 같은 약국의 조제 등의 필요한 목적 외의 정보는 정보주체의 동의를 필요로 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-11', 60, 'https://www.129.go.kr/faq/faq00.do?pageIndex=72#faq15159', 'caf98e320869b9b579bab11d1b4f440a6ddab145d4471d327de3841f91e05cd1'),
('15160', 'faq129-20261010', '보건의료', '보건의료정책', '약국은 의료기관에서 전화상으로 환자의 조제내역을 알려달라고 하는 경우 알려줘도 되나요?', '원칙적으로 전화상으로 환자의 조제내역을 알려주는 경우 약사법 위반이 될 수 있습니다.

환자 본인이나 보호자와 직접 연락할 수 있도록 조치를 취해 주는 것이 바람직하며, 전화상으로 환자의 동의여부를 확인하기 어려운 경우에는 개인정보를 제공하지 않도록 주의하시기 바랍니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2024-12-11', 75, 'https://www.129.go.kr/faq/faq00.do?pageIndex=72#faq15160', '8a0ae3d90e5b607aaa4f2f8ccfd49b1e5123b323b78781d93894de31820a5d54');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('10976', 'faq129-20261010', '보건의료', '보건의료정책', '간호·간병통합서비스병동 입원이 가능한 대상은 누구인가요?', '간호·간병통밥서비스란? 진료 성격이나 질병 특성상 보호자의 간병을 제한할 필요가 있는 환자, 환자의 생활 여건이나 경제 상황 등에 비추어 보호자 등의 간병이 현저히 곤란한 환자, 의사가 간호·간병서비스가 필요하다고 인정하는 입원 환자를 대상으로 보호자 등이 상주하지 아니하고 간호사, 간호조무사 및 그 밖의 간병지원인력에 의하여 포괄적으로 제공되는 입원서비스를 말합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-10', 702, 'https://www.129.go.kr/faq/faq00.do?pageIndex=73#faq10976', 'e7158963a3e9c7fbf93ab84f72d7e6fe7cdc9882c64f4c04fe486ddd65b3c967'),
('14359', 'faq129-20261010', '인구아동', '아동분야사업', '(가정위탁) 고등학교 졸업 후 가정위탁 보호종료된 아동이 재보호 요청할 경우 가능한가요?', '「아동복지법」개정으로 2024. 8. 7.(수)부터 위탁가정 또는 아동복지시설에서 보호가 종료된 이후 혼자 자립을 준비하기 어려운 자립준비청년은 ­대학 재학 또는 진학 준비/ ­직업 교육·훈련 / ­경제·심리·주거의 어려움/ ­장애·질병 / ­지적 능력 등의 사유로 재보호를 희망하는 경우 가정위탁 또는 아동복지시설에서의 재보호를 받을 수 있게 되었습니다.

위탁가정·시설에서의 재보호를 희망하는 자립준비청년은 주소지를 관할하는 시·군·구에 신청해야 하며, 자립준비청년의 위임을 받아 친족이나 관계 공무원, 아동복지시설의 장 등도 대리로 신청할 수 있습니다. 신청을 접수한 시·군·구는 청년에 대한 보호계획을 수립하고, 아동복지심의위원회의 심의를 거친 후 재보호 여부를 결정하게 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-04', 22, 'https://www.129.go.kr/faq/faq00.do?pageIndex=73#faq14359', 'fd91fbc9cdc8b13e64715aa23db27f71602c3f669561676a292418388460ad06'),
('14479', 'faq129-20261010', '인구아동', '아동분야사업', '(위기임산부) 뜻하지 않은 임신을 하게 되었는데 어떤 도움을 받을 수 있나요?', '24년 7월 19일부터 위기임신 보호출산제를 시행하게 되었습니다.

이는 경제적·심리적·신체적 사유 등으로 출산 및 양육에 어려움을 겪고 있는 임산부의 안전한 출산을 지원하고 그 태아 및 자녀인 아동의 안전한 양육환경을 보장함으로써 생모 및 생부와 그 자녀의 복리 증진을 위해 만들어졌습니다.

위기임신 및 보호출산제 내용은 아래와 같습니다.

① (상담) 위기임산부는 언제든지, 누구든지 아동을 직접 양육하기 위해 위기임산부 상담기관에게 임신­출산­양육 전반에 대한 상담 가능

- 위기임산부 핫라인(통합전화) : 1308 (가까운 지역 상담기관으로 연결)

- (상담 방법) 대면 상담, 온라인­모바일 상담, 전화 상담 등

- (상담 내용) 원가정 양육을 위해 임신­출산­양육 시 지원받을 수 있는 공적 제도 안내, 각종 민간 복지 자원 및 후원 연계 등

② (보호출산) 원가정 양육을 위한 상담에도 불구하고 보호출산을 선택한 경우 위기임산부는 보호출산을 위한 상담을 추가로 받고, 보호출산을 신청한 위기임산부가 의료기관에서 가명으로 산전검진 및 출산할 수 있도록 비식별화 조치, 비용 지원 등 실시

* 출생통보제 도입 시 우려되는 위기임산부의 의료기관 밖 출산과 영아유기 방지를 위해 의료기관에서 신원을 밝히지 않고 출산할 수 있도록 지원

③ (아동보호) 보호출산을 신청한 위기임산부의 출산으로 태어난 아동에 대해서는 숙려기간(7일 이상)을 거쳐 지자체 인도하여 보호조치(후견인 선임, 일시보호 등), 의료기관은 출생사실을 건강보험심사평가원으로 통보하고, 건강보험심사평가원은 상담기관으로 통보하며, 상담기관은 지자체(시·­읍·면)로 통보하고 지자체는 아동에 대한 출생등록 절차 수행

④ (기록관리) 보호출산 아동의 생모·­생부의 인적사항, 보호출산 계기 등 상담내용과 아동의 정보가 기록된 출생증서를 아동권리보장원으로 이관하여 영구보존, 추후 출생증서 공개청구 등 절차를 통해 아동의 알 권리 보장

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-04', 21, 'https://www.129.go.kr/faq/faq00.do?pageIndex=73#faq14479', '5d9b2c4c70edf3070463033d81068b7c16c7468edde4198e4858991f13eafcf4'),
('15039', 'faq129-20261010', '보건의료', '건강정책', '유치원, 어린이집, 초중고교 시설이 금연구역인가요?', '국민건강증진법 제9조4항에 따라

­유아교육법­­­, 초­중등교육법­에 따른 학교[교사(校舍)와 운동장 등 모든 구역을 포함한다] 와 ­영유아보육법­에 따른 어린이집은 건물을 포함한 대지전체가 금연구역이며,

국민건강증진법 제9조6항에 따라

유치원,­ 어린이집­, 초중고교 시설 경계선으로부터 30미터 이내도 금연구역으로 지정됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-04', 52, 'https://www.129.go.kr/faq/faq00.do?pageIndex=73#faq15039', 'c27f8f8f3e48d7babf689327f2eed658207efdb029bf17e67c0d27009738d439'),
('15059', 'faq129-20261010', '보건의료', '건강정책', '보건소 금연클리닉이 뭔가요?', '보건소 금연클리닉은 흡연자를 위한 금연지원서비스 제공을 통해 금연실천을 유도하여 흡연율을 감소시키고 건강증진을 도모하기 위한 목적으로 운영되는 곳으로,

지역사회 흡연자(청소년, 외국인 포함)를 대상으로 6개월 9차 이상 금연상담서비스와 니코틴보조제 등을 제공하고 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-12-04', 61, 'https://www.129.go.kr/faq/faq00.do?pageIndex=73#faq15059', '5839a9fe82b19db607be92596bf32b0b0930c9d2c1023ca89d1c86ac76c6b5fe'),
('14860', 'faq129-20261010', '사회복지', '자활사업', '자활근로참여자의 근무 시간은 어떻게 되나요?', '자활근로 근무시간은 주 5일, 1일 8시간(09시~18시)이며 근로유지형은 1일 5시간(09시~15시)이 원칙입니다.

다만, 가구특성 등을 고려하여 종일 일자리 참여가 어려운 경우 예외적으로 시간제(일 4시간)자활근로 참여가 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-29', 283, 'https://www.129.go.kr/faq/faq00.do?pageIndex=73#faq14860', 'a65ed1f177ca1d50ed4c7531d2f957f28030809444b10b08fb2f70a0e250200b'),
('14919', 'faq129-20261010', '사회복지', '자활사업', '자활근로 참여자에게도 초과근무수당이 지급되나요?', '자활근로 참여자가 연장, 야간 및 휴일· 휴무일 근무를 할 경우 초과근무 시간에 대해 급여의 0.5배를 가산하여 초과근무 수당이 지급됩니다.

다만, 사업단 자체 매출액으로 지급하며 월 매출액 규모가 최소한 초과근무 수당을 충족하는 경우에 지급 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-29', 189, 'https://www.129.go.kr/faq/faq00.do?pageIndex=73#faq14919', 'f97df9ded4621419cfe3befb6e1d7309b1e945ae66b3f60b43a61e544f665351'),
('14939', 'faq129-20261010', '사회복지', '자활사업', '자활근로사업 참여자격은 어떻게 되나요?', '자활근로는 아래와 같은 자격으로 참여 가능합니다.

① 조건부수급자：자활사업 참여를 조건으로 생계급여를 지급받는 수급자

② 자활급여특례자：의료급여 수급자가 자활근로, 자활기업 등 자활사업 또는 국민취업지원제도에 참가하여 발생한 소득으로 인하여 소득인정액이 기준 중위소득의 40%를 초과한 자

③ 일반수급자 : 근로능력 없는 생계급여수급권자 및 조건부과유예자, 의료­·주거­·교육급여수급(권)자 중 참여 희망자

④ 특례수급가구의 가구원：의료급여특례 등 특례가구의 근로능력 있는 가구원 중 자활사업 참여를 희망하는 자

⑤ 차상위자：근로능력이 있고, 소득인정액이 기준 중위소득 50% 이하인 사람 중 비수급권자

⑥ 근로능력이 있는 시설수급자

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-29', 344, 'https://www.129.go.kr/faq/faq00.do?pageIndex=73#faq14939', 'e55c7bc48da570e6beaad70e4aa7fb82ba739f97dd39ad6481ef7c58b30cd5b2'),
('14940', 'faq129-20261010', '사회복지', '자활사업', '자활기업이란 무엇인가요?', '자활기업은 취약계층의 공동창업을 통한 탈빈곤을 지원하는 제도로, 2인 이상의 수급자 또는 차상위자가 상호협력하여 조합 또는 사업자의 형태로 자활사업을 운영하는 업체입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-29', 214, 'https://www.129.go.kr/faq/faq00.do?pageIndex=73#faq14940', 'd6fafcdddeb7ea29b304f3e2c8873633993d4009b3e0eb125bf7f336396b69f2'),
('3662', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급의료지원 범위에 보호자 식대도 포함되나요?', '급여 적용이 되는 환자 식대는 긴급의료비 지원 범위에 포함되어 있으나, 비급여 식대 및 보호자 식대는 지원 되지 않습니다.

* 긴급의료비 지원제외 : 간병비, 의료소모품 구입비. 보조기 또는 의료기구 구입비, 제증명료, 보호자 식대, 구급차 이용료, 비급여 도수치료비·증식치료비·추나요법, 비급여입원료(특실 및 1인실 비용), 비급여식대.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 3193, 'https://www.129.go.kr/faq/faq00.do?pageIndex=73#faq3662', 'c93ce6754173f77789fa5f7bc9948ddfb6d207e69ce19fb560c074188e5ab1d6'),
('4470', 'faq129-20261010', '사회복지', '긴급지원사업', '주민등록말소자의 수술비 요청 시 긴급의료지원 신청이 가능한가요?', '주민등록말소자의 중한 질병 또는 부상으로 의료비 감당이 곤란한 경우 지원요청이 가능합니다.

※ 위기사유 및 소득, 재산, 금융재산 기준을 충족하여야 함

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 6425, 'https://www.129.go.kr/faq/faq00.do?pageIndex=74#faq4470', 'd0f2c7fc2a544f0bf70f5ee5a807e2ba1d70c701e066cc34688d31d54500fd2c'),
('7830', 'faq129-20261010', '사회복지', '긴급지원사업', '도수치료비도 긴급의료지원으로 받을 수 있나요?', '급여가 되는 도수치료비는 긴급의료지원에 포함이 되나 비급여로 진행되는 도수치료비·증식치료비·추나요법은 지원에서 제외됩니다.

* 긴급의료비 지원제외 : 간병비, 의료소모품 구입비. 보조기 또는 의료기구 구입비, 제증명료, 보호자 식대, 구급차 이용료, 비급여 도수치료비·증식치료비·추나요법, 비급여입원료(특실 및 1인실 비용), 비급여식대

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 1521, 'https://www.129.go.kr/faq/faq00.do?pageIndex=74#faq7830', '6f7e3ba9c53fed6b08df8665476da59799b3a601168c943531a1d7fc6d489c06'),
('9791', 'faq129-20261010', '사회복지', '긴급지원사업', '호스피스병동 이용 시 긴급의료지원이 가능한가요?', '호스피스병동은 중한 질병에 따른 수술 및 치료를 위한 것이 아니기 때문에 긴급의료지원은 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 681, 'https://www.129.go.kr/faq/faq00.do?pageIndex=74#faq9791', 'f683d10cd5a6aa716bc0e4421ba6f3708296c07bf2da2a865fa024a0e2078875'),
('13924', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급생계지원 대상자의 전기요금도 지원되나요?', '긴급생계지원 대상 가구가 전기요금 체납으로 단전(전류제한기 부설 포함)이 된 경우에 한해 부가지원으로 50만원 범위 내에서 전기요금 지원이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 560, 'https://www.129.go.kr/faq/faq00.do?pageIndex=74#faq13924', '20ebc1fcd037cbd4f4fbf6342e0fc1216e28250821da5cbdeecf876f2375b36c'),
('13991', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급생계지원 신청대상은 누구인가요?', '주소득자의 사망, 가출, 실직 등의 위기사유로 생계가 곤란하여 도움이 필요한 경우 신청할 수 있으며 소득, 재산, 금융재산 기준 또한 충족하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 1209, 'https://www.129.go.kr/faq/faq00.do?pageIndex=74#faq13991', '6ba98c16c3ff0f5e3edd3d35210c1540aa8d950a31a522e28a7b6e3d41b5fe5e'),
('13992', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급의료지원 신청대상은 누구인가요?', '수술 및 입원이 필요한 중한 질병 또는 부상으로 발생한 의료비를 감당하기 곤란한 경우 신청대상이 되며, 소득, 재산, 금융재산 기준 또한 충족하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 531, 'https://www.129.go.kr/faq/faq00.do?pageIndex=74#faq13992', '7ab18321650b39bc7795e6d52e7b634e19ab60b040a30d32bf362ad8c1b1ec9e'),
('13993', 'faq129-20261010', '사회복지', '긴급지원사업', '당뇨, 고혈압 등 만성질환으로도 긴급의료지원이 가능한가요?', '긴급의료지원은 만성적으로 앓고 있는 질병에 대해 원칙적으로 지원 대상이 될 수 없습니다.

다만, 진단서를 통해 갑자기 악화되어 수술 또는 입원을 요하는 긴급한 진료가 필요하다고 시군구청장이 인정하는 경우 인정 가능합니다.

※ 위기상황 및 소득, 재산, 금융재산 기준을 충족하여야 함

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 409, 'https://www.129.go.kr/faq/faq00.do?pageIndex=74#faq13993', 'f91486754b1e9c05784f4f70dc46f07a1a550aee3332a14fa375249089c0d165'),
('13994', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급의료요청시 주택청약종합저축은 금융재산으로 산정되나요?', '「주택법」 제56조2항에 따른 주택청약종합저축은 금융재산에서 제외하고, 일반재산으로 산정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 188, 'https://www.129.go.kr/faq/faq00.do?pageIndex=74#faq13994', 'd30fca1c8411090666c71239f2fae8b3b2b8f0c7de7f175399c0f8fb6f037cfa'),
('14014', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급의료지원 신청은 어디로 하나요?', '위기상황 발생으로 긴급지원대상자(위기상황에 처한 사람)와 친족, 그 밖의 관계인은 읍면동주민센터, 시군구청 또는 보건복지상담센터(국번없이 129)로 신청합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 397, 'https://www.129.go.kr/faq/faq00.do?pageIndex=74#faq14014', '2ad7d737f5c41e3997c1c8a2874bbe52220d831c14bdeffea589945800324911'),
('14016', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급생계지원 재산기준이 어떻게 되나요?', '긴급생계지원의 재산기준은 지역별로 다음과 같으며, 해당 가구에 주거용재산*이 있는 경우 주거용재산 공제 한도액만큼 추가 적용할 수 있습니다.

* 주거용 재산 : 긴급지원 대상자가 실제 거주하며 생활하고 있는 주택(1호에 한하여 인정)

< 긴급생계지원 재산기준>

○ 대 도 시 : 2억 4,100만원 + 6,900만원(주거용재산)

○ 중 소 도 시 : 1억 5,200만원 + 4,200만원(주거용재산)

○ 농 어 촌 : 1억 3,000만원 + 3,500만원(주거용재산)

<긴급생계지원 금융재산기준>

○ 금융재산 : 600만원 + 가구수별 중위소득 100% 금액이하

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 758, 'https://www.129.go.kr/faq/faq00.do?pageIndex=74#faq14016', '20c60fdb0c2677414d0559a4ffb12ccdcb6b87bf4950506b4cf465395e206915');
