INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('14017', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급의료지원 요청시 소득에서 차감되는 지출항목이 있나요?', '지원요청 당시의 소득에서 정기적으로 지출되는 비용을 차감하는 항목은 다음과 같습니다.

① 3개월 이상 지속적으로 지출하는 의료비(의료기관의 진단서 및 진료비 영수증 첨부)로서 평균 1개월의 의료비, 약제비, 간병비

② 자신의 소득에서 지출하고 있는 대학생의등록금(입학금수업료), 기성회비

※ 당해연도 납부한 입학금수업료의 월평균 지출액

③ 월세(또는 보증부 월세)로 주거를 임차한 경우 매월 지출되는 임차료

※ 임차료 차감한도액 : 가구구성원수별 긴급주거지원금

④ 국민연금, 건강보험, 고용보험 등 사회보험료

⑤ 신용회복위원회를 통해 또는 법원의 판결을 받아 납부하고 있는 채무변제액 또는 금융부채로 인하여 매월 지출되고 있는 원금 및 이자비용

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 224, 'https://www.129.go.kr/faq/faq00.do?pageIndex=75#faq14017', '487d9bdae4e4483c8f36c96a75b1d381ce05de5aabd06a16e344aba14fb7bddc'),
('855', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급의료지원 재산기준이 어떻게 되나요?', '긴급의료지원의 재산기준은 지역별로 다음과 같으며, 해당 가구에 주거용재산*이 있는 경우 주거용재산 공제 한도액만큼 추가 적용할 수 있습니다.

* 주거용 재산 : 긴급지원 대상자가 실제 거주하며 생활하고 있는 주택(1호에 한하여 인정)

< 긴급생계지원 재산기준>

○ 대 도 시 : 2억 4,100만원 + 6,900만원(주거용재산)

○ 중 소 도 시 : 1억 5,200만원 + 4,200만원(주거용재산)

○ 농 어 촌 : 1억 3,000만원 + 3,500만원(주거용재산)

<긴급생계지원 금융재산기준>

○ 금융재산 : 600만원 + 가구수별 중위소득 100% 금액이하

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 4314, 'https://www.129.go.kr/faq/faq00.do?pageIndex=75#faq855', '084e44f206c5bc640434e25e5467c73a75767baac51ade55afd00d474f02a83c'),
('856', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급생계지원 대상자가 되면 추가로 받을 수 있는 지원이 있나요?', '긴급지원 대상자의 위기상황에 따라 생계지원 이외에 의료지원, 주거지원을 선택적 또는 복합적으로 지원을 받을 수도 있습니다.

또한, 생계지원을 받고 있는 기간 중 기타 위기상황 극복에 필요할 경우 부가지원으로 교육지원, 연료비, 해산비, 장제비, 전기요금 등을 병행하여 지원을 받을 수도 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 2877, 'https://www.129.go.kr/faq/faq00.do?pageIndex=75#faq856', 'd8ba6b52602c29fa9f29bf0fcbd94f9ed91683b421ddac5daeb49b9e70df4cc7'),
('857', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급생계지원 신청은 어디로 하나요?', '위기상황 발생으로 긴급지원대상자(위기상황에 처한 사람)와 친족, 그 밖의 관계인은 읍면동주민센터, 시군구청 또는 보건복지상담센터(국번없이 129)로 신청합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 4266, 'https://www.129.go.kr/faq/faq00.do?pageIndex=75#faq857', '7f811bd31b327c047a1e0c69d26afab652476512e97702869a8e0277fc2c338e'),
('864', 'faq129-20261010', '사회복지', '긴급지원사업', '실업급여 수령 중인데 긴급생계지원 신청이 가능한가요?', '실업급여를 받고 있는 경우에는 긴급생계지원 요청은 불가합니다.

실업급여 수령기한이 종료되었음에도 불구하고 재취업이 되지 않아 위기상황이 지속이 될 경우 소득상실한지 1년이내인 경우 긴급생계 요청가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 2586, 'https://www.129.go.kr/faq/faq00.do?pageIndex=75#faq864', '74e9cff61edde614dfbd71a2ff1aeab32baaf1398c7bb871e4e8abc907fcd031'),
('865', 'faq129-20261010', '사회복지', '긴급지원사업', '실직의 사유로 긴급생계지원 신청할 수 있나요?', '실직으로 가구의 생계유지 등이 곤란한 경우 긴급생계지원을 요청할 수 있으며, 다음의 요건을 모두 충족해야 합니다.

① 가구구성원 주(부)소득자가 실직했으나 고용보험법상 실업급여를 받지 못하거나 또는 실업급여가 종료 되었으나 계속적인 실직 상태로 생활이 어려운 경우

② 긴급지원 신청일 기준 실직한 날이 1개월 경과 12개월 이내이고, 실직 전 3개월 이상 근로한 경우

③ 1개월간 소정근로시간이 고용보험법 제10조 2호 및 동시행령 제3조1항에서 정한 적용제외 근로자 기준의 근로시간 이상인 경우(1개월간 60시간 이상) ※ 확인되는 급여가(최저임금 60시간) 이상이면 1개월간 근로 인정

④ 부소득자의 실직일 경우 : 부소득자의 실직 전 소득이 지원요청일 기준 가구구성원 수에 따른 긴급지원 생계지원 금액 이상인 경우

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2024-11-27', 4479, 'https://www.129.go.kr/faq/faq00.do?pageIndex=75#faq865', '030fa068721848ee6b537b9c44094de2bfec6d53aa11e4c0a556c8a096a3dc81'),
('858', 'faq129-20261010', '사회복지', '긴급지원사업', '휴·폐업으로 긴급생계지원을 요청 할 경우 조건이 있나요?', '가구 구성원 중 주소득자(부소득자)의 휴·폐업으로 가구의 생계유지 등이 곤란한 경우 긴급생계지원을 요청할 수 있으며, 다음의 요건을 모두 충족해야 합니다.

① 가구구성원 중 주소득자(부소득자)가 1년 이상의 영업을 지속한 후 휴·폐업신고를 한 경우

② 긴급지원 신청일 기준 휴·폐업신고일이 12개월 이내인 경우

③ 부소득자의 휴·폐업일 경우 : 부소득자의 휴·폐업전 소득이 지원요청일 기준 가구구성원 수에 따른 긴급생계지원금액 이상인 경우

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 2493, 'https://www.129.go.kr/faq/faq00.do?pageIndex=75#faq858', 'a343f982a3fbcb2d06b67d71e81ec873a5b68cb5cf89cbfa6d9c4bbc1d02a69a'),
('869', 'faq129-20261010', '사회복지', '긴급지원사업', '부모님 두분이 동시에 긴급의료지원 요청이 가능한가요?', '긴급의료지원은 개인단위 지원입니다.

따라서, 중한 질병 또는 부상으로 인한 의료비 감당이 어려운 경우 부모님 두분에 대해 각각 긴급의료지원 요청이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 1718, 'https://www.129.go.kr/faq/faq00.do?pageIndex=75#faq869', '81a09049d35de6cef74db92db710e7f0b7964cd837b38502dec61d2bed1eb92a'),
('870', 'faq129-20261010', '사회복지', '긴급지원사업', '외국인도 긴급생계지원 신청 가능한가요?', '국내에 체류하고 있는 외국인 중 다음에 해당하는 분들이 신청할 수 있습니다.

㉮ 대한민국 국민과 혼인중인 사람

㉯ 대한민국 국민인 배우자와 이혼하거나 그 배우자가 사망한 사람으로서 대한민국 국적의 직계존비속(直系尊卑屬)을 돌보고 있는 사람

㉰ ­난민법­ 제2조제2호에 따른 난민(難民)으로 인정된 사람

㉱ 본인의 귀책사유 없이 화재, 범죄, 천재지변으로 피해를 입은 사람

㉲ 그 밖에 보건복지부장관이 긴급한 지원이 필요하다고 인정하는 사람 ­

­- 본인의 귀책 사유 없이 재난 등으로 피해를 입은 사람

­­- 난민법­ 제2조제3호에 따른 인도적체류자25)

­- 특별기여자 : 법무부장관이 대한민국에 특별한 기여를 했거나 공익의 증진에 이바지 했다고 인정하는 사람

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 2565, 'https://www.129.go.kr/faq/faq00.do?pageIndex=75#faq870', '7a7bf6e05862afed5007977879823f6264c7fa303408a47d466a09e9b9793780'),
('872', 'faq129-20261010', '사회복지', '긴급지원사업', '불법체류자도 긴급생계지원 신청 가능한가요?', '외국인의 범위에 포함되더라도 불법체류 중인 외국인은 긴급복지지원 요청이 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2024-11-27', 2218, 'https://www.129.go.kr/faq/faq00.do?pageIndex=75#faq872', '048f33884d0e27a9ae745b0fd663b88e1c9a977bd8110b6dc764964ddaf747d7'),
('874', 'faq129-20261010', '사회복지', '긴급지원사업', '수술 예정인데 의료비를 얼마나 지원받을 수 있나요?', '300만원의 범위 내에서 의료기관 등이 긴급지원대상자에게 제공한 의료서비스 비용 중 약제비, 본인부담금 및 비급여 항목을 지원하고 있습니다. 또한, 300만원 한도로 1회 지원 후에도 위기상황이 계속되는 경우에는 긴급지원심의위원회의 심의를 거쳐 1회(300만원한도) 추가연장으로 지원이 가능합니다.

* 긴급의료비 지원제외 : 간병비, 의료소모품 구입비. 보조기 또는 의료기구 구입비, 제증명료, 보호자 식대, 구급차 이용료, 비급여 도수치료비증식치료비추나요법, 비급여입원료(특실 및 1인실 비용), 비급여식대

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2024-11-27', 2344, 'https://www.129.go.kr/faq/faq00.do?pageIndex=76#faq874', 'c63f249b77074af56857205065b4b2c45d378038179546f4a8a0b1eaf80a291e'),
('875', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급의료지원 신청은 언제해야 하나요?', '긴급의료지원은 퇴원 전에 요청이 가능하며, 퇴원한 이후에는 긴급의료비 요청이 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2024-11-27', 2678, 'https://www.129.go.kr/faq/faq00.do?pageIndex=76#faq875', 'cce475ac06557896962f5cfb3972390f37dbe651e0719d3e318e47e6d6d00244'),
('876', 'faq129-20261010', '사회복지', '긴급지원사업', '입원 중 사망한 경우 긴급의료지원 신청이 가능한가요?', '긴급의료지원 신청 후 사망한 경우 지원대상에 포함되나, 사망한 이후에는 긴급의료지원 신청이 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 2028, 'https://www.129.go.kr/faq/faq00.do?pageIndex=76#faq876', '5eb3afb56c9866f046fd2db25c57d0699095083c626b92a08827e0adce4b10af'),
('877', 'faq129-20261010', '사회복지', '긴급지원사업', '디스크 수술비를 지원받을 수 있나요?', '만성적으로 앓고 있는 질병(재활치료, 기타 척추병증, 기타 추간판 장애, 무릎관절증 및 척추성질환 등)은 원칙적으로 의료비 지원대상이 될 수 없습니다.

다만, 진단서를 통해 갑자기 악화되어 수술 또는 입원을 요하는 긴급한 진료가 필요하다고 시군구청장이 인정하는 경우 인정 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 3164, 'https://www.129.go.kr/faq/faq00.do?pageIndex=76#faq877', 'ed8a533f82a12f423c509896f40bac408217dd06cafe62a6362c7d8b5dd02bf5'),
('878', 'faq129-20261010', '사회복지', '긴급지원사업', '의료급여자도 긴급의료지원을 받을 수 있나요?', '기초의료급여 수급자는 원칙적으로 긴급지원대상자가 될 수 없습니다.

다만, 예외적으로 수술 또는 중환자실 이용 등 긴급한 사유로 의료비를 감당하기 어려운 경우에 긴급의료지원이 가능합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 8301, 'https://www.129.go.kr/faq/faq00.do?pageIndex=76#faq878', 'd697f7a535641004221ee584ce4651e929d45e92c48b2633b9b691ecd0a5e6c0'),
('880', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급의료지원을 이미 받은 경우 동일 사유로 다시 신청할 수 있나요?', '상이한 상병일 경우 다시 의료지원 신청이 가능하나, 동일 상병이라면 지원이 종료된 후 2년이 경과한 이후 의료지원 신청이 가능합니다.

다만, 동일 상병일 경우 2년이내 재지원은 제외되나, 동일상병이라도 환부의 위치가 명확하게 구분되는 경우에는 가능합니다

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 1881, 'https://www.129.go.kr/faq/faq00.do?pageIndex=76#faq880', '7c52e06b5266714523f8c0a2e08af35a188186933d7a71ca48c758b7163d38dc'),
('901', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급생계지원 대상자가 교육지원도 받을 수 있나요?', '긴급생계지원을 받는 가구 중 초중고등학생에 대해 학용품비 등 학비 지원이 필요하다고 인정되는 경우 교육지원도 가능합니다.

다만, 긴급지원대상자로서 국가 또는 지방자치단체 등으로 부터 타 교육지원(교육급여수급자, 고교학비 지원, 청소년 한부모가족 고교 교육비 지원, 지자체 특수시책사업 등)을 받고 있는 경우에는 제외됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 1916, 'https://www.129.go.kr/faq/faq00.do?pageIndex=76#faq901', '107b7bd501888c2ee9f6ff87e5fd57ad92de91e0875dd34e1e8bb82d4730c925'),
('882', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급생계지원 대상자가 연료비 신청도 가능한가요?', '긴급생계지원을 받고 있다면 따로 신청을 하지 않아도 됩니다.

동절기(10~3월)에 긴급생계 또는 긴급주거 지원을 받는 가구에 대해서 난방을 위해 기름, 가스, 연탄, 화목 등의 구입 또는 사용에 필요한 비용에 대한 지원이 필요하다고 인정되는 가구에 대해서 연료비를 부가로 지원합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 2718, 'https://www.129.go.kr/faq/faq00.do?pageIndex=76#faq882', '1065c205751bdb7b660619bc146ab5b55f049e069dd48f4f693f52d6d18267d1'),
('912', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급생계지원 요청 시 소득에서 차감되는 지출항목이 있나요?', '지원요청 당시의 소득에서 정기적으로 지출되는 비용을 차감하는 항목은 다음과 같습니다.

① 3개월 이상 지속적으로 지출하는 의료비(의료기관의 진단서 및 진료비 영수증 첨부)로서 평균 1개월의 의료비, 약제비, 간병비

② 자신의 소득에서 지출하고 있는 대학생의 등록금(입학금·­수업료), 기성회비

※ 당해연도­­ 납부한­­ 입학금·­수업료의­­ 월평균­­ 지출액

③ 월세(또는 보증부 월세)로 주거를 임차한 경우 매월 지출되는 임차료

※ 임차료 차감한도액 : 가구구성원수별 긴급주거지원금

④ 국민연금, 건강보험, 고용보험 등 사회보험료

⑤ 신용회복위원회를 통해 또는 법원의 판결을 받아 납부하고 있는 채무변제액 또는 금융부채로 인하여 매월 지출되고 있는 원금 및 이자비용

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 2389, 'https://www.129.go.kr/faq/faq00.do?pageIndex=76#faq912', '193a94a042aef49966bf3f3de940b0c195523714c76fcd3762f0bf440508337a'),
('913', 'faq129-20261010', '사회복지', '긴급지원사업', '긴급생계요청시 주택청약종합저축은 금융재산으로 산정되나요?', '「주택법」 제56조2항에 따른 주택청약종합저축은 금융재산에서 제외하고, 일반재산으로 산정합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-27', 5552, 'https://www.129.go.kr/faq/faq00.do?pageIndex=76#faq913', 'eaacf5bd49e78e6db0edcb2ca1e8f3c052dffc0b956ab55a182bb2c0218b1943');
