INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('15021', 'faq129-20261010', '노인장애인', '장애인활동지원', '제한적 가족급여를 제공하는 가족 활동지원사도 보수교육을 받아야 하나요?', '제한적 가족급여를 제공하는 가족 활동지원사도 타 활동지원사와 마찬가지로 등록된 활동지원기관의 보수교육 일정에 맞춰 1년에 최소 8시간 이상의 보수교육을 받아야 합니다.

불가피한 사유*로 인해 보수교육 참석하지 못하는 경우 총 교육시간의 최소 2/3 이상의 보수교육은 이수하여야 합니다.

불가피한 사유 없이 보수교육 이수를 하지 않을 경우 가족급여 이용이 종료될 수 있습니다.

*(불가피한 사유) 민법 제779조(가족의 범위), 장애인활동지원사업안내 가족의 범위(수급자 기준)에 해당하는 가족의 경조사, 가족 활동지원사의 입원 등 사유가 보수교육 일정이 중복되는 경우

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-11-26', 102, 'https://www.129.go.kr/faq/faq00.do?pageIndex=77#faq15021', '2fd5b340d91c6f7bbadf659abe912b9261fd3702623c7633b66ec72d704d003d'),
('15000', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인거주시설 입소신청은 어디로 하나요?', '중증장애인 거주시설과 장애유형별 거주시설 입소신청은 장애인 주소지 관할 읍·면·동 주민센터에서 신청 할 수 있습니다.

중증장애인 거주시설과 장애유형별 거주시설(독립형 주거서비스 제공기관)은 서비스 지원 종합조사 기능제한(X1) 점수*가 최소한의 요건(필수조건)으로 지자체 혹은 지방 장애인복지위원회 등에서 적격성 여부를 심사하여 결정합니다.

* 중증장애인 거주시설 (성인 240점/ 아동 190점), 장애유형별 거주시설, 독립형 주거서비스 제공기관(성인120점/ 아동 110점)

** 장애영유아거주시설, 장애단기거주시설, 장애인공동생활가정은 서비스지원 종합조사 점수와 관계없이 입소 가능

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-11-25', 63, 'https://www.129.go.kr/faq/faq00.do?pageIndex=77#faq15000', 'b9830e958d04d573dbbf30eca7dd09832c1367b6f2aa1e75a6342a84e50ceaf5'),
('15019', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인 거주시설 직원은 인권교육을 받아야 하나요?', '장애인 거주시설 직원 전체를 대상으로 반드시 연2회(8시간) 이상 받아야 합니다.(단, 하반기 채용자는 익년부터 적용)

또한, 장애아동이 생활하고 있는 장애인 거주시설에서 장애아동을 지원하는 직원은 인권교육 시간 중 1시간 이상은 장애아동 인권 관련 교육을 받아야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-11-25', 32, 'https://www.129.go.kr/faq/faq00.do?pageIndex=77#faq15019', '5c9e4d9d3022b88228aba5f57bf75def15204f8b2d9c076d29f9f442e558ead6'),
('15020', 'faq129-20261010', '노인장애인', '장애인복지사업', '장애인 거주시설 인권교육을 할 수 있는 외부 강사 자격기준이 있나요?', '장애인거주시설 직원 및 이용자 인권교육은 외부 강사를 초빙하여 진행함을 원칙으로 하되, 인권교육 강사양성과정 수료자에 한하여 내부 교육을 진행할 수 있습니다. (단, 강사양성과정 수료자에 의한 내부교육은 이용자 인권교육 2시간, 직원 인권교육은 4시간에 한해 인정)

인권교육 외부강사 기준은 다음과 같습니다.

- 국가인권위원회 주관 인권교육 관계자 및 양성과정 수료자

- 인권단체 소속으로 3년 이상 활동한 자

- 지자체, 공공기관 및 인권지킴이지원센터에서 주관한 인권교육 강사양성과정 수료자

- 사회복지학과 교수

- 기타 위 각호에 준하는 인권관련 자격 및 경력이 있다고 인정되는 자

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-11-25', 32, 'https://www.129.go.kr/faq/faq00.do?pageIndex=77#faq15020', '4e7108050de0e36d1c325717c865ca77f631d77f85efacf63f218d2d2ce974a9'),
('7034', 'faq129-20261010', '보건의료', '보건의료정책', '간호·간병통합서비스 제공기관이란 무엇인가요?', '의료법 시행규칙 1조의4 제1항에서 정하는 입원 환자를 대상으로 보호자 등이 상주하지 아니하고 간호사, 간호조무사 및 그 밖에 간병지원인력에 의하여 포괄적인 입원서비스를 제공하는 의료기관을 의미합니다.

또한, 병원급 의료기관 중 간호·간병통합서비스 제공기관으로 지정받고자 하는 경우에는 의료법 시행규칙 ''[별표 1의2] 간호·간병통합서비스 제공기관의 인력, 시설, 운영 등 기준''을 준수하여 국민건강보험공단에 사업 참여 신청을 하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-18', 2796, 'https://www.129.go.kr/faq/faq00.do?pageIndex=77#faq7034', '6b54200bc252034e7b39eaf9ff4841497a0a651ca27409f909d019db4519430e'),
('14839', 'faq129-20261010', '사회복지', '의료급여사업', '의료급여 유형이 1종에서 2종으로 변경된 경우, 기존 의료급여증을 계속 사용해도 되나요?', '의료급여 유형이 1종에서 2종 또는 2종에서 1종으로 변경된 경우, 기존 의료급여증은 회수하고 변경된 내용에 맞게 새로운 의료급여증을 발급합니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2024-11-18', 164, 'https://www.129.go.kr/faq/faq00.do?pageIndex=77#faq14839', '996c89a2e1c28f458ae24d95f6d0cc693f2265c2334226b21b07e7d6ddae71d1'),
('14840', 'faq129-20261010', '사회복지', '의료급여사업', '임신·출산진료비를 신청하기 전에 사용한 진료비도 소급적용 되나요?', '임신­·출산 진료비는 보장기관이 지원 결정한 날부터 사용가능하므로 신청일 이전에 부담한 본인부담금에 대해서는 원칙적으로 소급 적용되지 않습니다.

더 자세한 사항은 보건복지상담센터(국번없이129)로 연락주시기 바랍니다.', '2024-11-18', 48, 'https://www.129.go.kr/faq/faq00.do?pageIndex=77#faq14840', '5c1deef61f784082dde8a53ce63bce9d9e4733a1aa992e51b050d9972b5e6b78'),
('14859', 'faq129-20261010', '사회복지', '자활사업', '자활근로의 최대 참여기간이 정해져 있나요?', '자활참여자의 자활 촉진 및 자활근로 안주를 방지하기 위하여 자활근로 참여기간은 최대 60개월로 제한하고 있습니다.

단, 근로유지형 자활근로는 연속 참여기간의 제한이 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-18', 178, 'https://www.129.go.kr/faq/faq00.do?pageIndex=77#faq14859', '83fb1864a8a357c1dc6addaf1802754ae92fcbfff7a7139603e2d622369cabfe'),
('14861', 'faq129-20261010', '사회복지', '자활사업', '자활급여는 언제 지급되나요?', '자활급여는 근로한 달의 다음달 3일까지 지급을 원칙으로 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-18', 155, 'https://www.129.go.kr/faq/faq00.do?pageIndex=77#faq14861', '45c9d3095c96006db3b597a600edcb1e3d268065d4bfbab3edf1904f1fac5fdb'),
('14959', 'faq129-20261010', '보건의료', '건강보험정책', '65세 이상 의원급 외래진료 시 본인부담금은 어떻게 되나요?', '65세 이상인 환자(가입자 및 피부양자)가 의원급 의료기관 외래 진료 시 요양급여비용 총액에 따라 본인부담금을 경감하며, 본인부담액은 다음과 같습니다.

- 요양급여비용 총액이 15,000원을 넘지 않는 경우 본인부담 1,500원,

- 요양급여비용 총액이 15,000원을 넘고 20,000원을 넘지 않는 경우 본인부담 10%,

- 요양급여비용 총액이 20,000원을 넘고 25,000원을 넘지 않는 경우 본인부담 20%,

- 25,000원 초과 본인부담 30%

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-18', 170, 'https://www.129.go.kr/faq/faq00.do?pageIndex=77#faq14959', 'be00fe4d5010d1e1e747d766b97c5a1009da86ea824f346cba1a001b3288d6a2'),
('14979', 'faq129-20261010', '보건의료', '건강보험정책', '요양기관 본인확인 시 촬영한 신분증을 제시하는 경우에도 본인확인이 가능한가요?', '요양기관이 요양급여를 실시하는 경우, 신분증 또는 건강보험증 사본은 본인확인 수단으로 인정하고 있지 않으므로 영상 및 사진촬영 등에 의한 사본은 본인확인 수단으로 인정이 불가합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-18', 132, 'https://www.129.go.kr/faq/faq00.do?pageIndex=78#faq14979', '58a7baf3c191bc6ca4b6a4c403e43d2c9dfc3615d68338126a5b99c21f257d9f'),
('14862', 'faq129-20261010', '보건의료', '건강정책', '이용업의 “손님”은 남성으로만, 미용업의 “손님”은 여성으로만 한정되나요?', '­공중위생관리법­에서는 이용업 및 미용업의 대상을 “손님”으로만 규정하고 있을 뿐,

그 성별을 제한하는 특별한 규정을 두고 있지 않아 이용업의 “손님”은 남성으로만, 미용업의 “손님”은 여성으로만 한정된다고 볼 수 없습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-06', 148, 'https://www.129.go.kr/faq/faq00.do?pageIndex=78#faq14862', '7bbf4b794d4030f520ed73a46dd2d906263c8320fa5e46915e5ad246823ca02d'),
('14899', 'faq129-20261010', '보건의료', '보건의료정책', '환자는 친족에게 진료기록 사본 발급을 위임할 수 있나요?', '네, 있습니다.

환자의 대리인이 될 수 있는 자에서 친족을 제외할 이유가 없으므로, 환자의 친족은 환자의 대리인이 될 수 있습니다.

따라서 친족은 가족관계증명서를 구비하여 환자의 친족으로서 진료기록 사본 발급을 요청할 수도 있고, 환자의 위임장을 교부받아 진료기록 사본 발급을 요청할 수도 있습니다.

물론 두 경우 모두 환자의 자필서명 동의서, 친족의 신분증 사본 등 의료법령에서 정하고 있는 서류를 의료기관에 제출하여야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-06', 124, 'https://www.129.go.kr/faq/faq00.do?pageIndex=78#faq14899', 'e2330dedf2fe5d4a79713b4e24e7069a87ab49c3c95ef51fe96148864ae13618'),
('14900', 'faq129-20261010', '보건의료', '보건의료정책', '14세 이상의 미성년 환자는 친권자(법정대리인)가 진료기록 사본발급을 대리할 수 없나요?', '아닙니다.

환자가 19세 미만인 미성년자인 경우에 14세 도달 여부와 관계없이 법정대리인인 친권자가 대리하여 진료기록 사본을 발급받을 수 있습니다.

19세 미만의 미성년자인 경우에는 부모인 친권자는 가족관계증명서로 친권자임을 증명하여 자녀의 진료기록 사본을 요청할 수 있고,

또는, 법정대리인이 대리인을 선임하여 자필서명 동의서 및 위임장, 법정대리인의 신분증 사본을 교부하고 대리인으로 하여금 진료기록 사본을 발급받도록 할 수도 있습니다.

다만 환자가 미성년자라도 의사능력 및 진료기록 사본 발급 및 그 위임에 대한 사무처리능력이 인정되는 경우에 환자 본인이 단독으로 진료기록 사본을 발급받을 수 있고,

제3자를 대리인으로 선임하여 자필서명 동의서, 위임장, 환자 본인의 신분증 사본을 교부하고 대리인으로 하여금 진료기록 사본을 발급받도록 할 수도 있습니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-11-06', 95, 'https://www.129.go.kr/faq/faq00.do?pageIndex=78#faq14900', 'c21a74e44a84fe7b68b0b6edd0d15923bd3f36a3b1048984d7cf9b7f45f80396'),
('14799', 'faq129-20261010', '노인장애인', '장애인활동지원', '장애인활동지원 가족급여 제한적 허용이 가능한 대상자는 누구인가요?', '장애인활동지원에 관한 법률 시행령 제21조제4호 개정으로 보건복지부장관이 정하는 최중증 발달장애인 또는 희귀질환자인 경우 장애인활동지원 가족급여를 2024년 11월 1일부터 2026년 10월 31일까지 한정하여 제한적으로 허용합니다.

장애인활동지원에 관한 법률 시행령 제21조 제4호에 따른 예외적 가족급여의 대상자는 GAS 척도 30점 이하, 지능지수 35점 이하의 최중증 발달장애인과 장애인활동지원 가산급여 기준에 해당하는 희귀질환관리법 제2조제1호에 따른 희귀질환자입니다. 또한, 활동지원사 미연계가 60일 이상 지속되어야 합니다.

이는 장애인에 대한 사회적 돌봄 책임 및 가족의 직접 돌봄 부담을 경감하고자 하는 활동지원 제도의 취지를 유지하기 위해, 발달장애인의 도전적 행동으로 인한 어려움, 희귀질환자 등에 대한 지원인력의 기피 현상을 고려하여 예외적으로 대상자를 설정하였습니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-11-04', 168, 'https://www.129.go.kr/faq/faq00.do?pageIndex=78#faq14799', 'ea7474fefff2d18d5dfae500eb868ba88dd04c74a512361b4ff70e8defb249de'),
('14801', 'faq129-20261010', '노인장애인', '장애인등록', '온라인으로 장애인 등록 신청 가능한가요?', '''복지로(bokjiro.go.kr)에 로그인* 하여 장애인등록 신청이 가능합니다.

* 신청인이 미성년인 경우 신청인과 주소가 같은 부모가 로그인하여 대리 신청 가능

다만, 온라인 신청일부터 30일 내에 해당 장애유형에 대한 필수 첨부서류를 우편 또는 방문을 통해 관할 읍면동 주민센터에 제출해야 하며, 필수 첨부서류가 관할 읍면동 주민센터에 제출된 날이 장애인 등록 신청일이 됩니다. 만일 30일 내에 필수 첨부서류가 제출되지 않으면 온라인 신청은 자동 취소됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-11-04', 163, 'https://www.129.go.kr/faq/faq00.do?pageIndex=78#faq14801', '403862008ee31f810110860e2a147405240533592e18bff137f0d9fe74cb70f5'),
('14802', 'faq129-20261010', '노인장애인', '장애인활동지원', '장애인활동지원 제한적 가족급여 이용 시 이용량은 어떻게 되나요?', '장애인활동지원에 관한 법률 시행규칙 제15조 제2항에 따라 가족인 활동지원인력으로부터 활동지원급여를 받는 경우 급여량이 50% 감산된 급여가 지급됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-11-04', 117, 'https://www.129.go.kr/faq/faq00.do?pageIndex=78#faq14802', '52ff325c69e89780b0a07a13899ae3cb38d51f49300d118a390b513bf12fd11d'),
('14800', 'faq129-20261010', '노인장애인', '장애인등록', '장애인등록증 진위확인 방법이 있나요?', '장애인이 제시하는 장애인등록증의 진위확인이 필요한 경우, 누구나 ''복지로(bokjiro.go.kr)''에 로그인하고, 확인하고자 하는 장애인등록증 정보(성명, 주민등록번호(외국인등록번호), 발급일자, 조회기관(선택)) 입력한 후 "진위확인" 버튼 클릭하면 진위확인 메시지*가 표출됩니다.

* ‘입력하신 내용은 장애인등록 정보와 일치합니다.’ 또는 ‘입력하신 내용은 장애인등록 정보와 일치하지 않습니다. 자세한 사항은 가까운 읍면동 주민센터에 문의하시기 바랍니다.’

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-10-31', 100, 'https://www.129.go.kr/faq/faq00.do?pageIndex=78#faq14800', 'a67517c7934ded2f4613af229250959088c1148d1a7fd3ae5b5bf0b4668103c5'),
('14819', 'faq129-20261010', '노인장애인', '장애인활동지원', '장애인활동지원 제한적 가족급여 제공하는 가족도 활동지원기관에 소속되어야 하나요?', '고정된 1인의 가족이 활동지원인력으로 등록을 하고, 관할 내 활동지원기관과 근로계약을 체결하고 서비스를 제공해야합니다.

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-10-31', 81, 'https://www.129.go.kr/faq/faq00.do?pageIndex=78#faq14819', 'ec6a5881dfce6355fd4c4405b82edf86af2347bad87af19dc2a820ee52482211'),
('10275', 'faq129-20261010', '보건의료', '건강보험정책', '상병수당은 누가 신청 할 수 있나요?', '상병수당 시범사업 지역에 거주하는 취업자 또는 해당 지역 내 사업장에서 근무하는 근로자 중 만 15세 이상 만 65세 미만 대한민국 국적자 중 지역별 시범사업 모형에 따른 요건이 충족하는 경우,

관련서류를 준비하여 건강보험공단 지사에 신청하면 심사 후 상병수당을 지급합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-10-29', 790, 'https://www.129.go.kr/faq/faq00.do?pageIndex=78#faq10275', 'f8fcfea0f8ed11e15fca6d087a020b0ab157302604b124bc6222cc0d3f0a622d');
--> statement-breakpoint
INSERT INTO faq_129 (faq_id, revision, group_name, category, question, answer, written_date, views, source_url, content_sha256) VALUES
('4451', 'faq129-20261010', '보건의료', '보건의료정책', '진료기록 사본의 우편송부 또는 팩스나 이메일을 통한 전송이 가능한가요?', '네, 가능합니다.

요청자의 요청이 적법요건을 갖춘 것으로 확인된 이후에는 환자의 요구 및 의료기관 여건에 따라 다양한 방법으로 진료기록 사본의 제공이 가능합니다.

따라서 내원한 환자에게 종이출력물 또는 전자기록을 저장한 USB, CD 등을 교부하는 방식 뿐만 아니라, 우편송부 또는 팩스나 이메일을 통한 전송이 가능합니다. 다만, 이 과정에서 정보 유출 사고 위험을 최소화 할 수 있도록 주의해야 합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-10-25', 7653, 'https://www.129.go.kr/faq/faq00.do?pageIndex=79#faq4451', '58ccd6ce8de3a373734c4c74adc33d41530dba5e37f53d1cb9fc066ab7f61a6f'),
('10599', 'faq129-20261010', '보건의료', '보건의료정책', '의료기관 가정간호서비스 이용 대상자는 누구인가요?', '가정간호 대상자는 의료기관에서 입원치료 후 퇴원한 환자와 외래 및 응급실 환자 중 다음에 해당되는 자로서 의사 또는 한의사가 가정에서 계속적인 치료와 관리가 필요하다고 인정하는 경우에 해당됩니다.

- 수술 후 조기퇴원환자

- 만성질환자(고혈압·당뇨·암 등)

- 만성호흡기질환자

- 말기환자

- 심뇌혈관질환자

- 산모 및 신생아

- 의학적 상태 감시가 지속적으로 필요한 환자

- 기타 의사가 필요하다고 인정하는 환자

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-10-25', 435, 'https://www.129.go.kr/faq/faq00.do?pageIndex=79#faq10599', '7b6872a2b4735eebc79853b6ebff5e241a86044f05ec623fd98e31dcc718cfd7'),
('14338', 'faq129-20261010', '보건의료', '보건의료정책', '의료기관의 임종실 면적은 어떻게 산정하나요?', '임종실은 현행 의료법상 1인실과 같이 10㎡ 이상으로 하여야하며, 이때의 면적은 벽, 기둥, 화장실의 면적을 제외한 유효면적을 의미합니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2024-10-24', 71, 'https://www.129.go.kr/faq/faq00.do?pageIndex=79#faq14338', '5b472b715823ab02e2979a0312d3e03ce5dec6b9cbec528fdb2470d577290778'),
('14779', 'faq129-20261010', '보건의료', '보건의료정책', '의료기관의 임종실 내에 손씻기 시설 및 환기시설을 설치해야 하나요?', '임종실에도 1인실 입원실과 동일하게 손씻기 시설 및 환기시설을 의무적으로 설치하여야 합니다.

다만, 의료기관이 기존의 1인실 입원실을 임종실로 전환하려는데 해당 입원실이 ''17.2.3. 이전에 설치된 경우, 손씻기 시설 및 환기시설을 별도로 설치하지 않아도 됩니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2024-10-24', 30, 'https://www.129.go.kr/faq/faq00.do?pageIndex=79#faq14779', '4189ea4d6b428dd4e99e773bc270ee3bae470f270bbf620f756f7d57880f49c8'),
('14780', 'faq129-20261010', '보건의료', '보건의료정책', '의료기관의 임종실이 비어 있는 경우, 임종환자가 아닌 일반환자를 수용하여 입원실로 사용할 수 있나요?', '임종실의 특성상 급작스럽게 사용해야 할 상황이 자주 발생할 것으로 예상되고 병상에 관한 여러 정책적 제도 등을 고려 시, 의료법상 설치되는 임종실은 임종환자를 위해서만 사용하는 것이 입법취지에 부합할 것으로 판단되어, 임종환자가 아닌 자의 사용은 적절하지 않을 것 입니다.

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다', '2024-10-24', 38, 'https://www.129.go.kr/faq/faq00.do?pageIndex=79#faq14780', '93bc1527e43e3cc50463bff9b7c60c4fc0e8ecaacca3200a4486065de5ddeb87'),
('10795', 'faq129-20261010', '보건의료', '보건의료정책', '보건복지부에서 지정한 전문병원은 어디에서 확인할 수 있나요?', '보건복지부에서 지정한 전문병원 현황은 다음의 방법으로 확인이 가능합니다.

① 건강보험심사평가원 홈페이지(www.hira.or.kr)

☞ 상단 ''의료정보'' > 병원·약국 찾기 > 전문병원 찾기 - 지역별 검색

② 국민건강보험공단 홈페이지(www.nhis.or.kr)

☞ 오른쪽 상단 ''전체메뉴(세줄)의 건강IN > 검진기관/병원찾기 > 병(의)원정보 - 병(의)원찾기 > 조건별 검색에서 ''특성별 병원'' - ''전문병원'' 선택 후 지역별 검색

③ 보건복지부 홈페이지(www.mohw.go.kr)

☞ 알림 > 공지사항 > 검색구분 제목으로 ''전문병원'' 입력 후 검색

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-10-15', 1622, 'https://www.129.go.kr/faq/faq00.do?pageIndex=79#faq10795', 'a7edf320f513618e3e355a32043b4c28e053a0edc2de0b8d386f2619423e352e'),
('12718', 'faq129-20261010', '보건의료', '건강보험정책', '건강보험가입자 본인부담상한제란 무엇인가요?', '본인부담상한제는 과도한 의료비로 인한 가계 부담을 덜어주기 위하여 가입자가 부담한 연간(1.1~12.31) 건강보험 본인일부부담금 총액이 본인부담 상한액을 초과하는 경우, 그 초과액을 국민건강보험공단에서 부담하는 제도입니다.

* 비급여, 전액본인부담, 선별급여, 임플란트, 상급병실(2,3인실)입원료, 추나요법, 상급종합병원 외래 경증질환 초·재진 등 본인부담금은 제외

더 자세한 사항은 보건복지상담센터(국번없이 129)로 연락주시기 바랍니다.', '2024-10-15', 442, 'https://www.129.go.kr/faq/faq00.do?pageIndex=79#faq12718', '222e04e5f7d776a0308df6ce42d6ef98b4bd8faac164f586c6565811a18a0c12'),
('1461', 'faq129-20261010', '노인장애인', '장애인연금(수당)', '장애인연금을 신청할 때 필요한 서류는 무엇인가요?', '장애인연금 신청시 제출해야 하는 서류는 다음과 같습니다.

<필수 제출서류>

① 신분증(대리신청 시 위임장 및 대리인의 신분증 포함)

② ­사회보장급여 신청(변경)서

③ ­소득­·재산 신고서

④ 본인 및 배우자의 ­금융정보등 제공 동의서

* 차상위 부가급여를 신청하는 경우에는 「금융정보등 제공 동의서」에 가구원 포함

⑤ 중증장애인 본인의 계좌 통장 사본

⑥ 장애정도 재심사에 따른 구비서류(장애정도 재심사 대상자만 해당)

<추가 제출서류> - 소득­·재산 및 부채 관련 입증서류로 해당시 제출

① 소득：월급명세서, 고용임금확인서 등

② 재산：전·월세 임대차계약서, 조합원입주권 등

③ 부채：전세권 설정등기 또는 확정일자를 받은 임대차 계약서 등

④ 사용대차확인서(중증장애인의 주거여건이 무료임차인 경우)

더 자세한 사항은 보건복지상담센터(국번없이 ☎129)로 연락주시기 바랍니다.', '2024-10-11', 5566, 'https://www.129.go.kr/faq/faq00.do?pageIndex=79#faq1461', '42e0c8c39ffb57ddf15a4291cee7c83e198cfc687b42585b70bd1e9ef3579141');
--> statement-breakpoint
